window.JUNWEN_QUESTIONS = {"questions":[{"id":"bk-pol-001","subject":"基本知识","chapter":"政治","stem":"我国的根本政治制度是：","options":["人民代表大会制度","多党合作制度","基层群众自治制度","民族区域自治制度"],"answer":0,"explanation":"人民代表大会制度是我国的根本政治制度。后三项是基本政治制度，不是根本政治制度。","source":"原创练习"},{"id":"bk-pol-002","subject":"基本知识","chapter":"政治","stem":"中国共产党的根本宗旨是：","options":["解放思想、实事求是","全心全意为人民服务","独立自主、自力更生","民主集中制"],"answer":1,"explanation":"全心全意为人民服务是党的根本宗旨。其余选项分别涉及思想路线、自力更生方针和组织原则。","source":"原创练习"},{"id":"bk-pol-003","subject":"基本知识","chapter":"政治","stem":"“一国两制”首先成功运用于：","options":["澳门回归","香港回归","台湾问题","经济特区设立"],"answer":1,"explanation":"香港于1997年7月1日回归，是“一国两制”的首次成功实践。澳门回归在1999年。","source":"原创练习"},{"id":"bk-pol-004","subject":"基本知识","chapter":"政治","stem":"我国国家机构实行的组织原则是：","options":["首长负责制","民主集中制","三权分立","委员会制"],"answer":1,"explanation":"国家机构的组织原则是民主集中制。首长负责制只是部分机关的工作责任制，三权分立不是我国的原则，委员会制也不是这个宪法表述。题干问组织原则，就不要用某一机关的内部责任制来代替。","source":"原创练习"},{"id":"bk-law-001","subject":"基本知识","chapter":"法律","stem":"我国的根本法是：","options":["民法典","刑法","宪法","立法法"],"answer":2,"explanation":"根本法指最高效力的法。宪法是根本法，民法典、刑法、立法法都要符合宪法，不能与它相抵触。看到“根本”，先找效力最高的那一部，而不是最常用的那一部。","source":"原创练习"},{"id":"bk-law-002","subject":"基本知识","chapter":"法律","stem":"完全民事行为能力人一般是指：","options":["八周岁以上的未成年人","十六周岁以上以自己劳动收入为主要生活来源的未成年人","十八周岁以上的成年人","不能辨认自己行为的成年人"],"answer":2,"explanation":"十八周岁以上的自然人为成年人，是完全民事行为能力人。十六周岁以上以自己劳动收入为主要生活来源的未成年人，法律上视为完全民事行为能力人，但题干问的是一般情形。","source":"原创练习"},{"id":"bk-law-003","subject":"基本知识","chapter":"法律","stem":"犯罪的本质特征是：","options":["刑事违法性","应受刑罚处罚性","社会危害性","主观恶性"],"answer":2,"explanation":"犯罪的三个特征里，社会危害性是本质特征，刑事违法性和应受刑罚处罚性是法律特征。主观恶性可以说明责任，但不是这三个特征里的本质特征。先分本质特征和法律特征。","source":"原创练习"},{"id":"bk-law-004","subject":"基本知识","chapter":"法律","stem":"下列哪一项属于行政处罚？","options":["刑事罚金","行政拘留","民事赔偿","党纪警告"],"answer":1,"explanation":"行政拘留是公安机关依法作出的行政处罚。罚金属于刑罚，赔偿属于民事责任，党纪处分不是行政处罚。","source":"原创练习"},{"id":"bk-eco-001","subject":"基本知识","chapter":"经济","stem":"商品的两个基本属性是：","options":["使用价值和价值","价格和价值","具体劳动和抽象劳动","个别劳动时间和社会必要劳动时间"],"answer":0,"explanation":"商品是使用价值和价值的统一体。具体劳动和抽象劳动是生产商品的劳动的二重性，不是商品本身的两个属性。","source":"原创练习"},{"id":"bk-eco-002","subject":"基本知识","chapter":"经济","stem":"在其他条件不变时，某种商品价格上升，其需求量通常会：","options":["增加","减少","不变","先增后减"],"answer":1,"explanation":"需求规律：价格上升，需求量下降。这是一般情形，吉芬商品等例外不在本题范围内。","source":"原创练习"},{"id":"bk-eco-003","subject":"基本知识","chapter":"经济","stem":"通货膨胀通常表现为：","options":["货币升值、物价下跌","货币贬值、物价总水平上涨","失业率一定下降","利率一定为零"],"answer":1,"explanation":"通货膨胀是纸币发行量超过流通中实际需要的货币量，引起货币贬值和物价总水平持续上涨。","source":"原创练习"},{"id":"bk-eco-004","subject":"基本知识","chapter":"经济","stem":"国内生产总值（GDP）衡量的是：","options":["一国居民在一定时期获得的全部收入","一国领土范围内一定时期生产的最终产品和服务的市场价值","一国的黄金储备","居民的可支配收入"],"answer":1,"explanation":"GDP按国土原则统计一定时期内生产的最终产品和服务。居民收入更接近GNP或国民总收入的口径。","source":"原创练习"},{"id":"bk-hum-001","subject":"基本知识","chapter":"人文与社会","stem":"“四书”不包括：","options":["《大学》","《中庸》","《论语》","《诗经》"],"answer":3,"explanation":"四书是《大学》《中庸》《论语》《孟子》。《诗经》属于五经，不属于四书。","source":"原创练习"},{"id":"bk-hum-002","subject":"基本知识","chapter":"人文与社会","stem":"我国现行行政区划中，直辖市目前有：","options":["三个","四个","五个","六个"],"answer":1,"explanation":"直辖市要按现行名单数：北京、天津、上海、重庆，一共四个。重庆是后来设立的，按更早的记忆会少算成三个。先写出四个名称，再选数字。","source":"原创练习"},{"id":"bk-hum-003","subject":"基本知识","chapter":"人文与社会","stem":"端午节的传统习俗主要纪念：","options":["孔子","屈原","李白","岳飞"],"answer":1,"explanation":"端午节的纪念对象，民间传统对应屈原，习俗是赛龙舟、吃粽子。孔子对应祭孔，李白是诗人，岳飞对应的纪念不是端午。人物和节日要成对，不要用知名度代替对应关系。","source":"原创练习"},{"id":"bk-hum-004","subject":"基本知识","chapter":"人文与社会","stem":"我国人口最多的少数民族是：","options":["回族","藏族","壮族","蒙古族"],"answer":2,"explanation":"比较人口规模时，壮族是我国人口最多的少数民族，主要聚居在广西。回族、藏族、蒙古族人口都少于壮族。人口最多和居住区域最广不是同一个问题。","source":"原创练习"},{"id":"bk-sci-001","subject":"基本知识","chapter":"科学技术","stem":"光在真空中的速度大约是：","options":["3×10^5 米/秒","3×10^8 米/秒","3×10^6 千米/秒","340 米/秒"],"answer":1,"explanation":"真空中光速约为3×10^8米/秒，也就是每秒30万千米。340米/秒接近空气中的声速。","source":"原创练习"},{"id":"bk-sci-002","subject":"基本知识","chapter":"科学技术","stem":"水的化学式是：","options":["HO","H2O","H2O2","CO2"],"answer":1,"explanation":"一个水分子由两个氢原子和一个氧原子组成，化学式为H2O。H2O2是过氧化氢。","source":"原创练习"},{"id":"bk-sci-003","subject":"基本知识","chapter":"科学技术","stem":"计算机中，1个字节（Byte）等于：","options":["2个比特","4个比特","8个比特","16个比特"],"answer":2,"explanation":"存储单位里，1字节等于8比特。这是固定换算，不是任意取2的一次方。看到Byte和bit，就按8倍关系选择，不要把字和位的数量记反。","source":"原创练习"},{"id":"bk-sci-004","subject":"基本知识","chapter":"科学技术","stem":"地球自转一周大约需要：","options":["12小时","24小时","30天","365天"],"answer":1,"explanation":"自转造成昼夜交替，周期大约是24小时。公转造成四季，周期大约是365天。30天更接近月相变化。题干问的是自转，不要用公转的时间来回答。","source":"原创练习"},{"id":"bk-def-001","subject":"基本知识","chapter":"国防与军队","stem":"中国人民解放军的建军节是：","options":["7月1日","8月1日","10月1日","9月3日"],"answer":1,"explanation":"1927年8月1日南昌起义，8月1日后来成为建军节。7月1日是党的生日，10月1日是国庆节。","source":"原创练习"},{"id":"bk-def-002","subject":"基本知识","chapter":"国防与军队","stem":"我国武装力量由哪几部分组成？","options":["解放军、武警、民兵","陆军、海军、空军","现役、预备役、文职","中央军委、战区、军种"],"answer":0,"explanation":"武装力量按宪法上的组成来分，是解放军、武警部队和民兵。陆军、海军、空军是军种，不是武装力量的全部构成。现役、预备役、文职是人员身份，中央军委、战区、军种是领导指挥层次。先看题干问的是哪一种分类。","source":"原创练习"},{"id":"bk-def-003","subject":"基本知识","chapter":"国防与军队","stem":"全民国防教育日是：","options":["3月5日","5月4日","8月1日","9月第三个星期六"],"answer":3,"explanation":"全民国防教育日是每年9月的第三个星期六，不是某一天固定的月日。3月5日、5月4日、8月1日各自对应别的纪念日。问“第几个星期几”时，不要改成一个固定日期。","source":"原创练习"},{"id":"bk-def-004","subject":"基本知识","chapter":"国防与军队","stem":"新中国成立后，人民海军、人民空军领导机构正式成立的年份是：","options":["1949年","1950年","1955年","1966年"],"answer":1,"explanation":"人民海军、人民空军领导机构都在1950年正式成立。1949年是新中国成立的年份。","source":"原创练习"},{"id":"pa-verb-001","subject":"岗位能力","chapter":"言语理解与表达","stem":"填入最恰当的一项是：复习要有计划，不能____，也不能只看解析不自己做题。","options":["三心二意","循序渐进","融会贯通","举一反三"],"answer":0,"explanation":"空缺处与“不能”搭配，应填消极说法。三心二意符合。后三项都是正面的学习方法，不能放在“不能”后面。","source":"原创练习"},{"id":"pa-verb-002","subject":"岗位能力","chapter":"言语理解与表达","stem":"这段话的主旨是：错题如果不回看，下次遇到同类题仍会错。把错题整理出来，隔一段时间再做，比把同一套卷子连刷三遍更有用。","options":["刷题数量越多越好","错题需要间隔复习","解析可以不看","模拟考试没有必要"],"answer":1,"explanation":"文段强调整理错题并隔一段时间再做，核心是错题的间隔复习，而不是单纯增加刷题次数。","source":"原创练习"},{"id":"pa-verb-003","subject":"岗位能力","chapter":"言语理解与表达","stem":"“他这个人很轴”中的“轴”，意思最接近：","options":["灵活","固执","幽默","健忘"],"answer":1,"explanation":"口语里说人“轴”，通常指认死理、不轻易转弯，意思接近固执。","source":"原创练习"},{"id":"pa-verb-004","subject":"岗位能力","chapter":"言语理解与表达","stem":"下列句子没有语病的是：","options":["通过这次模考，使我发现了薄弱章节。","他的复习进度整整提前了一个星期。","能否坚持复盘，是提高正确率的关键。","我们要采取各种措施，防止不再出现同样的错。"],"answer":1,"explanation":"A句“通过……使……”缺主语。C句两面对一面。D句“防止不再”否定失当。B句主谓搭配成立。","source":"原创练习"},{"id":"pa-math-001","subject":"岗位能力","chapter":"数量关系","stem":"一套练习有40题，已做完16题。已完成的比例是：","options":["25%","40%","50%","60%"],"answer":1,"explanation":"比例等于已完成除以总量。16除以40等于0.4，也就是40%。不要用16除以还没做的24题，也不要看到题目里的其他百分数就直接选。先写“部分除以整体”。","source":"原创练习"},{"id":"pa-math-002","subject":"岗位能力","chapter":"数量关系","stem":"某商品原价200元，先打八折，再减10元。现价是：","options":["150元","160元","170元","180元"],"answer":0,"explanation":"200×0.8=160，再减10元为150元。注意先折扣后减免的顺序。","source":"原创练习"},{"id":"pa-math-003","subject":"岗位能力","chapter":"数量关系","stem":"一项工作，甲单独做要6天，乙单独做要3天。两人合作，需要：","options":["1天","2天","3天","4天"],"answer":1,"explanation":"甲效率1/6，乙效率1/3，合作效率1/6+1/3=1/2，所以需要2天。","source":"原创练习"},{"id":"pa-math-004","subject":"岗位能力","chapter":"数量关系","stem":"一个两位数，十位数字是个位数字的2倍，两数字之和为9。这个数是：","options":["18","27","36","63"],"answer":3,"explanation":"设个位为x，十位为2x，2x+x=9，x=3，十位为6，数是63。","source":"原创练习"},{"id":"pa-judge-001","subject":"岗位能力","chapter":"判断推理","stem":"所有参加模考的人都交了答卷。小周交了答卷。由此可以必然推出：","options":["小周参加了模考","小周没有参加模考","参加模考的人一定是小周","不能确定小周是否参加了模考"],"answer":3,"explanation":"“参加模考”推出“交答卷”，不能反过来由交答卷推出参加了模考。小周可能因其他原因交了答卷。","source":"原创练习"},{"id":"pa-judge-002","subject":"岗位能力","chapter":"判断推理","stem":"找规律：2，6，12，20，30，（ ）","options":["40","42","46","56"],"answer":1,"explanation":"相邻差为4、6、8、10，下一次差为12。30+12=42。也可以看成n(n+1)：2×1不对；实际是n(n+1)：2=1×2，6=2×3，12=3×4，20=4×5，30=5×6，下一项6×7=42。","source":"原创练习"},{"id":"pa-judge-003","subject":"岗位能力","chapter":"判断推理","stem":"如果下雨，比赛就改期。比赛没有改期。可以推出：","options":["下了雨","没有下雨","比赛取消了","天气一定晴朗"],"answer":1,"explanation":"原命题的逆否命题成立：比赛没有改期，所以没有下雨。不能进一步推出一定是晴天。","source":"原创练习"},{"id":"pa-judge-004","subject":"岗位能力","chapter":"判断推理","stem":"笔：写字，最相近的一组是：","options":["杯子：喝水","书本：纸张","教师：学生","汽车：汽油"],"answer":0,"explanation":"笔是写字的工具。杯子是喝水的工具。书本与纸张是材料关系，教师与学生是人际关系，汽车与汽油是消耗关系。","source":"原创练习"},{"id":"pa-data-001","subject":"岗位能力","chapter":"资料分析","stem":"某班40人参加练习，正确率达到80%及以上的有16人。这部分人占全班的：","options":["20%","32%","40%","80%"],"answer":2,"explanation":"人数比例等于16除以40，是40%。题干里的80%是正确率标准，不是人数占比。先看问题问的是“人占全班的比例”，再决定用哪一个数当分子。","source":"原创练习"},{"id":"pa-data-002","subject":"岗位能力","chapter":"资料分析","stem":"去年报名1000人，今年报名1200人。同比增长：","options":["12%","16.7%","20%","25%"],"answer":2,"explanation":"增长率等于增长量除以基期。增长量是200人，基期是去年的1000人，200除以1000等于20%。16.7%左右是用今年的1200作分母，分母选错了。","source":"原创练习"},{"id":"pa-data-003","subject":"岗位能力","chapter":"资料分析","stem":"一张表里，甲科室支出30万元，乙科室支出20万元，丙科室支出50万元。甲科室支出占总支出的：","options":["20%","30%","40%","50%"],"answer":1,"explanation":"比重等于部分除以合计。30加20加50等于100万元，甲占30除以100，即30%。20%是把乙的金额当成了甲的比重。先加总，再做除法。","source":"原创练习"},{"id":"pa-data-004","subject":"岗位能力","chapter":"资料分析","stem":"某指标基期为80，现期为100。增长量是：","options":["20","25","80","1.25"],"answer":0,"explanation":"增长量=现期−基期=100−80=20。1.25是现期与基期的比值，不是增长量。","source":"原创练习"},{"id":"bk-pol-005","subject":"基本知识","chapter":"政治","stem":"做概念题时，先看题干问的是哪一种“路线”。党的思想路线，核心是：","options":["群众路线","实事求是","民主集中制","独立自主"],"answer":1,"explanation":"思想路线回答怎么认识世界，核心是实事求是，完整表述还包括一切从实际出发、理论联系实际、在实践中检验和发展真理。群众路线是根本工作路线，民主集中制是组织原则，独立自主常用来说明立足自身的方针。题干已经限定“思想路线”，其他路线不能拿来顶替。","source":"原创练习"},{"id":"bk-pol-006","subject":"基本知识","chapter":"政治","stem":"下列哪一项对应的是党的根本工作路线？","options":["实事求是","民主集中制","一切为了群众，一切依靠群众，从群众中来，到群众中去","独立自主、自力更生"],"answer":2,"explanation":"先给“路线”归类。根本工作路线回答依靠谁、怎么开展工作，内容是群众路线。实事求是属于思想路线，民主集中制是组织原则。类别对上之后，再看句子是不是完整的群众路线，而不是只出现“群众”两个字。","source":"原创练习"},{"id":"bk-pol-007","subject":"基本知识","chapter":"政治","stem":"“一个中心、两个基本点”中的两个基本点是：","options":["发展和安全","物质文明和精神文明","改革和稳定","四项基本原则和改革开放"],"answer":3,"explanation":"数字概括要先还原原句。基本路线是以经济建设为中心，坚持四项基本原则，坚持改革开放。两个基本点就是后两句。发展和安全、两个文明、改革发展稳定都很重要，但不是这句固定结构里的“两个基本点”。","source":"原创练习"},{"id":"bk-pol-008","subject":"基本知识","chapter":"政治","stem":"把改革开放也写进四项基本原则，这种归类错在哪里？","options":["把基本路线的另一个基本点并进了四项基本原则","把国体写成了政体","把外交准则写成了文化方针","把组织原则写成了思想路线"],"answer":0,"explanation":"四项基本原则是坚持社会主义道路、人民民主专政、中国共产党的领导、马列主义毛泽东思想。改革开放与这四项并列，同为基本路线的基本点，不能互相吞并。归类题先画两个圈，看选项是不是把隔壁概念塞了进来。","source":"原创练习"},{"id":"bk-pol-009","subject":"基本知识","chapter":"政治","stem":"判断国家性质时看的是国体。我国的国体是：","options":["人民代表大会制度","人民民主专政","单一制","中国共产党领导的多党合作和政治协商制度"],"answer":1,"explanation":"四个选项分属四条线：国体是国家性质，政体是政权组织形式，国家结构形式处理中央与地方，政党制度处理党与党的关系。我国国体是人民民主专政。人民代表大会制度是政体，单一制是国家结构形式。先翻译题眼，再对线。","source":"原创练习"},{"id":"bk-pol-010","subject":"基本知识","chapter":"政治","stem":"政体问的是政权怎样组织。我国的政体是：","options":["人民民主专政","联邦制","人民代表大会制度","基层群众自治制度"],"answer":2,"explanation":"政体对应人民代表大会制度。人民民主专政回答的是国体。我国不是联邦制。基层群众自治是基层民主的实现形式，不是国家政权组织形式本身。国体、政体、国家结构形式三个格子不要放进同一个答案。","source":"原创练习"},{"id":"bk-pol-011","subject":"基本知识","chapter":"政治","stem":"从中央与地方的关系看，我国的国家结构形式是：","options":["联邦制","邦联制","复合制","单一制"],"answer":3,"explanation":"国家结构形式回答整体与部分的关系。我国是单一制，地方权力来自中央授权。民族区域自治和特别行政区都在单一制里面，不能因为有自治区就答成联邦。联邦成员单位拥有联邦宪法保障的固有权力，和我国的安排不同。","source":"原创练习"},{"id":"bk-pol-012","subject":"基本知识","chapter":"政治","stem":"中国人民政治协商会议的性质是：","options":["爱国统一战线组织","最高国家权力机关","中央人民政府","最高监察机关"],"answer":0,"explanation":"政协履行政治协商、民主监督、参政议政职能，不制定法律，不行使行政权和监察权。它是爱国统一战线组织。权力机关看人大，行政机关看政府，监察职能看监察委员会。看到“政协”，先把这三类国家机关排除。","source":"原创练习"},{"id":"bk-pol-013","subject":"基本知识","chapter":"政治","stem":"外交上的宗旨、基本立场、基本准则要分开记。其中“宗旨”是：","options":["独立自主","维护世界和平、促进共同发展","和平共处五项原则","不结盟"],"answer":1,"explanation":"宗旨是要达到的目的，即维护世界和平、促进共同发展。基本立场是独立自主，基本准则是和平共处五项原则。不结盟是独立自主立场下的政策表现。题干问哪一个层次，就选那一层，不要用准则代替目的。","source":"原创练习"},{"id":"bk-pol-014","subject":"基本知识","chapter":"政治","stem":"和平共处五项原则中，作为基础的一项是：","options":["互不侵犯","平等互利","互相尊重主权和领土完整","和平共处"],"answer":2,"explanation":"五项是互相尊重主权和领土完整、互不侵犯、互不干涉内政、平等互利、和平共处。基础是互相尊重主权和领土完整。和平共处是整体性的目标表述，不能因为它放在名称里就当成基础。问“基础”时，先找前提，不找总称。","source":"原创练习"},{"id":"bk-pol-015","subject":"基本知识","chapter":"政治","stem":"题干限定“新时代”时，我国社会主要矛盾的正确表述是：","options":["人民日益增长的物质文化需要同落后的社会生产之间的矛盾","无产阶级和资产阶级之间的矛盾","计划和市场哪一个为主的矛盾","人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾"],"answer":3,"explanation":"先看时间限定。物质文化需要同落后社会生产之间的矛盾，是新时代之前的概括。新时代的两侧关键词换成“美好生活需要”和“不平衡不充分的发展”。它不是阶级对抗，也不是计划与市场之争。时间变了，旧句子不能继续当答案。","source":"原创练习"},{"id":"bk-pol-016","subject":"基本知识","chapter":"政治","stem":"“五位一体”总体布局不包括：","options":["国防和军队建设","经济建设","文化建设","生态文明建设"],"answer":0,"explanation":"五个位子是经济建设、政治建设、文化建设、社会建设、生态文明建设。国防和军队建设很重要，但不在这个数字清单里。数字型概念先默写满五项，多出来的领域就是要排除的项。","source":"原创练习"},{"id":"bk-pol-017","subject":"基本知识","chapter":"政治","stem":"“四个全面”战略布局中，用来引领其他三项的战略目标是：","options":["全面深化改革","全面建设社会主义现代化国家","全面依法治国","全面从严治党"],"answer":1,"explanation":"先分目标与举措。全面建设社会主义现代化国家是战略目标，全面深化改革、全面依法治国、全面从严治党是战略举措。目标引领举措。全面建成小康社会是目标已经实现前的旧表述，题干问现在的布局，要用现代化国家这一目标。","source":"原创练习"},{"id":"bk-pol-018","subject":"基本知识","chapter":"政治","stem":"新发展理念中，创新着重解决的是：","options":["发展不平衡问题","人与自然和谐问题","发展动力问题","社会公平正义问题"],"answer":2,"explanation":"五个理念要和各自的问题配对：创新对动力，协调对不平衡，绿色对人与自然和谐，开放对内外联动，共享对公平正义。只记住五个词不够。题干点名“创新”，就找动力，不要把共享要解决的公平正义安到创新上。","source":"原创练习"},{"id":"bk-pol-019","subject":"基本知识","chapter":"政治","stem":"下列对中国式现代化的理解，正确的是：","options":["可以先污染，等富裕以后再治理","需要走对外扩张的积累道路","物质指标先行，精神文明可以先放下","全体人民共同富裕，但不是同时同步同等富裕"],"answer":3,"explanation":"用五个特征做排除：人口规模巨大，全体人民共同富裕，物质文明和精神文明相协调，人与自然和谐共生，走和平发展道路。先污染违背人与自然和谐，对外扩张违背和平发展，只顾物质违背两个文明相协调。共同富裕还要排除“同时、同步、同等”这种绝对化说法。","source":"原创练习"},{"id":"bk-pol-020","subject":"基本知识","chapter":"政治","stem":"全过程人民民主中的“全过程”，强调的是：","options":["民主贯穿选举、协商、决策、管理、监督等环节","民主只发生在投票那一天","用协商代替选举","民主只在党内存在"],"answer":0,"explanation":"“全过程”针对的是把民主收成投票日的窄理解。它包括选举、协商、决策、管理、监督，不是用后面的环节取消选举。看到范围词，先检查选项有没有把过程收缩成一个点，或者把它扩大到否定选举。","source":"原创练习"},{"id":"bk-pol-021","subject":"基本知识","chapter":"政治","stem":"居民委员会的性质是：","options":["基层人民政府","基层群众性自治组织","街道办事处","区法院的派出法庭"],"answer":1,"explanation":"机构题先问它是政权机关还是群众自治组织。居委会和村委会是基层群众性自治组织。街道办事处是派出机关，乡镇政府才是基层政权。名字里有“委员会”，不能因此把它当成一级政府或法院。","source":"原创练习"},{"id":"bk-pol-022","subject":"基本知识","chapter":"政治","stem":"实行民族区域自治的前提是：","options":["各民族分别制定宪法","自治地方可以违背宪法","国家统一领导","取消中央的统一领导"],"answer":2,"explanation":"自治不是分离。结构是：在国家统一领导下，各少数民族聚居的地方实行区域自治。自治机关行使自治权，但自治条例、单行条例不得与宪法和法律相抵触。前提不成立，后面的自治权就无从谈起。","source":"原创练习"},{"id":"bk-pol-023","subject":"基本知识","chapter":"政治","stem":"作为改革开放起点的会议是：","options":["党的八大","党的十四大","党的十九大","党的十一届三中全会"],"answer":3,"explanation":"1978年十一届三中全会把党和国家工作重点转移到社会主义现代化建设上来，并作出改革开放的决策，所以是起点。十四大是在1992年明确建立社会主义市场经济体制的目标，属于后来的推进。先把1978和1992两个年份分开，再看题干问的是起点还是后续目标。","source":"原创练习"},{"id":"bk-pol-024","subject":"基本知识","chapter":"政治","stem":"“马克思主义活的灵魂”指的是：","options":["具体问题具体分析","背诵现成结论","用一种模式解决所有问题","只靠经验、不必学习理论"],"answer":0,"explanation":"这是一句固定判断：马克思主义活的灵魂在于具体地分析具体的情况。它要求原理联系实际，既反对把理论当教条，也不是抛弃理论。选项里的“一种模式”和“只靠经验”都把这句话说绝对了。","source":"原创练习"},{"id":"bk-pol-025","subject":"基本知识","chapter":"政治","stem":"理解“实践是检验真理的唯一标准”时，最关键的限定是：","options":["理论不再有用","最终标准只能是实践","书本可以代替实践","权威人物的判断高于实践结果"],"answer":1,"explanation":"“唯一”把书本、权威和主观愿望排除出最终标准。理论可以指导实践，但理论对不对，最终要看实践结果。选项如果把经典表述或权威判断写成最终标准，就和这个限定冲突。不要把“唯一标准”误读成“理论无用”。","source":"原创练习"},{"id":"bk-pol-026","subject":"基本知识","chapter":"政治","stem":"若把“白马非马”理解成白马根本不是马，从共性与个性的关系看，错在：","options":["承认了个性里面有共性","承认了联系","否认个性中包含着共性","承认了发展"],"answer":2,"explanation":"先翻译句子：白马是个性，马是共性。白马是马的一种特殊形态，个性中包含着共性。把特殊说成与普遍无关，就割裂了这一层。这道题不是在讨论联系或发展是否存在，翻译对关系之后，干扰项就容易排除。","source":"原创练习"},{"id":"bk-pol-027","subject":"基本知识","chapter":"政治","stem":"面对一堆问题时，矛盾分析法在用力次序上要求优先抓住：","options":["所有矛盾平均用力","只看外部条件","先回避矛盾","主要矛盾"],"answer":3,"explanation":"主要矛盾居于支配地位，抓住它，次要矛盾更容易带动。这不是说次要矛盾可以取消，而是次序上先抓决定性的那个。平均用力和回避矛盾都没有使用这个方法。题干问的是次序，不是把复杂问题说成只有一个因素。","source":"原创练习"},{"id":"bk-pol-028","subject":"基本知识","chapter":"政治","stem":"“不积跬步，无以至千里”用来说明量变与质变时，重点是：","options":["量变是质变的必要准备","质变可以离开量变突然出现","只有量变、不必发生质变","量变和质变没有关系"],"answer":0,"explanation":"名言题先找比喻的两端。跬步是一点一滴的积累，对应量变；千里是状态变化，对应质变。句子强调没有积累就到不了后来的变化，所以重点是量变准备质变。它没有说质变不重要，也没有说量变会自动等于质变。","source":"原创练习"},{"id":"bk-pol-029","subject":"基本知识","chapter":"政治","stem":"“城门失火，殃及池鱼”最直接体现的哲学道理是：","options":["事物之间可以没有任何联系","事物处在联系之中","规律可以由愿望创造","矛盾双方永远不能转化"],"answer":1,"explanation":"火并不直接烧鱼，但通过池水把两件事连起来。典故题先找出故事里的中介，再判断观点。它说明存在联系，并不是说任何两件事物都一定有直接联系。选项如果把联系说成毫无条件，或者否认联系，都不符合这个典故的尺度。","source":"原创练习"},{"id":"bk-pol-030","subject":"基本知识","chapter":"政治","stem":"对客观规律和主观能动性的关系，理解正确的是：","options":["规律可以按愿望改写","只要发挥能动性就能取消规律","在认识和利用规律的前提下发挥能动性","人完全被动，不必制定计划"],"answer":2,"explanation":"规律不以人的意志为转移，不能创造、不能消灭，但可以被认识并用来指导行动。正确项必须同时保住“客观”和“能动”。认为愿望可以改写规律，或者认为人只能被动等待，都只剩下一头。","source":"原创练习"},{"id":"bk-pol-031","subject":"基本知识","chapter":"政治","stem":"下列机构与地位对应正确的是：","options":["国务院是最高国家权力机关","最高人民法院是最高行政机关","国家监察委员会是最高审判机关","全国人民代表大会是最高国家权力机关"],"answer":3,"explanation":"按职能分线：权力机关看人大，行政机关看政府，审判机关看法院，监察机关看监察委员会。全国人大是最高国家权力机关。其余三项都把职能线串了。做机构题时先写“它干什么”，再对名称。","source":"原创练习"},{"id":"bk-pol-032","subject":"基本知识","chapter":"政治","stem":"国务院在国家机关体系中的定位是：","options":["最高国家行政机关","最高国家权力机关","最高监察机关","领导全国武装力量的机关"],"answer":0,"explanation":"行政机关负责贯彻法律、管理行政事务。国务院是最高国家行政机关，由全国人大产生，对全国人大及其常委会负责。中央军事委员会领导全国武装力量，国家监察委员会是监察机关。不要看到“最高”就把各类最高机关当成同一个。","source":"原创练习"},{"id":"bk-pol-033","subject":"基本知识","chapter":"政治","stem":"对“党的领导是中国特色社会主义最本质的特征”，理解错误的是：","options":["党的领导关系中国特色社会主义的方向","党的组织直接取代国家机关行使全部法定职权","这一特征同时被表述为中国特色社会主义制度的最大优势","党的主张通过法定程序转化为国家意志"],"answer":1,"explanation":"“最本质的特征”说的是领导地位，不是把党的组织写成直接办理一切行政、审判事务的机关。国家机关仍依法行使各自职权。遇到“理解错误的是”，先找说过头的绝对化选项。把领导写成全面代替，就是这一类。","source":"原创练习"},{"id":"bk-pol-034","subject":"基本知识","chapter":"政治","stem":"“四个自信”不包括：","options":["道路自信","理论自信","军事自信","文化自信"],"answer":2,"explanation":"四个自信是中国特色社会主义道路、理论、制度、文化自信。文化自信被强调为更基础、更广泛、更深厚的自信。军事力量重要，但不在这四项清单里。清单题用数量去卡，多出来的词就是答案。","source":"原创练习"},{"id":"bk-pol-035","subject":"基本知识","chapter":"政治","stem":"“全面从严治党，基础在全面，关键在严，要害在治”中，“要害在治”强调的是：","options":["只要口号说全就够了","严只针对普通党员，不涉及领导机关","治理可以离开党的领导来谈","要求要落到管党治党的实际行动上"],"answer":3,"explanation":"三个词有分工：全面是范围，严是标准，治是落点。要害在治，就是不能停在口号上。只讲全面、把对象缩小，或者把治党和党的领导拆开，都不符合这句结构。结构题先对齐每个词的分工。","source":"原创练习"},{"id":"bk-pol-036","subject":"基本知识","chapter":"政治","stem":"新民主主义革命的三大法宝不包括：","options":["市场经济","统一战线","武装斗争","党的建设"],"answer":0,"explanation":"三大法宝是统一战线、武装斗争、党的建设，属于新民主主义革命时期的概括。市场经济是后来经济体制改革中的内容。先看题干的时代，再排除另一个时代才出现的概念。","source":"原创练习"},{"id":"bk-pol-037","subject":"基本知识","chapter":"政治","stem":"1956年生产资料私有制的社会主义改造基本完成，直接标志着：","options":["新民主主义革命开始","社会主义基本制度在我国确立","改革开放正式启动","社会主义市场经济体制的目标被明确提出"],"answer":1,"explanation":"三大改造解决的是生产资料所有制，基本完成后社会主义基本制度确立。新民主主义革命在1949年已经取得基本胜利。改革开放对应1978年，社会主义市场经济体制目标对应1992年党的十四大。先问“这件事解决了什么”，再排除其他年代的事件。","source":"原创练习"},{"id":"bk-pol-038","subject":"基本知识","chapter":"政治","stem":"人民政协的主要职能是：","options":["制定和修改宪法","指挥全国武装力量","政治协商、民主监督、参政议政","审理行政诉讼案件"],"answer":2,"explanation":"职能题同时看能做什么、不能做什么。政协的三项职能是政治协商、民主监督、参政议政。立法权在人大，武装力量由中央军委领导，行政诉讼由法院审理。不要把统一战线组织的职能写成国家机关职权。","source":"原创练习"},{"id":"bk-pol-039","subject":"基本知识","chapter":"政治","stem":"在中国共产党领导的多党合作和政治协商制度中，民主党派的定位是：","options":["执政党","轮流执政的在野党","反对党","参政党"],"answer":3,"explanation":"中国共产党是执政党。各民主党派是接受中国共产党领导、同共产党通力合作的参政党，不是议会制里轮流上台的在野党或反对党。定位题先排除另一套政党制度的用词，再在执政与参政之间选择。","source":"原创练习"},{"id":"bk-pol-040","subject":"基本知识","chapter":"政治","stem":"“两个维护”指的是：","options":["维护习近平总书记党中央的核心、全党的核心地位，维护党中央权威和集中统一领导","维护地方各自为政，维护部门可以不执行中央决定","维护所有意见不加比较地并列，维护无原则的一团和气","维护个别领导干部的个人偏好，维护超越组织的个人决定"],"answer":0,"explanation":"“两个维护”是两句具体内容：维护习近平总书记党中央的核心、全党的核心地位，维护党中央权威和集中统一领导。它不是泛指维护任何个人偏好，也不是各行其是。原文对应题要整句对齐，看到“各自为政”或“个人偏好”就可以排除。","source":"原创练习"},{"id":"bk-law-005","subject":"基本知识","chapter":"法律","stem":"八周岁以上的未成年人，一般属于：","options":["无民事行为能力人","限制民事行为能力人","当然的完全民事行为能力人","必须经法院宣告才具有任何行为能力的人"],"answer":1,"explanation":"年龄先分三档：不满八周岁是无民事行为能力人；八周岁以上的未成年人是限制民事行为能力人；十八周岁以上一般是完全民事行为能力人。十六周岁以上靠自己劳动收入为主要生活来源的，视为完全民事行为能力人，那是例外。题干写了“一般”，就选原则档，不选例外。","source":"原创练习"},{"id":"bk-law-006","subject":"基本知识","chapter":"法律","stem":"不能辨认自己行为的成年人，其民事法律行为的效力是：","options":["一律有效","一律可撤销","无效","只要对方履行就有效"],"answer":2,"explanation":"成年人不自动都有完全民事行为能力。不能辨认自己行为的成年人是无民事行为能力人，其实施的民事法律行为无效。不能完全辨认的成年人则是限制民事行为能力人，两者差在“完全”两个字。先判断辨认程度，再判断效力。","source":"原创练习"},{"id":"bk-law-007","subject":"基本知识","chapter":"法律","stem":"普通诉讼时效期间届满后，产生的法律效果是：","options":["权利绝对消灭，当事人不得再提","法院必须主动适用，不需要当事人主张","义务人已经自愿履行的，可以请求返还","义务人可以提出不履行义务的抗辩"],"answer":3,"explanation":"普通时效是三年，从知道或者应当知道权利受损及义务人之日起算。届满后权利并不变成从来没有过，而是义务人取得时效抗辩。法院不能在无人主张时主动适用。义务人已经自愿履行的，不得再以时效为由要求返还。只记“三年”还不够，要把届满后的三层效果分开。","source":"原创练习"},{"id":"bk-law-008","subject":"基本知识","chapter":"法律","stem":"从权利受到损害之日起计算，人民法院保护民事权利的一般最长期间是：","options":["二十年","三年","五年","十年"],"answer":0,"explanation":"三年和二十年的起算点不同。三年看权利人知道或应当知道；二十年从权利受到损害之日起算。特殊情况，法院可以根据权利人申请决定延长。题干写的是“受到损害之日”，对应二十年，不要把知道之日的三年填进来。","source":"原创练习"},{"id":"bk-law-009","subject":"基本知识","chapter":"法律","stem":"构成正当防卫，必须满足的时间条件是：","options":["侵害结束后的报复","不法侵害正在进行","对方仅仅流露犯意","任何过去的民事纠纷"],"answer":1,"explanation":"正当防卫要同时看起因、时间、对象、意图和限度。时间窗口是不法侵害已经开始、尚未结束。事前动手和事后报复都不在窗口内，对象还必须是不法侵害人本人。五个条件缺一个，就不能整项认定为正当防卫。","source":"原创练习"},{"id":"bk-law-010","subject":"基本知识","chapter":"法律","stem":"对正在进行的抢劫采取防卫，造成不法侵害人伤亡的，刑法上的处理原则是：","options":["一律按防卫过当处罚","必须先经被害人承诺才可能正当","不属于防卫过当，不负刑事责任","只能由行政机关认定为行政处罚"],"answer":2,"explanation":"针对正在进行的行凶、杀人、抢劫、强奸、绑架以及其他严重危及人身安全的暴力犯罪，防卫造成伤亡的，不属于防卫过当，不负刑事责任。条件仍然是暴力犯罪正在进行。不能把它扩大到所有纠纷，也不能提前到犯罪尚未着手的阶段。","source":"原创练习"},{"id":"bk-law-011","subject":"基本知识","chapter":"法律","stem":"紧急避险和正当防卫的一个关键差别是：","options":["避险没有限度","防卫可以针对任何旁观者","两者都只适用于保护财产、不适用于保护人身","避险损害的往往是另一合法利益，防卫指向不法侵害人"],"answer":3,"explanation":"先问损害落在谁身上。防卫打的是侵害人；避险是不得已把正在发生的危险转给另一合法利益，而且造成的损害不应超过所避免的损害。职务上、业务上负有特定责任的人，不能为避免本人危险主张紧急避险。对象不同，是分开两个制度的第一步。","source":"原创练习"},{"id":"bk-law-012","subject":"基本知识","chapter":"法律","stem":"明知结果可能发生，并且放任它发生。这种心理属于：","options":["间接故意","直接故意","疏忽大意的过失","过于自信的过失"],"answer":0,"explanation":"用两步判断：是否明知，以及对结果持什么态度。希望发生是直接故意，放任发生是间接故意。应当预见而没有预见是疏忽大意的过失，已经预见却轻信能够避免是过于自信的过失。本题同时有“明知”和“放任”，落在间接故意。","source":"原创练习"},{"id":"bk-law-013","subject":"基本知识","chapter":"法律","stem":"已经预见危害结果可能发生，却轻信能够避免，以致结果发生。这是：","options":["直接故意","过于自信的过失","间接故意","疏忽大意的过失"],"answer":1,"explanation":"和间接故意的差别在态度。放任是结果发生也可以接受；轻信能够避免是不愿意结果发生，只是过高估计了防范措施。题干里的“轻信”就是划分词。不能因为“已经预见”就一律写成故意。","source":"原创练习"},{"id":"bk-law-014","subject":"基本知识","chapter":"法律","stem":"已满十四周岁不满十六周岁的人，应当负刑事责任的范围是：","options":["一切违法行为","一切故意犯罪","法律点名的故意杀人、故意伤害致人重伤或者死亡、强奸、抢劫、贩卖毒品、放火、爆炸、投放危险物质等罪","只有过失犯罪"],"answer":2,"explanation":"年龄分档不能并在一起。十六周岁以上，犯罪一般都应负责。十四至十六周岁只对法律点名的八类严重犯罪负责，不是对所有故意犯罪负责。十二至十四周岁还有更窄的故意杀人、故意伤害，并要经最高人民检察院核准追诉。题干是哪一档，就只用那一档的范围。","source":"原创练习"},{"id":"bk-law-015","subject":"基本知识","chapter":"法律","stem":"下列哪一项不属于主刑？","options":["管制","拘役","有期徒刑","罚金"],"answer":3,"explanation":"主刑是管制、拘役、有期徒刑、无期徒刑、死刑，一个犯罪只能适用一个主刑。罚金、剥夺政治权利、没收财产是附加刑，可以附加适用，处罚金时依法也可以独立适用。分类题先默写主刑名单，名单外面的就是答案。","source":"原创练习"},{"id":"bk-law-016","subject":"基本知识","chapter":"法律","stem":"罚金和罚款的实质差别是：","options":["罚金是刑罚，罚款是行政处罚","只是金额大小不同","两者都由行政机关决定","两者都只能由法院判处"],"answer":0,"explanation":"名字相近时先问决定机关和法律性质。罚金由法院依照刑法判处，罚款由行政机关依照行政处罚法作出。同理，刑事拘留是刑事强制措施，行政拘留是行政处罚。只比较要不要交钱，区分不开这两对概念。","source":"原创练习"},{"id":"bk-law-017","subject":"基本知识","chapter":"法律","stem":"法律没有明文规定为犯罪行为的，不得定罪处刑。这条原则是：","options":["类推适用","罪刑法定","客观归罪","对行为时合法的行为溯及既往从重"],"answer":1,"explanation":"罪刑法定的两端都要看：法律明文规定为犯罪的，依法定罪处刑；没有明文规定的，不得定罪处刑。它排斥用类推把条文外的行为定成犯罪，也排斥对行为时并不构成犯罪的情形事后加重。客观归罪只看结果、不问主观，不是这条原则。","source":"原创练习"},{"id":"bk-law-018","subject":"基本知识","chapter":"法律","stem":"为了犯罪准备工具、制造条件，尚未着手实行犯罪。这属于：","options":["犯罪未遂","犯罪中止","犯罪预备","犯罪既遂"],"answer":2,"explanation":"预备、未遂、中止都停在既遂之前，先看停在哪里。还没有着手，是预备。已经着手、由于意志以外的原因没有得逞，是未遂。自动放弃或者自动有效防止结果，是中止。本题明确尚未着手，先归预备。","source":"原创练习"},{"id":"bk-law-019","subject":"基本知识","chapter":"法律","stem":"已经着手实行犯罪，因被在场群众制止而没有得逞。这属于：","options":["犯罪预备","犯罪中止","不构成任何犯罪形态","犯罪未遂"],"answer":3,"explanation":"先看着手：已经实施构成要件行为，就不再是预备。再看停下的原因：被群众制止，是犯罪分子意志以外的原因，所以是未遂。中止必须是自己能够继续却自动停下，或者自动有效防止结果。外部障碍不能写成中止。","source":"原创练习"},{"id":"bk-law-020","subject":"基本知识","chapter":"法律","stem":"犯罪过程中自动放弃犯罪，并且没有造成损害。处罚原则是：","options":["应当免除处罚","可以比照既遂从轻","应当与既遂同等处罚","只给予行政处罚"],"answer":0,"explanation":"中止分两档：没有造成损害的，应当免除处罚；造成损害的，应当减轻处罚。用词是“应当”，不是未遂那种“可以”。题干已经给了自动放弃和没有造成损害，就走到免除这一档。不要和预备、未遂的从宽幅度混用。","source":"原创练习"},{"id":"bk-law-021","subject":"基本知识","chapter":"法律","stem":"二人以上共同过失造成同一事故，正确的处理是：","options":["必然构成共同犯罪","不以共同犯罪论处，按照各自的过失分别追究","只能处罚其中职务最高的人","过失一律不负刑事责任"],"answer":1,"explanation":"共同犯罪以共同故意为要件。共同过失不按共同犯罪处理，而是分别确定各自的过失责任。几个人对结果都有责任，不等于刑法上的共同犯罪。先看主观方面是故意还是过失。","source":"原创练习"},{"id":"bk-law-022","subject":"基本知识","chapter":"法律","stem":"一般情况下，合同成立的时间是：","options":["要约发出时","合同履行完毕时","承诺生效时","发生争议时"],"answer":2,"explanation":"成立看双方意思表示是否达成一致。典型过程是要约和承诺，承诺生效时合同成立。成立不等于一律马上生效，附条件、附期限的合同可以先成立、后生效。题干只问成立，不要答成已经履行完毕。","source":"原创练习"},{"id":"bk-law-023","subject":"基本知识","chapter":"法律","stem":"无权处分时，受让人要构成善意取得，通常还需要：","options":["只要价格便宜就可以","必须经过原权利人当场签字","只能适用于盗赃物","受让时善意、以合理价格受让，并完成登记或交付"],"answer":3,"explanation":"善意取得保护的是交易安全，不是鼓励无权处分。要件要同时具备：处分人无权，受让人善意，价格合理，不动产已经登记或者动产已经交付。少一个要件就不能用这个制度。盗赃物并不能因为价格低就当然取得。","source":"原创练习"},{"id":"bk-law-024","subject":"基本知识","chapter":"法律","stem":"不动产物权的设立和转让，原则上：","options":["依法登记后发生效力","合同签字后物权立即变动","只要交付钥匙就完成","口头约定即可对抗第三人"],"answer":0,"explanation":"公示方法跟着客体走。不动产看登记，动产看交付。只签合同通常产生交付或过户的请求权，不等于物权已经转移。法律另有规定的除外，但题干问的是原则。先把债权效力和物权变动拆开。","source":"原创练习"},{"id":"bk-law-025","subject":"基本知识","chapter":"法律","stem":"继承开始后，第一顺序法定继承人是：","options":["兄弟姐妹、祖父母、外祖父母","配偶、子女、父母","只有配偶","只有子女"],"answer":1,"explanation":"第一顺序是配偶、子女、父母；第二顺序是兄弟姐妹、祖父母、外祖父母。有第一顺序继承人的，第二顺序不继承。子女包括婚生、非婚生、养子女和有扶养关系的继子女。不要把兄弟姐妹提前到第一顺序。","source":"原创练习"},{"id":"bk-law-026","subject":"基本知识","chapter":"法律","stem":"丧偶儿媳对公婆尽了主要赡养义务的，在继承法上：","options":["不能继承","只能作为第二顺序继承人","可以作为第一顺序继承人","必须再婚后才可以继承"],"answer":2,"explanation":"这是血缘顺序之外的法定情形，两个条件都要有：已经丧偶，并且尽了主要赡养义务。偶尔探望不够。丧偶女婿对岳父母尽了主要赡养义务的，规则相同。例外题把条件勾齐再选，不要只看到“儿媳”两个字。","source":"原创练习"},{"id":"bk-law-027","subject":"基本知识","chapter":"法律","stem":"民法典规定的三十日离婚冷静期适用于：","options":["所有诉讼离婚","法院一审判决离婚","解除收养关系","婚姻登记机关办理的协议离婚"],"answer":3,"explanation":"冷静期是协议离婚登记里的程序：登记机关收到申请之日起三十日内，任何一方可以撤回。诉讼离婚由法院审理，没有这个三十日登记冷静期。先看当事人是去登记机关还是去法院，再决定能不能适用。","source":"原创练习"},{"id":"bk-law-028","subject":"基本知识","chapter":"法律","stem":"法定结婚年龄是：","options":["男不得早于二十二周岁，女不得早于二十周岁","男女均不得早于十八周岁","男女均不得早于二十二周岁","男不得早于二十周岁，女不得早于十八周岁"],"answer":0,"explanation":"结婚年龄是特别规定，不能用十八周岁的完全民事行为能力代替。男二十二、女二十，两边不要对调。达到年龄只是条件之一，还要双方完全自愿，并且不存在禁止结婚的情形。","source":"原创练习"},{"id":"bk-law-029","subject":"基本知识","chapter":"法律","stem":"限制人身自由的行政处罚，只能由哪一类规范设定？","options":["行政法规","法律","地方性法规","部门规章"],"answer":1,"explanation":"处罚越严厉，可以设定它的文件位阶越高。限制人身自由涉及基本权利，只能由法律设定。行政法规、地方性法规和规章都不能创设这类处罚。看到“限制人身自由”，直接收到法律这一层。","source":"原创练习"},{"id":"bk-law-030","subject":"基本知识","chapter":"法律","stem":"刑事拘留的性质是：","options":["对犯罪的最终刑罚","行政处罚","刑事诉讼中的强制措施","民事制裁"],"answer":2,"explanation":"刑事拘留发生在侦查阶段，是暂时剥夺人身自由的强制措施，不是案件的最终处罚。行政拘留才是行政处罚，由行政机关依法决定。看它是办案过程中的手段，还是处理结论，就能把两个“拘留”分开。","source":"原创练习"},{"id":"bk-law-031","subject":"基本知识","chapter":"法律","stem":"行政复议维持原行政行为后，公民提起行政诉讼。被告应当是：","options":["只有复议机关","行政复议的申请人","上一级人民法院","作出原行政行为的行政机关和复议机关为共同被告"],"answer":3,"explanation":"先看复议结果，再确定告谁。复议维持的，原机关和复议机关是共同被告；复议改变原行政行为的，复议机关是被告。申请人是提起诉讼的人，不能写成被告。维持和改变两套规则不要互换。","source":"原创练习"},{"id":"bk-law-032","subject":"基本知识","chapter":"法律","stem":"国家监察委员会是：","options":["最高监察机关","国务院的组成部门","最高审判机关","社会团体"],"answer":0,"explanation":"监察委员会是行使国家监察职能的专责机关，由人大产生，对本级人大及其常委会负责。它不是政府的职能部门，也不审理诉讼案件。机构题不要把监察机关答回行政机关或法院。","source":"原创练习"},{"id":"bk-law-033","subject":"基本知识","chapter":"法律","stem":"下列效力排序正确的是：","options":["行政法规高于宪法","宪法、法律、行政法规、地方性法规","地方性法规高于法律","部门规章高于法律"],"answer":1,"explanation":"先看制定机关。宪法最高，全国人大及其常委会制定法律，国务院制定行政法规，地方人大及其常委会制定地方性法规。下位法不得与上位法相抵触。规章冲突还有专门规则，但本题四级用制定机关就能够排序。","source":"原创练习"},{"id":"bk-law-034","subject":"基本知识","chapter":"法律","stem":"侵权责任的一般归责原则是：","options":["一切损害都无过错赔偿","只看损害大小、不看法定义务","过错责任","由受害人自担一切风险"],"answer":2,"explanation":"有损害不一定都赔。一般侵权要看行为人有没有过错。法律明确规定无过错责任或过错推定的，才离开一般原则。高度危险、环境污染、产品缺陷等走特别规则。题干说“一般”，就选过错责任，特别条款优先时再单独适用。","source":"原创练习"},{"id":"bk-law-035","subject":"基本知识","chapter":"法律","stem":"因产品存在缺陷造成他人损害，生产者承担侵权责任的规则是：","options":["受害人必须证明生产者有过错","只有销售者可能承担责任","缺陷产品一律只退货、不赔偿人身损害","不论生产者有无过错，依法都要承担责任"],"answer":3,"explanation":"先看问的是生产者还是销售者。生产者对缺陷产品造成的损害承担无过错责任，受害人要说明缺陷、损害和因果关系，不必再证明生产者有过错。销售者则区分有无过错，不能指明生产者或供货者时也要承担责任。","source":"原创练习"},{"id":"bk-law-036","subject":"基本知识","chapter":"法律","stem":"防卫时误伤了没有实施侵害的路人。对路人的损害，不能直接认定为：","options":["对路人的正当防卫","需要另看是否符合紧急避险等其他条件","打击对象已经不是不法侵害人","可能超过合法行为的界限"],"answer":0,"explanation":"正当防卫的对象只能是正在实施不法侵害的人。路人不是侵害人，不能把对他的损害叫作正当防卫。如果是为了避免正在发生的危险、不得已损害另一合法利益，才转入紧急避险的条件去判断。方法是先锁定打击对象。","source":"原创练习"},{"id":"bk-law-037","subject":"基本知识","chapter":"法律","stem":"行为砸坏的是铁轨上的枕木。这里的犯罪对象应当理解为：","options":["刑法所保护的公共安全关系","被砸坏的枕木","行为人的主观动机","法院后来判处的刑罚"],"answer":1,"explanation":"对象是行为触及的具体人或物，客体是刑法保护的社会关系。枕木是对象；行为危害的公共安全或财产关系才是客体。同一个物体背后的客体还要看行为究竟破坏了什么关系。两个词不能互相替换。","source":"原创练习"},{"id":"bk-law-038","subject":"基本知识","chapter":"法律","stem":"关于行政法规，正确的是：","options":["由国务院各部委制定","就是地方性法规的另一个名称","由国务院制定","可以设定限制人身自由的行政处罚"],"answer":2,"explanation":"行政法规专指国务院制定的规范性文件。部委制定的是部门规章，省、市人大及其常委会制定的是地方性法规。限制人身自由的处罚只能由法律设定，行政法规不能创设。看到“行政”两个字，不能理解成所有行政机关制定的文件都叫行政法规。","source":"原创练习"},{"id":"bk-law-039","subject":"基本知识","chapter":"法律","stem":"从事高度危险作业造成他人损害，受害人请求赔偿时，原则上：","options":["必须证明作业人有故意","只能向法院申请行政处罚","必须先证明自己没有任何损失","不必证明作业人有过错"],"answer":3,"explanation":"高度危险作业造成损害，法律规定的是无过错责任。受害人仍要说明危险作业、损害和因果关系，只是不用证明过错。法律另有不承担责任的情形除外。特别条款优先于一般的过错责任，先看题干是不是点了“高度危险”。","source":"原创练习"},{"id":"bk-law-040","subject":"基本知识","chapter":"法律","stem":"民法自愿原则的边界是：","options":["不得违反法律、行政法规的强制性规定，不得违背公序良俗","当事人约定可以排除一切法律","只要双方签字，损害他人合法权益也有效","口头约定一律无效"],"answer":0,"explanation":"自愿不是想怎样就怎样。意思表示要真实，内容还不能违反法律、行政法规的强制性规定，不能违背公序良俗。恶意串通损害他人合法权益的民事法律行为无效。原则题要看后半句的限制，绝对化的“约定高于一切”可以直接排除。","source":"原创练习"},{"id":"bk-eco-005","subject":"基本知识","chapter":"经济","stem":"商品的使用价值和价值，在属性上的差别是：","options":["使用价值是社会属性，价值是自然属性","使用价值是自然属性，价值是社会属性","两者都只是自然属性","两者都只在交换之后才存在"],"answer":1,"explanation":"使用价值是商品能满足需要的有用性，由物品本身的属性决定，是自然属性。价值是凝结在商品中的抽象人类劳动，只有在商品关系里才表现出来，是社会属性。交换价值是价值的表现形式，不是价值本身。属性题先问“离开社会还能不能单独存在”。","source":"原创练习"},{"id":"bk-eco-006","subject":"基本知识","chapter":"经济","stem":"生产商品的劳动二重性中，形成商品价值的是：","options":["具体劳动","生产资料本身","抽象劳动","商品的使用价值"],"answer":2,"explanation":"具体劳动是不同形式的劳动，生产使用价值。抽象劳动是撇开具体形式的一般人类劳动，形成价值。两边要成对记忆：具体对使用价值，抽象对价值。生产资料转移旧价值，不是“形成”新价值的那一部分劳动。","source":"原创练习"},{"id":"bk-eco-007","subject":"基本知识","chapter":"经济","stem":"决定单位商品价值量的是：","options":["个别生产者实际花费的劳动时间","商品的价格标签","购买者愿意支付的最高价格","生产该商品的社会必要劳动时间"],"answer":3,"explanation":"个别劳动时间只决定这个生产者自己花了多少劳动。商品价值量由社会必要劳动时间决定。个别时间低于社会必要时间，仍按社会必要劳动时间实现价值，生产者就更有优势。价格会偏离价值，所以价格标签不是价值量本身。","source":"原创练习"},{"id":"bk-eco-008","subject":"基本知识","chapter":"经济","stem":"价值规律的表现形式是：","options":["价格受供求影响，围绕价值上下波动","价格永远等于价值","价格只升不降","供求不影响价格"],"answer":0,"explanation":"价值决定价格，供求影响价格。供不应求价格上升，供过于求价格下降，所以价格围绕价值波动，而不是每时每刻等于价值。波动也不是脱离价值无限跑开。看到“永远等于”，就把规律的表现形式说死了。","source":"原创练习"},{"id":"bk-eco-009","subject":"基本知识","chapter":"经济","stem":"关于需求价格弹性，通常正确的是：","options":["生活必需品的弹性通常大于奢侈品","替代品多、非急需的商品，弹性通常更大","所有商品弹性都等于1","价格上升需求量一定同比例上升"],"answer":1,"explanation":"弹性衡量价格变动百分之一时，需求量变动百分之几。生活必需、难替代的商品，需求量反应通常较小。奢侈品和替代品多的商品，消费者更容易转向别处，弹性通常更大。没有一条定律说所有商品弹性都是1。","source":"原创练习"},{"id":"bk-eco-010","subject":"基本知识","chapter":"经济","stem":"其他条件不变时，供给曲线的一般方向是：","options":["价格上升，供给量减少","价格与供给量无关","价格上升，供给量增加","供给量先增后必须降到零"],"answer":2,"explanation":"供给规律与需求规律方向相反。价格上升，生产者通常愿意多供给，曲线向右上方倾斜。需求曲线则一般向右下方。做图题先看问的是供给还是需求，再决定价格和数量是同向还是反向。","source":"原创练习"},{"id":"bk-eco-011","subject":"基本知识","chapter":"经济","stem":"市场均衡价格指的是：","options":["政府宣布的任何价格","生产者的成本价","消费者愿意出的最高价","供给量等于需求量时的价格"],"answer":3,"explanation":"均衡不是成本，也不是最高出价，而是供给量和需求量正好相等时的价格。价格高于均衡，供给量大于需求量，价格趋向回落；低于均衡则出现短缺，价格趋向上升。用供求缺口判断价格往哪边走。","source":"原创练习"},{"id":"bk-eco-012","subject":"基本知识","chapter":"经济","stem":"机会成本指的是：","options":["为了当前选择而放弃的其他选择中价值最高的那一项","已经花掉且收不回的全部账单","所有放弃项的价值相加","会计账本上的折旧"],"answer":0,"explanation":"机会成本看“假如不选这项，最好的另一项值多少”，只取放弃方案里价值最高的一项，不是把所有没选的方案加总。已经花掉且无法收回的是沉没成本。会计成本也不等于机会成本。决策题先列出被放弃的最好替代。","source":"原创练习"},{"id":"bk-eco-013","subject":"基本知识","chapter":"经济","stem":"已经支付且不能退回的报名费，在决定要不要继续参加后续课程时，应当视为：","options":["下一步的边际成本","沉没成本，不应当因为它改变下一步选择","机会成本的全部","必须再支付一次的费用"],"answer":1,"explanation":"沉没成本已经发生、无法收回。继续还是退出，要看以后还要付出的成本和还能得到的收益。报名费不能因为“已经花了”就强迫自己把不合适的课程读完。把沉没成本当成下一步的边际成本，是常见的决策错误。","source":"原创练习"},{"id":"bk-eco-014","subject":"基本知识","chapter":"经济","stem":"连续增加同一种消费时，边际效用通常会：","options":["递增","永远不变","递减","先降后必须变成负数"],"answer":2,"explanation":"边际效用是新增一单位消费带来的额外满足。同一物品连续增加，额外满足通常下降，这就是递减。它不等于总效用马上下降，更没有规定第几单位起一定变成负数。先分清总效用和每一单位新增的效用。","source":"原创练习"},{"id":"bk-eco-015","subject":"基本知识","chapter":"经济","stem":"汽油价格大幅上升后，短期内对燃油汽车需求的常见影响是：","options":["汽车需求上升，因为两者是替代品","汽车供给必然立刻为零","汽油和汽车没有关系","汽车需求下降，因为两者是互补品"],"answer":3,"explanation":"互补品要一起使用。汽油变贵，开车的使用成本上升，燃油汽车的需求可能下降。替代品才是一个涨价、另一个需求上升，例如茶叶涨价后咖啡需求可能增加。先判断两种商品是互补还是替代，再决定需求同向还是反向。","source":"原创练习"},{"id":"bk-eco-016","subject":"基本知识","chapter":"经济","stem":"茶叶价格上升，咖啡需求增加。茶叶和咖啡在这里属于：","options":["替代品","互补品","公共物品","劣等品"],"answer":0,"explanation":"一个商品涨价，消费者转向另一种能满足相近需要的商品，后者需求上升，两者就是替代关系。互补品涨价会让搭配使用的另一种商品需求下降。公共物品看的是排他性和竞争性，本题没有这个信息。","source":"原创练习"},{"id":"bk-eco-017","subject":"基本知识","chapter":"经济","stem":"本国公民在国外取得的劳动收入，应当：","options":["计入本国GDP，不计入GNP","计入本国GNP，不计入本国GDP","两个指标都不计","两个指标都计"],"answer":1,"explanation":"GDP按国土原则，统计本国境内生产的最终产品和服务，不管生产者是不是本国居民。GNP按国民原则，统计本国居民的收入，不管生产发生在境内还是境外。人在国外、收入属于本国居民，进GNP，不进本国GDP。外国公司在本国境内的生产则相反。","source":"原创练习"},{"id":"bk-eco-018","subject":"基本知识","chapter":"经济","stem":"居民消费价格指数（CPI）上升，能够直接说明的是：","options":["每一种商品都涨价了","居民收入一定同步上升","一篮子消费品和服务的价格总水平上升","失业率一定下降"],"answer":2,"explanation":"CPI追踪的是固定篮子的价格总水平。总指数上升，只说明篮子整体更贵，其中仍可以有商品跌价。它不直接等于收入增长，也不直接推出失业率变化。读指数先看它的篮子和“总水平”三个字，不要替换成每一种商品。","source":"原创练习"},{"id":"bk-eco-019","subject":"基本知识","chapter":"经济","stem":"通货紧缩的典型表现是：","options":["物价涨幅比去年小一些，但仍在上涨","货币立刻退出流通","失业率一定降到零","物价总水平持续下降"],"answer":3,"explanation":"通货膨胀是物价总水平持续上涨，通货紧缩是物价总水平持续下降，常和需求不足联系在一起。涨幅收窄但价格仍在涨，只是通胀放缓，不是紧缩。名称里的“缩”要对应总水平下降，而不是上涨速度变慢。","source":"原创练习"},{"id":"bk-eco-020","subject":"基本知识","chapter":"经济","stem":"下列属于财政政策工具的是：","options":["增加政府购买支出","提高存款准备金率","公开市场卖出国债以回笼货币","提高再贴现率"],"answer":0,"explanation":"财政政策由政府的收支决定，工具包括税收、政府购买、转移支付和国债发行。存款准备金、再贴现、公开市场操作是中央银行的货币政策工具。先看实施主体是财政部门还是中央银行，再选工具。","source":"原创练习"},{"id":"bk-eco-021","subject":"基本知识","chapter":"经济","stem":"中央银行上调存款准备金率，通常属于：","options":["扩张性货币政策","紧缩性货币政策","扩张性财政政策","价格上限政策"],"answer":1,"explanation":"存款准备金率上调后，银行必须把更多存款交给中央银行，可贷资金减少，货币信贷通常收缩，所以是紧缩。下调才是放松。它不是政府加减税，也不是直接规定商品价格。方向题先写“可贷资金变多还是变少”。","source":"原创练习"},{"id":"bk-eco-022","subject":"基本知识","chapter":"经济","stem":"总需求不足、需要政府拉动需求时，扩张性财政政策表现为：","options":["增税并削减支出","提高存款准备金率","减税或增加政府支出","规定所有商品价格上涨"],"answer":2,"explanation":"扩张是让总需求变大，财政上可以减税，让居民和企业留下更多收入，或者直接增加政府支出。增税、减支是紧缩方向。存款准备金率是货币政策，不因为目标相同就改名成财政政策。","source":"原创练习"},{"id":"bk-eco-023","subject":"基本知识","chapter":"经济","stem":"下列哪一项属于市场失灵的典型情形？","options":["完全竞争下价格等于边际成本","消费者按自己的预算购买私人物品","供给等于需求","工厂排污却不承担外部成本"],"answer":3,"explanation":"市场失灵常见于垄断、外部性、公共物品和信息不对称。排污若只由附近居民承担损失，私人成本低于社会成本，市场产量会偏多，这是负外部性。完全竞争达到均衡、供求相等，本身不是失灵。先看有没有成本或收益落在交易双方之外。","source":"原创练习"},{"id":"bk-eco-024","subject":"基本知识","chapter":"经济","stem":"公共物品区别于私人物品的两个特征是：","options":["非排他并且非竞争","排他并且竞争","只能由政府人员消费","价格一定为零"],"answer":0,"explanation":"非排他是很难阻止不付费的人使用，非竞争是增加一个人使用并不明显减少别人的使用。国防常被当作接近这两个特征的例子。私人物品又排他又竞争。价格为零不是定义，收费与否要另看，不能用免费代替非排他。","source":"原创练习"},{"id":"bk-eco-025","subject":"基本知识","chapter":"经济","stem":"负外部性存在时，如果不加纠正，市场供给通常会：","options":["少于社会最合适的数量","多于社会最合适的数量","正好等于社会最合适的数量","立刻消失"],"answer":1,"explanation":"负外部性中，生产者没有支付全部社会成本，私人觉得生产很划算，产量就会偏多。纠正的思路是把外部成本内部化，例如征税或设定排放规则。正外部性则相反，私人收益小于社会收益，供给容易偏少。先判断外部影响是成本还是收益。","source":"原创练习"},{"id":"bk-eco-026","subject":"基本知识","chapter":"经济","stem":"恩格尔系数下降，通常说明：","options":["收入差距扩大","物价总水平一定为负","食品支出占消费支出的比重下降，生活水平往往提高","食品支出的绝对金额必须下降"],"answer":2,"explanation":"恩格尔系数是食品支出除以消费支出。比重下降，通常被用来说明消费结构升级、生活水平提高。它不是基尼系数，不直接衡量收入差距，也不要求食品花费的绝对金额下降。比较时还要注意统计口径是否一致。","source":"原创练习"},{"id":"bk-eco-027","subject":"基本知识","chapter":"经济","stem":"基尼系数从0.30变为0.45，直接表示：","options":["GDP增长了15%","物价上涨15%","失业率下降","收入差距扩大"],"answer":3,"explanation":"基尼系数衡量收入分配差距。0是绝对平均，1是绝对不平均，数值变大表示差距扩大。它不是增长率，不能把0.15的差值当成GDP或物价涨了15%。不同指标的单位和含义不能直接平移。","source":"原创练习"},{"id":"bk-eco-028","subject":"基本知识","chapter":"经济","stem":"甲生产1米布要2小时、1升酒要4小时；乙生产1米布要6小时、1升酒要6小时。按比较优势，乙应专业化生产：","options":["酒，因为乙产酒的机会成本更低","布，因为乙生产布的绝对时间更短","两种都生产，绝对优势全在乙","两种都不生产"],"answer":0,"explanation":"先算机会成本，不看谁的绝对时间更短。乙生产1升酒放弃1米布，甲生产1升酒放弃2米布，乙产酒的机会成本更低。甲两种产品用时都更少，那是绝对优势，不能直接决定分工。比较优势看的是各自放弃了多少。","source":"原创练习"},{"id":"bk-eco-029","subject":"基本知识","chapter":"经济","stem":"建筑业在三次产业划分中属于：","options":["第一产业","第二产业","第三产业","不计入任何产业"],"answer":1,"explanation":"第一产业主要是农业，包括林牧渔业。第二产业是工业和建筑业。第三产业是服务业。建筑业容易被误放到服务业里，划分时看它是否从事物质生产建设。先背三类的代表，再把边界行业归位。","source":"原创练习"},{"id":"bk-eco-030","subject":"基本知识","chapter":"经济","stem":"我国社会主义初级阶段分配制度的主体是：","options":["平均分配","只按资本分配","按劳分配","只按需要分配"],"answer":2,"explanation":"分配制度是按劳分配为主体、多种分配方式并存。劳动以外的合法要素收入可以存在，但不能因此把主体改成只按资本。平均分配也不是按劳分配。题干问“主体”，就找占主体地位的那一种，不把并存的其他方式写成主体。","source":"原创练习"},{"id":"bk-eco-031","subject":"基本知识","chapter":"经济","stem":"其他条件不变，本币升值通常会：","options":["使进口商品变贵","同时使出口和进口都变为不可能","不改变任何相对价格","使出口商品以外币计价变贵，抑制出口"],"answer":3,"explanation":"本币升值后，同样的外国货币换到的本币变少，本国商品用外币标价就变贵，出口通常受抑制；外国商品用本币标价变便宜，进口通常增加。不要把进出口两个方向写成同一种变化。","source":"原创练习"},{"id":"bk-eco-032","subject":"基本知识","chapter":"经济","stem":"比较不同年份实际生产了多少，应当优先看：","options":["实际GDP，因为它剔除了价格变动","名义GDP，因为它包含涨价","CPI本身","基尼系数"],"answer":0,"explanation":"名义GDP按当年价格计算，涨价也会让数字变大。实际GDP用不变价格，把价格因素剥掉，才能比较产量。CPI是价格总水平，基尼系数是收入差距，都不是产量指标。跨年比生产，先问数字里有没有价格。","source":"原创练习"},{"id":"bk-eco-033","subject":"基本知识","chapter":"经济","stem":"劳动者正常更换工作、短期内尚未找到下一份工作。这种失业主要是：","options":["结构性失业","摩擦性失业","周期性失业","自愿退出劳动市场后不再找工作"],"answer":1,"explanation":"摩擦性失业来自劳动力市场的正常流动和搜寻。结构性失业是技能或地区与岗位不匹配，不是短时间换工作就能对上。周期性失业来自经济衰退、总需求不足。已经不找工作的人，不再计入失业。先看原因是搜寻、错配还是总需求。","source":"原创练习"},{"id":"bk-eco-034","subject":"基本知识","chapter":"经济","stem":"政府把价格上限定在均衡价格之下，市场上容易出现：","options":["过剩","供给和需求仍然相等","短缺","价格继续自由升到均衡以上"],"answer":2,"explanation":"价格上限是最高限价。它低于均衡价格时，需求量大于供给量，出现短缺。价格下限如果高于均衡，才会出现过剩。先画均衡，再看管制价格在均衡的上方还是下方，最后决定积压的是货物还是买不到的人。","source":"原创练习"},{"id":"bk-eco-035","subject":"基本知识","chapter":"经济","stem":"用支出法计算GDP时，净出口指的是：","options":["出口总额","进口总额","出口加上进口","出口减去进口"],"answer":3,"explanation":"支出法看消费、投资和净出口。净出口等于出口减进口。只写出口会把外国生产、由本国购买的部分重复或漏处理。名称里的“净”就是相减。顺差是净出口为正，逆差是净出口为负。","source":"原创练习"},{"id":"bk-eco-036","subject":"基本知识","chapter":"经济","stem":"名义利率为5%，通货膨胀率为3%。近似的实际利率是：","options":["2%","8%","15%","5%"],"answer":0,"explanation":"实际利率大约等于名义利率减去通货膨胀率，5%减3%等于2%。它表示扣除物价上涨后，储蓄或借贷真正增加的购买力。把两个百分数相加，得到的是另一回事。费雪关系用减法，不用乘法。","source":"原创练习"},{"id":"bk-eco-037","subject":"基本知识","chapter":"经济","stem":"垄断与充分竞争相比，通常会出现：","options":["产量更高、价格更低","产量更低、价格更高","价格一定等于零","供给无限大"],"answer":1,"explanation":"垄断厂商面对向下的需求曲线，会把产量限制在边际收益等于边际成本的位置，这个产量通常低于竞争产量，价格则高于竞争价格。这是市场失灵里垄断这一支的典型结果。不要把垄断理解成产量越大价格越低。","source":"原创练习"},{"id":"bk-eco-038","subject":"基本知识","chapter":"经济","stem":"基础研究常常让全社会受益，研究者自己只能获得其中一部分。若不补偿，市场供给容易：","options":["偏多，因为存在负外部性","刚好最优","偏少，因为存在正外部性","与收益无关"],"answer":2,"explanation":"社会收益大于私人收益时，是正外部性。研究者只按自己能拿到的收益决定投入，供给就会少于社会需要的数量。负外部性才是供给偏多。补贴、公共资助等办法，是在补上私人没拿到的那部分社会收益。","source":"原创练习"},{"id":"bk-eco-039","subject":"基本知识","chapter":"经济","stem":"保护价把农产品最低价格定在均衡价格之上，最可能出现：","options":["市场上完全买不到该农产品","价格会自动跌破保护价","需求和供给同时消失","农民卖不完，形成过剩"],"answer":3,"explanation":"最低限价高于均衡时，生产者愿意多供给，消费者愿意少购买，差额就是过剩。政府若要维持这个价格，往往还要考虑收购或限制产量。它和最高限价造成的短缺方向相反。先确认管制价格是地板还是天花板。","source":"原创练习"},{"id":"bk-eco-040","subject":"基本知识","chapter":"经济","stem":"今年出口额大于进口额。这个贸易状况称为：","options":["贸易顺差","贸易逆差","贸易平衡","资本外逃"],"answer":0,"explanation":"货物贸易中，出口大于进口是顺差，进口大于出口是逆差，两者相等是平衡。资本外逃说的是资本流动，不是进出口差额。先写出口减进口的符号，正数对应顺差。","source":"原创练习"},{"id":"bk-hum-005","subject":"基本知识","chapter":"人文与社会","stem":"“五经”不包括：","options":["《诗经》","《论语》","《尚书》","《周易》"],"answer":1,"explanation":"五经是《诗经》《尚书》《礼记》《周易》《春秋》。四书是《大学》《中庸》《论语》《孟子》。看到《论语》，先把它放进四书，不要因为同样经典就放进五经。数字清单题先默写对应的那一套。","source":"原创练习"},{"id":"bk-hum-006","subject":"基本知识","chapter":"人文与社会","stem":"被称为“诗圣”的唐代诗人是：","options":["李白","白居易","杜甫","王维"],"answer":2,"explanation":"诗仙是李白，诗圣是杜甫。两个称号都要配对，不能只记得“唐代大诗人”。白居易、王维也很重要，但没有这两个固定称号。称号题先把最容易互换的两项写在一起再选。","source":"原创练习"},{"id":"bk-hum-007","subject":"基本知识","chapter":"人文与社会","stem":"苏轼的词，文学史上通常归入：","options":["婉约派","宫体诗","新乐府","豪放派"],"answer":3,"explanation":"宋词常按风格分成豪放和婉约。苏轼、辛弃疾是豪放派的代表，李清照、柳永通常归入婉约。宫体诗、新乐府是别的诗歌现象，不是这道题的词派。先看作家，再对风格，不要用时代代替流派。","source":"原创练习"},{"id":"bk-hum-008","subject":"基本知识","chapter":"人文与社会","stem":"《史记》在体裁上最准确的定位是：","options":["我国第一部纪传体通史","编年体断代史","第一部诗歌总集","章回小说"],"answer":0,"explanation":"《史记》由司马迁撰写，以人物传记为中心，贯通古今，所以是纪传体通史，并且通常称为第一部。《诗经》才是第一部诗歌总集。体裁题要同时看写法和对时间的覆盖范围。","source":"原创练习"},{"id":"bk-hum-009","subject":"基本知识","chapter":"人文与社会","stem":"《资治通鉴》的体裁是：","options":["纪传体","编年体","语录体","书信体"],"answer":1,"explanation":"司马光主持编成的《资治通鉴》按年月记事，是编年体通史的代表。纪传体的代表是《史记》。不要因为两部都是史书，就把体裁写成同一个。看它以人物为纲，还是以时间为纲。","source":"原创练习"},{"id":"bk-hum-010","subject":"基本知识","chapter":"人文与社会","stem":"《红楼梦》前八十回的作者，一般认为是：","options":["罗贯中","施耐庵","曹雪芹","吴承恩"],"answer":2,"explanation":"四大名著要和作者分开记：罗贯中与《三国演义》，施耐庵与《水浒传》，吴承恩与《西游记》，曹雪芹与《红楼梦》前八十回。后四十回在流传中另有续写争议，题干限定前八十回，就选曹雪芹。","source":"原创练习"},{"id":"bk-hum-011","subject":"基本知识","chapter":"人文与社会","stem":"秦完成统一、建立起中央集权王朝，常用的年份是：","options":["公元前770年","公元前475年","公元221年","公元前221年"],"answer":3,"explanation":"公元前221年，秦灭六国，秦王嬴政称始皇帝。公元前770年和前475年分别常被用来标记春秋、战国的开端，那时还没有统一。公元221年已经晚了四百多年，公元前和公元不能掉一个“前”字。","source":"原创练习"},{"id":"bk-hum-012","subject":"基本知识","chapter":"人文与社会","stem":"科举制度形成的标志，通常追溯到：","options":["隋代创立进士科","汉代察举制","唐代开始有诗","宋代发明活字印刷"],"answer":0,"explanation":"察举是荐举人才，不是分科考试。隋代创立进士科，通常被看作科举制度形成的标志。唐代是这个制度发展完备的时期，不是起点。印刷术解决的是书籍传播，不是选官制度的起点。","source":"原创练习"},{"id":"bk-hum-013","subject":"基本知识","chapter":"人文与社会","stem":"郑和首次下西洋发生在：","options":["唐朝","明朝永乐年间","宋朝","清朝康熙年间"],"answer":1,"explanation":"1405年郑和首次出航，正处于明成祖永乐年间。把时间线放在明朝前期，就可以排除唐、宋和清朝。下西洋是远航朝贡与贸易往来，不要和汉代陆上丝绸之路的开通混成同一次事件。","source":"原创练习"},{"id":"bk-hum-014","subject":"基本知识","chapter":"人文与社会","stem":"古代陆上丝绸之路的东方起点，通常是指：","options":["泉州","广州","长安","扬州"],"answer":2,"explanation":"陆上丝绸之路从长安（今西安）向西，连接中亚和更远的地区。泉州、广州、扬州更多和海上贸易联系在一起。题干里的“陆上”和“起点”两个限制一起用，才不会选成港口城市。","source":"原创练习"},{"id":"bk-hum-015","subject":"基本知识","chapter":"人文与社会","stem":"长江的发源地位于：","options":["巴颜喀拉山","长白山","武夷山","唐古拉山"],"answer":3,"explanation":"长江发源于青藏高原唐古拉山一带，黄河发源于巴颜喀拉山。两山都在青海方向，最容易记反。长白山、武夷山不在江河源区。源头题把长江、黄河成对记忆，不要只记“都在西部”。","source":"原创练习"},{"id":"bk-hum-016","subject":"基本知识","chapter":"人文与社会","stem":"我国地势的总体特征是：","options":["西高东低，呈三级阶梯","东高西低，呈三级阶梯","南高北低，没有阶梯","中部高、四周都是平原"],"answer":0,"explanation":"西高东低决定了大江大河多向东流。地势分成三级阶梯，青藏高原在第一级。说成东高西低，河流方向就解释不通。地势题可以用水往哪边流来检验。","source":"原创练习"},{"id":"bk-hum-017","subject":"基本知识","chapter":"人文与社会","stem":"我国第一大岛是：","options":["海南岛","台湾岛","崇明岛","舟山岛"],"answer":1,"explanation":"按面积，台湾岛是第一大岛，海南岛是第二大岛。崇明岛是河口冲积岛，舟山岛是群岛中的大岛，都不是全国第一。岛屿题先排面积顺序，再看它是大陆岛还是冲积岛。","source":"原创练习"},{"id":"bk-hum-018","subject":"基本知识","chapter":"人文与社会","stem":"在北半球，昼夜长短相等的节气是：","options":["夏至","冬至","春分","大暑"],"answer":2,"explanation":"春分和秋分，太阳直射赤道，全球昼夜基本等长。夏至北半球昼最长，冬至北半球昼最短。节气题先看太阳直射在赤道还是回归线。只记“夏至很热”，回答不了昼夜长短。","source":"原创练习"},{"id":"bk-hum-019","subject":"基本知识","chapter":"人文与社会","stem":"儒家学说最核心的道德范畴是：","options":["法术势","道法自然","兼爱非攻","仁"],"answer":3,"explanation":"儒家重仁和礼，核心常概括为仁。道家强调道法自然。法家讨论法、术、势。墨家主张兼爱、非攻。学派题先找每个学派不能替换的关键词，再看题干点的是哪一家。","source":"原创练习"},{"id":"bk-hum-020","subject":"基本知识","chapter":"人文与社会","stem":"目前所见最早的成熟汉字是：","options":["甲骨文","小篆","隶书","楷书"],"answer":0,"explanation":"商代甲骨文已经是成熟汉字。其后大致经历金文、小篆、隶书、楷书。小篆是秦统一后的标准字体，不是最早。演变题按时间排队，最早和最规范不是同一个问题。","source":"原创练习"},{"id":"bk-hum-021","subject":"基本知识","chapter":"人文与社会","stem":"汉字中数量最多的构造类型是：","options":["象形","形声","指事","会意"],"answer":1,"explanation":"六书里，象形、指事、会意、形声是造字方法。形声字一边表意、一边表音，便于组合，所以数量最多。看见一个字有偏旁又有声旁，优先想到形声，但题干问的是总体数量，不是某一个字。","source":"原创练习"},{"id":"bk-hum-022","subject":"基本知识","chapter":"人文与社会","stem":"京剧的四大行当是：","options":["诗、书、礼、乐","琴、棋、书、画","生、旦、净、丑","笔、墨、纸、砚"],"answer":2,"explanation":"行当是角色类型：生、旦、净、丑。诗书礼乐是教化内容，琴棋书画是文娱修养，笔墨纸砚是文具。题干出现“行当”，就限定在戏曲角色，不要选成其他四字组合。","source":"原创练习"},{"id":"bk-hum-023","subject":"基本知识","chapter":"人文与社会","stem":"世界三大宗教是：","options":["道教、儒教、佛教","基督教、道教、印度教","伊斯兰教、神道教、锡克教","基督教、伊斯兰教、佛教"],"answer":3,"explanation":"通常说的世界三大宗教是基督教、伊斯兰教、佛教，强调的是世界范围的广泛传播。道教、儒教是中国传统思想文化，不能因为熟悉就替换进这三项。范围词“世界”决定了清单。","source":"原创练习"},{"id":"bk-hum-024","subject":"基本知识","chapter":"人文与社会","stem":"文艺复兴的核心思潮是：","options":["人文主义","神权至上","封闭自守","取消一切古典文化"],"answer":0,"explanation":"人文主义把关注点从单纯的神权拉回人的价值和现世生活，并重新学习古典文化。它不是取消古典，也不是封闭。思想史题先找这场运动要抬高什么，再排除与之相反的选项。","source":"原创练习"},{"id":"bk-hum-025","subject":"基本知识","chapter":"人文与社会","stem":"第一次世界大战的起止年份是：","options":["1939—1945年","1914—1918年","1840—1842年","1894—1895年"],"answer":1,"explanation":"1914年战争爆发，1918年结束。1939年至1945年是第二次世界大战。1840年前后是鸦片战争，1894年是甲午战争。世纪和序号一起看，一战在二十世纪初，不要和二战对调。","source":"原创练习"},{"id":"bk-hum-026","subject":"基本知识","chapter":"人文与社会","stem":"《联合国宪章》生效、联合国正式成立的年份是：","options":["1919年","1949年","1945年","1955年"],"answer":2,"explanation":"1945年10月24日宪章生效，这一天后来成为联合国日。1919年是国际联盟的时间。1949年是中华人民共和国成立。把全球组织的年份和本国政权的年份分开记。","source":"原创练习"},{"id":"bk-hum-027","subject":"基本知识","chapter":"人文与社会","stem":"我国省级行政区的现行数目是：","options":["28个","32个","36个","34个"],"answer":3,"explanation":"23个省、5个自治区、4个直辖市、2个特别行政区，加起来是34个。省的数目包含台湾。少算特别行政区会得到32，少算直辖市或自治区也会偏离。分类相加，比直接背总数更不容易错。","source":"原创练习"},{"id":"bk-hum-028","subject":"基本知识","chapter":"人文与社会","stem":"我国南方与北方的地理分界，大致是：","options":["秦岭—淮河一线","长江一线","黄河一线","南岭一线"],"answer":0,"explanation":"秦岭—淮河一线对应亚热带与暖温带、水田与旱地等多项差别，是常用的南北分界。长江、黄河是重要河流，但不是这条综合分界线本身。分界题看的是一组地理差异叠在哪里，不是只看一条河。","source":"原创练习"},{"id":"bk-hum-029","subject":"基本知识","chapter":"人文与社会","stem":"我国最大的咸水湖是：","options":["鄱阳湖","青海湖","洞庭湖","太湖"],"answer":1,"explanation":"青海湖是最大咸水湖，鄱阳湖是最大淡水湖。洞庭湖、太湖都是淡水湖。咸和淡先分开，再比面积。只记得“青海有湖”还不够，要把它和鄱阳湖的属性对上。","source":"原创练习"},{"id":"bk-hum-030","subject":"基本知识","chapter":"人文与社会","stem":"描述我国人口东南密、西北疏的分界线是：","options":["秦岭—淮河线","京杭运河","胡焕庸线","北回归线"],"answer":2,"explanation":"胡焕庸线从黑龙江黑河到云南腾冲，线的东南侧集中了绝大部分人口。秦岭—淮河是南北地理分界，不是人口分界。线的两端城市记准，才不会和气候分界互换。","source":"原创练习"},{"id":"bk-hum-031","subject":"基本知识","chapter":"人文与社会","stem":"莫高窟位于：","options":["山西大同","河南洛阳","陕西西安","甘肃敦煌"],"answer":3,"explanation":"莫高窟在甘肃敦煌，是石窟艺术的代表。云冈石窟在山西大同，龙门石窟在河南洛阳。三处石窟要和省份绑定。只回答“在北方”区分不了选项。","source":"原创练习"},{"id":"bk-hum-032","subject":"基本知识","chapter":"人文与社会","stem":"社会化指的是：","options":["个人学习规范、掌握技能并形成社会角色的过程","把所有财产收归国有","人口从农村搬到城市","国家建立外交关系"],"answer":0,"explanation":"社会化是个人成为社会成员的过程，包括学习语言、规范和角色。它不是所有制改造，也不是城市化或外交。学科词汇要回到定义里的主语：这里的主语是个人如何进入社会。","source":"原创练习"},{"id":"bk-hum-033","subject":"基本知识","chapter":"人文与社会","stem":"家庭这类规模小、关系密切、面对面交往的群体，属于：","options":["次级群体","初级群体","正式科层组织","虚拟社区"],"answer":1,"explanation":"初级群体关系亲密、感情色彩浓，家庭是典型。次级群体为了特定目标组成，关系更正式，例如机关里的科室。分类时看交往是不是直接、情感是不是首要，而不是只看人数。","source":"原创练习"},{"id":"bk-hum-034","subject":"基本知识","chapter":"人文与社会","stem":"一个人同时承担的两种角色提出了互相矛盾的要求。这是：","options":["角色一致","社会流动","角色冲突","文化冲击"],"answer":2,"explanation":"角色冲突的关键是同一人身上的不同角色要求打架，例如值班职责和回家照顾家人的要求撞在一起。社会流动是地位变化，文化冲击是进入另一种文化后的不适应。先看矛盾发生在角色之间，还是发生在地区或文化之间。","source":"原创练习"},{"id":"bk-hum-035","subject":"基本知识","chapter":"人文与社会","stem":"法律规范与道德规范最主要的区别是：","options":["法律没有约束力","道德全部由法院判决","两者完全不能同时调整同一行为","法律由国家强制力保证实施"],"answer":3,"explanation":"法律以国家强制力为后盾，道德主要依靠舆论、习惯和内心信念。同一件事可以既受道德评价又受法律调整，所以不是互相排斥。道德也不会全部变成法院判决。比较规范时，先问靠什么力量实施。","source":"原创练习"},{"id":"bk-hum-036","subject":"基本知识","chapter":"人文与社会","stem":"2021年修改后的人口与计划生育法明确规定，一对夫妻可以生育：","options":["三个子女","一个子女","两个子女","不限制也不再规定子女数"],"answer":0,"explanation":"这道题问的是2021年那次修改写明的内容，不是更早的独生子女政策。修改后的法律规定一对夫妻可以生育三个子女，并配套支持措施。做政策年份题，先把题干里的年份和那一版条文对齐，不要用旧政策回答新条文。","source":"原创练习"},{"id":"bk-hum-037","subject":"基本知识","chapter":"人文与社会","stem":"我国面积最大的平原是：","options":["华北平原","东北平原","长江中下游平原","成都平原"],"answer":1,"explanation":"东北平原面积最大，华北平原、长江中下游平原次之。成都平原是西部重要平原，但不是全国最大。平原题先排面积，再记它们各自对应的地形区，避免用“最重要”代替“最大”。","source":"原创练习"},{"id":"bk-hum-038","subject":"基本知识","chapter":"人文与社会","stem":"有“世界屋脊”之称的是：","options":["内蒙古高原","云贵高原","青藏高原","黄土高原"],"answer":2,"explanation":"青藏高原平均海拔最高，所以被称为世界屋脊。黄土高原的特征是黄土覆盖和水土流失，云贵高原多喀斯特地貌，内蒙古高原较平坦。称号题要和平均海拔这个依据连在一起。","source":"原创练习"},{"id":"bk-hum-039","subject":"基本知识","chapter":"人文与社会","stem":"黄河最终注入：","options":["东海","南海","黄海","渤海"],"answer":3,"explanation":"黄河向东注入渤海，长江注入东海。两河的入海海域不要对调。看河流从哪里入海，比只记“都向东流”更具体。题干如果换成长江，答案就要改到东海。","source":"原创练习"},{"id":"bk-hum-040","subject":"基本知识","chapter":"人文与社会","stem":"汉字字体演变中，排在小篆之后、楷书之前的是：","options":["隶书","甲骨文","金文","行书"],"answer":0,"explanation":"常见顺序是甲骨文、金文、小篆、隶书、楷书。隶书上承小篆、下启楷书。行书是楷书之后在书写中形成的字体，不是小篆和楷书之间的那一环。排序题先写出整条链，再看空位的前后邻居。","source":"原创练习"},{"id":"bk-sci-005","subject":"基本知识","chapter":"科学技术","stem":"宇航员在没有空气的月球表面面对面说话，对方听不见。主要原因是：","options":["月球上没有光","声波不能在真空中传播","声音只能沿直线在金属中传播","月球重力太小把声音吸走了"],"answer":1,"explanation":"声音靠介质振动传播。真空里没有空气这种介质，声波无法传过去。光可以在真空中传播，所以“没有光”不是原因。重力影响物体受力，不是把声音吸走。介质题先问：振动靠什么传递。","source":"原创练习"},{"id":"bk-sci-006","subject":"基本知识","chapter":"科学技术","stem":"牛顿第一定律主要说明：","options":["力是维持运动的原因","加速度越大质量越大","物体不受力或合外力为零时，保持静止或匀速直线运动","作用力与反作用力作用在同一物体上"],"answer":2,"explanation":"惯性定律说的是运动状态不需要力来“维持”，力是改变运动状态的原因。合外力为零时，静止的继续静止，运动的继续匀速直线。质量衡量惯性大小，不是加速度。作用力与反作用力作用在两个物体上，那是第三定律。","source":"原创练习"},{"id":"bk-sci-007","subject":"基本知识","chapter":"科学技术","stem":"关于惯性，正确的是：","options":["速度越大，惯性一定越大","只有静止物体才有惯性","惯性就是速度","质量越大，惯性越大"],"answer":3,"explanation":"惯性是保持原有运动状态的性质，大小只看质量，不看速度，也不看物体当时是静是动。速度大只说明状态本身，不增加惯性。把惯性和速度画等号，是这道题最常见的错法。","source":"原创练习"},{"id":"bk-sci-008","subject":"基本知识","chapter":"科学技术","stem":"书对桌面的压力和桌面对书的支持力，这两个力：","options":["是一对作用力与反作用力，作用在两个物体上","是作用在书上的一对平衡力","可以合成后使书的质量消失","大小不一定相等"],"answer":0,"explanation":"作用力与反作用力大小相等、方向相反、作用在同一直线上，但分别作用在两个物体上，不能放在同一个物体上抵消。书受到的重力和支持力才是作用在书上的一对平衡力。先找出每个力的受力物体。","source":"原创练习"},{"id":"bk-sci-009","subject":"基本知识","chapter":"科学技术","stem":"第一类永动机不可能制成，因为它违背：","options":["只有杠杆原理","能量守恒定律","欧姆定律","质量守恒定律以外的一切规律"],"answer":1,"explanation":"第一类永动机想不消耗能量就持续对外做功，违背能量守恒。能量可以从一种形式变成另一种，但不能凭空产生或消失。杠杆、电路规律解释不了“不消耗能量还持续输出”。判断永动机，先看它想逃过哪一条守恒。","source":"原创练习"},{"id":"bk-sci-010","subject":"基本知识","chapter":"科学技术","stem":"一个杠杆的动力臂大于阻力臂。使用它的特点是：","options":["费力，且距离也更短","既省力又省距离","省力，但动力移动的距离更长","不能平衡"],"answer":2,"explanation":"平衡条件是动力乘动力臂等于阻力乘阻力臂。动力臂更长，动力就可以更小，所以省力。功不会因此变少，力小了，沿力的方向移动的距离就要更长。既省力又省距离不符合这个关系。","source":"原创练习"},{"id":"bk-sci-011","subject":"基本知识","chapter":"科学技术","stem":"用凸透镜做照相机镜头时，物距大于二倍焦距，成的像是：","options":["正立、放大的虚像","倒立、放大的实像","正立、缩小的实像","倒立、缩小的实像"],"answer":3,"explanation":"凸透镜按物距分区：大于二倍焦距，成倒立缩小实像，照相机用这一区；在一倍和二倍焦距之间，成倒立放大实像；小于焦距，成正立放大虚像，那是放大镜。先量物距是焦距的几倍，再选像的性质。","source":"原创练习"},{"id":"bk-sci-012","subject":"基本知识","chapter":"科学技术","stem":"金属导线能够导电，主要是因为内部有：","options":["可以自由移动的电子","固定不动的原子核单独导电","大量静止的中子","完全没有电荷"],"answer":0,"explanation":"导体里有大量可自由移动的电荷。金属中是自由电子在电场作用下定向移动形成电流。原子核质量大，不会随电流一起漂移。绝缘体不容易导电，是因为几乎没有自由移动的电荷。","source":"原创练习"},{"id":"bk-sci-013","subject":"基本知识","chapter":"科学技术","stem":"一段电路两端电压是6伏，电阻是3欧。通过的电流是：","options":["0.5安","2安","3安","18安"],"answer":1,"explanation":"欧姆定律写成电流等于电压除以电阻。6伏除以3欧等于2安。18安是把电压和电阻相乘，0.5安是把电阻除以电压，都把公式倒了。先写I=U/R，再代入，单位保持伏、欧、安。","source":"原创练习"},{"id":"bk-sci-014","subject":"基本知识","chapter":"科学技术","stem":"两个电阻串联后接到电源上。正确的是：","options":["两个电阻两端的电压一定相等","干路电流等于两条支路电流之和","通过两个电阻的电流一定相等","电阻越大电流越大"],"answer":2,"explanation":"串联只有一条路径，电流处处相等，总电压等于各段电压之和，电压按电阻分配。并联才是各支路电压相等、干路电流等于支路电流之和。先看电路是一条路还是分叉，再选电流和电压哪个相等。","source":"原创练习"},{"id":"bk-sci-015","subject":"基本知识","chapter":"科学技术","stem":"紫色石蕊试液滴进酸性溶液，颜色变为：","options":["蓝色","无色","绿色","红色"],"answer":3,"explanation":"石蕊遇酸变红，遇碱变蓝，中性时保持紫色。只要先记住“酸红碱蓝”这一对，就不容易把两端写反。它不是酸碱指示剂里的酚酞，酚酞遇碱变红、遇酸基本无色。看清试剂名称再选颜色。","source":"原创练习"},{"id":"bk-sci-016","subject":"基本知识","chapter":"科学技术","stem":"燃烧需要的三个条件是可燃物、与氧气接触以及：","options":["温度达到着火点","必须有水","必须是金属","必须在密闭容器中"],"answer":0,"explanation":"三要素是可燃物、氧气（或空气）和温度达到着火点，缺一不可。灭火就是破坏其中至少一个条件，例如隔绝氧气或降温到着火点以下。水可以用来降温，但不是燃烧本身的必要条件。","source":"原创练习"},{"id":"bk-sci-017","subject":"基本知识","chapter":"科学技术","stem":"绿色植物光合作用的主要产物是有机物和：","options":["二氧化碳","氧气","氮气","氢气"],"answer":1,"explanation":"光合作用在叶绿体中利用光能，把二氧化碳和水合成有机物，并释放氧气。呼吸作用则消耗有机物、释放能量，有氧呼吸还消耗氧气。两个过程的气体方向相反，题干点名光合作用，就选释放氧气。","source":"原创练习"},{"id":"bk-sci-018","subject":"基本知识","chapter":"科学技术","stem":"除病毒等少数类型外，生物体结构和功能的基本单位是：","options":["器官","组织","细胞","生态系统"],"answer":2,"explanation":"细胞是结构和功能的基本单位。组织由细胞组成，器官由组织组成，生态系统还包含无机环境。病毒没有细胞结构，所以表述里要留出这个例外。层次题从最小的生命结构单元往上排。","source":"原创练习"},{"id":"bk-sci-019","subject":"基本知识","chapter":"科学技术","stem":"关于遗传物质，表述准确的是：","options":["所有生物的遗传物质都是DNA","蛋白质是主要遗传物质","脂肪携带基因","细胞生物的遗传物质是DNA，部分病毒以RNA为遗传物质"],"answer":3,"explanation":"细胞生物的遗传物质是DNA。多数生物如此，但部分病毒只含RNA，以RNA为遗传物质。所以不能说“一切生物毫无例外都是DNA”。蛋白质执行功能，不是遗传信息的主要载体。例外出现时，绝对化选项先排除。","source":"原创练习"},{"id":"bk-sci-020","subject":"基本知识","chapter":"科学技术","stem":"基因是：","options":["有遗传效应的DNA片段","任意一段蛋白质","一条染色体的别名","细胞壁的成分"],"answer":0,"explanation":"基因是有遗传效应的DNA片段，能够决定一定的遗传信息。不是DNA上的随便一段都叫基因，也不是蛋白质或细胞壁。染色体由DNA和蛋白质组成，一条染色体上有许多基因。范围从大到小是染色体、DNA、基因。","source":"原创练习"},{"id":"bk-sci-021","subject":"基本知识","chapter":"科学技术","stem":"疫苗能够预防传染病，主要是因为：","options":["它直接代替抗生素杀死所有病毒","它使机体预先产生免疫记忆","它降低遗传物质的数量","它使白细胞永久消失"],"answer":1,"explanation":"疫苗把减毒、灭活或特定成分引入体内，刺激免疫系统产生记忆。再次遇到相应病原体时，免疫反应更快。抗生素主要抑制或杀灭细菌，不能用来建立对病毒的免疫记忆。机制不同，两者不能互相替代。","source":"原创练习"},{"id":"bk-sci-022","subject":"基本知识","chapter":"科学技术","stem":"病毒与细菌的一个根本差别是：","options":["病毒有完整的细胞结构","细菌不能遗传","病毒没有细胞结构，必须在活细胞内增殖","病毒可以在任何无生命培养基上独立繁殖"],"answer":2,"explanation":"细菌是单细胞生物，有细胞结构，可以在适宜条件下独立代谢。病毒没有细胞结构，只能寄生在活细胞里，利用宿主的系统增殖。说病毒能在无生命培养基上独立繁殖，就把它写成了细菌。","source":"原创练习"},{"id":"bk-sci-023","subject":"基本知识","chapter":"科学技术","stem":"达尔文用来解释生物适应环境的主要理论是：","options":["用进废退","获得性遗传一定主导进化","环境不改变种群","自然选择"],"answer":3,"explanation":"自然选择强调变异已经存在，有利变异更容易存活并留下后代。用进废退和获得性遗传是拉马克的思路，不是达尔文理论的核心。环境通过选择起作用，不是对种群毫无影响。先分清理论属于谁。","source":"原创练习"},{"id":"bk-sci-024","subject":"基本知识","chapter":"科学技术","stem":"北半球形成四季，主要原因是：","options":["黄赤交角使太阳直射点在南北回归线之间移动","地球自转一周是24小时","月球每月绕地球一周","地球与太阳的距离每天减半"],"answer":0,"explanation":"地球公转时，地轴倾斜形成约23.5度的黄赤交角，太阳直射点因此在南北回归线之间移动，各地正午太阳高度和昼夜长短改变，形成四季。自转主要造成昼夜交替。月球公转关联月相。不要用昼夜现象回答季节问题。","source":"原创练习"},{"id":"bk-sci-025","subject":"基本知识","chapter":"科学技术","stem":"关于太阳系行星，正确的是：","options":["冥王星目前仍被划为八大行星之一","八大行星包括水星、金星、地球、火星、木星、土星、天王星、海王星","太阳是一颗行星","地球位于木星之外"],"answer":1,"explanation":"八大行星按离太阳由近到远是水、金、地、火、木、土、天王、海王。2006年起冥王星被归为矮行星，不再列入八大行星。太阳是恒星。排序题先写八个名字，再看选项有没有把矮行星或恒星混进来。","source":"原创练习"},{"id":"bk-sci-026","subject":"基本知识","chapter":"科学技术","stem":"云、雨、雪等天气现象主要发生在：","options":["外核","地幔","对流层","高层真空"],"answer":2,"explanation":"大气分层里，对流层最贴近地面，气温大体随高度增加而降低，水汽和对流集中在这里，天气现象主要发生在这一层。平流层水汽少、气流以水平为主，适合飞机巡航，天气变化少。先定位层次，再看有没有水汽和对流。","source":"原创练习"},{"id":"bk-sci-027","subject":"基本知识","chapter":"科学技术","stem":"铁制品在哪种条件下最容易生锈？","options":["干燥的纯氧气中","真空中","隔绝空气的油中","与水和氧气同时接触"],"answer":3,"explanation":"铁锈的形成通常需要铁、氧气和水共同作用，盐分还会加快。只放在干燥氧气里，或缺水、或缺氧，都不容易形成常见的铁锈。真空和油中隔绝了反应条件。多条件反应要把条件都点齐。","source":"原创练习"},{"id":"bk-sci-028","subject":"基本知识","chapter":"科学技术","stem":"把铜片放入稀硫酸，通常观察不到氢气产生。原因是：","options":["铜的活动性排在氢之后，不能置换出酸中的氢","稀硫酸里没有氢元素","铜是绝缘体","氢气比铜重所以沉在底部看不见"],"answer":0,"explanation":"金属活动性顺序里，氢前面的金属才能与稀酸反应放出氢气，例如锌。铜在氢后面，不能置换稀硫酸中的氢。稀硫酸当然含氢，铜也不是绝缘体。活动性题先找金属和氢谁在前面。","source":"原创练习"},{"id":"bk-sci-029","subject":"基本知识","chapter":"科学技术","stem":"下列属于可再生能源的是：","options":["煤炭","风能","石油","天然气"],"answer":1,"explanation":"煤、石油、天然气是化石能源，形成远慢于人类使用速度，归入不可再生能源。风能、太阳能、水能可以持续获得，属于可再生能源。分类时看能否在人类时间尺度上持续再生，不看现在用得广不广。","source":"原创练习"},{"id":"bk-sci-030","subject":"基本知识","chapter":"科学技术","stem":"十进制的8，写成二进制是：","options":["111","1010","1000","110"],"answer":2,"explanation":"二进制每一位表示2的幂。8等于2的3次方，所以是1后面跟三个0，即1000。111是7，110是6，1010是10。把数字拆成8、4、2、1再填位，比直接背一个结果更稳。","source":"原创练习"},{"id":"bk-sci-031","subject":"基本知识","chapter":"科学技术","stem":"人们用域名访问网站，计算机最终仍要靠什么定位主机？","options":["把域名变成电压的颜色","只靠网站的中文简称","把域名打印在纸上","把域名解析成IP地址"],"answer":3,"explanation":"域名方便记忆，网络传输时要先通过域名系统解析成IP地址，设备再按地址寻找主机。中文简称本身不是网络地址。这道题区分的是给人看的名字和机器用来定位的地址。","source":"原创练习"},{"id":"bk-sci-032","subject":"基本知识","chapter":"科学技术","stem":"对算法理解正确的是：","options":["算法是有限、确定、可执行的解题步骤","算法就是某一台具体电脑","算法必须用同一种编程语言书写","步骤无限延续也算算法"],"answer":0,"explanation":"算法要有明确步骤，每一步可执行，并且在有限步内结束。它可以用不同语言实现成程序，所以不等于某一台机器或某一种语言。无限循环下去、没有结束条件的过程，不满足有穷性。","source":"原创练习"},{"id":"bk-sci-033","subject":"基本知识","chapter":"科学技术","stem":"书包带做得比较宽，主要是为了：","options":["减小受力面积，从而增大压强","增大受力面积，从而减小压强","增加书包的质量","改变地球引力常数"],"answer":1,"explanation":"压强等于压力除以受力面积。压力大致不变时，面积越大，压强越小，肩膀就更舒服。刀磨快是相反的做法：减小面积、增大压强。先写公式，再看题目是想增大还是减小压强。","source":"原创练习"},{"id":"bk-sci-034","subject":"基本知识","chapter":"科学技术","stem":"在生态系统中，绿色植物属于：","options":["消费者","分解者","生产者","非生物环境"],"answer":2,"explanation":"生产者能通过光合作用制造有机物，主要是绿色植物。消费者直接或间接以其他生物为食。分解者把有机物分解成无机物，多为细菌和真菌。非生物环境是光、水、空气等。按“谁制造有机物”来归类。","source":"原创练习"},{"id":"bk-sci-035","subject":"基本知识","chapter":"科学技术","stem":"关于生态系统中的能量和物质，正确的是：","options":["能量可以循环，物质只能单向流动","两者都在每一级增加","两者都不进入生物体","能量单向流动、逐级递减，物质可以循环"],"answer":3,"explanation":"能量沿食物链单向传递，每一级只有一部分传到下一级，所以逐级递减，不能循环回上一营养级。碳、氮等物质则可以在生物与环境之间循环。两个方向不要对调。","source":"原创练习"},{"id":"bk-sci-036","subject":"基本知识","chapter":"科学技术","stem":"关于输血，更符合临床原则的说法是：","options":["应当以同型输血为原则，不能把旧称“万能供血者”当成可以随意输血","任何情况下都应优先大量输入O型血","血型相同也一定不能输","输血不需要核对血型"],"answer":0,"explanation":"O型红细胞没有A、B抗原，旧教材才把它叫作万能供血者。临床仍以同型输注为原则，还要做交叉配血等核对，不能据此随意输血。绝对化的“永远优先O型”和“同型也不能输”都不对。","source":"原创练习"},{"id":"bk-sci-037","subject":"基本知识","chapter":"科学技术","stem":"科学家推断地核外核为液态，主要依据之一是：","options":["外核完全不让纵波通过","横波不能通过外核","地表没有地震","外核由空气组成"],"answer":1,"explanation":"横波只能在固体中传播，不能通过液体；纵波可以通过固体和液体。地震横波在外核处消失，纵波仍能通过，因此推断外核是液态。说纵波也不能通过，就和观测相反。波的种类决定它能穿过什么物态。","source":"原创练习"},{"id":"bk-sci-038","subject":"基本知识","chapter":"科学技术","stem":"在高海拔地区烧开水，水的沸点通常：","options":["高于100℃","永远是0℃","低于100℃","与气压无关"],"answer":2,"explanation":"标准大气压下，水的沸点约是100℃。海拔升高，气压降低，水更容易沸腾，沸点下降。所以高原上水开了，温度却可能还不到100℃。沸点随气压变化，不是一个固定不变的数。","source":"原创练习"},{"id":"bk-sci-039","subject":"基本知识","chapter":"科学技术","stem":"基因型同为Aa的两个人，后代表现出显性性状的概率是：","options":["1/4","1/2","1","3/4"],"answer":3,"explanation":"用棋盘把配子列出来：A和a各占一半。组合是AA、Aa、Aa、aa，四种机会相等。其中AA和Aa表现显性，占3/4；aa表现隐性，占1/4。不要把“有两个Aa”直接当成概率1/2。先画四种组合再合并表现型。","source":"原创练习"},{"id":"bk-sci-040","subject":"基本知识","chapter":"科学技术","stem":"人正常向前走路时，地面对鞋底的静摩擦力方向是：","options":["向前，作为使人前进的动力","向后，因为摩擦力总是阻碍运动","竖直向上","不存在"],"answer":0,"explanation":"摩擦力阻碍的是相对运动或相对运动趋势，不是笼统地阻碍一切运动。走路时脚向后蹬，相对地面有向后的趋势，静摩擦力就向前，正好成为前进的动力。说“摩擦力永远向后”，是把阻力和相对趋势混在了一起。","source":"原创练习"},{"id":"bk-def-005","subject":"基本知识","chapter":"国防与军队","stem":"人民军队的宗旨是：","options":["只为完成单项任务","全心全意为人民服务","以个人荣誉为最高标准","脱离人民单独存在"],"answer":1,"explanation":"宗旨回答军队为谁服务。人民军队的宗旨是全心全意为人民服务。单项任务、个人荣誉都不能代替这个总方向。性质和宗旨题先看“为了谁”，再排除把军队和人民拆开的说法。","source":"原创练习"},{"id":"bk-def-006","subject":"基本知识","chapter":"国防与军队","stem":"人民军队的军魂是：","options":["武器装备的数量","单一兵种的传统","党对军队的绝对领导","脱离组织的个人勇敢"],"answer":2,"explanation":"军魂是决定军队性质和方向的根本原则，即党对军队的绝对领导。装备、兵种和个人勇敢都不能代替这一条。看到“军魂”，先找领导关系，不找某一项技术指标。","source":"原创练习"},{"id":"bk-def-007","subject":"基本知识","chapter":"国防与军队","stem":"坚持党对军队绝对领导的根本制度和根本实现形式是：","options":["军事机关各自决策","由地方各部门分别指挥","取消集中统一领导","军委主席负责制"],"answer":3,"explanation":"中央军事委员会实行主席负责制。公开表述中，军委主席负责制是坚持党对军队绝对领导的根本制度和根本实现形式。各自为政或把指挥权拆到地方部门，都和要求集中统一领导相反。","source":"原创练习"},{"id":"bk-def-008","subject":"基本知识","chapter":"国防与军队","stem":"强军目标的三句话是听党指挥、能打胜仗和：","options":["作风优良","规模越大越好","取消训练","只重形式"],"answer":0,"explanation":"强军目标是建设一支听党指挥、能打胜仗、作风优良的人民军队。三句话缺一不可。规模、形式都不是这句目标里的第三项。数字是三，先把三句话写全再看选项。","source":"原创练习"},{"id":"bk-def-009","subject":"基本知识","chapter":"国防与军队","stem":"“能打胜仗是强军之要”，强调的是：","options":["可以用形式代替训练","军队的根本职能和建设指向","政治方向可以不管","作风与战斗力无关"],"answer":1,"explanation":"三句目标有分工：听党指挥是强军之魂，能打胜仗是强军之要，作风优良是强军之基。能打胜仗对应军队的根本职能。不要把灵魂、要害和基础三张标签贴错。题干点了“之要”，就找职能这一支。","source":"原创练习"},{"id":"bk-def-010","subject":"基本知识","chapter":"国防与军队","stem":"三湾改编在军队建设上的关键举措是：","options":["取消政治工作","只改编番号、不建组织","把支部建在连上","把指挥权交给地方士绅"],"answer":2,"explanation":"1927年三湾改编的组织措施是支部建在连上，班排有党小组，从组织上保证党对军队的领导。只改番号或取消政治工作，都没有说到这次改编的关键。历史事件题先记“它解决了什么问题”。","source":"原创练习"},{"id":"bk-def-011","subject":"基本知识","chapter":"国防与军队","stem":"古田会议确立的原则可以概括为：","options":["取消思想工作","只讨论给养、不讨论建军原则","以个人服从代替组织","思想建党、政治建军"],"answer":3,"explanation":"1929年古田会议明确思想建党、政治建军，把政治工作摆到军队建设的重要位置。它不是一次单纯的后勤会议。和三湾改编放在一起记：一个着重把组织建到连，一个着重解决思想和政治建军。","source":"原创练习"},{"id":"bk-def-012","subject":"基本知识","chapter":"国防与军队","stem":"下列哪一个不是现行五大战区的名称？","options":["华北战区","东部战区","南部战区","西部战区"],"answer":0,"explanation":"2016年公开成立的五大战区是东部、南部、西部、北部、中部。没有“华北战区”这个现行名称。北部战区不能写成华北战区。清单题先写出五个方向，多出来的旧称或自拟名称就是答案。","source":"原创练习"},{"id":"bk-def-013","subject":"基本知识","chapter":"国防与军队","stem":"“战区主战、军种主建”中，军种主要负责：","options":["代替战区直接包揽一切战役指挥","本军种的建设、训练和力量管理","取消战区","只负责地方治安条例"],"answer":1,"explanation":"这条原则把建设和作战的侧重分开。战区侧重作战指挥，军种侧重建设、训练和管理本军种力量。不是取消战区，也不是军种把战区的战役指挥全部拿走。看到“主建”，就选建设训练这一侧。","source":"原创练习"},{"id":"bk-def-014","subject":"基本知识","chapter":"国防与军队","stem":"军队文职人员的身份是：","options":["授予军衔的现役军官","民兵中的临时群众","在军队编制岗位工作的非现役人员，不授予军衔","地方行政机关的公务员编制"],"answer":2,"explanation":"文职人员是军队人员的组成部分，在军队编制岗位从事管理工作和专业技术工作，但属于非现役人员，不授予军衔。不要把文职答成现役军官，也不要答成与军队无关的普通岗位。身份题先看授不授军衔、是不是现役。","source":"原创练习"},{"id":"bk-def-015","subject":"基本知识","chapter":"国防与军队","stem":"文职人员的岗位类别主要分为：","options":["只有作战指挥岗位","只有义务兵岗位","只有预备役登记岗位","管理岗位和专业技术岗位"],"answer":3,"explanation":"两类岗位是管理和专业技术。作战指挥岗位、义务兵岗位属于现役体系，不是文职岗位分类。预备役是另一套兵役安排。题干限定文职，就在管理和技术两类里选。","source":"原创练习"},{"id":"bk-def-016","subject":"基本知识","chapter":"国防与军队","stem":"面向社会公开招考是招录文职人员的方式之一。对此理解正确的是：","options":["对急需的高层次人才，还可以按规定直接引进","公开招考是唯一允许的方式","文职人员必须先成为现役军官","招录后一律授予军衔"],"answer":0,"explanation":"公开招考是面向社会选拔的重要方式，但不是唯一渠道。符合条件的高层次人才等，还可以按规定直接引进。文职人员不因此变成现役军官，也不授予军衔。看到“唯一”，先检查制度是不是还留了其他入口。","source":"原创练习"},{"id":"bk-def-017","subject":"基本知识","chapter":"国防与军队","stem":"2021年修改后的兵役法，对兵役制度的表述是：","options":["只保留义务兵役","以志愿兵役为主体的志愿兵役与义务兵役相结合","取消一切兵役","只按民兵组织代替兵役"],"answer":1,"explanation":"题干限定的是2021年修改后的条文：实行以志愿兵役为主体的志愿兵役与义务兵役相结合。旧概括没有突出“志愿兵役为主体”。只保留一端，或者用民兵代替兵役，都不符合这句结构。年份题先对齐那一次修改。","source":"原创练习"},{"id":"bk-def-018","subject":"基本知识","chapter":"国防与军队","stem":"我国国防政策的基本性质是：","options":["对外扩张","先发制人地争夺势力范围","防御性","不设任何国防"],"answer":2,"explanation":"我国实行防御性国防政策，国防的目的是保卫主权、安全和发展利益，不是对外扩张。防御性不等于取消国防，也不等于放弃必要的自卫能力。性质题先排除扩张、争夺势力范围这一类相反项。","source":"原创练习"},{"id":"bk-def-019","subject":"基本知识","chapter":"国防与军队","stem":"积极防御战略思想强调的是：","options":["不要任何准备","主动对外扩张","只做形式性演练","在防御的基础上做好能打赢的准备"],"answer":3,"explanation":"积极防御不是消极等待，也不是转为对外扩张。它是在战略上坚持防御的同时，把训练、战备和能力建设做扎实。两个“不是”能帮助排除两端的干扰项。","source":"原创练习"},{"id":"bk-def-020","subject":"基本知识","chapter":"国防与军队","stem":"民兵的特点是：","options":["不脱离生产的群众武装组织","全日制驻扎的现役军种","国家监察机关","代替人民法院的组织"],"answer":0,"explanation":"武装力量由解放军、武警部队和民兵组成。民兵是不脱离生产的群众武装组织，不是现役军种，也不行使监察或审判职能。组成题先三分，再看每一部分脱不脱离生产。","source":"原创练习"},{"id":"bk-def-021","subject":"基本知识","chapter":"国防与军队","stem":"2018年领导指挥体制改革后，武警部队的领导体制是：","options":["改由地方公安机关单独指挥","由党中央、中央军委集中统一领导","不再属于武装力量","由社会团体选举产生"],"answer":1,"explanation":"改革后，武警部队由党中央、中央军委集中统一领导，实行中央军委、武警部队、部队的领导指挥体制，不再沿用以前国务院与中央军委双重领导的说法。它仍是武装力量的组成部分。体制题要使用改革后的表述。","source":"原创练习"},{"id":"bk-def-022","subject":"基本知识","chapter":"国防与军队","stem":"宪法对武装力量任务的概括包括：","options":["只承担生产经营","代替人民代表大会立法","巩固国防、抵抗侵略、保卫祖国，参加国家建设事业，为人民服务","管理地方财政预算"],"answer":2,"explanation":"宪法规定武装力量属于人民，任务包括巩固国防、抵抗侵略、保卫祖国，保卫人民的和平劳动，参加国家建设事业，努力为人民服务。立法和财政预算不是军队的职权。任务题按宪法里的几项职能核对，不要缩成只搞生产。","source":"原创练习"},{"id":"bk-def-023","subject":"基本知识","chapter":"国防与军队","stem":"三大纪律中不包括：","options":["一切行动听指挥","不拿群众一针一线","一切缴获要归公","可以擅自处理缴获物品"],"answer":3,"explanation":"三大纪律是一切行动听指挥、不拿群众一针一线、一切缴获要归公。最后一条要求缴获归公，所以“擅自处理缴获”正好相反。纪律题先写全三条，方向相反的句子就是要排除的项。","source":"原创练习"},{"id":"bk-def-024","subject":"基本知识","chapter":"国防与军队","stem":"南昌起义在人民军队历史上的意义是：","options":["标志着人民军队的诞生","标志着空军领导机构成立","标志着五大战区成立","标志着文职人员条例公布"],"answer":0,"explanation":"1927年8月1日南昌起义，后来成为建军节，它的历史意义是打响武装反抗的第一枪、标志着人民军队诞生。空军领导机构在1950年，五大战区在2016年，文职人员制度是后来的人事制度。一个事件只回答它自己的意义。","source":"原创练习"},{"id":"bk-def-025","subject":"基本知识","chapter":"国防与军队","stem":"中国人民抗日战争胜利纪念日是：","options":["7月7日","9月3日","8月1日","10月1日"],"answer":1,"explanation":"9月3日是中国人民抗日战争胜利纪念日。7月7日是全面抗战爆发的纪念日，8月1日是建军节，10月1日是国庆节。四个日期各对应一件事，先把事件和月日配对，再看题干问的是胜利纪念日。","source":"原创练习"},{"id":"bk-def-026","subject":"基本知识","chapter":"国防与军队","stem":"中国人民志愿军出国作战开始于：","options":["1945年","1955年","1950年","1978年"],"answer":2,"explanation":"1950年10月，中国人民志愿军赴朝作战。1945年是抗日战争胜利，1955年是实行军衔制的年份，1978年是改革开放起步。战争和制度的年份不要并到同一格。","source":"原创练习"},{"id":"bk-def-027","subject":"基本知识","chapter":"国防与军队","stem":"人民解放军首次实行军衔制是在：","options":["1949年","1950年","2015年","1955年"],"answer":3,"explanation":"1955年人民解放军实行军衔制。1949年是新中国成立，1950年是海军、空军领导机构成立，2015年是陆军领导机构成立的年份。军衔是人事等级制度，不是军种领导机构成立本身。","source":"原创练习"},{"id":"bk-def-028","subject":"基本知识","chapter":"国防与军队","stem":"2015年12月31日成立的是：","options":["陆军领导机构","五大战区","人民空军领导机构","南昌起义部队"],"answer":0,"explanation":"陆军领导机构以及火箭军等调整在2015年12月31日公开成立。五大战区是2016年2月1日。空军领导机构在1950年。两个改革日期只差一个多月，必须分开记，不能都写成2016年。","source":"原创练习"},{"id":"bk-def-029","subject":"基本知识","chapter":"国防与军队","stem":"2024年4月公开的调整中，正确的是：","options":["五大战区全部撤销","信息支援部队组建，战略支援部队番号不再沿用","文职人员改为现役军衔制","取消军委主席负责制"],"answer":1,"explanation":"这道题问的是2024年4月那次公开调整本身：信息支援部队组建，战略支援部队的番号不再沿用。它没有取消五大战区，也没有改变军委主席负责制或把文职人员改成授衔现役。时间限定在这次调整，不要把其他改革塞进来。","source":"原创练习"},{"id":"bk-def-030","subject":"基本知识","chapter":"国防与军队","stem":"国防教育的方针是：","options":["只在建军节当天进行","只面向现役军人","全民参与、长期坚持、讲求实效","以取消国防教育为目标"],"answer":2,"explanation":"国防教育法写明的方针是全民参与、长期坚持、讲求实效。对象是全体公民，不是只有军人，也不是一年只搞一天。全民国防教育日是集中教育的一个日子，不能代替“长期坚持”。","source":"原创练习"},{"id":"bk-def-031","subject":"基本知识","chapter":"国防与军队","stem":"国防教育实行的“三个结合”不包括：","options":["经常教育与集中教育相结合","普及教育与重点教育相结合","理论教育与行为教育相结合","只搞理论、不联系行为"],"answer":3,"explanation":"三个结合是经常与集中、普及与重点、理论与行为。“只搞理论、不联系行为”把行为教育拿掉，正好违反第三条。列举题用法定的三对词去对照，被删掉一半的选项就是答案。","source":"原创练习"},{"id":"bk-def-032","subject":"基本知识","chapter":"国防与军队","stem":"中国人民解放军军旗的显著标志是：","options":["左上角有金黄色五角星和“八一”两字","没有任何图案","以绿色为唯一颜色且没有文字","印着某一位个人的姓名"],"answer":0,"explanation":"军旗以红色为底，左上角缀金黄色五角星和“八一”两字，对应1927年8月1日。没有图案、改成无关颜色，或者印上个人姓名，都不符合这面旗的标志。标志题抓颜色、星和“八一”三个要素。","source":"原创练习"},{"id":"bk-def-033","subject":"基本知识","chapter":"国防与军队","stem":"《中国人民解放军军歌》的前身是：","options":["《义勇军进行曲》","《八路军进行曲》","《歌唱祖国》","《黄河大合唱》"],"answer":1,"explanation":"军歌由《八路军进行曲》演变而来。《义勇军进行曲》是国歌。《歌唱祖国》《黄河大合唱》是别的音乐作品。歌曲题只记名称来源，不要把国歌和军歌合成一首。","source":"原创练习"},{"id":"bk-def-034","subject":"基本知识","chapter":"国防与军队","stem":"宪法规定，依照法律服兵役和参加民兵组织是公民的：","options":["可以交易的权利","与公民无关的事项","光荣义务","只属于军人家属的义务"],"answer":2,"explanation":"保卫祖国、抵抗侵略是公民的神圣职责；依照法律服兵役和参加民兵组织是公民的光荣义务。它不是可以买卖的资格，也不是只有军人家属才承担。义务题先找宪法里的主语是“公民”。","source":"原创练习"},{"id":"bk-def-035","subject":"基本知识","chapter":"国防与军队","stem":"对国防设施，任何组织和个人应当：","options":["可以擅自占用或破坏","用它替代普通商业广告牌","自行决定拆除后不必恢复","不得破坏、危害"],"answer":3,"explanation":"国防设施受法律保护。禁止任何组织和个人破坏、危害，也不得擅自占用、拆除。把它当成普通广告牌或可以随意拆除，都违反保护义务。设施题的判断标准是有没有危害行为和有没有合法权限。","source":"原创练习"},{"id":"bk-def-036","subject":"基本知识","chapter":"国防与军队","stem":"我国公开承诺的核武器政策是：","options":["在任何时候、任何情况下都不首先使用核武器","可以优先对无核武器国家使用","核政策由地方各自宣布","不承担任何自我约束"],"answer":0,"explanation":"我国公开的核政策是不首先使用核武器，并无条件不对无核武器国家和无核武器区使用或威胁使用核武器。这是政策表态题，不是武器性能题。选项里如果写成可以对无核国家优先使用，就与这一承诺相反。","source":"原创练习"},{"id":"bk-def-037","subject":"基本知识","chapter":"国防与军队","stem":"现役军官和文职人员的差别，表述正确的是：","options":["两者都授予军衔","军官授予军衔，文职人员不授予军衔","文职人员负责战役指挥并取代战区","军官不属于军队人员"],"answer":1,"explanation":"现役军官授予军衔。文职人员在军队编制岗位工作，是非现役人员，不授予军衔。两者都是军队人员体系中的不同身份，不能互相取代职务，也不能把军官排除出军队。比较题只抓“衔”和“现役”两个差别。","source":"原创练习"},{"id":"bk-def-038","subject":"基本知识","chapter":"国防与军队","stem":"预备役人员平时的状态，理解正确的是：","options":["每天都在现役部队全日制服役","不再属于国家兵役制度","经过登记，在国家需要时依法转服现役，平时一般不因此就在部队全日制服役","自动获得现役军衔"],"answer":2,"explanation":"预备役是后备兵员制度。人员经过登记，在战时或紧急需要时依法转服现役，不等于现在已经在部队按现役方式全日制服役，也不会因此自动变成授衔军官。先分清“在编后备”和“正在现役服役”。","source":"原创练习"},{"id":"bk-def-039","subject":"基本知识","chapter":"国防与军队","stem":"火箭军与原来的第二炮兵，关系是：","options":["1949年就已经使用火箭军番号","属于武警部队的一个总队","是民兵的别称","2015年由第二炮兵更名组建为火箭军"],"answer":3,"explanation":"2015年12月31日，第二炮兵更名为火箭军，并成立领导机构。它不是1949年的番号，也不属于武警或民兵。军种沿革题要把旧名、新名和年份绑在一起，避免用后来的名称改写早期历史。","source":"原创练习"},{"id":"bk-def-040","subject":"基本知识","chapter":"国防与军队","stem":"听党指挥、能打胜仗、作风优良，分别对应强军之魂、强军之要和：","options":["强军之基","强军之末","可有可无的补充","只在战时才提起的口号"],"answer":0,"explanation":"配对关系是：听党指挥对强军之魂，能打胜仗对强军之要，作风优良对强军之基。作风关系到军队的性质、宗旨和本色，不是附属口号。三个标签按顺序核对，第三项就是强军之基。","source":"原创练习"},{"id":"pa-verb-005","subject":"岗位能力","chapter":"言语理解与表达","stem":"计划写完后如果不再执行，就只是____。","options":["身体力行","纸上谈兵","循序渐进","举一反三"],"answer":1,"explanation":"先看空格前后的意思：计划没有执行。纸上谈兵就是停在说法上。身体力行、循序渐进、举一反三都是正面的做法，和“不再执行”对不上。成语题先用后文锁定褒贬和动作，再排除方向相反的项。","source":"原创练习"},{"id":"pa-verb-006","subject":"岗位能力","chapter":"言语理解与表达","stem":"讨论方案时他习惯____，很少听不同意见。","options":["集思广益","从善如流","刚愎自用","兼听则明"],"answer":2,"explanation":"后半句“很少听不同意见”已经解释了空格。刚愎自用是固执、不听劝。其余三项都表示善于听取别人，放进去就和后半句矛盾。解释性的后半句比单独看成语更可靠。","source":"原创练习"},{"id":"pa-verb-007","subject":"岗位能力","chapter":"言语理解与表达","stem":"这项规定只针对窗口岗位，不能____地套到所有后勤人员身上。","options":["有的放矢","对症下药","量体裁衣","生搬硬套"],"answer":3,"explanation":"对象从窗口岗位扩到所有后勤人员，问题在于不顾对象。生搬硬套正是这个意思。有的放矢、对症下药、量体裁衣都强调对准具体对象，和“不能”后面的行为相反。先找对象是否匹配。","source":"原创练习"},{"id":"pa-verb-008","subject":"岗位能力","chapter":"言语理解与表达","stem":"证据还没有核对，结论不能下得太____。","options":["武断","审慎","稳妥","保留"],"answer":0,"explanation":"“不能”后面要接应当避免的做法。证据未核对就下很死的结论，是武断。审慎、稳妥、保留都是谨慎，放在“不能太”后面，意思就反了。先看否定词管的是哪一种态度。","source":"原创练习"},{"id":"pa-verb-009","subject":"岗位能力","chapter":"言语理解与表达","stem":"老队员带新队员，重要的是把经验讲清楚，而不是____地只给一个分数。","options":["深入浅出","简单粗暴","语重心长","循循善诱"],"answer":1,"explanation":"“而不是”表示转折，后面接被否定的方式。只给一个分数、不讲清楚，对应简单粗暴。另外三项都是耐心、清楚的讲法，不能放在被否定的位置。转折后的空格优先选贬义。","source":"原创练习"},{"id":"pa-verb-010","subject":"岗位能力","chapter":"言语理解与表达","stem":"档案按年份归位，查找时才不会____。","options":["按部就班","井井有条","手忙脚乱","有条不紊"],"answer":2,"explanation":"“才不会”后面接希望避免的坏结果。手忙脚乱是忙乱。按部就班、井井有条、有条不紊都是有秩序，放进“不会”之后，就变成不希望有秩序，与归位的目的相反。","source":"原创练习"},{"id":"pa-verb-011","subject":"岗位能力","chapter":"言语理解与表达","stem":"他对这个词的理解有偏差，举例时____，把特例当成了一般情况。","options":["面面俱到","条分缕析","由此及彼","以偏概全"],"answer":3,"explanation":"逗号后面的“把特例当成一般情况”就是空格的定义。以偏概全与之同义。面面俱到、条分缕析是周全分析，由此及彼是合理引申，都不能表示用特例代替全部。后文定义可以直接用来排除。","source":"原创练习"},{"id":"pa-verb-012","subject":"岗位能力","chapter":"言语理解与表达","stem":"修订说明写得很长，真正的改动却只有两处，未免____。","options":["喧宾夺主","言简意赅","要言不烦","一语中的"],"answer":0,"explanation":"篇幅很长，重点却只有两处，说明文字压过了真正的改动，是喧宾夺主。言简意赅、要言不烦、一语中的都表示简短而且命中重点，与“写得很长”相反。比较篇幅和重点是否匹配。","source":"原创练习"},{"id":"pa-verb-013","subject":"岗位能力","chapter":"言语理解与表达","stem":"两份材料的数字不一致，公布前必须____，不能各说各话。","options":["各执一词","核对统一","含糊其辞","避而不谈"],"answer":1,"explanation":"“必须”后面接应当做的事，“不能各说各话”又规定了方向。核对统一是把数字对齐。各执一词、含糊其辞、避而不谈都是不解决问题的态度，不能接在“必须”后面。一正一反两个提示要同时满足。","source":"原创练习"},{"id":"pa-verb-014","subject":"岗位能力","chapter":"言语理解与表达","stem":"这个比喻很生动，但用来解释法规条款容易____，让人忽略例外条件。","options":["严谨周密","口径统一","产生歧义","边界清楚"],"answer":2,"explanation":"“但”把意思从生动转到风险，后面又说会忽略例外。产生歧义符合这个风险。严谨周密、口径统一、边界清楚都是准确，不能说“容易准确”。转折后选负面结果。","source":"原创练习"},{"id":"pa-verb-015","subject":"岗位能力","chapter":"言语理解与表达","stem":"培训反馈要具体到题目，少写一些____的空话。","options":["有的放矢","切中要害","可操作","不着边际"],"answer":3,"explanation":"“少写”后面接应当减少的东西，而且中心语是“空话”。不着边际和空话同向。有的放矢、切中要害、可操作都是具体有效，不会被称为要少写的空话。看中心语的感情色彩。","source":"原创练习"},{"id":"pa-verb-016","subject":"岗位能力","chapter":"言语理解与表达","stem":"他前半段一直反对，最后又投票赞成，态度前后____。","options":["自相矛盾","一以贯之","始终如一","表里如一"],"answer":0,"explanation":"反对和赞成是相反的两个行为。自相矛盾表示前后不一致。其余三项都表示一致，放进去就否定了前半句给出的反差。先判断两个行为是同向还是反向。","source":"原创练习"},{"id":"pa-verb-017","subject":"岗位能力","chapter":"言语理解与表达","stem":"宿舍的灯可以再亮一些，座位也可以再宽一些。可如果值日表总是落空，公共区域还是会乱。把值日排到人，比再买一盏灯更管用。这段话的主旨是：","options":["照明越亮，宿舍越整洁","把值日落实到人，比添置物品更能解决问题","座位宽窄决定学习成绩","值日表应当取消"],"answer":1,"explanation":"主旨看转折和收束。前文说灯和座位，“可”把重点移到值日落空，最后一句给出做法：排到人。照明和座位只是被比较的对象。取消值日表、用座位解释成绩，都没有文本依据。对策句通常就是主旨。","source":"原创练习"},{"id":"pa-verb-018","subject":"岗位能力","chapter":"言语理解与表达","stem":"模拟卷做了三套，错的仍是同一类图。继续换新卷，只是把同一处漏洞又看一遍。先把这类图的步骤写成清单，再做一小题检验。这段话强调：","options":["新卷越多，漏洞会自动消失","模拟卷以后都不必做","同一类错题要先整理步骤，再检验","图题只能靠感觉"],"answer":2,"explanation":"文段否定的是换新卷重复看同一漏洞，提出的做法是写步骤清单并检验。说模拟卷完全不必再做，把意思说过头了。主旨取作者给出的做法，不取被否定的做法，也不自行加绝对化结论。","source":"原创练习"},{"id":"pa-verb-019","subject":"岗位能力","chapter":"言语理解与表达","stem":"通知如果只写“尽快完成”，每个人理解的时间不一样。写上截止日期和交给谁，执行的人就不必再猜。这段话主要说明：","options":["通知越短越好","“尽快完成”是最精确的要求","口头通知一律无效","写明截止日期和接收人，才能减少猜测"],"answer":3,"explanation":"重点在后句的正面要求：日期和接收人让人不用猜。越短越好、口头一律无效，都是原文没有的绝对化说法。“尽快完成”恰恰是被批评的模糊写法。不要把例子本身当成作者赞成的做法。","source":"原创练习"},{"id":"pa-verb-020","subject":"岗位能力","chapter":"言语理解与表达","stem":"图书馆周末人多，不是因为书变少了，而是自习座位被占着却离开很久。只增加书架，解决不了占座。这段话的核心是：","options":["占座才是矛盾所在，加书架对不上问题","周末读者减少了","书少是拥挤的主因","应当取消周末开放"],"answer":0,"explanation":"“不是……而是……”后面才是作者认定的原因。对策如果只加书架，就没有对准占座。取消开放是原文没有提出的办法。因果句先抓“而是”后面的内容。","source":"原创练习"},{"id":"pa-verb-021","subject":"岗位能力","chapter":"言语理解与表达","stem":"记录错题时抄下选项，不如写下自己当时排除了什么、为什么排除错了。下次需要调用的是判断过程。这段话意在说明：","options":["选项原文比思路更重要","记录排除过程和误区，方便下次调用","错题不必再看","判断过程无法用文字记录"],"answer":1,"explanation":"“不如”后面是作者的倾向：记录排除过程和错因。说选项更重要，是把比较说反了。文段要求用文字留下过程，所以不是无法记录，也不是不必再看。比较结构以“不如”后的一侧为主旨。","source":"原创练习"},{"id":"pa-verb-022","subject":"岗位能力","chapter":"言语理解与表达","stem":"小组讨论如果没有人计时，每个人都会把例子越讲越长，最后没有时间做结论。指定计时的人，讨论才收得住。这段话强调：","options":["例子越长，结论越好","讨论不需要结论","指定计时，是为了把时间留给结论","小组讨论应当取消"],"answer":2,"explanation":"问题是例子挤占结论，对策是指定计时。主旨要同时包含问题和办法，不能只剩例子越长越好。取消讨论本身，超出了文段的建议。对策必须能回答前面的问题。","source":"原创练习"},{"id":"pa-verb-023","subject":"岗位能力","chapter":"言语理解与表达","stem":"数据表里的合计如果不能由分项加出来，先不要写分析。分析建立在加总正确的前提下。这段话要求的顺序是：","options":["先写分析，数字以后再改","分项数据没有用处","合计栏可以省略","合计对不上时，先停下核对"],"answer":3,"explanation":"“先不要”给出顺序：加总正确是分析的前提。先写分析把顺序颠倒了。省略合计或否定分项，会让核对无法进行。顺序题找“先”“再”和前提句。","source":"原创练习"},{"id":"pa-verb-024","subject":"岗位能力","chapter":"言语理解与表达","stem":"新规定公布后，窗口人员仍按旧口径回答。问题主要不在规定没写，而在没有人把新旧差别列成对照。这段话意在强调：","options":["公布之后还要把新旧差别做成对照","新规定没有任何文字","窗口人员不需要知道新规定","旧口径应当继续使用"],"answer":0,"explanation":"“不在……而在……”指出真正的缺口是缺少对照。作者承认规定已经公布，所以不是没有任何文字。继续用旧口径与更新方向相反。抓“而在”后面的不足。","source":"原创练习"},{"id":"pa-verb-025","subject":"岗位能力","chapter":"言语理解与表达","stem":"先看主语有没有被“使”字挤掉。下列没有语病的一句是：","options":["通过这次对照，使大家看清了新旧口径的差别。","大家通过这次对照，看清了新旧口径的差别。","通过这次对照，使新旧口径得到了看清。","由于这次对照，使大家看清了差别的原因造成的。"],"answer":1,"explanation":"先删掉句首状语，看还剩不剩主语。“通过这次对照，使大家……”和“通过这次对照，使新旧口径……”都把主语挤掉了。“由于这次对照，使大家看清了差别的原因造成的”又把原因和造成套在一起。主语是“大家”、主干为“大家看清了差别”的那一句才完整。","source":"原创练习"},{"id":"pa-verb-026","subject":"岗位能力","chapter":"言语理解与表达","stem":"先找重复的数量模糊词。下列有语病的一句是：","options":["他用了两天时间核对完全部名单。","名单上的重复项被他删掉了。","他大约花了三天左右才核对完。","核对工作在周五前结束。"],"answer":2,"explanation":"“大约”和“左右”都表示数量不确定，同时使用就重复。其他三句没有两套互相重复的限制，主干也清楚。数量模糊词只保留一个。","source":"原创练习"},{"id":"pa-verb-027","subject":"岗位能力","chapter":"言语理解与表达","stem":"先看两面词是不是一边多、一边少。下列没有语病的一句是：","options":["能否按期交表，是这次统计成功的关键。","按期交表，是这次统计能否成功的关键。","能否按期交表，是这次统计能否成功的关键因素的原因。","按期交表，是这次统计成功的关键。"],"answer":3,"explanation":"两面词和一面词要成对。“能否按期交表，是这次统计成功的关键”前两面后一面；“按期交表，是这次统计能否成功的关键”前一面后两面。带“关键因素的原因”的句子把两个框架套在一起。前后都只说“按期交表”和“统计成功”的那一句，搭配成立。","source":"原创练习"},{"id":"pa-verb-028","subject":"岗位能力","chapter":"言语理解与表达","stem":"先看两套句式有没有套在一起。下列有语病的一句是：","options":["文件对报名条件进行了说明的情况。","文件对报名条件作了说明。","文件对报名条件进行了说明。","文件说明了报名条件。"],"answer":0,"explanation":"“文件对报名条件进行了说明的情况”把“对……进行说明”和“……的情况”套在一起，谓语被截断。另外三句都有完整谓语。两套句式框架只能留一套。","source":"原创练习"},{"id":"pa-verb-029","subject":"岗位能力","chapter":"言语理解与表达","stem":"先数否定词有几层。下列没有语病的一句是：","options":["我们要防止不再出现漏项。","我们要防止出现漏项。","我们要防止漏项不再发生。","我们要避免防止漏项。"],"answer":1,"explanation":"“防止”本身已经带有不让发生的意思，后面再加“不再”，否定就多了一层，方向反了。“避免防止”也是两个动词互相打架。只有“我们要防止出现漏项”这一层否定，意思才是不让漏项出现。数否定词的层数。","source":"原创练习"},{"id":"pa-verb-030","subject":"岗位能力","chapter":"言语理解与表达","stem":"先看主语和宾语能不能用“是”连接。下列有语病的一句是：","options":["这次训练的参加人数是历史上最多的。","这次参加训练的人数创了新高。","这次训练的参加人数是历史最多的一次。","参加这次训练的人比上次多。"],"answer":2,"explanation":"主语是“人数”，不能用“是一次”来判断。“人数是一次”搭配不上。可以说人数历史上最多，或这次训练是人数最多的一次，但要把“一次”的主语换成训练。先看“是”两边能不能相等。","source":"原创练习"},{"id":"pa-verb-031","subject":"岗位能力","chapter":"言语理解与表达","stem":"先看因果说法有没有重复。下列没有语病的一句是：","options":["他的讲解清晰，让初学者听得懂的原因。","由于他的讲解清晰，使初学者听得懂。","他的讲解清晰的原因，是因为举例具体。","他的讲解清晰，让初学者听得懂。"],"answer":3,"explanation":"“让初学者听得懂的原因”没有把原因说完。“由于他的讲解清晰，使初学者听得懂”缺主语。“原因，是因为”重复。 “他的讲解清晰，让初学者听得懂”前后两个分句都完整。已经能说清的句子，不要再套一层因果框架。","source":"原创练习"},{"id":"pa-verb-032","subject":"岗位能力","chapter":"言语理解与表达","stem":"先看“把”字句里地点放在哪里。下列有语病的一句是：","options":["请把表格在203室送到。","请把表格送到203室。","请把表格送到203室张教员处。","表格请送到203室。"],"answer":0,"explanation":"“把”字短语要紧挨能够处置的动词，地点一般放在动词后面。“请把表格在203室送到”把地点插进“把表格”和“送到”中间，语序不当。送到203室、送到张教员处、以及“表格请送到203室”都顺。","source":"原创练习"},{"id":"pa-verb-033","subject":"岗位能力","chapter":"言语理解与表达","stem":"“报名门槛降低了”中的“门槛”，意思是：","options":["门口的横木","进入这件事所要满足的条件","房间的高度","脚步声"],"answer":1,"explanation":"先看搭配。门槛与“报名”“降低”连用时，不是木头或高度，而是进入报名所要满足的条件。字面义放进句子，会和“降低”搭不上。语境义优先于字面义。","source":"原创练习"},{"id":"pa-verb-034","subject":"岗位能力","chapter":"言语理解与表达","stem":"“讨论进行了一个小时，该收口了。”这里的“收口”最接近：","options":["把袋口扎上","开始一个新话题","结束并形成结论","提高说话音量"],"answer":2,"explanation":"语境是讨论已经进行一小时。收口在办事用语里指把事情收住并作出结论。字面的袋口、提高音量都没有上下文。开始新话题与“收”的方向相反。","source":"原创练习"},{"id":"pa-verb-035","subject":"岗位能力","chapter":"言语理解与表达","stem":"上午核对名单，下午复核数字。____。晚上再汇总例外情况。填入横线最恰当的是：","options":["先把晚上的汇总删掉","名单和数字不必保存","例外情况在上午已经全部解决","两步做完后，留出时间修改不一致的地方"],"answer":3,"explanation":"填空要承接上午、下午两步，并通向晚上的汇总。留出修改时间，顺序接得上。删掉汇总、不保存数据，或说例外上午已全部解决，都和最后一句冲突。看空格前后两句能不能同时成立。","source":"原创练习"},{"id":"pa-verb-036","subject":"岗位能力","chapter":"言语理解与表达","stem":"给下列三句选择合理顺序。①这种先入印象会使错误溜过去。②同一个人连续核对同一页。③所以应换一个没有看过该页的人再读一遍。","options":["②①③","①②③","③②①","①③②"],"answer":0,"explanation":"①的“这种先入印象”必须有前句交代，所以①不能开头，只能接在②后面。③的“所以”是结论，要放在原因之后。满足指代和关联词的只有②①③。开头如果是“这种”或“所以”，句子就悬空。","source":"原创练习"},{"id":"pa-verb-037","subject":"岗位能力","chapter":"言语理解与表达","stem":"标点使用正确的一句是：","options":["他问我什么时候交表？","他问：“什么时候交表？”","他问我，“什么时候交表。”","他问：“什么时候交表”。"],"answer":1,"explanation":"“他问我什么时候交表？”把间接问句错写成了问句。直接引语里的问句要用问号，并且问号放在引号内。引号里用句号，或把句号放在引号外，都不对。只有“他问：‘什么时候交表？’”问号的位置和句子类型都对。","source":"原创练习"},{"id":"pa-verb-038","subject":"岗位能力","chapter":"言语理解与表达","stem":"“时间像一把尺子，用来量每个环节还剩多少。”主要使用的修辞是：","options":["夸张","反问","比喻","对偶"],"answer":2,"explanation":"比喻要有本体和喻体。时间是本体，尺子是喻体，相似点是可以度量。句子没有把程度说到不真实，不是夸张；没有问句，不是反问；也没有两两对仗。先找像什么。","source":"原创练习"},{"id":"pa-verb-039","subject":"岗位能力","chapter":"言语理解与表达","stem":"“他们三个一组”有歧义。下列改写消除了歧义的是：","options":["他们三个一组。","一组他们三个。","三个他们一组。","他们每三个分成一组。"],"answer":3,"explanation":"原句既可以理解成“他们这三个人是一组”，也可以理解成“按每三个一组”。加上“每”，数量就变成分组标准，只剩后一种意思。后三个句子仍然能作两种切分。消除歧义要补上关系，不是只调一下词序。","source":"原创练习"},{"id":"pa-verb-040","subject":"岗位能力","chapter":"言语理解与表达","stem":"填入关联词最恰当的是：他____仔细核对，____放过了这个漏项。","options":["虽然；但是","如果；就","不但；而且","因为；所以"],"answer":0,"explanation":"前后意思相反：已经核对了，却仍然漏掉。要用转折。“如果……就……”和“因为……所以……”会把漏项说成核对的结果。“不但……而且……”要求后项与前项同向推进，不能接一个相反的失误。","source":"原创练习"},{"id":"pa-judge-005","subject":"岗位能力","chapter":"判断推理","stem":"温度计：测量温度。与此关系最相近的是：","options":["秤：金属","秤：称重","温度：天气","医生：医院"],"answer":1,"explanation":"先定关系：工具和它直接完成的功能。温度计用来测量温度，秤用来称重。秤和金属是材料关系，温度和天气是现象相关，医生和医院是人与场所。关系不一致的项，即使主题相近也要排除。","source":"原创练习"},{"id":"pa-judge-006","subject":"岗位能力","chapter":"判断推理","stem":"树根：大树。与此关系最相近的是：","options":["屋顶：瓦片","树叶：阳光","地基：房屋","砖块：水泥"],"answer":2,"explanation":"树根是大树赖以立住的基础，不是任意部件。地基对房屋也是基础对整体。屋顶和瓦片是整体对部件，方向反了。树叶与阳光是依赖阳光，不是组成关系。先说清是基础，还是普通零件。","source":"原创练习"},{"id":"pa-judge-007","subject":"岗位能力","chapter":"判断推理","stem":"医生：患者。与此关系最相近的是：","options":["医院：病房","药品：药房","司机：方向盘","教师：学生"],"answer":3,"explanation":"医生提供专业服务，患者是服务对象。教师和学生是同一关系。医院和病房是场所与部分，药品和药房是物品与存放处，司机和方向盘是人与操作部件。不要只因为都出现在工作场景里就选。","source":"原创练习"},{"id":"pa-judge-008","subject":"岗位能力","chapter":"判断推理","stem":"小说：文学。与此关系最相近的是：","options":["钢琴：乐器","乐器：钢琴","钢琴：音乐厅","乐谱：演奏"],"answer":0,"explanation":"小说是文学中的一种，种属关系的方向是小类指向大类。钢琴是乐器的一种，方向相同。乐器：钢琴把大小类说反了。音乐厅是场所，演奏是动作。种属题先检查哪一个包含哪一个。","source":"原创练习"},{"id":"pa-judge-009","subject":"岗位能力","chapter":"判断推理","stem":"节约：浪费。与此关系最相近的是：","options":["谦虚：礼貌","谦虚：骄傲","节约：储蓄","浪费：奢侈"],"answer":1,"explanation":"节约和浪费是反义。谦虚和骄傲也是反义。谦虚和礼貌是相近的正面品质，浪费和奢侈意思接近，节约和储蓄只是相关行为。反义题要两边都相反，不能一边反义、另一边近义。","source":"原创练习"},{"id":"pa-judge-010","subject":"岗位能力","chapter":"判断推理","stem":"春天：夏天。与此关系最相近的是：","options":["早晨：夜晚","种子：收获","早晨：中午","周一：周五"],"answer":2,"explanation":"春天之后紧接着夏天，是相邻阶段的先后。早晨之后紧接着中午。早晨到夜晚、周一到周五都跳过了中间阶段。种子到收获是过程的两端，不是同一序列里的相邻时段。先后关系还要看是否相邻。","source":"原创练习"},{"id":"pa-judge-011","subject":"岗位能力","chapter":"判断推理","stem":"轮胎：汽车。与此关系最相近的是：","options":["桌子：桌腿","汽车：汽油","驾驶员：汽车","桌腿：桌子"],"answer":3,"explanation":"轮胎是汽车的部件，方向是部件指向整体。桌腿是桌子的部件，方向一致。桌子：桌腿把方向说反了。汽油是消耗的燃料，驾驶员是使用的人。组成题先标出哪一个是部分。","source":"原创练习"},{"id":"pa-judge-012","subject":"岗位能力","chapter":"判断推理","stem":"法律：约束行为。与此关系最相近的是：","options":["尺子：衡量长度","尺子：木头","法律：纸张","法官：法庭"],"answer":0,"explanation":"法律的直接作用是约束行为，尺子的直接作用是衡量长度。这是事物与功能。木头和纸张是材料，法官和法庭是人与场所。功能题问“它用来做什么”，不要改成“它由什么做成”。","source":"原创练习"},{"id":"pa-judge-013","subject":"岗位能力","chapter":"判断推理","stem":"预习：听课。与此关系最相近的是：","options":["训练：热身","热身：训练","考试：缺考","笔记：书包"],"answer":1,"explanation":"预习是听课之前的准备。热身是训练之前的准备，先后方向相同。训练：热身把准备放到了正式活动之后。缺考是考试的相反情况，笔记和书包是物品与容器。先后不能颠倒。","source":"原创练习"},{"id":"pa-judge-014","subject":"岗位能力","chapter":"判断推理","stem":"过滤：去除杂质。与此关系最相近的是：","options":["过滤：增加杂质","水杯：饮水","搜索：定位信息","地图：旅行"],"answer":2,"explanation":"过滤这个动作的直接目的是去除杂质。搜索的直接目的是定位信息。增加杂质与过滤的目的相反。水杯是饮水器具，不是动作对目的。地图对旅行是辅助工具，范围更宽。动作题选直接目的，不选可能的后续活动。","source":"原创练习"},{"id":"pa-judge-015","subject":"岗位能力","chapter":"判断推理","stem":"“回看标记”指：作答后把仍然没有把握的题目单独标出，并且在当天用自己的话重写选择理由。只收藏、不重写的不算。下列属于回看标记的是：","options":["小周只把没把握的题放进收藏夹","小周重写了所有很有把握的题，没有单独标出","小周第二天原样抄下解析","小周把没把握的题标出，当晚用自己的话写下选择理由"],"answer":3,"explanation":"定义题把要件拆开：对象是没有把握的题，动作包括标出和当天用自己的话重写。只收藏缺少重写。重写有把握的题，对象错了。第二天抄解析，既不是当天，也不是自己的话。四个要件都满足才算符合。","source":"原创练习"},{"id":"pa-judge-016","subject":"岗位能力","chapter":"判断推理","stem":"“错因归类”指：把错题按审题、计算、概念、涂卡四类原因归类，同一题只归入最主要的一类。只按章节归类的不算。下列符合的是：","options":["一道因算错的题，归入计算类，不再归入其他类","把错题按章节分成政治、法律两组","同一题同时标成审题错误和计算错误","只记录对错，不写原因"],"answer":0,"explanation":"要件有两个：按规定的原因分类，并且一题只选最主要的一类。按章节归类用错了标准。同时标两类违反“只归入一类”。不写原因则根本没有归类。对照定义时，多出来的要求和没做到的要求都要勾掉。","source":"原创练习"},{"id":"pa-judge-017","subject":"岗位能力","chapter":"判断推理","stem":"“限时复盘”指：在15分钟内只回顾刚才做错的题，不看新题，并写下下一步如何避免。超时或改看新题的不算。下列符合的是：","options":["用12分钟做了一组新题","用12分钟看完错题，并写下避免办法，没有看新题","用20分钟写完错题笔记","用10分钟把错题答案涂掉，没有写避免办法"],"answer":1,"explanation":"三个限制要同时成立：15分钟以内、只看错题、写下避免办法。做新题违反对象。20分钟超时。只涂掉答案没有写下办法。定义里的时间、对象和产出缺一个就不算。","source":"原创练习"},{"id":"pa-judge-018","subject":"岗位能力","chapter":"判断推理","stem":"“双人核对”指：两个人分别独立计算同一张表，再对照差异，并共同找出抄错的原始数字。只由一个人看两遍的不算。下列符合的是：","options":["小周把表看了两遍","两个人分别计算两张不同的表","小周和小吴各自算完，对照后找出抄错的一个数字","两个人只对照了结论，没有寻找哪个数字抄错"],"answer":2,"explanation":"要件是独立计算、同一张表、对照差异、找到抄错的原始数字。一个人看两遍缺少第二个人。两张不同的表不满足同一对象。只对照结论而没有找到错在哪个数字，最后一步没完成。","source":"原创练习"},{"id":"pa-judge-019","subject":"岗位能力","chapter":"判断推理","stem":"“静音自测”指：在无人提示的条件下连续完成一组题，中途不查资料。中途打开笔记的不算。下列符合的是：","options":["做到一半打开笔记核对公式","别人每题提醒一次对错","只完成了题目的第一问","连续做完一组题，没有人提示，也没有查资料"],"answer":3,"explanation":"条件是连续完成、无人提示、不查资料。打开笔记就是查资料。每题被提醒违反无人提示。只做第一问不是完成这一组。三个条件用“并且”连接，要全部满足。","source":"原创练习"},{"id":"pa-judge-020","subject":"岗位能力","chapter":"判断推理","stem":"“例题迁移”指：看懂例题步骤后，把同一步骤用到数字不同、结构相同的新题。只把例题再抄一遍的不算。下列符合的是：","options":["用例题的步骤做出一道结构相同但数字不同的新题","把例题原数重抄一遍","不看例题，换一种无关方法做新题","只背下例题的最终答案"],"answer":0,"explanation":"迁移要换数字、留结构、沿用步骤。原样重抄没有新题。换无关方法就不是同一步骤。只背答案没有使用步骤。看定义时把“相同”和“不同”分别落在结构和数字上。","source":"原创练习"},{"id":"pa-judge-021","subject":"岗位能力","chapter":"判断推理","stem":"“分步估算”指：精确计算前，先用取整判断答案所在区间，并写出这个区间。直接精确计算、不写区间的不算。下列符合的是：","options":["直接算出精确值，没有写区间","先写出答案应在40到50之间，再精确计算","只取整，没有形成区间判断","计算结束后才补写一个与答案无关的区间"],"answer":1,"explanation":"顺序是先估算区间并写下来，再精确计算。不写区间、只取整但没有区间、事后补一个无关区间，都不符合。定义里的先后顺序也是要件，不能倒过来做。","source":"原创练习"},{"id":"pa-judge-022","subject":"岗位能力","chapter":"判断推理","stem":"“反向检查”指：得到答案后，把答案代回每一个条件，检查是否同时满足。只把运算重做一遍、不代回条件的不算。下列符合的是：","options":["把除法再算一遍，没有代回题目条件","只检查答案是不是整数","把求出的人数代回两种分法，确认都满足","换一道新题重新开始"],"answer":2,"explanation":"反向检查的关键不是重算，而是代回原始条件。重算只能发现计算错误，不能发现列式是否符合题意。只看整数、改做新题，都没有逐条核对条件。","source":"原创练习"},{"id":"pa-judge-023","subject":"岗位能力","chapter":"判断推理","stem":"如果参加值日，就会在表上签名。小周没有签名。由此必然推出：","options":["小周参加了值日","小周明天必须值日","签名表一定被撕掉了","小周没有参加值日"],"answer":3,"explanation":"把句子写成“值日→签名”。已知签名没有发生，就用逆否命题：没有签名→没有值日。不能顺着原句从后件往前推。表被撕掉、明天必须值日，原文都没有提供。","source":"原创练习"},{"id":"pa-judge-024","subject":"岗位能力","chapter":"判断推理","stem":"如果参加值日，就会在表上签名。小周没有参加值日。由此必然推出：","options":["不能确定小周有没有签名","小周一定没有签名","小周一定签了名","小周没有到过教室"],"answer":0,"explanation":"否定前件不能否定后件。没有值日，仍可能因为领取材料等别的原因签名。所以签名与否不能确定。只有否定后件，才能回头否定前件。这是“否前”和“逆否”的差别。","source":"原创练习"},{"id":"pa-judge-025","subject":"岗位能力","chapter":"判断推理","stem":"所有交了清单的人都复习过。小吴没有复习。由此必然推出：","options":["小吴交了清单","小吴没有交清单","小吴明天会复习","复习过的人都交了清单"],"answer":1,"explanation":"全称命题“交清单→复习过”。小吴没有复习，等于否定后件，所以否定前件：没有交清单。不能因此说所有复习过的人都交了清单，那是把箭头方向说反了。","source":"原创练习"},{"id":"pa-judge-026","subject":"岗位能力","chapter":"判断推理","stem":"所有交了清单的人都复习过。小吴复习过。由此必然推出：","options":["小吴一定交了清单","小吴一定没交清单","不能确定小吴有没有交清单","所有复习过的人都交了清单"],"answer":2,"explanation":"肯定后件不能肯定前件。复习过的人里，可以有交了清单的，也可以有没交的。小吴只满足后件，前件是否发生不能确定。把“所有A是B”读成“所有B是A”，是方向错误。","source":"原创练习"},{"id":"pa-judge-027","subject":"岗位能力","chapter":"判断推理","stem":"有些报名的人参加了晚自习。由此必然推出：","options":["有些报名的人没有参加晚自习","所有报名的人都参加了晚自习","参加晚自习的人都报名了","不能据此确定是否有报名的人没参加晚自习"],"answer":3,"explanation":"“有些A是B”只保证至少有一个A是B，并不排斥所有A都是B。因此推不出“有些A不是B”。也推不出所有A都是B，更不能把参加晚自习的人全部说成报名的人。特称肯定的信息量就这么多。","source":"原创练习"},{"id":"pa-judge-028","subject":"岗位能力","chapter":"判断推理","stem":"“除非先核对，否则不公布。”与其等价的是：","options":["如果不核对，就不公布","如果不核对，就公布","只要核对了，就一定公布","公布了也可以完全没有核对"],"answer":0,"explanation":"“除非P，否则Q”翻译成“非P→Q”。这里P是先核对，Q是不公布，所以不核对就导致不公布。它不表示核对之后必须公布。已经公布则可以逆否得到已经核对，因此“公布了也可以没核对”不成立。","source":"原创练习"},{"id":"pa-judge-029","subject":"岗位能力","chapter":"判断推理","stem":"“只有完成核对，才能公布。”现在已经公布。由此必然推出：","options":["一定没有核对","已经完成核对","核对是不必要的","明天不能再核对"],"answer":1,"explanation":"“只有P才Q”翻译成“Q→P”。公布是Q，核对是P，所以公布了就一定已经核对。不能理解成核对了就必然公布，那是另一个方向。必要条件要放在箭头指向的一端。","source":"原创练习"},{"id":"pa-judge-030","subject":"岗位能力","chapter":"判断推理","stem":"“只有完成核对，才能公布。”现在已经完成核对。由此必然推出：","options":["一定已经公布","一定没有公布","不能确定有没有公布","核对结果作废"],"answer":2,"explanation":"核对只是公布的必要条件，不是充分条件。完成核对之后，可以公布，也可以继续修改而不公布。肯定必要条件，推不出结果已经发生。只有看到“已经公布”，才能倒推核对完成。","source":"原创练习"},{"id":"pa-judge-031","subject":"岗位能力","chapter":"判断推理","stem":"所有参加模考的人都带了笔。所有带了笔的人都写了姓名。由此必然推出：","options":["所有写了姓名的人都参加了模考","有些没带笔的人参加了模考","没有人写姓名","所有参加模考的人都写了姓名"],"answer":3,"explanation":"两个全称判断可以传递：参加模考→带笔→写姓名，所以参加模考→写姓名。传递不能反向，写了姓名的人不一定参加模考。参加模考的人都带了笔，也推不出没带笔的人参加了模考。","source":"原创练习"},{"id":"pa-judge-032","subject":"岗位能力","chapter":"判断推理","stem":"所有甲班学员都交了表。有些没交表的人在乙班。由此必然推出：","options":["有些乙班的人不是甲班学员","乙班学员都是甲班学员","甲班有人没交表","乙班没有学员"],"answer":0,"explanation":"没交表的人不可能是甲班学员，因为甲班都交了表。这些人里又有一些在乙班，所以乙班里至少有一些人不是甲班学员。不能推出甲班有人没交表，那与第一句直接冲突。","source":"原创练习"},{"id":"pa-judge-033","subject":"岗位能力","chapter":"判断推理","stem":"某班把晚自习延长半小时后，模考平均分上升。负责人因此认为延长晚自习导致了分数上升。下列哪项最能削弱这一判断？","options":["延长自习的同学感到更疲劳","平行班没有延长自习，其他安排相同，分数上升幅度一样","该班同学希望继续延长","晚自习的教室刚刚换了灯泡"],"answer":1,"explanation":"因果判断要排除其他原因。平行班其他安排相同、只是没有延长，分数却同样上升，说明延长并不是分数变化的原因。疲劳和换灯泡没有对上分数，希望继续延长也不能检验因果。找一个条件相同、原因缺失、结果仍在的对照。","source":"原创练习"},{"id":"pa-judge-034","subject":"岗位能力","chapter":"判断推理","stem":"论证仍是：延长晚自习之后分数上升，所以延长导致上升。下列哪项最能加强？","options":["平行班没有延长，分数上升幅度相同","该班同时更换了全部教师","平行班没有延长，其他条件相同，分数没有上升","考试难度明显下降且未作记录"],"answer":2,"explanation":"加强因果要尽量保住其他条件、只让原因不同。没有延长的平行班分数没上升，差异就更可能来自延长本身。分数同样上升会削弱。同时换教师或降低难度，都引入了新的原因，不能加强原来的判断。","source":"原创练习"},{"id":"pa-judge-035","subject":"岗位能力","chapter":"判断推理","stem":"有人说：公共区域变乱，是因为值日没有排到人；所以只要排到人，区域就一定会变整洁。下列哪项最能削弱？","options":["目前值日表是空白的","同学们希望环境整洁","区域里新买了垃圾桶","值日已经排到每个人，区域仍然乱"],"answer":3,"explanation":"结论把“排到人”当成充分条件。如果已经排到人却仍然乱，就说明还有别的原因，充分条件不成立。值日表空白只是重复现状，希望整洁和新垃圾桶都没有反驳“一定变整洁”。削弱充分条件，要用原因已经具备、结果却没出现的例子。","source":"原创练习"},{"id":"pa-judge-036","subject":"岗位能力","chapter":"判断推理","stem":"甲、乙、丙恰有一人值日，三人的话恰有一句为真。甲说：“是乙值日。”乙说：“不是乙值日。”丙说：“不是甲值日。”谁在值日？","options":["甲","乙","丙","无法确定"],"answer":0,"explanation":"用假设逐一检验，只保留恰好一句为真的情况。若甲值日：甲的话为假，乙说“不是乙”为真，丙说“不是甲”为假，恰好一句为真。若乙值日：甲、丙都为真。若丙值日：乙、丙都为真。后两种都超过一句，所以只能是甲值日。","source":"原创练习"},{"id":"pa-judge-037","subject":"岗位能力","chapter":"判断推理","stem":"有人只调查了主动来咨询的考生，发现其中八成觉得时间不够，就说全体考生有八成觉得时间不够。这个推断的主要问题是：","options":["问卷句子写得比较短","样本只来自主动咨询的人，不能直接代表全体","调查使用了纸笔","人数用汉字书写"],"answer":1,"explanation":"主动来咨询的人，可能本来就更觉得时间不够。从这样一组人推到全体考生，样本的选取方式已经偏了。句子长短、纸笔和汉字都不决定能不能外推。先问样本是谁、怎么来的，再看结论覆盖了谁。","source":"原创练习"},{"id":"pa-judge-038","subject":"岗位能力","chapter":"判断推理","stem":"某班更换新台灯后成绩上升，于是认为新台灯导致了成绩上升。下列哪项最能削弱？","options":["新台灯比旧的更亮","学员喜欢新台灯的颜色","同期每名学员都增加了辅导","教室位于二楼"],"answer":2,"explanation":"成绩上升的同时，辅导也增加了，变化就不只是台灯。亮度只是重复台灯本身的特点，颜色和楼层没有解释分数。削弱“A导致B”时，优先找与B同时出现的另一个原因。","source":"原创练习"},{"id":"pa-judge-039","subject":"岗位能力","chapter":"判断推理","stem":"使用核对清单的小组漏项更少，于是认为清单减少了漏项。下列哪项最能加强？","options":["使用清单的组同时更换了全部人员","两组使用的表格内容不同","对照结果没有保存","不用清单的对照组成员经验相同、表格相同，漏项更多"],"answer":3,"explanation":"加强因果时，其他条件要尽量相同，只保留清单这一项差别。对照组成员经验相同、表格相同，又不用清单，漏项反而更多，清单的作用就更站得住。换人或换表格会引入新原因，没有保存结果则无法比较。","source":"原创练习"},{"id":"pa-judge-040","subject":"岗位能力","chapter":"判断推理","stem":"如果下雨，就带伞。今天带伞了，所以今天下雨了。这个推理错在：","options":["把“下雨则带伞”错用成“带伞则下雨”","正确使用了否定后件","正确使用了传递关系","正确把全称判断换了质"],"answer":0,"explanation":"原句只保证下雨时会带伞，没有保证带伞时一定下雨。带伞还可能是为了防晒。看到后件就回头肯定前件，是肯定后件的错误。能够回头推的只有否定后件：没带伞，才能推出没下雨。","source":"原创练习"},{"id":"pa-math-005","subject":"岗位能力","chapter":"数量关系","stem":"一项工作，甲单独做4天完成，乙单独做12天完成。两人同时做，需要几天？","options":["2天","3天","4天","6天"],"answer":1,"explanation":"先把工作量看成1。甲每天完成1/4，乙每天完成1/12，效率和是1/3。时间等于1除以效率和，所以是3天。把4天和12天相加再除以2，得到的是天数的算术平均，不是合作时间。","source":"原创练习"},{"id":"pa-math-006","subject":"岗位能力","chapter":"数量关系","stem":"两地相距180千米。甲、乙同时相向出发，速度分别为每小时40千米和50千米。几小时后相遇？","options":["3小时","4小时","2小时","4.5小时"],"answer":2,"explanation":"相向而行，每小时共同缩短的距离是速度和。40加50等于90千米，180除以90等于2小时。速度差用于同向追及。先看方向是相向还是同向，再决定用和还是用差。","source":"原创练习"},{"id":"pa-math-007","subject":"岗位能力","chapter":"数量关系","stem":"乙在甲前方24千米，两人同向出发。甲每小时80千米，乙每小时60千米。甲追上乙需要多久？","options":["0.3小时","2.4小时","6小时","1.2小时"],"answer":3,"explanation":"同向追及看速度差。甲每小时比乙多20千米，24千米需要24/20，即1.2小时。0.3小时是用24除以甲的速度，那是把乙当成静止而且路程理解错了。2.4小时来自把速度差算小。","source":"原创练习"},{"id":"pa-math-008","subject":"岗位能力","chapter":"数量关系","stem":"有100克浓度为10%的盐水。要稀释成5%，需要再加多少克水？","options":["100克","50克","150克","200克"],"answer":0,"explanation":"加水不改变溶质。溶质一直是10克。目标浓度5%时，溶液总量是10除以0.05，等于200克。原来100克，所以再加100克。100乘5%得到的是溶质质量，不是加水量。","source":"原创练习"},{"id":"pa-math-009","subject":"岗位能力","chapter":"数量关系","stem":"100克浓度为10%的盐水蒸发掉10克水。蒸发后的浓度是：","options":["10%","1/9","20%","9%"],"answer":1,"explanation":"蒸发去掉的是水，溶质仍是10克，溶液变成90克。浓度等于10/90，即1/9。它不会停留在10%，也不会变成20%。溶质质量要除以剩下的溶液质量。","source":"原创练习"},{"id":"pa-math-010","subject":"岗位能力","chapter":"数量关系","stem":"100克浓度为20%的溶液与100克浓度为50%的溶液混合。混合后的浓度是：","options":["20%","30%","35%","70%"],"answer":2,"explanation":"溶质分别是20克和50克，共70克；溶液共200克。70除以200等于35%。两份质量相等时，浓度可以算术平均。如果质量不等，就不能直接平均两个百分数，必须回到溶质除以溶液。","source":"原创练习"},{"id":"pa-math-011","subject":"岗位能力","chapter":"数量关系","stem":"一件商品成本80元。按标价打八折后，利润率要达到20%。标价应是：","options":["96元","100元","128元","120元"],"answer":3,"explanation":"先算成交价，再反推标价。成本80元，盈利20%后的成交价是96元。八折意味着成交价等于标价乘0.8，标价等于96除以0.8，即120元。96只是成交价，不是标价。","source":"原创练习"},{"id":"pa-math-012","subject":"岗位能力","chapter":"数量关系","stem":"原价100元的物品先涨价20%，再降价20%。现价是：","options":["96元","100元","80元","120元"],"answer":0,"explanation":"百分数的基数会变。上涨20%后变成120元，再下降20%减的是24元，不是原来的20元，结果是96元。连续相反的百分变化不能互相抵消。每一步都用新的基数。","source":"原创练习"},{"id":"pa-math-013","subject":"岗位能力","chapter":"数量关系","stem":"甲、乙、丙三人排成一排，甲不能站在中间。有多少种排法？","options":["2种","4种","3种","6种"],"answer":1,"explanation":"总排法是3×2×1等于6。甲在中间时，其余两人还有2种排法。6减2等于4。也可以正面数：甲在两端有2个位置，其余两人全排列2种，2×2也是4。限制条件可以用总数减去不符合的排法。","source":"原创练习"},{"id":"pa-math-014","subject":"岗位能力","chapter":"数量关系","stem":"5本书里有3本专业书。随机取2本，两本都是专业书的概率是：","options":["3/5","1/2","3/10","2/5"],"answer":2,"explanation":"概率等于符合条件的取法除以总取法。总取法C(5,2)等于10，两本都是专业书C(3,2)等于3，概率是3/10。3/5是只取一本时专业书的比例，不能直接当作取两本的答案。","source":"原创练习"},{"id":"pa-math-015","subject":"岗位能力","chapter":"数量关系","stem":"40人中，参加跑步的有28人，参加游泳的有18人，两项都参加的有10人。两项都不参加的有几人？","options":["6人","10人","14人","4人"],"answer":3,"explanation":"先求至少参加一项的人数：28加18再减去重复计算的10人，等于36人。总人数40减去36，得到4人。交集会在两个项目里各算一次，所以必须加回一次，不能连续减两次。","source":"原创练习"},{"id":"pa-math-016","subject":"岗位能力","chapter":"数量关系","stem":"鸡和兔共10只，脚共32只。兔有几只？","options":["6只","4只","5只","8只"],"answer":0,"explanation":"设兔x只，鸡就是10减x只。脚的方程是4x加2乘(10减x)等于32，化简得2x加20等于32，x等于6。也可以先假设全是鸡，应有20只脚，实际多12只，每把一只鸡换成兔就多2只脚，12除以2等于6。","source":"原创练习"},{"id":"pa-math-017","subject":"岗位能力","chapter":"数量关系","stem":"父亲今年42岁，儿子今年12岁。再过几年，父亲的年龄是儿子的2倍？","options":["12年","18年","15年","30年"],"answer":1,"explanation":"两人同时长大，年龄差不变。设x年后，42加x等于2乘(12加x)。展开得42加x等于24加2x，所以x等于18。验算：父亲60岁，儿子30岁，确实是2倍。不要用现在的42除以12直接当成年数。","source":"原创练习"},{"id":"pa-math-018","subject":"岗位能力","chapter":"数量关系","stem":"两个数的和是48，差是12。较大的数是：","options":["18","24","30","36"],"answer":2,"explanation":"较大数等于和加差再除以2，(48加12)除以2等于30。较小数等于和减差再除以2，是18。24只是和的一半，还没有把差分回去。公式用完后，用30减18等于12检验。","source":"原创练习"},{"id":"pa-math-019","subject":"岗位能力","chapter":"数量关系","stem":"奖金180元按1:2:3分配。最多的一份是：","options":["30元","60元","120元","90元"],"answer":3,"explanation":"总份数是1加2加3等于6，每一份是180除以6等于30元。最多的是3份，即90元。120元是把180按2:3只分成两份时的结果，题干有三份。先求总份数，再乘目标份数。","source":"原创练习"},{"id":"pa-math-020","subject":"岗位能力","chapter":"数量关系","stem":"5次成绩的平均分是86，前4次的平均分是85。第5次成绩是：","options":["90分","86分","87分","91分"],"answer":0,"explanation":"总分等于平均数乘次数。五次总分是430，前四次是340，相减得到第五次90。两个平均数不能直接相减当作成绩，因为它们对应的次数不同。先还原总分。","source":"原创练习"},{"id":"pa-math-021","subject":"岗位能力","chapter":"数量关系","stem":"一条200米的直路，每隔10米种一棵树，两端都种。一共种多少棵？","options":["19棵","21棵","20棵","22棵"],"answer":1,"explanation":"两端都种时，棵数等于间隔数加1。间隔数是200除以10等于20，棵数是21。只种一端是20，两端都不种是19。环形道路则棵数等于间隔数，不再加1。先看端点和是不是环形。","source":"原创练习"},{"id":"pa-math-022","subject":"岗位能力","chapter":"数量关系","stem":"一个实心方阵最外层每边站8人。最外层一共有多少人？","options":["24人","32人","28人","64人"],"answer":2,"explanation":"四个角的人如果按四条边相加，会被数两次。最外层人数等于4乘(每边人数减1)，即4乘7等于28。4乘8等于32，把角重复计算了。64是每边人数的平方，那是实心方阵的总人数，不是外层。","source":"原创练习"},{"id":"pa-math-023","subject":"岗位能力","chapter":"数量关系","stem":"不考虑2月29日，一年按365天。要保证至少有两个人生日在同一天，至少要有多少人？","options":["2人","365人","367人","366人"],"answer":3,"explanation":"先看最不利的情况：365天各有一个人，此时还没有两人生日相同。再加1人，第366人必然与其中某人生日相同。367是把闰日也算进天数后再加1。题干已经排除闰日，抽屉数就是365。","source":"原创练习"},{"id":"pa-math-024","subject":"岗位能力","chapter":"数量关系","stem":"分苹果，每人4个就剩3个，每人6个就缺5个。有多少人？","options":["4人","3人","5人","8人"],"answer":0,"explanation":"两种分法每人相差2个。从剩3个变成缺5个，总差额是8个。人数等于8除以2，即4人。再用4乘4加3等于19检验总量，6乘4减5也是19。8是盈亏和，不是人数。","source":"原创练习"},{"id":"pa-math-025","subject":"岗位能力","chapter":"数量关系","stem":"出租车3公里及以内收费8元，超出部分每公里1.5元，不足1公里按1公里计。行驶6.2公里，车费是：","options":["12.8元","14元","13元","15.5元"],"answer":1,"explanation":"先分档。起步3公里收8元，超出3.2公里。不足1公里按1公里，所以超出部分按4公里计，4乘1.5等于6元，合计14元。12.8元是用3.2直接乘单价，没有向上取整。看到“不足按1公里”就要进位。","source":"原创练习"},{"id":"pa-math-026","subject":"岗位能力","chapter":"数量关系","stem":"某年5月1日是星期四。这一年5月20日是：","options":["星期一","星期三","星期二","星期四"],"answer":2,"explanation":"从1日到20日，经过的整天数是20减1，等于19，不是20。19除以7余5，整周不改变星期，只看余数。星期四再数5天，是星期二。","source":"原创练习"},{"id":"pa-math-027","subject":"岗位能力","chapter":"数量关系","stem":"一个长方形的长增加2米，宽不变，面积增加10平方米。原来的宽是：","options":["2米","8米","12米","5米"],"answer":3,"explanation":"增加出来的部分是一个小长方形，面积等于增加的长度乘原宽。所以宽等于10除以2，即5米。原来的长没有给出，也不需要。先把增量图形单独画出来。","source":"原创练习"},{"id":"pa-math-028","subject":"岗位能力","chapter":"数量关系","stem":"圆的半径是3。它的周长是：","options":["6π","3π","9π","12π"],"answer":0,"explanation":"周长公式是2πr，不是πr，也不是πr的平方。半径为3时，2π乘3等于6π。9π是半径平方再乘π，那是面积。看清题目要周长还是面积，再选公式。","source":"原创练习"},{"id":"pa-math-029","subject":"岗位能力","chapter":"数量关系","stem":"一个三位数，各位数字之和是18，并且能被9整除。这样的数中最小的是：","options":["198","189","279","981"],"answer":1,"explanation":"各位数字之和是18，已经能被9整除，第二个条件自动满足。要最小，百位尽量小，取1；剩下17。个位最多是9，所以十位最小是8，个位是9，得到189。先保证整除，再按数位从高到低取最小。","source":"原创练习"},{"id":"pa-math-030","subject":"岗位能力","chapter":"数量关系","stem":"钟面上一圈是360度。6点整，时针和分针的夹角是：","options":["90度","120度","180度","150度"],"answer":2,"explanation":"12个大格，每格30度。6点整，时针在6，分针在12，相隔6格，6乘30等于180度。3点整才是90度。整点时分针一定在12，先数格再乘30。","source":"原创练习"},{"id":"pa-math-031","subject":"岗位能力","chapter":"数量关系","stem":"用不超过50元的钱买单价6元的本子。最多能买几本？","options":["6本","7本","9本","8本"],"answer":3,"explanation":"50除以6等于8余2。第9本需要54元，超过预算。余数不够再买一本时要舍去，不能四舍五入。用8乘6等于48检验，确认没有超过50。","source":"原创练习"},{"id":"pa-math-032","subject":"岗位能力","chapter":"数量关系","stem":"满足3x减5大于等于16的最小整数x是：","options":["7","6","8","21"],"answer":0,"explanation":"先解不等式。两边加5，得到3x大于等于21，x大于等于7。大于等于7的最小整数就是7。如果是严格大于7，最小整数才是8。等号能不能取，决定要不要再加1。","source":"原创练习"},{"id":"pa-math-033","subject":"岗位能力","chapter":"数量关系","stem":"一项任务已经完成2/7。未完成部分占全部的：","options":["2/7","5/7","3/7","1/2"],"answer":1,"explanation":"全部看成1，未完成等于1减2/7，即5/7。也可以把总量赋成7份，完成2份，剩下5份。不要只把分子相减后随便换一个分母。整体减去已完成，分母保持不变。","source":"原创练习"},{"id":"pa-math-034","subject":"岗位能力","chapter":"数量关系","stem":"某物体每分钟移动80米。合每小时多少千米？","options":["1.33千米","48千米","4.8千米","80千米"],"answer":2,"explanation":"时间和长度都要换算。每分钟80米，一小时60分钟，是4800米。1000米等于1千米，所以是4.8千米每小时。48少除了一个10，80没有做时间换算。一次只换一个单位，换完再进下一步。","source":"原创练习"},{"id":"pa-math-035","subject":"岗位能力","chapter":"数量关系","stem":"用30%和60%的两种溶液混合成40%的溶液。30%溶液与60%溶液的质量比是：","options":["1:2","1:1","3:2","2:1"],"answer":3,"explanation":"十字交叉时，浓度到目标的距离与用量成反比。30%离40%差10，60%离40%差20，所以30%溶液与60%溶液的质量比是20比10，即2比1。离目标越近，用量越大。不要把距离比直接写成用量比。","source":"原创练习"},{"id":"pa-math-036","subject":"岗位能力","chapter":"数量关系","stem":"一项指标从400增长到500。增长率是：","options":["25%","20%","100%","125%"],"answer":0,"explanation":"增长率等于增长量除以基期，不是除以现期。增长量是100，基期是400，100除以400等于25%。100除以500等于20%，那是除错了底数。500除以400等于125%，那是发展速度，发展速度等于1加增长率。","source":"原创练习"},{"id":"pa-math-037","subject":"岗位能力","chapter":"数量关系","stem":"今年的数量是630，比去年增长5%。去年的数量是：","options":["598.5","600","630","661.5"],"answer":1,"explanation":"已知现期和增长率，基期等于现期除以(1加增长率)。630除以1.05等于600。用现期乘(1减5%)会得到598.5，那不是这个精确关系。661.5是又乘了一次1.05，方向反了。","source":"原创练习"},{"id":"pa-math-038","subject":"岗位能力","chapter":"数量关系","stem":"甲、乙效率比是3:5，合作15天完成一项工作。甲单独完成需要多少天？","options":["24天","30天","40天","45天"],"answer":2,"explanation":"把效率赋成每天3份和5份。合作一天做8份，15天的工作量是120份。甲单独每天3份，120除以3等于40天。24天是乙单独需要的时间，不要安到甲身上。份数和天数成反比。","source":"原创练习"},{"id":"pa-math-039","subject":"岗位能力","chapter":"数量关系","stem":"每道题答对的概率都是1/2，各题相互独立。连续两题都答对的概率是：","options":["1/2","1","3/4","1/4"],"answer":3,"explanation":"相互独立的事件同时发生，概率相乘。1/2乘1/2等于1/4。相加会得到1，那是互斥事件把概率加起来的公式，用错了关系。两题都对，也不是“至少对一题”。","source":"原创练习"},{"id":"pa-math-040","subject":"岗位能力","chapter":"数量关系","stem":"同一段路，甲、乙的速度比是2:3。甲走完用30分钟。乙走完用多少分钟？","options":["20分钟","30分钟","45分钟","50分钟"],"answer":0,"explanation":"路程相同，时间与速度成反比。速度比2:3，时间比就是3:2。甲对应3份，用了30分钟，1份是10分钟，乙的2份是20分钟。45分钟是按正比算的，方向反了。","source":"原创练习"},{"id":"pa-data-005","subject":"岗位能力","chapter":"资料分析","stem":"某培训点报名人数：2023年管理岗500人、技术岗500人；2024年管理岗600人、技术岗900人。2024年报名总人数比2023年增加了多少人？","options":["400人","500人","900人","1500人"],"answer":1,"explanation":"增长量等于现期减基期。两年总人数分别是1000人和1500人，相差500人。900是2024年技术岗人数，1500是2024年总数，都不是增量。先分别求两年的合计，再相减。","source":"原创练习"},{"id":"pa-data-006","subject":"岗位能力","chapter":"资料分析","stem":"沿用上一组报名数据：2023年合计1000人，2024年合计1500人。总人数的同比增长率是：","options":["25%","150%","50%","500%"],"answer":2,"explanation":"增长率等于增长量除以基期。增长量500，基期1000，500除以1000等于50%。150%是现期除以基期，那是发展速度。不要用2024年的1500作分母。","source":"原创练习"},{"id":"pa-data-007","subject":"岗位能力","chapter":"资料分析","stem":"2023年技术岗500人，2024年技术岗900人。技术岗人数的增长率是：","options":["40%","50%","180%","80%"],"answer":3,"explanation":"技术岗增长量是400人，基期是500人，400除以500等于80%。50%是总人数的增长率，不能拿来代替技术岗。180%是现期900除以基期500，多算了原来的100%。","source":"原创练习"},{"id":"pa-data-008","subject":"岗位能力","chapter":"资料分析","stem":"2024年管理岗600人、技术岗900人。技术岗占当年报名总人数的比重是：","options":["60%","40%","50%","90%"],"answer":0,"explanation":"比重等于部分除以整体。技术岗900，总数1500，900除以1500等于60%。50%是2023年技术岗的比重。计算前先确认用的是哪一年的部分和整体，年份要一致。","source":"原创练习"},{"id":"pa-data-009","subject":"岗位能力","chapter":"资料分析","stem":"技术岗比重2023年是50%，2024年是60%。比重上升了：","options":["10%","10个百分点","20%","60%"],"answer":1,"explanation":"两个比重相减，单位是百分点。60%减50%等于10个百分点。说上升10%，会被理解成原来比重的百分之十；比重本身的相对变化是10除以50，即20%，那是另一个问题。题干问上升多少，先看它要的是百分点还是百分数。","source":"原创练习"},{"id":"pa-data-010","subject":"岗位能力","chapter":"资料分析","stem":"总人数增加500人，其中技术岗增加400人。技术岗对总增长的贡献率是：","options":["40%","50%","80%","400%"],"answer":2,"explanation":"贡献率等于部分的增长量除以总体的增长量。400除以500等于80%。40%是技术岗增长量除以基期总人数，那是拉动增长率，不是贡献率。两个公式的分母不同：一个是总增量，一个是基期总量。","source":"原创练习"},{"id":"pa-data-011","subject":"岗位能力","chapter":"资料分析","stem":"技术岗增加400人，2023年报名总人数是1000人。技术岗拉动总人数增长：","options":["80个百分点","400个百分点","4个百分点","40个百分点"],"answer":3,"explanation":"拉动增长等于部分增长量除以整体的基期值。400除以1000等于40%。这里的40%是增长率里的一部分，读作拉动40个百分点。80%是贡献率，分母换成了总增量。先看分母是基期总量还是总增量。","source":"原创练习"},{"id":"pa-data-012","subject":"岗位能力","chapter":"资料分析","stem":"某阅览室四个季度阅读量依次为120万页、150万页、180万页、150万页。第二季度比第一季度的增长率是：","options":["25%","20%","30万页","150%"],"answer":0,"explanation":"环比的基期是上一季度。第二季度增长量30万页，第一季度120万页，30除以120等于25%。20%是第三季度相对第二季度的增速。题目问增长率时，不要把增长量30万页直接当选项。","source":"原创练习"},{"id":"pa-data-013","subject":"岗位能力","chapter":"资料分析","stem":"阅读量第二季度150万页，第三季度180万页。第三季度环比增长率是：","options":["16.7%","20%","25%","30万页"],"answer":1,"explanation":"环比基期是相邻的前一个季度，不是全年，也不是第一季度。增长量30万页，除以第二季度的150万页，等于20%。25%用的是第一季度作分母，基期选错了。","source":"原创练习"},{"id":"pa-data-014","subject":"岗位能力","chapter":"资料分析","stem":"第三季度180万页，第四季度150万页。第四季度环比：","options":["增长1/6","下降30%","下降1/6","增长20%"],"answer":2,"explanation":"增长量是150减180，等于负30万页。除以第三季度180万页，得到负1/6，也就是下降1/6。下降后的量不能拿来当增长率的分母。先判断增减方向，再做除法。","source":"原创练习"},{"id":"pa-data-015","subject":"岗位能力","chapter":"资料分析","stem":"四个季度阅读量合计600万页，第三季度180万页。第三季度占全年的比重是：","options":["18%","25%","33%","30%"],"answer":3,"explanation":"比重等于部分除以整体。180除以600等于30%。18%是把180除以1000的误算。四个季度简单平均会得到25%左右的错觉，但第三季度高于平均，不能用25%代替。","source":"原创练习"},{"id":"pa-data-016","subject":"岗位能力","chapter":"资料分析","stem":"上半年阅读量270万页，下半年330万页。下半年是上半年的：","options":["11/9倍","6/11倍","1倍","60万页"],"answer":0,"explanation":"是几倍，用下半年除以上半年。330除以270等于11/9。6/11是把分子分母弄反了。60万页是两者的差，不是倍数。问“是几倍”用除法，问“多多少”才用减法。","source":"原创练习"},{"id":"pa-data-017","subject":"岗位能力","chapter":"资料分析","stem":"下半年330万页，上半年270万页。下半年比上半年多：","options":["11/9","2/9","6/11","60%"],"answer":1,"explanation":"多几分之几等于增量除以基期。增量60万页，上半年270万页，60除以270等于2/9。11/9是“是几倍”，比“多几分之几”正好大1。60%没有用270作分母。","source":"原创练习"},{"id":"pa-data-018","subject":"岗位能力","chapter":"资料分析","stem":"甲班40人，平均分75；乙班60人，平均分85。两班合在一起的平均分是：","options":["80分","85分","81分","75分"],"answer":2,"explanation":"人数不同，不能把75和85直接平均。总分是40乘75加60乘85，等于8100，再除以100人，得到81分。80分是两个班平均分的简单平均，人数多的乙班被低估了。加权平均要用人数作权重。","source":"原创练习"},{"id":"pa-data-019","subject":"岗位能力","chapter":"资料分析","stem":"甲班总分3000分，乙班总分5100分。乙班总分是甲班的：","options":["0.7倍","2100分","85%","1.7倍"],"answer":3,"explanation":"倍数等于5100除以3000，即1.7倍。0.7是多出的部分除以甲班，那是“多几成”附近的算法，不是“是几倍”。2100分是两个总分的差。","source":"原创练习"},{"id":"pa-data-020","subject":"岗位能力","chapter":"资料分析","stem":"今年销售额1260万元，同比增长5%。去年销售额是：","options":["1200万元","1197万元","1260万元","1323万元"],"answer":0,"explanation":"基期等于现期除以1加增长率。1260除以1.05等于1200。用现期乘0.95会得到1197，那不是增长5%的逆运算。1323是现期再乘1.05，方向反了。","source":"原创练习"},{"id":"pa-data-021","subject":"岗位能力","chapter":"资料分析","stem":"今年销售额1260万元、成本1050万元，两者都比去年增长5%。今年利润比去年增长：","options":["0%","5%","10%","210万元"],"answer":1,"explanation":"销售额和成本按同一比率增长时，利润也按这个比率增长，前提是基期利润为正。去年销售1200万、成本1000万，利润200万；今年利润210万，增长10万，正好是5%。210万元是今年利润本身，不是增长率。","source":"原创练习"},{"id":"pa-data-022","subject":"岗位能力","chapter":"资料分析","stem":"去年利润200万元，今年利润210万元。利润的增长量是：","options":["5万元","200万元","10万元","210万元"],"answer":2,"explanation":"增长量是现期减基期，210减200等于10万元。5%是增长率，不能把百分数直接写成万元。现期和基期本身也不是增长量。减法之前先确认两个数是同一指标的两年数值。","source":"原创练习"},{"id":"pa-data-023","subject":"岗位能力","chapter":"资料分析","stem":"四个分部的基期值和增速分别为：甲800、10%，乙500、20%，丙200、40%，丁1000、5%。增长量最大的是：","options":["甲","丙","丁","乙"],"answer":3,"explanation":"增长量等于基期乘增速。甲80，乙100，丙80，丁50。增速最高的是丙，但基期小，增量不是最大。只比较百分数会选错。先把四个增量算出来再比大小。","source":"原创练习"},{"id":"pa-data-024","subject":"岗位能力","chapter":"资料分析","stem":"仍是甲增速10%、乙20%、丙40%、丁5%。增速最高的是：","options":["丙","甲","乙","丁"],"answer":0,"explanation":"问增速就直接比较百分数，不必再乘基期。丙是40%，最高。上一题问增长量时丙不是最大，两题的比较对象不同。先看问题要的是量还是率。","source":"原创练习"},{"id":"pa-data-025","subject":"岗位能力","chapter":"资料分析","stem":"甲的增长量是80，丁的增长量是50。甲的增长量是丁的：","options":["0.6倍","1.6倍","30","8倍"],"answer":1,"explanation":"倍数用80除以50，等于1.6。0.6是多出的30除以50，表示多六成，不是“是几倍”。30是两者的差。问法里有“是”，用除法。","source":"原创练习"},{"id":"pa-data-026","subject":"岗位能力","chapter":"资料分析","stem":"某单位支出：办公30万元、培训45万元、设备75万元。设备支出占总支出的比重是：","options":["30%","45%","50%","75%"],"answer":2,"explanation":"总支出是30加45加75，等于150万元。设备75除以150等于50%。45%是把培训金额误当成比重。比重一定是部分除以合计，不是某一项的原始万元数。","source":"原创练习"},{"id":"pa-data-027","subject":"岗位能力","chapter":"资料分析","stem":"设备支出75万元，办公支出30万元。设备支出是办公支出的：","options":["1.5倍","45万元","50%","2.5倍"],"answer":3,"explanation":"75除以30等于2.5，所以是2.5倍。1.5倍对应的是“多1.5倍”，算法是(75减30)除以30。45万元是两项的差。是几倍和多几倍相差1。","source":"原创练习"},{"id":"pa-data-028","subject":"岗位能力","chapter":"资料分析","stem":"培训支出今年45万元，去年36万元。同比增长：","options":["25%","20%","9万元","80%"],"answer":0,"explanation":"增长量9万元，基期36万元，9除以36等于25%。20%是用今年45作分母得到的近似错误。9万元是增长量。率的分母用去年，不用今年。","source":"原创练习"},{"id":"pa-data-029","subject":"岗位能力","chapter":"资料分析","stem":"办公、培训、设备分别占20%、30%、50%。三者比重之和是：","options":["90%","100%","150%","50%"],"answer":1,"explanation":"同一整体拆开的各部分比重，应当加总为100%，可以用这个关系检查计算。150%是把万元数误加后再当成比重。若三项加起来不是100%，说明整体或某一部分算错了。","source":"原创练习"},{"id":"pa-data-030","subject":"岗位能力","chapter":"资料分析","stem":"某指标今年比去年增长10%，去年又比前年增长10%。今年大约是前年的：","options":["1.20倍","20%","1.21倍","2倍"],"answer":2,"explanation":"连续两年各增长10%，不能把两个10%相加。今年等于前年乘1.1再乘1.1，即1.21倍。1.20倍是只加了两次10%的近似，漏掉了10%乘10%的部分。间隔增长要连乘。","source":"原创练习"},{"id":"pa-data-031","subject":"岗位能力","chapter":"资料分析","stem":"基期200，连续两年各增长10%后的现期是：","options":["240","220","400","242"],"answer":3,"explanation":"200乘1.1等于220，再乘1.1等于242。240是按每年加20来算的，相当于把增长率直接相加。220只走了一年。连续增长每次都乘在新的现期上。","source":"原创练习"},{"id":"pa-data-032","subject":"岗位能力","chapter":"资料分析","stem":"去年总产量100吨、用工8人；今年总产量120吨、用工10人。今年人均产量比去年：","options":["下降4%","上升20%","上升25%","不变"],"answer":0,"explanation":"人均产量等于总产量除以人数。去年是12.5吨，今年是12吨，12除以12.5再减1，等于下降4%。总产量上升了20%，人数上升了25%，人数涨得更快，人均才会下降。不能只看总量的增长率。","source":"原创练习"},{"id":"pa-data-033","subject":"岗位能力","chapter":"资料分析","stem":"某窗口连续5天办件量为12、15、18、9、16。这5天的平均数是：","options":["15","14","16","18"],"answer":1,"explanation":"平均数等于总和除以天数。12加15加18加9加16等于70，70除以5等于14。15是按大小排序后的中位数，18是最大值。问平均数时，不要用正中间的那个数代替。","source":"原创练习"},{"id":"pa-data-034","subject":"岗位能力","chapter":"资料分析","stem":"办件量12、15、18、9、16。按从小到大排列后，中位数是：","options":["14","16","15","18"],"answer":2,"explanation":"先排序得到9、12、15、16、18。一共5个数，中位数是第3个，即15。14是这组数的平均数。中位数看位置，平均数看总和，两个指标不能互换。","source":"原创练习"},{"id":"pa-data-035","subject":"岗位能力","chapter":"资料分析","stem":"办件量12、15、18、9、16。最大值与最小值的差是：","options":["5","14","70","9"],"answer":3,"explanation":"极差等于最大值减最小值。先找出18和9，再相减得到9。14是平均数，70是总和。比较范围时不要把集中趋势的指标拿来当差值。","source":"原创练习"},{"id":"pa-data-036","subject":"岗位能力","chapter":"资料分析","stem":"某部分今年240、同比增长20%，整体今年600、同比增长20%。该部分占整体的比重比去年：","options":["不变","上升20个百分点","下降20个百分点","变为60%"],"answer":0,"explanation":"部分和整体的增速相同，比重不变。今年比重是240除以600等于40%，去年部分200、整体500，比重也是40%。增速相同就不要再减出一个百分点。60%是把240除以400一类的误算。","source":"原创练习"},{"id":"pa-data-037","subject":"岗位能力","chapter":"资料分析","stem":"某部分今年300、同比增长50%，整体今年600、同比增长20%。该部分比重比去年上升：","options":["30个百分点","10个百分点","50个百分点","20%"],"answer":1,"explanation":"先还原基期。部分去年是300除以1.5等于200，整体去年是600除以1.2等于500。今年比重50%，去年比重40%，上升10个百分点。部分增速高于整体增速，比重才会上升；上升多少仍要用两个比重相减。","source":"原创练习"},{"id":"pa-data-038","subject":"岗位能力","chapter":"资料分析","stem":"某指标今年3月为80，今年2月为64，去年3月为50。今年3月的同比增长率是：","options":["25%","30%","60%","80%"],"answer":2,"explanation":"同比比较的是去年同一时期。增长量是80减50等于30，除以去年3月的50，等于60%。25%是相对今年2月的环比，基期用错了。先看题目写的是同比还是环比，再选分母。","source":"原创练习"},{"id":"pa-data-039","subject":"岗位能力","chapter":"资料分析","stem":"某指标今年3月为80，今年2月为64，去年3月为50。今年3月的环比增长率是：","options":["60%","16","80%","25%"],"answer":3,"explanation":"环比的基期是上一个统计期，这里是今年2月。80减64等于16，16除以64等于25%。60%用的是去年3月，那是同比。16是增长量，不是增长率。","source":"原创练习"},{"id":"pa-data-040","subject":"岗位能力","chapter":"资料分析","stem":"比较328/792与410/990的大小。结果是：","options":["两者相等","前者更大","后者更大","无法比较"],"answer":0,"explanation":"比较两个分数，可以交叉相乘：比较328乘990与410乘792。两边都等于324720，所以分数相等。只看分子328小于410，会误以为前者更小。分子和分母要同时看。","source":"原创练习"},{"id":"jj-01","subject":"基本知识","chapter":"经济","stem":"生产商品的劳动，从抽象劳动这一面看，形成的是：","options":["商品的使用价值","商品的价值","柜台上的价格标签","货币的贮藏手段"],"answer":1,"explanation":"具体劳动创造使用价值，抽象劳动形成价值。使用价值对应劳动的具体形式，不是抽象劳动的产物。价格标签只是价值在交换中的货币表现；贮藏手段是货币的职能，不是劳动二重性的直接结果。","source":"原创练习"},{"id":"jj-02","subject":"基本知识","chapter":"经济","stem":"商品的价值量由什么决定？","options":["个别企业实际耗费的劳动时间","生产该商品的社会必要劳动时间","该商品当天的市场价格","货币流通一次所用的时间"],"answer":1,"explanation":"价值量由社会必要劳动时间决定，即正常生产条件、社会平均劳动熟练程度和强度下制造该商品所需的时间。个别劳动时间只决定这家企业盈亏，不能单独决定社会价值。市场价格围绕价值波动，货币流通速度影响的是货币需要量，二者都不是价值量的尺度。","source":"原创练习"},{"id":"jj-03","subject":"基本知识","chapter":"经济","stem":"一个部门的社会劳动生产率普遍提高以后，单位商品的价值量会：","options":["同比例提高","下降","保持不变，因为产量增加后总价值同比例放大","改由使用价值的种类决定"],"answer":1,"explanation":"社会劳动生产率提高，生产单位商品的社会必要劳动时间缩短，单位价值量下降。同一劳动时间创造的价值总量不变，增加的是使用价值数量。把总价值理解成随产量同比例变大，是把使用价值和价值混在一起了。","source":"原创练习"},{"id":"jj-04","subject":"基本知识","chapter":"经济","stem":"某企业的个别劳动时间低于社会必要劳动时间。商品仍按社会价值出售时，该企业：","options":["必须亏本，否则就不算等价交换","可能获得超额收益","生产的商品失去使用价值","只能把售价压到个别价值以下"],"answer":1,"explanation":"交换以社会价值为基础。个别耗费更低的企业按社会价值出卖，差额形成超额收益，这是价值规律推动改进技术的原因。若强制按更低的个别价值出卖，改进技术的企业反而吃亏。劳动时间较短也不会使使用价值消失。","source":"原创练习"},{"id":"jj-05","subject":"基本知识","chapter":"经济","stem":"价值规律在日常交换中表现为：","options":["价格每一时刻都精确等于价值","价格受供求影响，围绕价值上下波动","价值围绕价格上下波动","供求关系直接决定价值量"],"answer":1,"explanation":"价格以价值为基础，供过于求时偏低，供不应求时偏高，所以围绕价值波动。每一时刻都精确相等，只是等价交换的内在要求，不是市场上的日常表现。说价值围绕价格波动，把基础和现象弄反了。供求解释价格为何偏离，不能取代社会必要劳动时间。","source":"原创练习"},{"id":"jj-06","subject":"基本知识","chapter":"经济","stem":"货币最基本的两种职能是：","options":["贮藏手段和世界货币","价值尺度和流通手段","支付手段和世界货币","贮藏手段和支付手段"],"answer":1,"explanation":"价值尺度衡量商品价值，流通手段媒介交换，二者是货币一开始就具有的基本职能。贮藏、支付和世界货币是后来扩展出来的职能，不能倒过来当作最基本的职能。","source":"原创练习"},{"id":"jj-07","subject":"基本知识","chapter":"经济","stem":"货币给商品标价、执行价值尺度时：","options":["必须把现金摆在商品旁边","可以只是观念上的货币","只能用于到期以后再付款","必须退出流通被保存起来"],"answer":1,"explanation":"标价是在观念上用货币衡量价值，不需要现实货币出场。一手交钱的现货交易才需要现实货币，那是流通手段。延期付款属于支付手段，把货币存起来退出买卖属于贮藏手段。","source":"原创练习"},{"id":"jj-08","subject":"基本知识","chapter":"经济","stem":"顾客当场付款并取走商品，这里的货币主要执行：","options":["支付手段","流通手段","世界货币","贮藏手段"],"answer":1,"explanation":"现货交易中商品和货币同时换手，货币是转瞬即逝的媒介，即流通手段。支付手段用于清偿欠款、纳税、发工资，交货和付款在时间上分开。世界货币用于国际支付，贮藏手段则是货币离开流通。","source":"原创练习"},{"id":"jj-09","subject":"基本知识","chapter":"经济","stem":"企业用存款缴清上月税款，这笔货币执行的是：","options":["价值尺度","流通手段","支付手段","世界货币"],"answer":2,"explanation":"纳税时货币单方面转移，用来了结法定债务，属于支付手段。价值尺度只负责标价，并不真正付出货币。流通手段伴随商品同时成交。国内缴税也不是世界货币职能。","source":"原创练习"},{"id":"jj-10","subject":"基本知识","chapter":"经济","stem":"其他条件不变，待售商品的价格总额增大时，流通中需要的货币量通常：","options":["减少","增加","降为零","只由窖藏金银的数量决定"],"answer":1,"explanation":"流通中需要的货币量与商品价格总额成正比，与货币流通速度成反比，即需要量等于价格总额除以货币流通次数。价格总额变大，完成交换所需的货币就更多。窖藏金银不是这个公式的决定项。","source":"原创练习"},{"id":"jj-11","subject":"基本知识","chapter":"经济","stem":"为避免纸币贬值，纸币发行量应当：","options":["随财政赤字自动扩大","与流通中实际需要的货币量相适应","等于纸张的印刷成本","始终数倍于商品价格总额"],"answer":1,"explanation":"纸币是国家强制流通的价值符号。发行量长期超过流通需要，同样面额买到的商品减少，表现为贬值和物价上涨。印刷成本只是制造费用。靠增发填补赤字，正是容易使通货过多的做法。","source":"原创练习"},{"id":"jj-12","subject":"基本知识","chapter":"经济","stem":"判断出现了通货膨胀，关键要看：","options":["某一种商品因歉收而暂时涨价","货币贬值，物价总水平在一段时间内持续上涨","货币购买力上升","居民储蓄增加"],"answer":1,"explanation":"通货膨胀看的是货币贬值和物价总水平持续上涨，不是个别商品的短期波动。歉收导致的单一涨价，只要没有变成物价总水平持续上升，就不能称为通胀。购买力上升更接近通货紧缩。储蓄增减也不能单独定义通胀。","source":"原创练习"},{"id":"jj-13","subject":"基本知识","chapter":"经济","stem":"物价总水平持续下降时，按原定名义金额偿还债务的人通常会：","options":["感到债务更轻，因为货币不值钱了","感到实际负担加重，因为货币购买力上升","被自动免除全部债务","同时面临物价上涨"],"answer":1,"explanation":"通货紧缩使货币购买力上升，名义债务不变，债务人要用更多实际货物去偿还。物价上涨才会减轻债务人的实际负担，那是通货膨胀中的情形。通缩不会自动免债，也不会同时表现为物价上涨。","source":"原创练习"},{"id":"jj-14","subject":"基本知识","chapter":"经济","stem":"居民消费价格指数上升，直接说明的是：","options":["工业品出厂价格一定同幅度上升","居民购买的一篮子消费品和服务总体变贵","国内生产总值必然下降","收入分配差距扩大"],"answer":1,"explanation":"CPI跟踪居民消费的一篮子商品和服务，反映生活费用。工业品出厂价格由PPI反映，二者不必同幅度变化。物价上升时名义GDP还可能变大，不能推出产出必然下降。收入分配差距用基尼系数衡量。","source":"原创练习"},{"id":"jj-15","subject":"基本知识","chapter":"经济","stem":"比较不同年份的真实产出，更合适的指标是：","options":["按当年价格计算的名义GDP","按不变价格计算的实际GDP","当年的货币发行量","当年的财政收入"],"answer":1,"explanation":"名义GDP包含价格变动，物价上涨时即使产量不变，名义值也会变大。实际GDP按某一基期的不变价格计算，剔除了价格因素。货币发行量和财政收入都不是生产成果本身。","source":"原创练习"},{"id":"jj-16","subject":"基本知识","chapter":"经济","stem":"用支出法核算国内生产总值时，应当计入的是：","options":["居民购买一套二手住房所付的房价全额","企业当年新形成的固定资本以及存货增加","汽车厂购入钢材时把钢材价款再按全额加总一次","股票二级市场的成交额"],"answer":1,"explanation":"支出法加总最终消费、资本形成、货物和服务净出口。新的固定资本形成和存货增加属于资本形成。二手住房是已有资产转移。钢材价值已含在汽车这一最终产品中，再加一次就是重复计算。股票买卖主要是产权转让，不是新生产的货物或服务。","source":"原创练习"},{"id":"jj-17","subject":"基本知识","chapter":"经济","stem":"软件开发和家政服务在三次产业分类中属于：","options":["第一产业","第二产业","第三产业","不计入任何产业"],"answer":2,"explanation":"第一产业是农林牧渔，第二产业主要是工业和建筑业，其余服务业归入第三产业。软件和家政提供的都是服务。不能因为软件技术含量高就划进工业，也不能把家政排除在产业之外。","source":"原创练习"},{"id":"jj-18","subject":"基本知识","chapter":"经济","stem":"沿着同一条需求曲线向下移动，表示的是：","options":["消费者收入已经提高","该商品自身价格下降，需求量增加","替代品涨价，整条曲线向右平移","供给曲线向左移动"],"answer":1,"explanation":"需求曲线描述其他条件不变时自身价格与需求量的关系，沿曲线移动只由自身价格引起。收入或替代品价格变化会移动整条曲线。供给曲线移动是供给方的变化，不是需求曲线上的点移动。","source":"原创练习"},{"id":"jj-19","subject":"基本知识","chapter":"经济","stem":"肥料涨价使粮食生产成本上升。其他条件不变时，粮食供给曲线通常：","options":["向右移动","向左移动","变成向右下方倾斜","完全不受成本影响"],"answer":1,"explanation":"成本上升后，同一价格下愿意出售的数量减少，供给曲线向左移动。向右移动表示供给增加。供给规律仍是价格越高供给量越大，成本变化改变的是曲线位置，不是把规律改成价格越高供给越少。","source":"原创练习"},{"id":"jj-20","subject":"基本知识","chapter":"经济","stem":"政府把某种生活必需品的最高售价定在均衡价格之下，较可能出现：","options":["产品过剩","短缺以及排队或配给","供给量自动等于原来的需求量","生产者更愿意增加供给"],"answer":1,"explanation":"最高限价低于均衡价格时，需求量增加、供给量减少，形成短缺。过剩出现在最低收购价高于均衡价格时，方向相反。限价压低了意愿供给，不会使供给自动赶上原来的需求。","source":"原创练习"},{"id":"jj-21","subject":"基本知识","chapter":"经济","stem":"某种商品富有需求价格弹性。商家小幅降价以后，销售收入通常：","options":["减少，因为单价下降了","增加，因为销售量增加的比例更大","保持不变","降为零"],"answer":1,"explanation":"富有弹性是指需求量变动的百分比大于价格变动的百分比。降价损失的单价会被更大比例的销量增加补回，销售收入上升。只看单价下降就断定收入减少，更符合缺乏弹性的商品。本题已是富有弹性，收入不会不变，更不会变成零。","source":"原创练习"},{"id":"jj-22","subject":"基本知识","chapter":"经济","stem":"打印机制造商大幅降价。其他条件不变时，墨盒的需求往往会：","options":["下降，因为二者可以互相替代","上升，因为二者要搭配使用","消失","只由墨盒的生产成本决定"],"answer":1,"explanation":"必须一起使用的商品是互补品。打印机更便宜，购买增加，连带提高对墨盒的需求。替代品可以互相替换，一种降价会减少另一种的需求。互补品需求随搭配商品的价格变化，不是只由自身生产成本决定。","source":"原创练习"},{"id":"jj-23","subject":"基本知识","chapter":"经济","stem":"工程师辞去年薪较高的工作去读全日制研究生。读书期间放弃的薪水属于：","options":["学校发票上的学费","这一选择的机会成本","学校已经投入的固定成本","社会得到的外部收益"],"answer":1,"explanation":"机会成本是为了某个选择而放弃的最佳替代用途的价值。放弃的薪水不出现在学费发票上，却是读研的代价。会计成本只记实际支付的费用。学校的固定成本是校方的历史投入。放弃的薪水是个人代价，不是社会得到的外部收益。","source":"原创练习"},{"id":"jj-24","subject":"基本知识","chapter":"经济","stem":"连续喝水时，每多喝一杯所增加的满足程度越来越小。这说明：","options":["总效用从第一杯起就是负数","边际效用递减","边际成本递减","需求曲线向右上方倾斜"],"answer":1,"explanation":"新增的满足程度叫边际效用。它递减时，总效用仍可能继续增加，只是增加得更慢，所以不是从第一杯起就为负。边际成本是生产概念。需求曲线向右下方倾斜，因为多买一单位的边际效用下降，愿意支付的价格也下降。","source":"原创练习"},{"id":"jj-25","subject":"基本知识","chapter":"经济","stem":"上游小厂排污，下游养殖户减产，损失却没有计入小厂成本。与社会最优相比，这种产品往往会：","options":["被生产得过多","被市场自动压到最优产量以下","成为正外部性，因而供给不足","出现私人成本高于社会成本的情况"],"answer":0,"explanation":"污染是负外部性，社会成本等于私人成本加上外部损害。厂商只按私人成本决策，产量会超过社会最优。正外部性才是市场供给不足。这里私人成本低于社会成本，不是高于。","source":"原创练习"},{"id":"jj-26","subject":"基本知识","chapter":"经济","stem":"纯公共物品难以只靠市场足额提供，主要是因为：","options":["它既有竞争性又有排他性","它具有非竞争性和非排他性，容易出现搭便车","它只能由一个人消费","它的边际成本必定高于任何价格"],"answer":1,"explanation":"非竞争性是多一个人使用并不减少别人的使用，非排他性是很难拦住不付费的人。人们倾向等待别人付费，私人企业收不回成本。竞争性加排他性是私人物品的特征。纯公共物品可以由许多人同时使用。","source":"原创练习"},{"id":"jj-27","subject":"基本知识","chapter":"经济","stem":"投保前隐瞒病情，使健康状况较差的人更愿意购买高额健康保险。这属于：","options":["道德风险","逆向选择","正外部性","价格上限造成的短缺"],"answer":1,"explanation":"逆向选择发生在签约之前：对方分不清风险高低，高风险客户更积极进入。道德风险发生在签约之后，例如已经投保却降低预防。隐瞒病情是交易前的信息问题，不是外部溢出，也不是限价造成的短缺。","source":"原创练习"},{"id":"jj-28","subject":"基本知识","chapter":"经济","stem":"宏观调控通常要兼顾的目标是：","options":["冻结每一种商品的相对价格","促进经济增长、增加就业、稳定物价、保持国际收支平衡","保证财政每年都出现赤字","取消商品交换"],"answer":1,"explanation":"经济增长、就业、物价总水平稳定和国际收支平衡是常见目标。物价稳定不是冻结每一种相对价格，相对价格还要反映供求。财政赤字不是必须追求的目标。取消交换就不再是市场经济下的调控。","source":"原创练习"},{"id":"jj-29","subject":"基本知识","chapter":"经济","stem":"需求不足、产能闲置时，扩张性财政政策的典型做法是：","options":["增加政府购买或减税","提高税率并压缩支出","提高法定存款准备金率","中央银行卖出国债"],"answer":0,"explanation":"扩张性财政政策用增加开支或减税来补充需求。提高税率、压缩支出是紧缩财政。提高准备金率和卖出国债是紧缩性货币政策，由中央银行操作，不属于财政政策。","source":"原创练习"},{"id":"jj-30","subject":"基本知识","chapter":"经济","stem":"中央银行降低法定存款准备金率，主要是为了：","options":["直接提高商品税率","增加商业银行可贷资金，扩大货币供应","减少商业银行可贷资金","代替财政发放养老金"],"answer":1,"explanation":"准备金率下降，商业银行必须缴存的比例降低，可贷资金增多，货币供应扩张。这是货币政策，不直接改税率，也不发放养老金。减少可贷资金的做法是提高准备金率。","source":"原创练习"},{"id":"jj-31","subject":"基本知识","chapter":"经济","stem":"中央银行为了回笼过多的流动性，在公开市场上宜：","options":["买入政府债券","卖出政府债券","降低再贴现率","降低存款准备金率"],"answer":1,"explanation":"卖出债券时，购买者把货币付给中央银行，基础货币减少。买入债券是投放货币。降低再贴现率和降低准备金率都是放松银根，不能用来回笼流动性。","source":"原创练习"},{"id":"jj-32","subject":"基本知识","chapter":"经济","stem":"其他条件不变，人民币对美元升值，通常会使：","options":["中国出口商品以美元标价变得更贵","中国出口商品以美元标价变得更便宜，出口一定大增","进口的美国商品在中国变得更贵","两国物价立刻相等"],"answer":0,"explanation":"人民币升值后，同样的人民币货价要换成更多美元，外国买家觉得中国货变贵，出口压力加大；进口商品折成人民币更便宜。说出口变便宜，是把升值和贬值弄反了。进口商品变贵对应的是人民币贬值。","source":"原创练习"},{"id":"jj-33","subject":"基本知识","chapter":"经济","stem":"在直接标价法下，美元兑人民币的牌价由7.1变为7.3，表示：","options":["人民币升值","人民币贬值，一美元能换到更多人民币","美元贬值","牌价数字变大就是本币升值"],"answer":1,"explanation":"直接标价法用本币表示一单位外币。数值变大，说明一单位外币值更多本币，即本币贬值。我国使用直接标价法。只有间接标价法才是数字上升表示本币升值。","source":"原创练习"},{"id":"jj-34","subject":"基本知识","chapter":"经济","stem":"甲国生产布和小麦的绝对成本都高于乙国，但布的成本差距较小。按比较优势，甲国可以：","options":["退出一切贸易","多生产布，用布交换乙国的小麦","在两种产品上都比乙国有优势","只在绝对成本最低时才出口"],"answer":1,"explanation":"比较优势比较的是机会成本。甲国生产布所放弃的小麦相对较少，就应多生产布再交换小麦。绝对成本都更高，只说明没有绝对优势，并不因此失去贸易利益。只按绝对成本分工，会让样样落后的国家退出交换。","source":"原创练习"},{"id":"jj-35","subject":"基本知识","chapter":"经济","stem":"公有制的主体地位，主要体现在：","options":["公有制企业的户数必须占绝对多数","公有资产占优势，国有经济控制国民经济命脉并起主导作用","只允许国有独资一种形式","集体所有制不属于公有制"],"answer":1,"explanation":"主体地位要看公有资产是否占优势、国有经济是否控制国民经济命脉，主导作用主要体现在控制力上，不是单纯比企业户数。实现形式可以多样化。集体所有制和全民所有制同属公有制。","source":"原创练习"},{"id":"jj-36","subject":"基本知识","chapter":"经济","stem":"在公有制范围内实行按劳分配，尺度是：","options":["投入资本的多少","劳动者提供的劳动数量和质量","全体成员领取完全相同的份额","只按个人需要领取"],"answer":1,"explanation":"按劳分配以劳动为尺度，多劳多得、少劳少得。按资本分配属于按生产要素分配。平均分配不承认劳动差别。按需分配不是现阶段公有制内部的分配原则。","source":"原创练习"},{"id":"jj-37","subject":"基本知识","chapter":"经济","stem":"政府用个人所得税和社会保障支出调节收入差距，这一环节属于：","options":["初次分配","再分配","生产过程本身","只由企业内部工资谈判完成"],"answer":1,"explanation":"初次分配在生产部门内部形成工资、利润等原始收入。税收、社会保障和转移支付发生在其后，属于再分配。它不是生产过程本身，也不只存在于企业工资谈判之中。","source":"原创练习"},{"id":"jj-38","subject":"基本知识","chapter":"经济","stem":"税收区别于一般有对价的政府收费，其特征是：","options":["自愿、有偿、每次另行协商","强制性、无偿性、固定性","营利性、竞争性、排他性","只向国有企业征收"],"answer":1,"explanation":"税收依法强制征收，不以向某个纳税人提供对等给付为条件，征税对象和税率事先确定。有对价的收费往往可以协商。纳税人也不限于国有企业。","source":"原创练习"},{"id":"jj-39","subject":"基本知识","chapter":"经济","stem":"增值税主要针对的是：","options":["商品和服务在流转中新增的价值","个人的综合所得","企业占用的土地面积","房屋收取的租金"],"answer":0,"explanation":"增值税就本环节新增价值征税，一般纳税人可抵扣进项，避免对已税部分重复征收。个人综合所得对应个人所得税。按土地面积计征属于其他税种。房屋租金涉及租赁所得或房产相关税收，不是增值税特有的计税依据。","source":"原创练习"},{"id":"jj-40","subject":"基本知识","chapter":"经济","stem":"个人所得税对综合所得实行超额累进，含义是：","options":["全部所得都按所达到的最高一档税率计税","只对超过某一级距的部分适用更高税率","收入越高，税率逐级降为零","超出第一档的部分全部免税"],"answer":1,"explanation":"超额累进把所得分成级距，每一级只就超出的部分适用本级税率。全部所得都按最高档计征的是全额累进，临界点税负会突然跳跃。税率不会随收入升高降到零，超出部分也不是免税。","source":"原创练习"},{"id":"jj-41","subject":"基本知识","chapter":"经济","stem":"财政向低收入家庭发放现金补助，这笔支出属于：","options":["购买性支出","转移性支出","税收收入","债务还本，并且等额计入当年新生产的GDP"],"answer":1,"explanation":"购买性支出是政府付款并换回商品或服务。现金补助没有换回商品，属于单方面的转移性支出。它是支出不是税收，也不因发出现金就形成等额的新增生产。","source":"原创练习"},{"id":"jj-42","subject":"基本知识","chapter":"经济","stem":"纺织厂减员后，会开旧织机的工人短期内难以转到当地新设的数控岗位。这种失业主要是：","options":["摩擦性失业","结构性失业","季节性失业","只在经济高涨时出现的周期性失业"],"answer":1,"explanation":"结构性失业来自技能或产业与空缺岗位不匹配，附近有新岗位时仍会发生。摩擦性失业是技能基本匹配时的短期寻职。题干不是换季停工。周期性失业由总需求萎缩引起，多出现在衰退期。","source":"原创练习"},{"id":"jj-43","subject":"基本知识","chapter":"经济","stem":"设备款已经支付且无法转卖。企业决定今天是否再增产一批时，这笔设备款：","options":["应全部算进这批产品的边际成本","属于沉没成本，不应影响今天的产量决策","会随这批产品的产量逐件上升","是施加给第三方的外部成本"],"answer":1,"explanation":"沉没成本已经发生且无法收回。今天是否增产，应比较新增的边际成本和边际收益。把已花掉的设备款再算进边际成本，可能错失本来划算的订货。这笔钱不随今天的产量变化，也不是给别人造成的外部损害。","source":"原创练习"},{"id":"jj-44","subject":"基本知识","chapter":"经济","stem":"一定时期内货物出口额大于进口额，称为：","options":["贸易逆差","贸易顺差","财政赤字","资本项目等于零"],"answer":1,"explanation":"出口大于进口是顺差，进口大于出口是逆差。财政赤字比较的是政府收支，不是进出口。贸易顺差也不要求资本项目等于零。","source":"原创练习"},{"id":"jj-45","subject":"基本知识","chapter":"经济","stem":"一个家庭的食品支出占消费支出的比重下降，在收入正常提高的前提下通常说明：","options":["恩格尔系数下降，生活水平相对提高","恩格尔系数上升，生活水平下降","基尼系数一定变为零","食品消费量必须减少到零"],"answer":0,"explanation":"恩格尔系数等于食品支出除以消费总支出。收入提高后食品支出往往仍会增加，但比重趋于下降，所以系数下降表示生活水平相对提高，不是食品买到零。基尼系数衡量社会收入分配差距，不能由一个家庭的食品比重推出为零。","source":"原创练习"},{"id":"jj-46","subject":"基本知识","chapter":"经济","stem":"基尼系数从0.30上升到0.45，直接反映的是：","options":["物价总水平下降","收入分配差距扩大","失业率降为零","财政变为盈余"],"answer":1,"explanation":"基尼系数在0到1之间衡量收入分布偏离绝对平等的程度，数值越大差距越大。它不是价格指数，也不是就业或预算指标。从0.30到0.45是差距扩大。","source":"原创练习"},{"id":"jj-47","subject":"基本知识","chapter":"经济","stem":"政府把某种农产品的最低收购价定在均衡价格之上，市场上较可能出现：","options":["短缺","过剩，需要消化多余供给","需求量大于供给量","生产者减少供给"],"answer":1,"explanation":"最低限价高于均衡价格时，生产者愿意多供给，消费者愿意少购买，于是过剩。短缺是最高限价低于均衡价格的结果。价格被托住以后，生产者通常增加而不是减少供给。","source":"原创练习"},{"id":"jj-48","subject":"基本知识","chapter":"经济","stem":"车主投保盗抢险之后比投保前更少锁车。签约之后行为发生变化，这是：","options":["逆向选择","道德风险","比较优势","边际效用递增"],"answer":1,"explanation":"道德风险发生在合同成立之后，一方因损失部分转嫁而降低谨慎。逆向选择发生在签约之前，是高风险者更愿意成交。少锁车是事后行为。它也与比较优势、边际效用无关，边际效用通常是递减的。","source":"原创练习"},{"id":"rw-01","subject":"基本知识","chapter":"人文与社会","stem":"汉字字体演变的主要顺序是：","options":["楷书、隶书、小篆、甲骨文","甲骨文、金文、小篆、隶书、楷书","草书、行书、甲骨文、金文","简化字、甲骨文、楷书、金文"],"answer":1,"explanation":"商代甲骨文之后有青铜器上的金文，秦统一后以小篆为标准，汉代隶书成为主要字体，魏晋以后楷书成熟。草书和行书是便于书写的体式，不是这条主线的起点。把楷书放在甲骨文之前，顺序就倒了。","source":"原创练习"},{"id":"rw-02","subject":"基本知识","chapter":"人文与社会","stem":"汉字中数量最多、一半表意一半表音的结构是：","options":["象形","指事","形声","转注"],"answer":2,"explanation":"形声字用形旁提示意义类属、声旁提示读音，在汉字中占绝大多数。象形描摹外形，指事用符号标出抽象意义，数量都少得多。转注是古人所说的用字方法，不是半形半声的结构。","source":"原创练习"},{"id":"rw-03","subject":"基本知识","chapter":"人文与社会","stem":"《诗经》按音乐和用途分为：","options":["风、雅、颂","诗、书、礼","律诗、绝句、词牌","本纪、世家、列传"],"answer":0,"explanation":"风是各国民歌，雅是宫廷乐歌，颂是宗庙祭祀乐歌。赋、比、兴是表现手法，不是这三部分的名称。诗书礼是典籍，律诗绝句是后来的格律诗，本纪世家列传是《史记》的体例。","source":"原创练习"},{"id":"rw-04","subject":"基本知识","chapter":"人文与社会","stem":"下列著作中，属于五经而不属于四书的是：","options":["《论语》","《孟子》","《尚书》","《大学》"],"answer":2,"explanation":"五经一般指《诗》《书》《礼》《易》《春秋》，《尚书》就是其中的《书》。四书是《大学》《中庸》《论语》《孟子》。《大学》虽出自《礼记》，但作为四书单列，并不是五经的独立书名。","source":"原创练习"},{"id":"rw-05","subject":"基本知识","chapter":"人文与社会","stem":"《史记》在体例上的开创性在于它是：","options":["第一部编年体通史","第一部纪传体通史","第一部断代编年史","第一部纪事本末体"],"answer":1,"explanation":"司马迁用本纪、表、书、世家、列传记人叙事，创立纪传体，并贯通久远年代，所以是纪传体通史。编年体通史的代表是《资治通鉴》。第一部纪传体断代史是《汉书》。纪事本末体的代表是《通鉴纪事本末》。","source":"原创练习"},{"id":"rw-06","subject":"基本知识","chapter":"人文与社会","stem":"唐宋八大家中，属于唐代的是：","options":["韩愈和柳宗元","欧阳修和苏轼","王安石和曾巩","苏洵和苏辙"],"answer":0,"explanation":"八大家里只有韩愈、柳宗元是唐代作家，欧阳修、三苏、王安石、曾巩都是宋代人。苏轼诗文名气大，容易被误认到唐代，但三苏都是北宋人。","source":"原创练习"},{"id":"rw-07","subject":"基本知识","chapter":"人文与社会","stem":"苏轼《念奴娇·赤壁怀古》的词风通常归为：","options":["婉约","豪放","元曲本色","宫体诗"],"answer":1,"explanation":"苏轼把怀古和壮志写入词中，开拓了豪放词。婉约词多写离愁，音律更婉转，代表有柳永、李清照等。元曲是元代的曲体，宫体诗是南朝宫廷诗风，都不是这首宋词的流派。","source":"原创练习"},{"id":"rw-08","subject":"基本知识","chapter":"人文与社会","stem":"杂剧《窦娥冤》的作者是：","options":["关汉卿","马致远","曹雪芹","罗贯中"],"answer":0,"explanation":"关汉卿是元杂剧代表作家，《窦娥冤》写窦娥蒙冤。马致远有《天净沙·秋思》和《汉宫秋》。曹雪芹写《红楼梦》，罗贯中写《三国演义》，二者是明清小说作者。","source":"原创练习"},{"id":"rw-09","subject":"基本知识","chapter":"人文与社会","stem":"以魏、蜀、吴兴衰为线索的长篇历史演义是：","options":["《水浒传》","《三国演义》","《西游记》","《红楼梦》"],"answer":1,"explanation":"《三国演义》在史事骨架上展开演义，一般认为成于元末明初。《水浒传》写梁山聚义，《西游记》是神魔故事，《红楼梦》写家族兴衰。四部都是章回小说，要靠题材而不是体裁来区分。","source":"原创练习"},{"id":"rw-10","subject":"基本知识","chapter":"人文与社会","stem":"通常被看作中国现代白话短篇小说开端的作品是：","options":["《狂人日记》","《子夜》","《家》","《骆驼祥子》"],"answer":0,"explanation":"鲁迅的《狂人日记》于1918年发表在《新青年》上，用白话揭示礼教的压迫，被看作现代白话短篇小说的开端。《子夜》《家》《骆驼祥子》是后来的长篇，不能因为同样用白话就提前到开端的位置。","source":"原创练习"},{"id":"rw-11","subject":"基本知识","chapter":"人文与社会","stem":"科举殿试一甲第三名称为：","options":["状元","榜眼","探花","解元"],"answer":2,"explanation":"殿试一甲三名依次是状元、榜眼、探花。解元是乡试第一名，会试第一名是会元。只记得前三名、把探花和榜眼对调，次序就错了。","source":"原创练习"},{"id":"rw-12","subject":"基本知识","chapter":"人文与社会","stem":"古人说弱冠，指的是：","options":["女子十五岁","男子二十岁左右","六十岁","七十岁"],"answer":1,"explanation":"男子二十岁行冠礼，体犹未壮，称弱冠。女子十五岁及笄。六十岁称花甲，七十岁称古稀。这些称谓不能按相邻的整十岁顺推。","source":"原创练习"},{"id":"rw-13","subject":"基本知识","chapter":"人文与社会","stem":"破釜沉舟讲的是谁在巨鹿之战中断绝退路？","options":["刘邦","项羽","韩信","李世民"],"answer":1,"explanation":"项羽渡河后砸锅沉船，率楚军在巨鹿击溃秦军主力。刘邦当时主要走西路。韩信的背水一战发生在井陉，同是断退路，人物和战役不同。李世民是唐代人物。","source":"原创练习"},{"id":"rw-14","subject":"基本知识","chapter":"人文与社会","stem":"纸上谈兵讽刺的是：","options":["廉颇向蔺相如负荆请罪","赵括空谈兵法，长平之战大败","刘备三顾茅庐","勾践卧薪尝胆"],"answer":1,"explanation":"赵括取代廉颇后照搬兵书，长平被秦军围困，赵军大败。负荆请罪是廉颇认错。三顾茅庐说的是拜访诸葛亮。卧薪尝胆是勾践复国。这些都是旧典，只能靠人物和结局区分。","source":"原创练习"},{"id":"rw-15","subject":"基本知识","chapter":"人文与社会","stem":"商鞅变法发生在战国时期的：","options":["楚国","秦国","齐国","燕国"],"answer":1,"explanation":"商鞅在秦孝公支持下奖励耕战、推行县制，使秦国富强。楚国有吴起变法，齐、燕也有各自的变革。不能因为各国都在变，就把商鞅放到齐楚。","source":"原创练习"},{"id":"rw-16","subject":"基本知识","chapter":"人文与社会","stem":"都江堰位于今天的四川，主持兴建的是：","options":["李冰","郑国","李春","郭守敬"],"answer":0,"explanation":"战国秦国蜀守李冰父子在岷江修都江堰，分水、排沙、灌溉配合，成都平原成为天府。郑国渠是关中工程。赵州桥与李春有关。郭守敬是元代科学家，不是都江堰的创建者。","source":"原创练习"},{"id":"rw-17","subject":"基本知识","chapter":"人文与社会","stem":"关于蔡伦与纸，表述恰当的是：","options":["他在商代发明了世界上第一张纸","他在东汉改进造纸工艺，使纸更便于推广","他发明了泥活字","他编制了授时历"],"answer":1,"explanation":"考古所见，西汉已经有纸。蔡伦在东汉用树皮、麻头、破布等改进工艺，纸更易普及，所以要点是改进而不是最早发明。泥活字属于北宋毕昇。授时历是元代郭守敬等人的历法。","source":"原创练习"},{"id":"rw-18","subject":"基本知识","chapter":"人文与社会","stem":"北宋毕昇对印刷术的贡献是：","options":["制成泥活字","改进造纸术","亲自把雕版印刷传入欧洲","撰写《梦溪笔谈》"],"answer":0,"explanation":"毕昇在庆历年间制成泥活字，可以排版再印。沈括把这件事记入《梦溪笔谈》，作者不是毕昇。改进造纸的是蔡伦。欧洲后来的金属活字不能说成毕昇亲自传入。","source":"原创练习"},{"id":"rw-19","subject":"基本知识","chapter":"人文与社会","stem":"南北朝祖冲之在数学上的标志性成就之一是：","options":["把圆周率算到小数点后第七位","第一个提出勾股定理","发明十进制","第一次测量地球周长"],"answer":0,"explanation":"祖冲之把圆周率确定在3.1415926和3.1415927之间，并给出密率355/113。勾股关系在更早的算书里已有记载。十进制记数传统很久，不是他的发明。早期测量地球周长的著名工作属于古希腊学者。","source":"原创练习"},{"id":"rw-20","subject":"基本知识","chapter":"人文与社会","stem":"莫高窟开凿于今天的：","options":["甘肃敦煌","山西大同","河南洛阳","陕西西安"],"answer":0,"explanation":"莫高窟在甘肃敦煌，是丝绸之路上的佛教石窟。大同有云冈石窟，洛阳有龙门石窟，西安临潼有秦始皇兵马俑。同属北方文物，要靠具体地点区分。","source":"原创练习"},{"id":"rw-21","subject":"基本知识","chapter":"人文与社会","stem":"五岳中的东岳是：","options":["泰山","华山","衡山","嵩山"],"answer":0,"explanation":"东岳泰山在山东，西岳华山在陕西，南岳衡山在湖南，北岳恒山在山西，中岳嵩山在河南。居中受尊的是嵩山，不是泰山。","source":"原创练习"},{"id":"rw-22","subject":"基本知识","chapter":"人文与社会","stem":"我国地势第二级阶梯和第三级阶梯的分界大致是：","options":["昆仑山、祁连山、横断山脉","大兴安岭、太行山、巫山、雪峰山","秦岭、淮河","长城一线"],"answer":1,"explanation":"昆仑山、祁连山、横断山脉分隔第一、二级阶梯。大兴安岭、太行山、巫山、雪峰山分隔第二、三级，以东主要是平原和丘陵。秦岭淮河是南北气候和农业的分界。长城不是地势阶梯的界线。","source":"原创练习"},{"id":"rw-23","subject":"基本知识","chapter":"人文与社会","stem":"秦岭—淮河一线大致相当于：","options":["地势第一、二级阶梯的分界","一月0℃等温线和800毫米年等降水量线经过的地方","季风区与非季风区的分界","全部内流区与外流区的分界"],"answer":1,"explanation":"这条线两侧在气温、降水、水田与旱地、亚热带与暖温带上差异明显。阶梯分界是两组山脉。季风区与非季风区大致沿大兴安岭、阴山、贺兰山、巴颜喀拉山、冈底斯山。内流区主要在西北，不能用秦岭淮河概括。","source":"原创练习"},{"id":"rw-24","subject":"基本知识","chapter":"人文与社会","stem":"我国最大的咸水湖和最大的淡水湖通常分别是：","options":["青海湖和鄱阳湖","鄱阳湖和青海湖","洞庭湖和太湖","纳木错和洞庭湖"],"answer":0,"explanation":"青海湖是最大的内陆咸水湖，鄱阳湖通常被认定为最大的淡水湖。洞庭湖、太湖也是大淡水湖，但一般小于鄱阳湖。纳木错是西藏的大咸水湖，小于青海湖。最大的湖要先分清咸淡。","source":"原创练习"},{"id":"rw-25","subject":"基本知识","chapter":"人文与社会","stem":"关于长江、黄河的源头，正确的是：","options":["长江发源于唐古拉山一带，黄河发源于巴颜喀拉山一带","两条河都发源于秦岭","长江发源于巴颜喀拉山，黄河发源于唐古拉山","两条河都从黄土高原发源"],"answer":0,"explanation":"长江正源沱沱河出唐古拉山各拉丹冬一带，黄河源头在巴颜喀拉山北麓。两条河都源于青藏高原，秦岭不是源头。黄土高原是黄河中游携带大量泥沙的地区。最容易错的是把两座山脉对调。","source":"原创练习"},{"id":"rw-26","subject":"基本知识","chapter":"人文与社会","stem":"黄河下游形成地上河，主要是因为：","options":["泥沙长期淤积，河床高出两岸地面","下游是高山峡谷，岩石把河床抬高","下游没有水，河床因此变高","中游植被很好，清水把下游刷深"],"answer":0,"explanation":"中游流经黄土高原，含沙量大；下游进入平原后流速减慢，泥沙淤积，堤坝越加越高，河床高出地面。下游不是高山峡谷。植被越好泥沙越少，与淤积机制相反。","source":"原创练习"},{"id":"rw-27","subject":"基本知识","chapter":"人文与社会","stem":"在北半球，白昼最长、正午太阳高度最大的节气是：","options":["春分","夏至","秋分","冬至"],"answer":1,"explanation":"夏至太阳直射北回归线，北半球白昼达到最长，正午太阳高度达到一年中的最大。冬至则白昼最短。春分、秋分太阳直射赤道，昼夜等长，不能把分理解成白昼最长。","source":"原创练习"},{"id":"rw-28","subject":"基本知识","chapter":"人文与社会","stem":"既是二十四节气，又有扫墓、踏青习俗的是：","options":["清明","雨水","芒种","小寒"],"answer":0,"explanation":"清明既指导农时，又形成扫墓、踏青的节日。雨水、芒种、小寒只是节气。端午、中秋是节日，但不是节气，不能满足二者重合。","source":"原创练习"},{"id":"rw-29","subject":"基本知识","chapter":"人文与社会","stem":"农历九月初九的传统习俗主要是：","options":["赛龙舟、吃粽子","登高、赏菊、插茱萸","赏月、吃月饼","赏花灯、吃汤圆"],"answer":1,"explanation":"九月初九称重阳，习俗是登高、赏菊、插茱萸。龙舟和粽子属于端午，赏月吃月饼属于中秋，花灯汤圆属于元宵。不能因为都有团聚，就把习俗对调。","source":"原创练习"},{"id":"rw-30","subject":"基本知识","chapter":"人文与社会","stem":"京剧行当中的净，主要指：","options":["女性角色","勾画脸谱的花脸","滑稽的丑角","以唱工见长的老生"],"answer":1,"explanation":"生、旦、净、丑里，净行勾脸，扮演性格或身份较突出的男性人物。旦是女性角色，丑是喜剧或卑微角色，老生属于生行。同是男性，还要区分挂须的生和开脸的净。","source":"原创练习"},{"id":"rw-31","subject":"基本知识","chapter":"人文与社会","stem":"被称为天下第一行书的是：","options":["王羲之《兰亭集序》","颜真卿《祭侄文稿》","苏轼《寒食帖》","柳公权《玄秘塔碑》"],"answer":0,"explanation":"《兰亭集序》被称作天下第一行书。《祭侄文稿》和《寒食帖》分别常被称为第二、第三行书，不能并列第一。《玄秘塔碑》是楷书碑刻，书体就不是行书。","source":"原创练习"},{"id":"rw-32","subject":"基本知识","chapter":"人文与社会","stem":"欧洲文艺复兴首先兴起于：","options":["意大利","英国","俄国","美国"],"answer":0,"explanation":"文艺复兴从意大利城市发端，核心是人文主义，再影响欧洲其他地区。英国有后来的文学代表，但不是发源地。俄国不是这场运动的中心。美国当时尚未建立。","source":"原创练习"},{"id":"rw-33","subject":"基本知识","chapter":"人文与社会","stem":"系统主张把权力分为立法、行政、司法并互相制约的启蒙思想家是：","options":["孟德斯鸠","但丁","达·芬奇","莎士比亚"],"answer":0,"explanation":"孟德斯鸠在《论法的精神》里阐述分权与制衡。但丁、达·芬奇、莎士比亚是文艺复兴时期的文学艺术代表，提倡人文精神，并没有提出这套分权学说。时代相近，不能把文艺家和启蒙政治学说混为一人。","source":"原创练习"},{"id":"rw-34","subject":"基本知识","chapter":"人文与社会","stem":"社会学所说的社会化，指的是：","options":["把企业改为股份公司","个人学习社会规范、成为社会成员的过程","人口向城市集中","取消社会分工"],"answer":1,"explanation":"社会化是从生物个体成长为社会人的过程，要学会角色、规范和技能。企业改制是经济用语里的另一层意思。人口向城市集中是城镇化。取消分工与社会组织的方向相反。","source":"原创练习"},{"id":"rw-35","subject":"基本知识","chapter":"人文与社会","stem":"下列哪一种情况最符合再社会化？","options":["幼儿在家庭中学会基本礼让","一个人在与过去明显隔离的环境中，被要求改掉原有习惯并接受一套新规范","成年人业余加学一项职业技能","人口出生率上升"],"answer":1,"explanation":"再社会化是有意识地放弃原有行为模式、学习新规范，常发生在与过去隔离的环境中。幼儿学礼让是初级社会化。加学技能而原有价值大多保留，属于继续社会化。出生率是人口指标。","source":"原创练习"},{"id":"rw-36","subject":"基本知识","chapter":"人文与社会","stem":"家庭和亲密玩伴之所以称为初级群体，是因为：","options":["规模大，只靠章程维持","规模较小，面对面交往，情感色彩浓","只存在于正式组织的文件里","成员之间不能表达感情"],"answer":1,"explanation":"初级群体规模小、直接交往，关系带有情感。机关、公司这类正式组织是次级群体，靠规章和特定目标维持。初级群体恰恰以情感为纽带，不是禁止表达感情。","source":"原创练习"},{"id":"rw-37","subject":"基本知识","chapter":"人文与社会","stem":"值班医生的孩子突然生病，岗位要求留下，家长角色要求回家。这是：","options":["角色冲突","角色中断","水平流动","自然增长"],"answer":0,"explanation":"同一个人同时承担的两种角色提出了互相矛盾的要求，称为角色冲突。角色中断是前后角色衔接不上，例如原有身份突然停止而新身份尚未形成。水平流动是地位大致相当的变换。自然增长是人口概念。","source":"原创练习"},{"id":"rw-38","subject":"基本知识","chapter":"人文与社会","stem":"面向最低生活保障对象发放的救助金，主要属于：","options":["社会保险","社会救助","社会优抚","商业保险"],"answer":1,"explanation":"社会救助按困难程度给予帮助，资金主要来自财政，最低生活保障是其基本制度。社会保险强调参保缴费。社会优抚对象是军人及其家属。商业保险由保险公司按合同经营。四者都可能发现金，要看是否缴费、对象是谁。","source":"原创练习"},{"id":"rw-39","subject":"基本知识","chapter":"人文与社会","stem":"通常所说的五险不包括：","options":["基本养老保险","基本医疗保险","失业保险","住房公积金"],"answer":3,"explanation":"五项社会保险是养老、医疗、工伤、失业和生育保险。住房公积金是单位和个人缴存的住房储金，说五险一金时，那个一金才是公积金。把它算进五险，就把保险和住房储金混成了一类。","source":"原创练习"},{"id":"rw-40","subject":"基本知识","chapter":"人文与社会","stem":"人口自然增长率等于：","options":["出生率减去死亡率","迁入率减去迁出率","城镇人口除以总人口","老年人口除以劳动年龄人口"],"answer":0,"explanation":"自然增长只看出生和死亡，自然增长率等于出生率减死亡率，可以为负。迁入减迁出反映的是迁移。城镇人口除以总人口是城镇化率。老年人口与劳动年龄人口之比是抚养比。","source":"原创练习"},{"id":"rw-41","subject":"基本知识","chapter":"人文与社会","stem":"65岁及以上人口占总人口的比重达到7%，通常表示：","options":["仍属年轻型，因为还没到10%","进入老龄化","自然增长率必然高于5%","出生率已经等于零"],"answer":1,"explanation":"常用标准是：65岁及以上人口比重达到7%，或60岁及以上达到10%，即进入老龄化。7%已经是65岁口径的门槛，不必再等到10%。这是年龄结构，不能推出自然增长率或出生率的具体数值。","source":"原创练习"},{"id":"rw-42","subject":"基本知识","chapter":"人文与社会","stem":"计算城镇化率时，分子里的城镇人口指：","options":["城镇常住人口","只有城镇户口的人口","在城镇停留不到一日的全部旅客","农村户籍人口"],"answer":0,"explanation":"城镇化率等于城镇常住人口除以总人口。在城镇居住达到规定时间的人计入分子，不管户口在哪里。只用户籍会漏掉常住城镇的农业转移人口。一日旅客不是常住，农村户籍人口更不是城镇人口。","source":"原创练习"},{"id":"rw-43","subject":"基本知识","chapter":"人文与社会","stem":"下列哪一项不是民族自治地方？","options":["新疆维吾尔自治区","某个民族乡","某个自治州","某个自治县"],"answer":1,"explanation":"民族自治地方只有自治区、自治州、自治县三级。民族乡可以照顾民族特点，但不是自治地方，乡政权也不是自治机关。名称里有民族，不能因此升格。","source":"原创练习"},{"id":"rw-44","subject":"基本知识","chapter":"人文与社会","stem":"我国分布最广的少数民族是：","options":["壮族","回族","藏族","维吾尔族"],"answer":1,"explanation":"回族散居在全国绝大多数县级行政区，分布最广。壮族人口最多，主要聚居广西。人口规模和分布广度不是一回事。藏族、维吾尔族都有相对集中的聚居区。","source":"原创练习"},{"id":"rw-45","subject":"基本知识","chapter":"人文与社会","stem":"社会学所说的社区，指的是：","options":["政府的派出机关","聚居在一定地域内的人们生活的共同体","必须由同一职业组成的组织","只存在于农村"],"answer":1,"explanation":"社区以地域为纽带，居民在同一地域生活并形成联系，城乡都有。居民委员会是基层群众性自治组织，街道办事处才是派出机关，社区不等于派出机关。成员职业多样，也不限于农村。","source":"原创练习"},{"id":"rw-46","subject":"基本知识","chapter":"人文与社会","stem":"某一群体特有的趣味和习惯与主流文化并存，并不以对抗主流为目标。这一般属于：","options":["主文化本身","亚文化","反文化","已经不再是文化"],"answer":1,"explanation":"亚文化是群体在共享主流文化的同时具有的特殊习惯，可以并存。反文化以否定、对抗主流价值为特征。这些趣味仍然使用符号和习俗，仍然是文化，只是不等于全体成员共同强调的那一层。","source":"原创练习"},{"id":"rw-47","subject":"基本知识","chapter":"人文与社会","stem":"普通技工被晋升为工厂厂长，这种地位变化属于：","options":["水平流动","向上的垂直流动","结构性失业","再社会化失败"],"answer":1,"explanation":"垂直流动是社会地位上升或下降，从技工到厂长是向上流动。水平流动是地位大致相当的变换，例如同级岗位调动。失业是失去工作。晋升是地位上升，不是再社会化失败。","source":"原创练习"},{"id":"rw-48","subject":"基本知识","chapter":"人文与社会","stem":"发源于江苏昆山一带、后来被称为百戏之祖的戏曲是：","options":["昆曲","京剧","越剧","黄梅戏"],"answer":0,"explanation":"昆曲经明代改良后广为流传，对后来许多剧种的声腔和表演都有影响，因而称百戏之祖。京剧形成于清代北京。越剧源于浙江，黄梅戏发展于安徽。后三者受过昆曲影响，但不是这一称号所指。","source":"原创练习"},{"id":"yy-01","subject":"岗位能力","chapter":"言语理解与表达","stem":"填入画横线处最恰当的一项是：核对页码必须在装订之前完成。若两步次序____，装订后再拆开，等于同一份材料做了两遍。","options":["前后颠倒","轻重不分","详略失当","主次分明"],"answer":0,"explanation":"次序说的是先后。前后颠倒对应把装订和核对做反了。最接近的轻重不分说的是哪一步更重要，文段只规定谁先谁后，没有比较轻重。","source":"原创练习"},{"id":"yy-02","subject":"岗位能力","chapter":"言语理解与表达","stem":"填入画横线处最恰当的一项是：值班日志要让接班的人一眼看清发生了什么，用语应当____，把时间、地点和处置写全即可。","options":["生动","平实","委婉","铺陈"],"answer":1,"explanation":"日志要能核对，平实可以把事实写清楚。最接近的生动适合讲故事，却会让形容盖过可核对的信息，接班人更难看清处置。","source":"原创练习"},{"id":"yy-03","subject":"岗位能力","chapter":"言语理解与表达","stem":"填入画横线处最恰当的一项是：老旧营房改造不能只换门窗，管线、消防和排水要____推进；只做表面，隐患会在雨季____。","options":["陆续；自行消失","暂停；提前排除","同步；集中显现","单独；逐步缓解"],"answer":2,"explanation":"文段否定只做表面，所以相关项目要一起做，隐患会在雨季集中显现。最接近的陆续；自行消失好像也在说分步施工，但自行消失和隐患的走向相反。","source":"原创练习"},{"id":"yy-04","subject":"岗位能力","chapter":"言语理解与表达","stem":"填入画横线处最恰当的一项是：两份名单行号不同、人数相同。比对时应以证件号为____，姓名只作辅助，避免同名被错配。","options":["点缀","障碍","例外","准绳"],"answer":3,"explanation":"准绳是拿来对照的标准，证件号承担的就是这个作用。最接近的点缀好像也承认姓名之外还有信息，但点缀只是陪衬，不能当比对依据。","source":"原创练习"},{"id":"yy-05","subject":"岗位能力","chapter":"言语理解与表达","stem":"填入画横线处最恰当的一项是：复盘时若一上来就追究个人，大家会忙着辩解，事实和时间线反而被____。","options":["搁置","坐实","公开","重申"],"answer":0,"explanation":"忙着辩解之后，事实没有被继续核对，而是被放到一边，所以是搁置。最接近的坐实表示已经查清并确定，和还没对齐就追究的语境相反。","source":"原创练习"},{"id":"yy-06","subject":"岗位能力","chapter":"言语理解与表达","stem":"填入画横线处最恰当的一项是：高峰时段增设一个只供套餐的窗口，是为了把人流____开，而不是为了减少菜品。","options":["聚集","分流","截留","混杂"],"answer":1,"explanation":"多开一个窗口是把排队的人分走，所以是分流。最接近的截留也像在控制人流，但截留是拦住，队伍会更长，和缩短等待相反。","source":"原创练习"},{"id":"yy-07","subject":"岗位能力","chapter":"言语理解与表达","stem":"填入画横线处最恰当的一项是：转发通知时删掉附件、只留正文，接收方会____附件里的数据，并不是有人改写了正文。","options":["篡改","夸大","遗漏","重复"],"answer":2,"explanation":"附件被删掉，是数据没有带到，所以是遗漏。最接近的篡改也表示信息不对，但正文并没有被改写，不能把没带上说成改写了。","source":"原创练习"},{"id":"yy-08","subject":"岗位能力","chapter":"言语理解与表达","stem":"填入画横线处最恰当的一项是：器材入库的外观检查要____，划痕、缺件和封条异常都记入同一张表，不能只看最外面一层。","options":["走马观花","点到为止","不求甚解","逐项过目"],"answer":3,"explanation":"都记入要求一项一项看，所以是逐项过目。最接近的走马观花也是在看，但是粗看，和不能只看最外面一层矛盾。","source":"原创练习"},{"id":"yy-09","subject":"岗位能力","chapter":"言语理解与表达","stem":"填入画横线处最恰当的一项是：安全须知里把禁止和应当分列，是为了让界限更____，省得读者从一段长话里自己猜。","options":["明确","弹性","笼统","隐晦"],"answer":0,"explanation":"分列是为了减少猜测，界限要明确。最接近的弹性像是留有余地，但文段要的是读者不用猜，不是留下解释空间。","source":"原创练习"},{"id":"yy-10","subject":"岗位能力","chapter":"言语理解与表达","stem":"填入画横线处最恰当的一项是：图书推荐语写得____，读者就能分辨哪本适合入门、哪本适合深读，不必把目录再抄一遍。","options":["含糊其辞","言简意赅","洋洋洒洒","闪烁其词"],"answer":1,"explanation":"短而把读者对象说清楚，是言简意赅。最接近的洋洋洒洒像是写得很完整，但又长又顺不等于能区分对象，文段强调不必把目录再抄一遍。","source":"原创练习"},{"id":"yy-11","subject":"岗位能力","chapter":"言语理解与表达","stem":"夜航保障不是把灯光全部调到最亮。跑道、滑行道和停机位的亮度要随能见度和任务阶段调整：能见度好时过亮会造成眩光，能见度差时亮得不够又会让地标难以辨认。值班员应按当夜标准逐项核对，而不是凭越亮越安全操作。这段文字主要说明：","options":["能见度好时应关闭全部灯光","值班员凭印象操作即可","夜航灯光应按当夜标准调整亮度","灯光一旦调定就不再改动"],"answer":2,"explanation":"落点是按当夜标准调整亮度，既反对过亮，也反对不足。最接近的能见度好时应关闭全部灯光，把避免眩光夸成了关闭，原文只要求按标准调低，不是全部关掉。","source":"原创练习"},{"id":"yy-12","subject":"岗位能力","chapter":"言语理解与表达","stem":"档案数字化之后，纸质原件仍应按规定期限保存。扫描件便于检索，但遇争议时，往往要以原件上的印章、骑缝和纸张状态作为核对依据。因此，检索系统上线并不意味着库房可以立即清空。这段文字主要说明：","options":["扫描件可以完全替代原件","印章只能在扫描件上辨认","库房应在系统上线当天清空","数字化便于检索，但不能因此放弃应保存的纸质原件"],"answer":3,"explanation":"文段先承认扫描件好检索，接着用转折把重点转到原件仍要保存。最接近的扫描件可以完全替代原件只接住了前一半，被后文的核对依据否定。","source":"原创练习"},{"id":"yy-13","subject":"岗位能力","chapter":"言语理解与表达","stem":"班组周例会若只念上周完成数，问题会被平均数盖住。把延误、返工和临时插入的事项单独列出，并写明原因和下周改法，例会才会从报数字变成改做法。这段文字主要说明：","options":["例会要把问题单列出来并写明改法","例会只要宣读完成数就够了","平均数会自动暴露延误和返工","临时插入的事项不必写入记录"],"answer":0,"explanation":"才会后面是中心：单列问题并写明改法。最接近的例会只要宣读完成数就够了，是开头否定的做法；平均数恰恰会把问题盖住。","source":"原创练习"},{"id":"yy-14","subject":"岗位能力","chapter":"言语理解与表达","stem":"新兵炊事培训常把刀工课时排得很满，却把留样、餐具消毒和过敏原标识挤到最后半小时。一旦前面超时，这几项就被口头带过。食品安全依赖的正是这些容易被挤掉的步骤，课时应给它们留出不能占用的固定时段。这段文字主要说明：","options":["刀工课时应当全部取消","食品安全步骤应占有不可挤占的固定课时","过敏原标识适合下课前口头提一句","课时超时说明内容已经讲透"],"answer":1,"explanation":"文段点名留样、消毒和标识容易被挤掉，结论是给它们固定时段。最接近的口头提一句，正是文段批评的口头带过，不能当作安排办法。","source":"原创练习"},{"id":"yy-15","subject":"岗位能力","chapter":"言语理解与表达","stem":"库房温湿度如果只在下班前补填全天数据，曲线会看起来平稳，却丢掉中午超标的时刻。记录的价值在于抓住波动发生的时间，所以应按间隔实记，发现超标当即注明处置。这段文字主要说明：","options":["下班前一次补记更整齐","曲线平稳就可以认定全天合格","记录要如实抓住波动并注明处置","超标只需在次日汇总里说明"],"answer":2,"explanation":"中心是按间隔实记波动，并写上当时的处置。最接近的曲线平稳就可以认定全天合格，把补记造成的假象当成了结论，原文说这种平稳会丢掉超标时刻。","source":"原创练习"},{"id":"yy-16","subject":"岗位能力","chapter":"言语理解与表达","stem":"外来施工人员进入营区，陪同不只是领路。陪同人要确认对方只在批准的区域作业，临时离开时作业应暂停，完工后核对工具是否全部带出。把陪同理解成送到门口即可，会留下人员和物品的管控缺口。这段文字主要说明：","options":["陪同把人送到门口就可以离开","施工人员可以自行进入相邻区域","工具可以等到下周再清点","陪同要管住作业区域、临时离岗和工具带出"],"answer":3,"explanation":"区域、离岗、工具三个动作合在一起，才是陪同的职责。最接近的送到门口就可以离开，是原文点名会留下缺口的理解。","source":"原创练习"},{"id":"yy-17","subject":"岗位能力","chapter":"言语理解与表达","stem":"公文标题过长，往往是把正文里的背景也塞了进去。标题只需标明事由和文种，背景、依据和过程放到正文开头。标题堆满信息，接收方越难在列表里快速认出这份文件。这段文字主要说明：","options":["标题标明事由和文种即可，背景留给正文","标题应写入背景、依据和全过程","为了缩短标题可以不写文种","接收方主要靠正文第一句认文件"],"answer":0,"explanation":"文段把标题的任务收成事由加文种。最接近的应写入背景、依据和全过程，正是标题变长的原因，也是文段要求挪到正文里的内容。","source":"原创练习"},{"id":"yy-18","subject":"岗位能力","chapter":"言语理解与表达","stem":"车辆回场若只看外观和油量，刹车、灯光和轮胎气压的小故障会留到次日上路才发现。回场时按短清单逐项打勾，比次日抢修更省出车时间。清单要短到值班员愿意逐项打勾，过长的清单最后常常被整页签掉。这段文字主要说明：","options":["回场只登记油量和外观即可","短而必须逐项打勾的清单更容易落实","清单越长执行就越完整","小故障留到次日出车再处理更从容"],"answer":1,"explanation":"文段比较的是短而必做和过长被整页签掉，结论是短清单更容易落实。最接近的清单越长执行就越完整，和后一句相反，长清单反而签得更马虎。","source":"原创练习"},{"id":"yy-19","subject":"岗位能力","chapter":"言语理解与表达","stem":"学员提问后，教员若立刻给出完整结论，课堂会很快，但学员少了自己组织理由的机会。更好的做法是先让提问者说出已经排除的选项和依据，教员只补充被忽略的条件。这样一次提问就变成一次思路校对。这段文字主要说明：","options":["教员不必回答，以免打乱节奏","提问应一律改到课后书面提交","先听学员的排除过程，再补充遗漏条件","立刻给出完整结论最有利于学员组织理由"],"answer":2,"explanation":"更好的做法是后面就是主旨：先听排除过程，再补遗漏条件。最接近的立刻给出完整结论，文段承认它更快，但会挤掉组织理由的机会，并不是推荐的做法。","source":"原创练习"},{"id":"yy-20","subject":"岗位能力","chapter":"言语理解与表达","stem":"连队图书借阅率下降，不一定是书不受欢迎。有的连队把借还时间定在正课期间，战士无法到场；改到晚点名前的二十分钟开放后，同一批书的借出量明显回升。调整开放时段，有时比再买一批新书更先见效。这段文字主要说明：","options":["借阅率下降就能说明这批书不受欢迎","提高借阅率只能靠继续买新书","晚点名前的时间不应用于借还","开放时段若错开战士能到场的时间，借阅会被压低"],"answer":3,"explanation":"同一批书在改时段后借出回升，说明能到场的时间才是直接原因。最接近的书不受欢迎，是文段用不一定先放下的解释，后文的对照并不支持它。","source":"原创练习"},{"id":"yy-21","subject":"岗位能力","chapter":"言语理解与表达","stem":"某仓库本月盘点：A区账实相符；B区账上120件、实有117件，短少3件已登记待查；C区实有比账多2件，多出的被认定为上月未入账的退库。盘点当天没有报废。根据上文，下列说法正确的是：","options":["C区多出的2件被认定为上月未入账的退库","B区短少的3件已经报废","A区账实不一致","三个区都出现了短少"],"answer":0,"explanation":"原文对C区的定性就是上月未入账的退库。最接近的已经报废抓住了B区确实短少，但原文是登记待查，并且写明当天没有报废。","source":"原创练习"},{"id":"yy-22","subject":"岗位能力","chapter":"言语理解与表达","stem":"通知写明：周六上午9时在礼堂进行健康讲座，对象为在营的文职人员；值班人员听录音回放，不要求到场。讲座约40分钟，结束后可自愿领取纸质提纲。根据上文，下列说法与原文不符的是：","options":["讲座安排在周六上午","值班人员必须到礼堂听讲","对象包括在营的文职人员","纸质提纲可以不领"],"answer":1,"explanation":"这题要选与原文不符的一项。值班人员原文是听录音、不要求到场，不是必须到礼堂。最容易误选提纲可以不领：可自愿领取就是可以不领，这一项与原文相符。","source":"原创练习"},{"id":"yy-23","subject":"岗位能力","chapter":"言语理解与表达","stem":"训练基地开放时间：周一至周五6:30至21:00，周六8:00至17:00，周日检修闭馆。在上述开放日内若遇雨天，取消室外跑道，室内馆照常。外来人员须提前一天预约。根据上文，下列说法正确的是：","options":["周日室内馆仍然开放","周六与工作日开放的时长相同","外来人员要提前一天预约","雨天室内馆一并关闭"],"answer":2,"explanation":"末句直接规定外来人员提前一天预约。最接近的周日室内馆仍然开放，误用了雨天室内馆照常；照常只发生在开放日，周日已经检修闭馆。","source":"原创练习"},{"id":"yy-24","subject":"岗位能力","chapter":"言语理解与表达","stem":"采购清单：笔记本80本、签字笔10盒、文件夹24个。笔记本周四送达，笔和文件夹周五送达。验收时笔记本少2本，已当场补齐；文件夹多1个，已退回。笔的数量与清单一致。根据上文，下列说法正确的是：","options":["三类物品在同一天送达","文件夹短少1个","签字笔比清单少1盒","验收结束后笔记本数量与清单一致"],"answer":3,"explanation":"少的2本已经当场补齐，验收结束时笔记本仍是清单上的80本。最接近的文件夹短少1个也看到了数量差异，但原文是多1个并已退回，不是短少。","source":"原创练习"},{"id":"yy-25","subject":"岗位能力","chapter":"言语理解与表达","stem":"阅览室规定：每次最多借3册，期限14天，可续借1次，续借后再延长14天。逾期每天每册记0.1个信用分，满1分暂停借阅30天。工具书不外借。根据上文，下列说法与原文不符的是：","options":["工具书可以按14天外借","续借一次后借期最长可以达到28天","一次最多借3册","信用分累计满1分会暂停借阅30天"],"answer":0,"explanation":"题干问的是不符项。原文写明工具书不外借，所以可以按14天外借不成立。最容易漏看续借后再延长14天：14天再加14天是28天，这一项与原文相符，不能选。","source":"原创练习"},{"id":"yy-26","subject":"岗位能力","chapter":"言语理解与表达","stem":"某日车班：甲车7:00出发去市区接人，预计9:30返回；乙车全天在营区待命；丙车13:00送物资到邻县，返回不早于16:00。上午10:00营区临时需要一辆车，调度改派了乙车。根据上文，下列说法正确的是：","options":["上午10:00改派的是甲车","乙车原计划全天在营区待命","丙车上午已经回到营区","甲车预计上午11:00返回"],"answer":1,"explanation":"原文先写乙车全天待命，后文改派的也是乙车。最接近的改派的是甲车只抓住10:00确实改派了一辆车，但对象写的是乙，不是预计9:30返回的甲。","source":"原创练习"},{"id":"yy-27","subject":"岗位能力","chapter":"言语理解与表达","stem":"体检安排：第一批7:40集合，项目为血压、视力和抽血；第二批9:00集合，项目相同，但不抽血。抽血者需空腹，可在抽血后领取延时早餐券。未抽血者不发放该券。根据上文，下列说法正确的是：","options":["第二批也要抽血","第二批比第一批集合更早","抽血者可以在抽血之后领取延时早餐券","未抽血的人同样发放延时早餐券"],"answer":2,"explanation":"领券被限定在抽血之后，主体是抽血者。最接近的未抽血的人同样发放沿用了早餐券这个信息，但把发放对象扩大了，末句已经排除。","source":"原创练习"},{"id":"yy-28","subject":"岗位能力","chapter":"言语理解与表达","stem":"岗位说明：文电岗负责收发和登记，不负责拟稿；拟稿由业务科完成。文电岗发现附件缺失时，应退回业务科补齐，不得自行用旧附件顶替。紧急件登记后30分钟内送出。根据上文，下列说法与原文不符的是：","options":["文电岗负责登记","附件缺失时应退回业务科补齐","紧急件登记后要在30分钟内送出","文电岗可以用旧附件先顶上"],"answer":3,"explanation":"这题选不符的说法。用旧附件先顶上，与不得自行用旧附件顶替直接相反。其余三项都能在原文找到对应句，不能因为紧急件要快就推断允许顶替。","source":"原创练习"},{"id":"yy-29","subject":"岗位能力","chapter":"言语理解与表达","stem":"培训通知：初级班限40人，已报名36人。剩余名额优先给未参加过同类培训的人。已结业者可以旁听，不占这4个名额，旁听不发结业证。报名周三17:00截止。根据上文，下列说法正确的是：","options":["剩余4个名额优先给没有参加过同类培训的人","已结业者旁听会计入40人的名额","旁听结束后发放结业证","报名截止时间是周四17:00"],"answer":0,"explanation":"40减36等于4，原文规定这4个名额优先给未参加过同类培训的人。最接近的旁听计入名额承认可以旁听，但原文写的是不占这4个名额。","source":"原创练习"},{"id":"yy-30","subject":"岗位能力","chapter":"言语理解与表达","stem":"某办公室本周领用：A4纸5包、硒鼓1个、订书钉3盒。纸和订书钉周一已发；硒鼓缺货，预计周四到货。到货前借用邻室旧硒鼓，归还期限不超过周五。旧硒鼓不计入本周领用数。根据上文，下列说法正确的是：","options":["硒鼓已在周一发给该办公室","旧硒鼓的归还期限不超过周五","借用的旧硒鼓要算进本周领用数","订书钉尚未发放"],"answer":1,"explanation":"借用句后面直接写了归还不超过周五。最接近的要算进领用数看到旧硒鼓确实在用，但末句规定不计入本周领用数。","source":"原创练习"},{"id":"yy-31","subject":"岗位能力","chapter":"言语理解与表达","stem":"将下列句子组成语意连贯的语段，排序正确的是：①比对出差异后只登记，不在现场改账②从系统导出当日账面数量③按货位逐件清点实数④把实数与账面逐项比对⑤全部货位比对结束后，双人签署盘点表","options":["③②④①⑤","②①③④⑤","②③④①⑤","②③①④⑤"],"answer":2,"explanation":"先导出账面②，再清点③，再比对④，之后才登记差异①，最后签署⑤。最接近的②③①④⑤把比对出差异后放到了比对之前，差异还没比出来。","source":"原创练习"},{"id":"yy-32","subject":"岗位能力","chapter":"言语理解与表达","stem":"将下列句子组成语意连贯的语段，排序正确的是：①装订完成后才能在侧面盖骑缝标记②发放前核对骑缝标记与签收单编号③正文要先检查，避免装订后难以替换缺页④检查无误后再套上封面和目录⑤封面套好后再装订","options":["③⑤④①②","①③④⑤②","③④①⑤②","③④⑤①②"],"answer":3,"explanation":"③先检查，④再套封面，⑤才能装订，①装订后才盖骑缝，②发放前核对。最接近的③⑤④①②把封面套好后再装订放在套上封面之前，前提还没发生。","source":"原创练习"},{"id":"yy-33","subject":"岗位能力","chapter":"言语理解与表达","stem":"将下列句子组成语意连贯的语段，排序正确的是：①因此把室外考核改到室内教室②前一日傍晚预报有持续降雨③室内座位不够的人员改期，并且不并入其他连队④改期名单在开考前一小时张贴⑤开考前两小时确认雨势没有减弱","options":["②⑤①③④","②①⑤③④","⑤②①③④","②⑤③①④"],"answer":0,"explanation":"先有预报②，开考前两小时确认⑤，因此才改室内①；座位不够的人改期③，名单在开考前一小时张贴④。最接近的②①⑤③④把因此放在确认雨势之前，结论早于依据。","source":"原创练习"},{"id":"yy-34","subject":"岗位能力","chapter":"言语理解与表达","stem":"将下列句子组成语意连贯的语段，排序正确的是：①过期物品单独封存并登记②按清单把物品全部取出③对照有效期逐一查看④剔除过期品后，缺项当即补齐⑤数量与清单一致后再放回原位","options":["②①③④⑤","②③①④⑤","③②①④⑤","②③④①⑤"],"answer":1,"explanation":"先取出②，再看有效期③，然后封存过期品①，剔除之后才能补缺④，数量一致再放回⑤。最接近的②③④①⑤把剔除过期品后才补齐放在封存之前，补数仍把即将剔除的物品算在里面。","source":"原创练习"},{"id":"yy-35","subject":"岗位能力","chapter":"言语理解与表达","stem":"将下列句子组成语意连贯的语段，排序正确的是：①再写清时间、地点和需要携带的物品②先用一句话说明要办的事项③最后补充联系人，以及变更时通知哪一个渠道④然后删去与接收人无关的背景⑤发出前通读一遍，去掉重复的句子","options":["①②④③⑤","②①③④⑤","②①④③⑤","②④①③⑤"],"answer":2,"explanation":"②的先开头，①的再紧跟，④的然后在具体内容之后，③的最后补联系人，⑤发出前收尾。最接近的②①③④⑤把然后删背景放到了最后补充之后，顺序词互相冲突。","source":"原创练习"},{"id":"yy-36","subject":"岗位能力","chapter":"言语理解与表达","stem":"将下列句子组成语意连贯的语段，排序正确的是：①返回后按出发时的路线登记里程②出发前核对通行证和天气③途中每到检查点报告一次位置④里程与通行证一并交回调度⑤确认油量、备胎和灯光后再驶出","options":["⑤②③①④","②⑤①③④","②③⑤①④","②⑤③①④"],"answer":3,"explanation":"出发前先核对②，确认车况后再驶出⑤，途中报告③，返回登记①，最后把里程和通行证一起交回④。最接近的⑤②③①④让再驶出发生在核对通行证之前，车已经出去了。","source":"原创练习"},{"id":"yy-37","subject":"岗位能力","chapter":"言语理解与表达","stem":"将下列句子组成语意连贯的语段，排序正确的是：①不合格者在一周内补考一次②先公布考核范围和参考资料③再组织闭卷测验④测验结束后按标准匿名评卷⑤补考仍不合格的安排复训，不直接记为通过","options":["②③④①⑤","②④③①⑤","③②④①⑤","②③①④⑤"],"answer":0,"explanation":"②先公布范围，③再测验，④评卷之后才知道谁不合格，才能①补考，⑤处理仍不合格的人。最接近的②③①④⑤把补考放到评卷之前，此时还没有成绩。","source":"原创练习"},{"id":"yy-38","subject":"岗位能力","chapter":"言语理解与表达","stem":"将下列句子组成语意连贯的语段，排序正确的是：①确认取样量合格后，给每份样品标注时间、窗口和操作者②标注后放入冷藏，保存到规定时长③开餐前从每个窗口取样④保存到期后由双人销毁并登记⑤取样量不足的窗口当天不得开餐","options":["①③⑤②④","③⑤①②④","③①②⑤④","③⑤②①④"],"answer":1,"explanation":"开餐前取样③，量不足则不得开餐⑤，合格后才标注①，然后冷藏②，到期销毁④。最接近的③①②⑤④先标注、冷藏，把不得开餐的判断放到了已经开过餐之后。","source":"原创练习"},{"id":"yy-39","subject":"岗位能力","chapter":"言语理解与表达","stem":"将下列句子组成语意连贯的语段，排序正确的是：①审核通过后，把器材放回原货位②放回时在货位卡上写下退库日期③入库前先核对实物与退库单④核对发现数量不符的，整单退回，不进入清洁⑤整单未退回的，清洁后送审","options":["④③⑤①②","③⑤④①②","③④⑤①②","③④①⑤②"],"answer":2,"explanation":"先核对③，不符则整单退回④，未退回的才清洁送审⑤，审核通过后放回①，放回时写日期②。最接近的③⑤④①②让清洁送审发生在不符就退回之前，不合格的单子可能已经送审。","source":"原创练习"},{"id":"yy-40","subject":"岗位能力","chapter":"言语理解与表达","stem":"将下列句子组成语意连贯的语段，排序正确的是：①会后把决定写入值班板②先用两分钟对齐昨日未完成事项③再确认今日人员和车辆④人员和车辆都明确后，才分配临时任务⑤临时任务分配完，散会","options":["③②④⑤①","②③⑤④①","②③④①⑤","②③④⑤①"],"answer":3,"explanation":"②先对齐昨日，③再确认今日人车，④之后才分配，⑤分配完散会，①会后写板。最接近的②③⑤④①把分配完才散会放到了分配之前，会已经散了，任务还没分。","source":"原创练习"},{"id":"sl-01","subject":"岗位能力","chapter":"数量关系","stem":"书架上层有36本，中层比上层少8本，下层比中层多15本。三层一共有多少本？","options":["107本","99本","115本","121本"],"answer":0,"explanation":"中层是36−8=28本，下层是28+15=43本，合计36+28+43=107本。最接近的99本把下层算成28+(15−8)=35本，也就是把比中层多15减掉了上层已经少的8本，36+28+35=99。","source":"原创练习"},{"id":"sl-02","subject":"岗位能力","chapter":"数量关系","stem":"一份名单有240人，已核对其中的3/5。尚未核对的有多少人？","options":["144人","96人","120人","80人"],"answer":1,"explanation":"已核对占3/5，未核对占1−3/5=2/5，240×2/5=96人。最接近的144人是已经核对的3/5，问的是剩下的部分，不能把已完成人数填进来。","source":"原创练习"},{"id":"sl-03","subject":"岗位能力","chapter":"数量关系","stem":"打印机每分钟打印12页，一份材料有180页。中途卡纸耽误3分钟，这3分钟不打印。从开始到打完共用多少分钟？","options":["15分钟","21分钟","18分钟","12分钟"],"answer":2,"explanation":"净打印时间是180÷12=15分钟，卡纸的3分钟要另加，15+3=18分钟。最接近的15分钟只算了出纸时间，把题目单列的耽误漏掉了。","source":"原创练习"},{"id":"sl-04","subject":"岗位能力","chapter":"数量关系","stem":"某库第一周用水36吨，第二周比第一周少1/4，第三周比第二周多6吨，第四周与第三周相同。四周一共用水多少吨？","options":["123吨","135吨","141吨","129吨"],"answer":3,"explanation":"第二周36×(1−1/4)=27吨，第三周27+6=33吨，第四周也是33吨，合计36+27+33+33=129吨。最接近的123吨把第四周误写成第二周的27吨，36+27+33+27=123。","source":"原创练习"},{"id":"sl-05","subject":"岗位能力","chapter":"数量关系","stem":"编号从1001连续编到1048，一共有多少个号？","options":["48个","47个","49个","50个"],"answer":0,"explanation":"连续编号的个数是末号减首号再加1：1048−1001+1=48。最接近的47个只做了1048−1001，两端都要计入时少算了1个。","source":"原创练习"},{"id":"sl-06","subject":"岗位能力","chapter":"数量关系","stem":"买6支笔和4本笔记本共花52元，笔每支3元。笔记本每本多少元？","options":["8元","8.5元","9元","7.5元"],"answer":1,"explanation":"笔的钱是6×3=18元，剩下52−18=34元是4本笔记本的，34÷4=8.5元。最接近的8元把34÷4的余数丢掉了，34不能整除成8。","source":"原创练习"},{"id":"sl-07","subject":"岗位能力","chapter":"数量关系","stem":"一个数除以9余5，除以4余1，并且在60到80之间。这个数是多少？","options":["73","75","77","79"],"answer":2,"explanation":"9和4互质，公共周期是36。5除以4正好余1，所以这个数可以写成36k+5。k=2时得77，落在60到80之间。验算：77÷9=8余5，77÷4=19余1。最接近的73除以4也余1，但73÷9=8余1，不满足除以9余5。","source":"原创练习"},{"id":"sl-08","subject":"岗位能力","chapter":"数量关系","stem":"商店满100元减20元，每位顾客限用一次。买了48元、36元、30元三件商品，应付多少元？","options":["114元","84元","74元","94元"],"answer":3,"explanation":"三件合计48+36+30=114元，超过100元，只能减一次20元，应付94元。最接近的84元相当于114−20之后又多减了10元；114没有满第二个100，不能再减。","source":"原创练习"},{"id":"sl-09","subject":"岗位能力","chapter":"数量关系","stem":"一个正方形的边长增加2厘米，面积就增加36平方厘米。原来的边长是多少厘米？","options":["8厘米","10厘米","6厘米","16厘米"],"answer":0,"explanation":"设原边长为x厘米，(x+2)²−x²=4x+4=36，于是4x=32，x=8。最接近的10厘米把4x+4=36错写成4x−4=36，得到4x=40，x=10。","source":"原创练习"},{"id":"sl-10","subject":"岗位能力","chapter":"数量关系","stem":"四次小测的成绩是78分、85分、91分、82分。再考一次后，五次的平均分是84分。第五次考了多少分？","options":["86分","84分","88分","80分"],"answer":1,"explanation":"前四次之和78+85+91+82=336，平均已经是336÷4=84分。五次总分是5×84=420，第五次是420−336=84分。最接近的86分以为必须靠更高的分数把平均拉到84，其实前四次平均已经是84，第五次等于84就能保持。","source":"原创练习"},{"id":"sl-11","subject":"岗位能力","chapter":"数量关系","stem":"甲、乙、丙的资金比是2:3:5，一共8000元。乙比甲多多少元？","options":["1600元","2400元","800元","400元"],"answer":2,"explanation":"总份数2+3+5=10，每份8000÷10=800元。乙是3份、甲是2份，相差1份，就是800元。最接近的1600元是甲的全部金额，问的是两人相差的那一份。","source":"原创练习"},{"id":"sl-12","subject":"岗位能力","chapter":"数量关系","stem":"果汁和水按2:3配成500毫升饮料。其中果汁有多少毫升？","options":["300毫升","250毫升","150毫升","200毫升"],"answer":3,"explanation":"果汁占2/(2+3)=2/5，500×2/5=200毫升。最接近的300毫升是水所占的3/5，把前后项看反了。","source":"原创练习"},{"id":"sl-13","subject":"岗位能力","chapter":"数量关系","stem":"一幅地图的比例尺是1:50000，图上距离为4厘米。实际距离是多少千米？","options":["2千米","0.2千米","20千米","200千米"],"answer":0,"explanation":"图上1厘米代表实际50000厘米，也就是0.5千米，4厘米代表4×0.5=2千米。最接近的200千米把1:50000理解成1厘米代表50千米，4×50=200，放大了100倍。","source":"原创练习"},{"id":"sl-14","subject":"岗位能力","chapter":"数量关系","stem":"男生与女生的人数比是5:3，男生比女生多24人。一共有多少人？","options":["72人","96人","120人","64人"],"answer":1,"explanation":"相差5−3=2份，2份=24人，1份=12人。总份数是8，一共8×12=96人。最接近的72人是24×3，只拿女生的份数去乘人数差，没有先求出每一份是多少。","source":"原创练习"},{"id":"sl-15","subject":"岗位能力","chapter":"数量关系","stem":"铜和锌按7:3制成合金。现有铜35千克，按这个比例还需要锌多少千克？","options":["10千克","21千克","15千克","12千克"],"answer":2,"explanation":"铜的7份对应35千克，每份5千克，锌的3份是15千克。最接近的21千克用了35×3/5，把铜当成了5份，而不是7份。","source":"原创练习"},{"id":"sl-16","subject":"岗位能力","chapter":"数量关系","stem":"甲、乙的速度比是4:5。走同一段路，甲用50分钟，乙要用多少分钟？","options":["62.5分钟","45分钟","60分钟","40分钟"],"answer":3,"explanation":"路程相同，时间与速度成反比，时间比是5:4。甲的50分钟对应5份，每份10分钟，乙的4份是40分钟。最接近的62.5分钟是50×5/4，把反比做成了正比，快的一方反而用时更长。","source":"原创练习"},{"id":"sl-17","subject":"岗位能力","chapter":"数量关系","stem":"桶里有药液20升，浓度是15%。倒出4升后加满清水，现在的浓度是多少？","options":["12%","10%","15%","11%"],"answer":0,"explanation":"原溶质20×15%=3升。倒出4/20=1/5，溶质剩3×4/5=2.4升。加满后仍是20升，浓度2.4÷20=12%，也可直接算15%×(1−4/20)=12%。最接近的10%把倒出的4升误当成整桶的1/3，15%×2/3=10%。","source":"原创练习"},{"id":"sl-18","subject":"岗位能力","chapter":"数量关系","stem":"一笔奖金按3:4:5发给三人，最少的一位得1800元。奖金总额是多少元？","options":["5400元","7200元","9000元","6000元"],"answer":1,"explanation":"最少的是3份，3份=1800元，1份=600元。总份数12，总额12×600=7200元。最接近的6000元用了1800÷3×10，把总份数算成10，少算了2份。","source":"原创练习"},{"id":"sl-19","subject":"岗位能力","chapter":"数量关系","stem":"抽检150件产品，合格率从80%提高到92%。合格件数增加了多少件？","options":["12件","15件","18件","20件"],"answer":2,"explanation":"合格率提高92−80=12个百分点，增加件数是150×12%=18件。最接近的12件只写下了百分点之差，没有乘上150这个基数。","source":"原创练习"},{"id":"sl-20","subject":"岗位能力","chapter":"数量关系","stem":"同一时刻，树高与影长的比是5:3，影长6米。树高是多少米？","options":["9米","12米","8米","10米"],"answer":3,"explanation":"树高与影长是5:3，树高=6×5/3=10米。最接近的9米来自6×3/2，把5:3的前后项弄反后取了另一个倍数。","source":"原创练习"},{"id":"sl-21","subject":"岗位能力","chapter":"数量关系","stem":"一项工作，甲单独做12天完成，乙单独做8天完成。两人合作，需要多少天？","options":["4.8天","5天","4天","6天"],"answer":0,"explanation":"甲的效率是1/12，乙的效率是1/8，合作效率1/12+1/8=2/24+3/24=5/24，天数是24/5=4.8天。最接近的5天把24/5四舍五入成整数，题目要的是精确天数。","source":"原创练习"},{"id":"sl-22","subject":"岗位能力","chapter":"数量关系","stem":"一项工作，甲、乙合作6天可以完成，甲单独做需要10天。乙单独做需要多少天？","options":["12天","15天","18天","20天"],"answer":1,"explanation":"合作效率是1/6，甲的效率是1/10，乙的效率是1/6−1/10=1/15，所以乙单独做要15天。最接近的12天相当于用6×10÷(10−5)来算，把分母里的6误换成了5。","source":"原创练习"},{"id":"sl-23","subject":"岗位能力","chapter":"数量关系","stem":"一项工程，甲单独做需要15天。甲先单独做4天，乙再加入，两人又一起做了6天才完成。乙单独做需要多少天？","options":["12天","16天","18天","20天"],"answer":2,"explanation":"甲一共做了4+6=10天，完成10/15=2/3，剩下1/3由乙用6天完成。乙的效率是(1/3)÷6=1/18，单独做要18天。最接近的12天把剩下的工作当成一半，(1/2)÷6的倒数是12，但甲10天完成的是2/3，不是1/2。","source":"原创练习"},{"id":"sl-24","subject":"岗位能力","chapter":"数量关系","stem":"甲、乙的工作效率比是3:2，两人合作10天完成一项任务。甲单独做需要多少天？","options":["20天","15天","25天","16又2/3天"],"answer":3,"explanation":"两人每天共完成3+2=5份，10天是50份。甲每天3份，50÷3=16又2/3天。最接近的15天是10×3/2，只拿效率比去乘天数，没有把总工作量50份除以甲每天的3份。","source":"原创练习"},{"id":"sl-25","subject":"岗位能力","chapter":"数量关系","stem":"一个空池，进水管6小时可以注满，出水管8小时可以放完。先只开进水管2小时，再将两管同时打开。还要多少小时才能注满？","options":["16小时","24小时","12小时","8小时"],"answer":0,"explanation":"先注入2/6=1/3，还剩2/3。两管净效率是1/6−1/8=1/24，所需时间是(2/3)÷(1/24)=16小时。最接近的24小时是空池从一开始就两管同开的时间，忘记已经注入了1/3。","source":"原创练习"},{"id":"sl-26","subject":"岗位能力","chapter":"数量关系","stem":"甲机每小时打印30页，乙机每小时打印20页。一份400页的材料，甲先打2小时，然后两机一起打。还要多少小时？","options":["8小时","6.8小时","6小时","7.5小时"],"answer":1,"explanation":"甲先完成30×2=60页，剩下340页。两机每小时共50页，340÷50=6.8小时。最接近的8小时是400÷50，把已经打完的60页又算进了剩余工作。","source":"原创练习"},{"id":"sl-27","subject":"岗位能力","chapter":"数量关系","stem":"一项工程，甲、乙合作12天完成，乙、丙合作15天完成，甲、丙合作20天完成。三人一起合作，需要多少天？","options":["5天","8天","10天","12天"],"answer":2,"explanation":"1/12+1/15+1/20=5/60+4/60+3/60=1/5。两两相加时每个人都被算了两次，三人效率和是(1/5)÷2=1/10，所以需要10天。最接近的5天忘记除以2，把1/5直接当成了三人效率和。","source":"原创练习"},{"id":"sl-28","subject":"岗位能力","chapter":"数量关系","stem":"一段路原计划由15人用12天修完。开工4天后调走3人，剩下的工作还要多少天？","options":["8天","9天","12天","10天"],"answer":3,"explanation":"总工作量是15×12=180人天，已完成15×4=60人天，剩下120人天。还剩15−3=12人，120÷12=10天。最接近的8天用120÷15来除，调走的3人仍按原来的15人计算。","source":"原创练习"},{"id":"sl-29","subject":"岗位能力","chapter":"数量关系","stem":"甲的效率是乙的1.5倍。乙需要9天完成的工作，甲几天可以完成？","options":["6天","13.5天","4.5天","12天"],"answer":0,"explanation":"效率是乙的1.5倍，时间就是9÷1.5=6天。最接近的13.5天是9×1.5，把效率更高、用时更短做成了正比。","source":"原创练习"},{"id":"sl-30","subject":"岗位能力","chapter":"数量关系","stem":"A泵单独工作5小时可以抽完一池水，A、B两泵一起工作3小时可以抽完。B泵单独工作需要多少小时？","options":["8小时","7.5小时","6小时","10小时"],"answer":1,"explanation":"合作效率是1/3，A的效率是1/5，B的效率是1/3−1/5=2/15，单独时间是15/2=7.5小时。最接近的8小时把7.5四舍五入了，而选项里已经有精确的7.5小时。","source":"原创练习"},{"id":"sl-31","subject":"岗位能力","chapter":"数量关系","stem":"甲、乙两地相距180千米。甲每小时行60千米，乙每小时行40千米，两人同时从两地相向出发。几小时后相遇？","options":["1.5小时","2小时","1.8小时","3小时"],"answer":2,"explanation":"相向而行，速度相加，180÷(60+40)=1.8小时。最接近的2小时相当于用90千米/时去除，而60+40等于100，不是90。","source":"原创练习"},{"id":"sl-32","subject":"岗位能力","chapter":"数量关系","stem":"甲以每小时72千米的速度在前方行驶，乙以每小时90千米的速度从后方36千米处同向追赶。乙几小时可以追上甲？","options":["1.5小时","4小时","2.5小时","2小时"],"answer":3,"explanation":"追及只看速度差，36÷(90−72)=36÷18=2小时。最接近的1.5小时是36÷24，把速度差18误当成了24。","source":"原创练习"},{"id":"sl-33","subject":"岗位能力","chapter":"数量关系","stem":"去程速度为每小时40千米，用了3小时。回程用了2.5小时。回程速度是多少？","options":["48千米/时","50千米/时","44千米/时","52千米/时"],"answer":0,"explanation":"路程是40×3=120千米，回程速度120÷2.5=48千米/时。最接近的50千米/时把120÷2.5算成了50；2.5×48=120，2.5×50并不等于120。","source":"原创练习"},{"id":"sl-34","subject":"岗位能力","chapter":"数量关系","stem":"一只船在静水中的速度是每小时24千米，水流速度是每小时4千米。顺水行驶2小时、逆水行驶2小时，顺水比逆水多行多少千米？","options":["8千米","16千米","32千米","12千米"],"answer":1,"explanation":"顺水速度24+4=28千米/时，逆水速度24−4=20千米/时，每小时多行8千米，2小时多行16千米。最接近的8千米只算了1小时的速度差，漏乘了2小时。","source":"原创练习"},{"id":"sl-35","subject":"岗位能力","chapter":"数量关系","stem":"环形跑道长400米。甲每秒跑5米，乙每秒跑3米，两人从同一点同时反向出发。首次相遇需要多少秒？","options":["80秒","100秒","50秒","40秒"],"answer":2,"explanation":"反向跑，速度相加，400÷(5+3)=50秒。最接近的80秒是400÷5，只让甲一个人跑完一圈，没有加上迎面而来的乙。","source":"原创练习"},{"id":"sl-36","subject":"岗位能力","chapter":"数量关系","stem":"乙比甲早出发30分钟，速度为每小时48千米；甲的速度为每小时64千米，两人同向。甲出发后几小时追上乙？","options":["1小时","2小时","2.5小时","1.5小时"],"answer":3,"explanation":"乙先走0.5×48=24千米。甲每小时多走64−48=16千米，24÷16=1.5小时。最接近的2小时用甲的速度去算乙的领先距离：0.5×64=32，32÷16=2。已经在路上的是乙，不能按甲的速度计算提前量。","source":"原创练习"},{"id":"sl-37","subject":"岗位能力","chapter":"数量关系","stem":"上坡路30千米，速度为每小时20千米；下坡路30千米，速度为每小时30千米。全程的平均速度是多少？","options":["24千米/时","25千米/时","26千米/时","22千米/时"],"answer":0,"explanation":"平均速度等于总路程除以总时间。上坡用30÷20=1.5小时，下坡用30÷30=1小时，一共2.5小时，60÷2.5=24千米/时。最接近的25千米/时是(20+30)÷2。慢的一段花的时间更长，不能把两个速度直接平均。","source":"原创练习"},{"id":"sl-38","subject":"岗位能力","chapter":"数量关系","stem":"一列火车长200米，以每小时60千米的速度完全通过一座800米长的桥，需要多少秒？","options":["48秒","60秒","72秒","36秒"],"answer":1,"explanation":"完全通过桥，路程是桥长加车长，800+200=1000米。每小时60千米等于每分钟1千米，1000米正好用1分钟，也就是60秒。最接近的48秒只除了桥长800米，0.8分钟=48秒，这时车尾还在桥上。","source":"原创练习"},{"id":"sl-39","subject":"岗位能力","chapter":"数量关系","stem":"A、B两地相距240千米。甲每小时行80千米，乙每小时行40千米，两人同时从两地相向出发。相遇以后，甲还要几小时才能到达B地？","options":["2小时","0.5小时","1小时","1.5小时"],"answer":2,"explanation":"相遇时间是240÷(80+40)=2小时。这两小时甲已行160千米，剩下240−160=80千米，80÷80=1小时。最接近的2小时是相遇前已经用去的时间，不是剩下80千米所需要的时间。","source":"原创练习"},{"id":"sl-40","subject":"岗位能力","chapter":"数量关系","stem":"原计划以每小时40千米的速度走完一段路，3小时可以到达。实际用了2.5小时。实际速度比计划快多少？","options":["6千米/时","10千米/时","12千米/时","8千米/时"],"answer":3,"explanation":"路程是40×3=120千米。实际速度120÷2.5=48千米/时，比计划的40千米/时快8千米/时。最接近的10千米/时把120÷2.5算成50，再减40得到10；2.5×48才等于120。","source":"原创练习"},{"id":"zz-01","subject":"基本知识","chapter":"政治","stem":"辩证唯物主义在“物质和意识谁是本原”这个问题上的观点是：","options":["先有意识，物质只在认识完成之后才出现","意识是本原，物质只是意识的投影","物质和意识互为本原，谁也不决定谁","物质是本原，意识是物质的产物和反映，同时意识对物质具有能动作用"],"answer":3,"explanation":"辩证唯物主义认为物质是世界的本原，意识是人脑对物质的反映，所以物质第一性、意识第二性。意识能够指导实践，这是能动作用，但能动作用改变不了本原。最容易混的是把能动作用理解成意识可以另立一个本原：反作用再大，仍然是物质决定意识，而不是两个本原平行，更不是意识在先。","source":"原创练习"},{"id":"zz-02","subject":"基本知识","chapter":"政治","stem":"一种认识究竟对不对，最终应当由什么来判定？","options":["是否在实践中达到了预期目的","是否在逻辑上没有破绽","是否被权威机构写进文件","是否得到多数人赞成"],"answer":0,"explanation":"实践是检验真理的唯一标准。认识是否正确，要看用它指导实践时能不能达到预想的结果。逻辑上自圆其说，只说明推理内部不矛盾，并不能保证符合实际，所以它最像标准，其实只解决了形式问题。多数人赞成、权威表态，都出现过集体出错，也不能代替实践。","source":"原创练习"},{"id":"zz-03","subject":"基本知识","chapter":"政治","stem":"唯物辩证法诸规律中，揭示发展源泉和动力、因而居于实质和核心地位的是：","options":["对立统一规律","质量互变规律","否定之否定规律","因果联系规律"],"answer":0,"explanation":"对立统一规律说明事物为什么会发展，其他规律和范畴都要由它来说明，所以它是唯物辩证法的实质和核心。质量互变回答的是发展的状态，否定之否定回答的是发展的道路，都重要，但不是源泉。质量互变最常被举例，例子多不等于地位更核心，这是最容易把它抬成核心的原因。","source":"原创练习"},{"id":"zz-04","subject":"基本知识","chapter":"政治","stem":"一个单位同时存在几对矛盾。对全局起决定作用、应当集中力量解决的那一对，称为：","options":["矛盾的主要方面","主要矛盾","非对抗性矛盾","外部矛盾"],"answer":1,"explanation":"主要矛盾在矛盾体系中居于支配地位，决定事物发展的全局。矛盾的主要方面则是同一对矛盾内部占支配地位的一方，决定的是这对矛盾的性质，不是哪一对左右全局。这两个词只差几个字，是最常见的对调。外部矛盾、对抗还是非对抗，说的是范围和形式，没有回答哪一对决定全局。","source":"原创练习"},{"id":"zz-05","subject":"基本知识","chapter":"政治","stem":"关于量变和质变，正确的说法是：","options":["质变完成以后，新的量变不再开始","量变是质变的必要准备，质变是量变的必然结果","质变不必经过量变，可以凭空发生","量变阶段不会发生任何局部性质变化"],"answer":1,"explanation":"变化从量变开始，积累到度的关节点才引起质变，质变又在新质基础上开始新的量变。因此量变是质变的必要准备，质变是量变的必然结果。最有迷惑性的是“质变可以不经过量变”：它把飞跃看成没有积累的突变，否认了度是量变积累出来的。总的量变过程中也可以有部分质变，不能说量变阶段一片静止。","source":"原创练习"},{"id":"zz-06","subject":"基本知识","chapter":"政治","stem":"历史唯物主义用来和历史唯心主义划界的基本问题及其回答是：","options":["社会意识决定社会存在","上层建筑决定经济基础","基本问题是社会存在和社会意识的关系，回答是社会存在决定社会意识","杰出人物决定历史发展的总方向"],"answer":2,"explanation":"社会历史观的基本问题是社会存在和社会意识的关系。历史唯物主义认为社会存在决定社会意识，社会意识又有相对独立性，可以反作用。最容易把决定关系说反的是上层建筑和经济基础：经济基础决定上层建筑，上层建筑只能反作用，不能决定经济基础。杰出人物可以影响进程，但不能决定历史的总方向。","source":"原创练习"},{"id":"zz-07","subject":"基本知识","chapter":"政治","stem":"既承认人民群众是历史的创造者，又怎样评价杰出人物？","options":["杰出人物对历史进程没有实际作用","杰出人物可以加速或延缓历史进程，但不能决定历史发展的总趋势","杰出人物是历史的唯一创造者，群众只负责跟随","杰出人物能够改写历史发展的总趋势"],"answer":1,"explanation":"人民群众是社会物质财富和精神财富的创造者，也是社会变革的决定力量。杰出人物顺应规律时能加快进程，违背规律时会拖慢进程，却不能代替人民群众，也不能扭转总趋势。最接近的错误是“能够改写总趋势”：它承认人物有作用，却把作用夸大成了英雄史观。说杰出人物毫无作用，则走到了另一个极端。","source":"原创练习"},{"id":"zz-08","subject":"基本知识","chapter":"政治","stem":"生产力和生产关系这对矛盾中，最终起决定作用的一方是：","options":["生产关系","生产力","上层建筑","社会心理"],"answer":1,"explanation":"生产力是最活跃、最革命的因素，它决定生产关系；生产关系必须适合生产力状况，否则就要被调整。生产关系适应时促进生产力、不适应时阻碍生产力，这是反作用，不是最终的决定作用。把生产关系选成决定的一方，就是把反作用记成了决定作用。上层建筑要经过经济基础才能影响到生产力，不能直接取代生产力的地位。","source":"原创练习"},{"id":"zz-09","subject":"基本知识","chapter":"政治","stem":"贯穿毛泽东思想各个组成部分的立场、观点和方法，称为活的灵魂。它包括：","options":["实事求是、群众路线、独立自主","统一战线、武装斗争、党的建设","理论联系实际、密切联系群众、批评与自我批评","解放思想、与时俱进、求真务实"],"answer":0,"explanation":"实事求是、群众路线、独立自主，是毛泽东思想活的灵魂的三个基本方面。最容易配错的是理论联系实际、密切联系群众、批评与自我批评，那是党的三大作风，词面和活的灵魂很近，却不是同一组概括。统一战线、武装斗争、党的建设是新民主主义革命的三大法宝。解放思想、与时俱进、求真务实是后来强调的思想方法，不能回写成活的灵魂。","source":"原创练习"},{"id":"zz-10","subject":"基本知识","chapter":"政治","stem":"新民主主义革命的三大法宝是：","options":["整风运动、大生产运动、精兵简政","统一战线、武装斗争、党的建设","土地革命、武装斗争、根据地建设","实事求是、群众路线、独立自主"],"answer":1,"explanation":"三大法宝是统一战线、武装斗争、党的建设，其中党的建设是掌握前两件武器的关键。土地革命、武装斗争和根据地建设，是农村包围城市这条道路中的具体内容，常和法宝同时出现，所以最容易被当成法宝本身。活的灵魂是立场观点方法，不是对敌斗争的三件武器。","source":"原创练习"},{"id":"zz-11","subject":"基本知识","chapter":"政治","stem":"中国新民主主义革命被实践证明走得通的道路是：","options":["等待各派军阀互斗，政权自行转到人民手中","通过议会席位逐步取得全国政权","先夺取中心城市，再把胜利推向农村","建立农村革命根据地，以农村包围城市、武装夺取政权"],"answer":3,"explanation":"当时城市里敌人的力量强，照搬中心城市暴动站不住。中国共产党人从实践中走出了农村包围城市、武装夺取政权的道路。议会道路和等待军阀自行交出政权，都绕开了武装斗争。最要和正确道路对照着记的，就是“先城市、后农村”那种不符合当时力量对比的打法。","source":"原创练习"},{"id":"zz-12","subject":"基本知识","chapter":"政治","stem":"1956年对农业、手工业和资本主义工商业的社会主义改造基本完成，标志着：","options":["改革开放和社会主义市场经济体制同时起步","社会主义基本制度在我国初步确立，我国进入社会主义初级阶段","半殖民地半封建社会由此形成","新民主主义革命刚刚开始"],"answer":1,"explanation":"三大改造基本完成后，公有制主体地位确立，社会主义基本制度在我国建立，社会进入社会主义初级阶段。最容易把时间点提前到1949年：中华人民共和国成立标志着新民主主义革命基本胜利，并开始向社会主义过渡，但社会主义基本制度还要等到改造完成才确立。改革开放是1978年以后的决策，社会主义市场经济体制的目标是1992年党的十四大才明确的。","source":"原创练习"},{"id":"zz-13","subject":"基本知识","chapter":"政治","stem":"1978年党的十一届三中全会作出的关键决策是：","options":["结束“以阶级斗争为纲”，把党和国家工作中心转移到经济建设上来，并实行改革开放","立即把建立社会主义市场经济体制写为改革目标","宣布社会主义改造提前完成","确定到2035年基本实现社会主义现代化的时间表"],"answer":0,"explanation":"十一届三中全会重新确立解放思想、实事求是的思想路线，决定把工作中心转到经济建设，并实行改革开放，是新中国成立以来党的历史上的伟大转折。最常见的年代错位，是把社会主义市场经济体制当成这次会议的决定：那个目标是1992年党的十四大才明确的。2035年的现代化安排是新时代的战略步骤，不能回写到1978年。社会主义改造则在1956年已经基本完成。","source":"原创练习"},{"id":"zz-14","subject":"基本知识","chapter":"政治","stem":"对社会主义本质比较完整的概括是：","options":["解放生产力，发展生产力，消灭剥削，消除两极分化，最终达到共同富裕","用计划完全取代市场","维持单一公有制和指令性计划","只讲共同富裕，不必再谈生产力"],"answer":0,"explanation":"这一概括把发展生产力和共同富裕连在一起：解放和发展生产力是基础，消灭剥削、消除两极分化、最终达到共同富裕是目标。只留下共同富裕、拿掉生产力，看起来最接近，其实把实现目标所依靠的生产力标准砍掉了。公有制、按劳分配是基本经济制度的重要内容，计划也不是社会主义的本质。本质概括回答的是社会主义要干什么，不是某一种管理形式。","source":"原创练习"},{"id":"zz-15","subject":"基本知识","chapter":"政治","stem":"邓小平理论首先要回答的基本理论问题是：","options":["新时代坚持和发展什么样的中国特色社会主义、怎样坚持和发展中国特色社会主义","实现什么样的发展、怎样发展","什么是社会主义、怎样建设社会主义","建设什么样的党、怎样建设党"],"answer":2,"explanation":"这四个问句分别属于不同的理论成果，要按理论去配问题，不能看哪一句更长。邓小平理论围绕什么是社会主义、怎样建设社会主义。建设什么样的党、怎样建设党，对应“三个代表”重要思想。实现什么样的发展、怎样发展，对应科学发展观。最后一个长句对应习近平新时代中国特色社会主义思想。","source":"原创练习"},{"id":"zz-16","subject":"基本知识","chapter":"政治","stem":"贯彻“三个代表”重要思想，关键、核心和本质的正确对应是：","options":["关键在执政为民，核心在与时俱进，本质在党的先进性","关键是发展速度，核心是独立自主，本质是按劳分配","关键在党的先进性，核心在执政为民，本质在与时俱进","关键在坚持与时俱进，核心在坚持党的先进性，本质在坚持执政为民"],"answer":3,"explanation":"三个定位是：关键在坚持与时俱进，核心在坚持党的先进性，本质在坚持执政为民。把先进性、执政为民、与时俱进三个词互换位置，每个词都眼熟，所以特别容易错。做的时候先钉死“本质是执政为民”，再把核心留给党的先进性，把关键留给与时俱进。发展速度、独立自主、按劳分配都不在这组对应里。","source":"原创练习"},{"id":"zz-17","subject":"基本知识","chapter":"政治","stem":"科学发展观的核心、基本要求和根本方法，依次是：","options":["以人为本；全面协调可持续；统筹兼顾","全面协调可持续；以人为本；统筹兼顾","发展；加快速度；重点突破","统筹兼顾；全面协调可持续；以人为本"],"answer":0,"explanation":"科学发展观的第一要义是发展，核心是以人为本，基本要求是全面协调可持续，根本方法是统筹兼顾。题目问的是后三个位置，不要把第一要义的“发展”塞进核心。最容易错的是让“以人为本”和“全面协调可持续”换班：一个是核心，一个是基本要求。统筹兼顾是根本方法，不是核心。","source":"原创练习"},{"id":"zz-18","subject":"基本知识","chapter":"政治","stem":"党的思想路线的完整表述是：","options":["个人服从组织，少数服从多数，下级服从上级，全党服从中央","一切为了群众，一切依靠群众，从群众中来，到群众中去","独立自主、自力更生、艰苦奋斗","一切从实际出发，理论联系实际，实事求是，在实践中检验真理和发展真理"],"answer":3,"explanation":"思想路线回答认识怎样和实际打交道：一切从实际出发，理论联系实际，实事求是，在实践中检验真理和发展真理，精髓是实事求是。从群众中来、到群众中去是群众路线；四个服从是民主集中制的组织原则。这两条最容易和思想路线串名，因为都有“从哪里出发、服从什么”的说法。独立自主是活的灵魂的一个方面，也不是思想路线的全称。","source":"原创练习"},{"id":"zz-19","subject":"基本知识","chapter":"政治","stem":"中国特色社会主义进入新时代后，我国社会主要矛盾的规范表述是：","options":["人民日益增长的物质文化需要同落后的社会生产之间的矛盾","工人阶级和资产阶级之间的矛盾","沿海地区和内陆地区之间的矛盾","人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾"],"answer":3,"explanation":"社会主要矛盾已经转化为人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾。需求一侧从物质文化需要扩展为美好生活需要，供给一侧从落后的社会生产改为不平衡不充分的发展。最要防的是仍用旧表述作答：那组话曾经长期使用，但已经不再概括当前的主要矛盾。地区差距只是不平衡的一种表现，不能代替主要矛盾本身。","source":"原创练习"},{"id":"zz-20","subject":"基本知识","chapter":"政治","stem":"社会主要矛盾发生变化之后，对社会主义初级阶段应当如何判断？","options":["阶段判断随之改变，我国已经走出初级阶段","我国仍处于并将长期处于社会主义初级阶段的基本国情没有变","主要任务转回以阶级斗争为纲","基本路线中的以经济建设为中心应当取消"],"answer":1,"explanation":"主要矛盾转化，说明初级阶段内部的需求和供给状况变了，不等于社会阶段本身变了。我国仍处于并将长期处于社会主义初级阶段的基本国情没有变，以经济建设为中心也不能因此拿掉。最有迷惑性的是“已经走出初级阶段”：它把“矛盾变了”直接推成“阶段变了”。以阶级斗争为纲是已经被纠正的提法，不能因为矛盾转化而恢复。","source":"原创练习"},{"id":"zz-21","subject":"基本知识","chapter":"政治","stem":"中国特色社会主义最本质的特征是：","options":["社会主义市场经济体制","人民代表大会制度","多党合作和政治协商制度","中国共产党领导"],"answer":3,"explanation":"中国共产党领导是中国特色社会主义最本质的特征，也是中国特色社会主义制度的最大优势。人民代表大会制度是根本政治制度，多党合作和政治协商制度是基本政治制度，社会主义市场经济体制是经济运行和基本经济制度中的重要内容。三项都是支柱，但都不是“最本质的特征”所指的那一项。先把特征、优势和具体制度分成不同层次，再选择。","source":"原创练习"},{"id":"zz-22","subject":"基本知识","chapter":"政治","stem":"新发展理念中，共享对应的定位是：","options":["永续发展的必要条件","中国特色社会主义的本质要求","引领发展的第一动力","国家繁荣发展的必由之路"],"answer":1,"explanation":"创新是引领发展的第一动力，协调是持续健康发展的内在要求，绿色是永续发展的必要条件和人民对美好生活追求的重要体现，开放是国家繁荣发展的必由之路，共享是中国特色社会主义的本质要求。五个词要和五个定位一起记。最容易把本质要求让给创新，因为创新排在首位又叫第一动力；首位说的是动力，不是发展为了谁。开放才是必由之路，绿色才和永续发展的必要条件相连。","source":"原创练习"},{"id":"zz-23","subject":"基本知识","chapter":"政治","stem":"“五位一体”总体布局包括的五个建设是：","options":["经济建设、政治建设、文化建设、社会建设、国防建设","经济建设、政治建设、文化建设、党的建设、军队建设","经济建设、政治建设、文化建设、社会建设、生态文明建设","经济建设、外交建设、国防建设、社会建设、生态文明建设"],"answer":2,"explanation":"五位一体是经济、政治、文化、社会、生态文明五个建设一起部署。国防和军队建设、党的建设都极其重要，但分别放在强军安排和全面从严治党中，不占用这五个席位。最常见的替换是拿掉生态文明、补上国防。外交同样不是这五个建设中的一项。看到“总体布局”就要先核对是不是这五个固定名称。","source":"原创练习"},{"id":"zz-24","subject":"基本知识","chapter":"政治","stem":"全面建成小康社会的目标实现以后，“四个全面”战略布局的第一项是：","options":["全面扩大商品出口","全面实行基层直接选举","全面建成小康社会","全面建设社会主义现代化国家"],"answer":3,"explanation":"小康社会全面建成之后，战略布局的首项是全面建设社会主义现代化国家，与全面深化改革、全面依法治国、全面从严治党并列。继续把“全面建成小康社会”放在第一项，是没有把已经完成的目标和正在推进的目标分开，这是最容易沿用的旧句。扩大出口和基层选举是具体工作，不是四个全面的组成项。","source":"原创练习"},{"id":"zz-25","subject":"基本知识","chapter":"政治","stem":"构建新发展格局，准确的说法是：","options":["以国内大循环为主体、国内国际双循环相互促进","关掉国际循环，只保留国内循环","以国际大循环为主体，国内循环用来补缺","各省各自形成封闭市场，减少国内统一流通"],"answer":0,"explanation":"新发展格局是以国内大循环为主体、国内国际双循环相互促进。国内大循环成为主体，是因为超大规模市场是发展的基本盘；国际循环不能切断，两个循环要相互促进。最像又最错的是“只保留国内循环”：它把“主体”理解成了“唯一”。以国际循环为主体，是另一种重心，不是当前这一格局。省与省之间切断流通，更与全国统一大市场相反。","source":"原创练习"},{"id":"zz-26","subject":"基本知识","chapter":"政治","stem":"关于中国式现代化和共同富裕，正确的是：","options":["全体人民共同富裕，但不是少数人富裕，也不是整齐划一的平均主义","现代化只要求一部分人先富，共同富裕不列入目标","全体人民在同一时间达到完全相同的收入","只安排城镇居民富裕，乡村不纳入现代化"],"answer":0,"explanation":"中国式现代化是全体人民共同富裕的现代化。共同富裕是社会主义的本质要求，要分阶段推进，允许存在合理差别。最容易走偏的是“同时、同步、同等富裕”：它把“共同”理解成了平均和同步。另一个极端是只讲少数人富裕，把共同富裕从目标里拿掉。两种极端都不是这一现代化的要求。","source":"原创练习"},{"id":"zz-27","subject":"基本知识","chapter":"政治","stem":"全过程人民民主在我国民主政治中的定位是：","options":["社会主义民主政治的本质属性","用来代替中国共产党的领导","人民代表大会制度之外的另一套政体","只存在于基层投票那一个环节"],"answer":0,"explanation":"全过程人民民主是社会主义民主政治的本质属性，覆盖民主选举、协商、决策、管理、监督，不是投票结束就退场。把它收成“只有基层投票”，是最常见的缩小。它在党的领导下、通过人民代表大会制度等安排来实现，不是用来取消党的领导，也不是政体旁边另起的一套制度。","source":"原创练习"},{"id":"zz-28","subject":"基本知识","chapter":"政治","stem":"总体国家安全观的宗旨和根本分别是：","options":["宗旨是经济安全，根本是军事安全","宗旨是人民安全，根本是政治安全","宗旨是国际安全，根本是资源安全","宗旨是军事安全，根本是文化安全"],"answer":1,"explanation":"总体国家安全观以人民安全为宗旨，以政治安全为根本，以经济安全为基础，以军事、文化、社会安全为保障，以促进国际安全为依托。宗旨回答为了谁，根本回答什么居于根本位置，两处最容易对调。经济安全是基础，不是宗旨；军事安全放在保障里面，不是根本。国际安全是依托，也不是宗旨。","source":"原创练习"},{"id":"zz-29","subject":"基本知识","chapter":"政治","stem":"全面建设社会主义现代化国家的两步安排，正确的是：","options":["只保留本世纪中叶一个节点，2035年不作为阶段目标","到2020年基本实现现代化，到2035年建成社会主义现代化强国","到2035年就全面建成社会主义现代化强国，本世纪中叶不再设目标","到2035年基本实现社会主义现代化，到本世纪中叶建成富强民主文明和谐美丽的社会主义现代化强国"],"answer":3,"explanation":"两步是：2035年基本实现社会主义现代化，本世纪中叶把我国建成富强民主文明和谐美丽的社会主义现代化强国。两个节点的动词不同，2035年是基本实现，中叶是建成强国。最容易错的是把两件事都压到2035年，或者仍用2020年去安排现代化。2020年对应的是已经实现的小康目标，不是基本实现现代化。","source":"原创练习"},{"id":"zz-30","subject":"基本知识","chapter":"政治","stem":"处理市场和政府在资源配置中的关系，当前应当坚持：","options":["市场起基础性作用，政府起决定性作用","计划起决定性作用，市场只填补计划留下的空隙","使市场在资源配置中起决定性作用，更好发挥政府作用","市场起决定性作用，政府因此退出宏观调控"],"answer":2,"explanation":"经济体制改革要处理好政府和市场的关系，使市场在资源配置中起决定性作用，更好发挥政府作用。早先的规范提法是市场起基础性作用，后来提升为决定性作用；继续答基础性作用，就不是当前的表述。决定性作用也不等于取消政府。最容易多走一步的，就是由市场决定推出政府退出宏观调控。政府还要在宏观调控、市场监管和公平秩序上更好发挥作用。","source":"原创练习"},{"id":"zz-31","subject":"基本知识","chapter":"政治","stem":"下列哪一项属于我国的基本政治制度，而不是根本政治制度？","options":["中国共产党领导的多党合作和政治协商制度","民主集中制","人民民主专政","人民代表大会制度"],"answer":0,"explanation":"人民代表大会制度是根本政治制度。中国共产党领导的多党合作和政治协商制度、民族区域自治制度、基层群众自治制度，属于基本政治制度。题目要求选出基本政治制度，所以人民代表大会制度虽然重要，却不是这一问的答案。人民民主专政是国体，民主集中制是组织原则，都不在基本政治制度这个名单里。先把根本、基本、国体、组织原则四层分开。","source":"原创练习"},{"id":"zz-32","subject":"基本知识","chapter":"政治","stem":"民族区域自治制度中的民族自治地方是：","options":["少数民族人口较多的街道","民族乡","自治区、自治州和自治县","特别行政区"],"answer":2,"explanation":"民族自治地方分自治区、自治州、自治县三级，设立自治机关，行使自治权。民族乡虽然工作上要照顾民族特点，但不是民族自治地方，这是最常见的错点。特别行政区实行的是“一国两制”下的高度自治，不是民族区域自治。街道办事处是政府的派出机关，更不是自治地方。","source":"原创练习"},{"id":"zz-33","subject":"基本知识","chapter":"政治","stem":"城市居民委员会的法律性质是：","options":["基层群众性自治组织","公安机关的派出机构","一级地方政权机关","区人民政府的派出机关"],"answer":0,"explanation":"居民委员会和村民委员会是基层群众性自治组织，办理本居住地区的公共事务和公益事业，调解纠纷，协助维护社会治安，并向政府反映意见。它们不是政权机关。最容易混的是区政府的派出机关：街道办事处才是市辖区或者不设区的市政府的派出机关，居委会不是。派出所是公安机关的派出机构，和居委会也不是一回事。","source":"原创练习"},{"id":"zz-34","subject":"基本知识","chapter":"政治","stem":"关于中国人民政治协商会议，正确的是：","options":["它和全国人大共同行使最高国家权力","它是行政机关，负责执行法律","它是国家权力机关，可以制定法律","它是爱国统一战线组织，主要职能是政治协商、民主监督、参政议政"],"answer":3,"explanation":"人民政协是爱国统一战线组织，是中国共产党领导的多党合作和政治协商的重要机构，职能是政治协商、民主监督、参政议政。它不是国家机关，没有立法权和行政权。两会往往同期召开，最容易因此把政协看成和全国人大并列的权力机关。同期开会不改变政协不是国家权力机关这一条。","source":"原创练习"},{"id":"zz-35","subject":"基本知识","chapter":"政治","stem":"民主集中制的“四个服从”里，用来保证党中央集中统一领导的是：","options":["少数服从多数","党员个人服从党的组织","全党各个组织和全体党员服从党的全国代表大会和中央委员会","下级组织服从上级组织"],"answer":2,"explanation":"四个服从是一个整体：个人服从组织，少数服从多数，下级服从上级，全党服从党的全国代表大会和中央委员会。最后一条最重要，它保证党中央的集中统一领导。只记住少数服从多数，看起来最像民主集中制的通俗说法，其实把组织原则收成了表决规则。表决上的少数服从多数，也不能用来对抗党中央的集中统一领导。","source":"原创练习"},{"id":"zz-36","subject":"基本知识","chapter":"政治","stem":"预备党员在预备期内，与正式党员相比，权利义务的差别是：","options":["义务与正式党员相同；除没有表决权、选举权和被选举权以外，其他权利也与正式党员相同","有表决权，但可以不交纳党费","既不履行义务，也不享有任何权利","权利和正式党员完全一样，义务减半"],"answer":0,"explanation":"预备党员的义务同正式党员一样。权利方面，除了没有表决权、选举权和被选举权，其他也同正式党员一样。预备期是组织考察期，不是可以少尽义务的过渡身份，更不是已经享有全部决定权。最容易错的是认为预备党员还没入党、因而既无权利也无义务。预备期从支部大会通过其为预备党员之日算起，义务已经开始。","source":"原创练习"},{"id":"zz-37","subject":"基本知识","chapter":"政治","stem":"党的最高理想和最终目标是：","options":["全面建成小康社会","到2035年基本实现社会主义现代化","实现共产主义","完成对生产资料的社会主义改造"],"answer":2,"explanation":"党的最高理想和最终目标是实现共产主义。小康社会、基本实现社会主义现代化，是阶段性目标，有的已经完成，有的正在推进，都不能代替最终目标。最容易混进最终目标的是2035年基本实现社会主义现代化：它是两步走里的前一步，层次低于共产主义。社会主义改造则是1956年已经基本完成的历史任务。","source":"原创练习"},{"id":"zz-38","subject":"基本知识","chapter":"政治","stem":"党在社会主义初级阶段基本路线所说的“一个中心”是：","options":["以党的自身建设为中心","以经济建设为中心","以文化出口为中心","以阶级斗争为中心"],"answer":1,"explanation":"基本路线可以压缩成一个中心、两个基本点：以经济建设为中心，坚持四项基本原则，坚持改革开放。党的建设是新的伟大工程，必须始终抓紧，但不是这条基本路线里的那个中心。以阶级斗争为中心是已经纠正的错误提法。两个基本点不能顶替中心：丢掉中心，基本点就失去了服务的大局。","source":"原创练习"},{"id":"zz-39","subject":"基本知识","chapter":"政治","stem":"四项基本原则的内容是：","options":["坚持社会主义道路、坚持人民民主专政、坚持改革开放、坚持市场经济","坚持党的领导、坚持依法治国、坚持一国两制、坚持独立自主和平外交","坚持人民代表大会制度、坚持多党合作、坚持民族区域自治、坚持基层群众自治","坚持社会主义道路、坚持人民民主专政、坚持中国共产党的领导、坚持马克思列宁主义、毛泽东思想"],"answer":3,"explanation":"四项基本原则是立国之本：坚持社会主义道路，坚持人民民主专政，坚持中国共产党的领导，坚持马克思列宁主义、毛泽东思想。改革开放是另一个基本点，是强国之路，不写进这四项。最容易加进去的就是改革开放，因为它和四项基本原则并列出现，人们会以为它是四项中的一项。把依法治国、一国两制，或者人民代表大会制度、民族区域自治写进来，列的是其他原则或政治制度，不是这四个坚持。","source":"原创练习"},{"id":"zz-40","subject":"基本知识","chapter":"政治","stem":"社会主义核心价值观在公民个人层面的准则是：","options":["富强、民主、文明、和谐","爱国、敬业、诚信、友善","创新、协调、绿色、开放、共享","自由、平等、公正、法治"],"answer":1,"explanation":"核心价值观分三层：国家层面是富强、民主、文明、和谐，社会层面是自由、平等、公正、法治，公民个人层面是爱国、敬业、诚信、友善。三组词都熟悉，错多半错在层次。自由、平等、公正、法治最容易被当成个人品德，其实是社会层面的价值取向。创新、协调、绿色、开放、共享是新发展理念，不是核心价值观的一层。","source":"原创练习"},{"id":"zz-41","subject":"基本知识","chapter":"政治","stem":"坚持党对人民军队绝对领导的根本实现形式是：","options":["由各民主党派轮流担任军队领导","军委主席负责制","由部队驻地的地方政府分别统率","用战斗力排名代替政治领导"],"answer":1,"explanation":"党对人民军队的绝对领导是人民军队的建军之本、强军之魂。军委主席负责制是坚持这一领导的根本制度和根本实现形式。人民军队不搞多党轮流领导，也不把领导权拆给驻地政府。最容易拿来替代的是战斗力标准：它衡量军队建设的成效，但不能回答领导权属于谁。","source":"原创练习"},{"id":"zz-42","subject":"基本知识","chapter":"政治","stem":"在“听党指挥、能打胜仗、作风优良”中，居于核心位置的是：","options":["能打胜仗","三句完全并列，没有灵魂、核心和保证的区分","听党指挥","作风优良"],"answer":0,"explanation":"听党指挥是灵魂，能打胜仗是核心，作风优良是保证。三个要求都要达到，但定位不同。最容易把核心说成听党指挥，因为党的领导在政治上最根本；在这组特定表述里，灵魂留给听党指挥，核心留给能打胜仗，保证留给作风优良。说三项没有任何主次，就抹掉了这个已经明确的定位。","source":"原创练习"},{"id":"zz-43","subject":"基本知识","chapter":"政治","stem":"把党的支部建在连上，从组织上保证党对军队的领导。这一原则确立于：","options":["南昌起义","三湾改编","党的第七次全国代表大会","洛川会议"],"answer":1,"explanation":"1927年秋收起义之后的三湾改编，把支部建在连上，从组织上落实党对军队的领导。南昌起义打响了武装反抗国民党反动派的第一枪，标志着党独立领导革命战争、创建人民军队的开端，但支部建在连上不是南昌起义当场确立的。把这两件事并成一件，是军史时间线上最常见的合并。洛川会议解决的是全面抗战中的路线和战略问题，党的七大则把毛泽东思想写为党的指导思想。","source":"原创练习"},{"id":"zz-44","subject":"基本知识","chapter":"政治","stem":"人民军队的唯一宗旨是：","options":["支部建在连上","听党指挥、能打胜仗、作风优良","军委主席负责制","全心全意为人民服务"],"answer":3,"explanation":"人民军队的唯一宗旨是全心全意为人民服务。听党指挥、能打胜仗、作风优良是强军目标，支部建在连上是组织原则，军委主席负责制是党对军队绝对领导的实现形式。这三句都容易因为反复出现而被当成宗旨。宗旨只有一条，回答的是军队为了谁；目标和制度回答的是怎样建设、怎样领导。","source":"原创练习"},{"id":"zz-45","subject":"基本知识","chapter":"政治","stem":"和平共处五项原则中，排在第一项并作为其他几项前提的是：","options":["平等互利","互相尊重主权和领土完整","互不干涉内政","互不侵犯"],"answer":1,"explanation":"五项原则是互相尊重主权和领土完整、互不侵犯、互不干涉内政、平等互利、和平共处。第一项是互相尊重主权和领土完整。互不侵犯、互不干涉内政、平等互利都是五项里的内容，单独拿出来都真实，但都不是第一项，也不能代替完整原则。漏掉领土完整、只写尊重主权，同样不完整。","source":"原创练习"},{"id":"zz-46","subject":"基本知识","chapter":"政治","stem":"我国爱国统一战线比较完整的范围包括：","options":["全体社会主义劳动者、社会主义事业的建设者、拥护社会主义的爱国者、拥护祖国统一和致力于中华民族伟大复兴的爱国者","只有工人和农民两个阶级","只包括已经实现统一的地区的居民","只包括中国共产党党内的各个组织"],"answer":0,"explanation":"爱国统一战线是全体社会主义劳动者、社会主义事业的建设者、拥护社会主义的爱国者、拥护祖国统一和致力于中华民族伟大复兴的爱国者的广泛联盟。后来写明的“致力于中华民族伟大复兴的爱国者”，把凝聚点放在民族复兴上，而不是只看阶级出身。只保留工农两个阶级，是民主革命时期的窄口径。统一战线也不是党内部门，更不以是否已经生活在统一地区为条件。","source":"原创练习"},{"id":"zz-47","subject":"基本知识","chapter":"政治","stem":"全面依法治国的总抓手是：","options":["把一切纠纷都送进法院","科学立法、严格执法、公正司法、全民守法","用内部文件代替公开发布的法律","建设中国特色社会主义法治体系"],"answer":3,"explanation":"全面依法治国的总抓手，是建设中国特色社会主义法治体系。科学立法、严格执法、公正司法、全民守法，是法治工作的布局，说明立法、执法、司法、守法要一起推进，但不是总抓手这个定位。最容易把这十六个字当成总抓手，就是因为它们更常被背到。诉讼不是解决纠纷的唯一途径，内部文件也不能代替法律。","source":"原创练习"},{"id":"zz-48","subject":"基本知识","chapter":"政治","stem":"社会主义基本经济制度，除了公有制为主体、多种所有制经济共同发展，还包括：","options":["按资分配为主体，市场不受任何调节","只保留按劳分配，取消其他分配方式","单一公有制和完全指令性计划","按劳分配为主体、多种分配方式并存，以及社会主义市场经济体制"],"answer":3,"explanation":"社会主义基本经济制度包括三项：公有制为主体、多种所有制经济共同发展，按劳分配为主体、多种分配方式并存，社会主义市场经济体制。只记住所有制，是印象最深、因而最容易漏掉按劳分配和市场经济体制的答法。分配方式和市场经济体制已经列入基本经济制度，不再被看成制度外面的临时办法。单一公有制加指令性计划，不是当前的制度。","source":"原创练习"},{"id":"zz-49","subject":"基本知识","chapter":"政治","stem":"国防和军队现代化的阶段安排，正确的是：","options":["2035年实现建军一百年奋斗目标，之后再研究要不要现代化","只有本世纪中叶一个节点，2027年和2035年都没有安排","2020年就全面建成世界一流军队","2027年实现建军一百年奋斗目标，2035年基本实现国防和军队现代化，本世纪中叶全面建成世界一流军队"],"answer":3,"explanation":"阶段安排是：到2027年实现建军一百年奋斗目标，到2035年基本实现国防和军队现代化，到本世纪中叶把人民军队全面建成世界一流军队。2027年对应的是建军一百年，不是世界一流军队；世界一流军队放在本世纪中叶。最容易对调的是2027年和2035年的任务，或者把国家层面2035年基本实现现代化直接写成建军一百年。三个节点的任务用语不能互换。","source":"原创练习"},{"id":"zz-50","subject":"基本知识","chapter":"政治","stem":"“两个确立”指的是：","options":["确立习近平同志党中央的核心、全党的核心地位，确立习近平新时代中国特色社会主义思想的指导地位","确立人民代表大会制度，确立民族区域自治制度","确立社会主义市场经济的改革目标，确立依法治国基本方略","维护党中央权威和集中统一领导，维护人民军队的宗旨"],"answer":0,"explanation":"两个确立，是确立习近平同志党中央的核心、全党的核心地位，确立习近平新时代中国特色社会主义思想的指导地位。两个维护，是坚决维护习近平总书记党中央的核心、全党的核心地位，坚决维护党中央权威和集中统一领导。最容易把“维护党中央权威”写进两个确立：那是两个维护里的内容，动词是维护，不是确立。市场经济目标和依法治国方略是更早的重要决策，也不是两个确立。","source":"原创练习"},{"id":"zz-51","subject":"基本知识","chapter":"政治","stem":"四个自信里，被强调为更基础、更广泛、更深厚的自信是：","options":["道路自信","文化自信","理论自信","制度自信"],"answer":1,"explanation":"四个自信是道路自信、理论自信、制度自信、文化自信。文化自信是更基础、更广泛、更深厚的自信，因为它连着一个民族的历史传统、价值观念和精神追求，另外三个自信都要有文化作支撑。最容易选成道路自信，因为道路问题常常被说成最根本的问题。最根本的问题和“更基础、更广泛、更深厚的自信”不是同一个定位，不能互相替换。","source":"原创练习"},{"id":"fl-01","subject":"基本知识","chapter":"法律","stem":"关于宪法和其他法的效力关系，正确的是：","options":["地方性法规与宪法不一致时，优先适用本地法规","宪法只在没有普通法律时起补充作用，效力与行政法规相同","宪法只约束公民，不约束国家机关如何行使职权","宪法是根本法，一切法律、行政法规和地方性法规都不得同宪法相抵触"],"answer":3,"explanation":"宪法规定国家的根本制度和根本任务，具有最高法律效力。法律、行政法规、地方性法规同宪法抵触的，失去效力，不能和宪法平行，更不能以地方规定压过宪法。最容易错的是“宪法只约束公民”：宪法首先规范国家权力怎样产生和行使，公民基本权利也要靠约束公权力来保障。","source":"原创练习"},{"id":"fl-02","subject":"基本知识","chapter":"法律","stem":"把国家性质和政权组织形式分开以后，我国对应的一对是：","options":["国家性质是多党合作制度，政权组织形式是联邦制","国家性质是民主集中制，政权组织形式是委员会制","国家性质是人民民主专政，政权组织形式是人民代表大会制度","国家性质是人民代表大会制度，政权组织形式是人民民主专政"],"answer":2,"explanation":"国家性质回答各阶级在国家中的地位，我国是人民民主专政的社会主义国家。政权组织形式是人民代表大会制度。这两个词经常被对调，对调之后每个词都眼熟，位置却错了。多党合作是基本政治制度，民主集中制是组织原则，都不是国家性质或政权组织形式的名称。联邦制也不是我国的国家结构形式。","source":"原创练习"},{"id":"fl-03","subject":"基本知识","chapter":"法律","stem":"我国的国家结构形式应当如何理解？","options":["单一制；民族区域自治和特别行政区都不改变国家的统一","联邦制，民族自治地方和特别行政区都是加盟单位","邦联制，各地方保留退出的权利","复合制，中央和地方分掌主权"],"answer":0,"explanation":"我国是单一制国家，主权由中央统一行使。民族区域自治是在国家统一领导下的自治，特别行政区的高度自治权来自中央授权，两者都是单一制之内的安排，不是联邦的成员单位。最有迷惑性的是看到自治区、特别行政区就选联邦制，那是把自治程度误认成了主权分割。","source":"原创练习"},{"id":"fl-04","subject":"基本知识","chapter":"法律","stem":"解释宪法、监督宪法实施的职权，主要由谁行使？","options":["解释宪法和监督宪法实施都属于国务院","最高人民法院解释宪法，最高人民检察院监督宪法实施","全国人大及其常委会监督宪法实施，全国人大常委会解释宪法","省级人大常委会各自解释宪法在本省的含义"],"answer":2,"explanation":"监督宪法实施的职权属于全国人民代表大会及其常务委员会。宪法的解释权属于全国人大常委会。我国不实行由最高法院解释宪法的体制，所以“最高人民法院解释宪法”虽然像某些国家的制度，但不是我国的安排。国务院没有宪法解释权，地方机关也不能各自解释宪法。","source":"原创练习"},{"id":"fl-05","subject":"基本知识","chapter":"法律","stem":"刑事、民事、国家机构等方面的基本法律，由谁制定和修改？","options":["省级人民代表大会","最高人民法院审判委员会","全国人民代表大会","国务院常务会议"],"answer":2,"explanation":"全国人民代表大会制定和修改刑事、民事、国家机构的和其他的基本法律。全国人大常委会制定和修改基本法律以外的其他法律，并可以在全国人大闭会期间对基本法律作部分补充和修改，但不得同该法律的基本原则相抵触。最容易把制定权上收到常委会，或者下放到省级人大。国务院制定的是行政法规，法院没有立法权。","source":"原创练习"},{"id":"fl-06","subject":"基本知识","chapter":"法律","stem":"公民享有选举权和被选举权，应当同时具备的条件是：","options":["年满十六周岁，并且在本地有固定工作","只要具有中国国籍，不设年龄和资格限制","年满十八周岁，并且没有被剥夺政治权利","年满十八周岁，并且具有大专以上学历"],"answer":2,"explanation":"年满十八周岁的公民都有选举权和被选举权，但是依照法律被剥夺政治权利的人除外。民族、性别、职业、教育程度、财产状况和居住期限都不是条件。最容易把年龄记成十六周岁，那是部分劳动或刑事责任规则里的年龄，不是选举年龄。被判处刑罚的人，只要没有被剥夺政治权利，选举权仍然在。不能行使选举权利的精神病患者，经选举委员会确认不列入选民名单，这是行使能力问题，不是剥夺政治权利。","source":"原创练习"},{"id":"fl-07","subject":"基本知识","chapter":"法律","stem":"我国人大代表中，由选民直接选举产生的是：","options":["不设区的市、市辖区、县、自治县、乡、民族乡、镇的人民代表大会代表","从乡到全国的各级人大代表全部由选民直接投票","省、自治区、直辖市人民代表大会的代表","全国人民代表大会的全体代表"],"answer":0,"explanation":"县、乡两级人大代表由选民直接选举，包括不设区的市、市辖区、县、自治县、乡、民族乡、镇。设区的市、自治州以上的人大代表由下一级人民代表大会选举，是间接选举。最常见的错误是以为全国人大代表也由选民直接投票产生，或者反过来以为县级也是间接选举。直接和间接相结合，不是每一级都直接。","source":"原创练习"},{"id":"fl-08","subject":"基本知识","chapter":"法律","stem":"国务院在国家机构中的地位是：","options":["最高国家权力机关的执行机关，也是最高国家行政机关","最高国家权力机关","最高监察机关","单独决定国家重大事务的元首机关"],"answer":0,"explanation":"国务院即中央人民政府，是最高国家权力机关的执行机关，是最高国家行政机关。最高国家权力机关是全国人民代表大会。国家监察委员会是最高监察机关。国家主席根据全国人大及其常委会的决定行使国家元首职权，不单独决定国家重大事务。最容易把“最高”用错对象，把国务院写成最高国家权力机关。","source":"原创练习"},{"id":"fl-09","subject":"基本知识","chapter":"法律","stem":"人民法院依照法律规定独立行使审判权，不受哪些主体干涉？","options":["不受上级人民法院依照法定程序进行的审判监督","不受行政机关、社会团体和个人的干涉","不受任何国家机关监督，包括权力机关","不受法律约束，只接受当事人私下和解"],"answer":1,"explanation":"独立审判针对的是行政机关、社会团体和个人的干涉，目的是避免以言代法、以权压法。它不排除人大及其常委会的监督，也不排除上级法院依照法定程序的审判监督，更不是说法官可以不依法律。“不受任何国家机关监督”把独立审判扩大成了不受监督，是最接近也最出界的一种说法。","source":"原创练习"},{"id":"fl-10","subject":"基本知识","chapter":"法律","stem":"宪法对公民私有财产的态度是：","options":["只要目的是公共利益，征收就可以不给补偿","只有生活资料受保护，生产资料一律不受保护","任何情况下都不得征收或者征用公民财产","公民的合法私有财产不受侵犯；国家为了公共利益需要，可以依照法律规定征收或者征用并给予补偿"],"answer":3,"explanation":"公民的合法私有财产不受侵犯。国家为了公共利益的需要，可以依照法律规定实行征收或者征用并给予补偿。保护不是绝对不能动用；动用必须同时有公共利益、法律依据和补偿。只写一律不得征收，看起来最保护财产，却和允许依法征收征用并补偿的规则不符。只讲公共利益、不讲补偿，同样缺了条件。","source":"原创练习"},{"id":"fl-11","subject":"基本知识","chapter":"法律","stem":"在公民的基本权利义务中，受教育这一项的特点是：","options":["既是权利，又是义务","只是义务，公民不能主张受教育的机会","只是权利，国家不能对接受规定教育提出义务要求","只适用于未成年人，成年人不再享有也不再承担"],"answer":0,"explanation":"公民有受教育的权利和义务。说它是权利，是因为国家要提供条件、公民可以主张受教育机会；说它是义务，是因为完成国家规定的教育也是公民的责任。劳动同样既是权利又是义务。只承认其中一面，是最常见的半对。成年以后继续学习的权利，也不因成年而消失。","source":"原创练习"},{"id":"fl-12","subject":"基本知识","chapter":"法律","stem":"特别行政区的高度自治权应当如何理解？","options":["高度自治权来自当地投票，中央只有建议权","特别行政区拥有主权，可以自行决定退出国家","高度自治权来源于中央授权；外交和国防由中央负责","高度自治等于完全自治，中央不再过问本地事务"],"answer":2,"explanation":"“一国两制”下，特别行政区保持原有的资本主义制度和生活方式长期不变，享有行政管理权、立法权、独立的司法权和终审权。这些高度自治权来源于中央授权，不是当地固有的主权。外交和国防由中央统一管理，中央对特别行政区拥有全面管治权。最要防的是把高度自治说成完全自治：高度不等于完整，授权也不等于分出主权。","source":"原创练习"},{"id":"fl-13","subject":"基本知识","chapter":"法律","stem":"民法主要调整哪一类社会关系？","options":["行政机关与相对人之间的命令服从关系","平等主体的自然人、法人和非法人组织之间的人身关系和财产关系","检察机关与犯罪嫌疑人之间的追诉关系","单位依据内部隶属关系作出的人事处理"],"answer":1,"explanation":"民法调整平等主体之间的人身关系和财产关系。主体地位平等，是把它和行政法、刑法分开的第一刀。行政机关处罚相对人、单位基于隶属管理职工，都有命令与服从，不由民法来调整。最容易混进来的是行政征收、行政处罚这一类纵向关系。劳动关系还有专门的劳动法，也不能简单并进一般民事合同。","source":"原创练习"},{"id":"fl-14","subject":"基本知识","chapter":"法律","stem":"一家大型国有公司和一名个体摊贩签订买卖合同。二人在民法上的地位是：","options":["个体摊贩不适用民法，只适用内部政策","只有国有主体受民法保护","国有公司享有命令权，摊贩必须服从","双方民事法律地位一律平等，不因所有制和规模不同而分高下"],"answer":3,"explanation":"民事主体在民事活动中的法律地位一律平等，不因所有制、规模或职业而让一方在签约时高人一等。最容易被现实中的强势一方带偏，以为国企可以在民事合同里命令对方。机关行使职权时是纵向的行政管理；一旦走入合同，就回到平等主体。与平等相连的自愿原则还要求，一方不得把自己的意志强加给对方。","source":"原创练习"},{"id":"fl-15","subject":"基本知识","chapter":"法律","stem":"涉及遗产继承、接受赠与等胎儿利益保护时，胎儿的民事权利能力如何处理？","options":["只有办完出生登记，才回溯保护胎儿时期的利益","胎儿视为具有民事权利能力；但是娩出时为死体的，其民事权利能力自始不存在","胎儿在任何领域都和已经出生的人完全相同","胎儿一律没有民事权利能力，利益只能记在母亲名下"],"answer":1,"explanation":"自然人的民事权利能力一般从出生时起到死亡时止。为了保护胎儿将来能够得到的遗产、赠与等利益，法律把胎儿视为具有民事权利能力。这个“视为”附有条件：娩出时是死体的，权利能力自始不存在。把它说成在任何领域都和已出生的人完全相同，就把一项有限保护扩成了普遍的权利能力。出生登记是管理手续，不是权利能力开始的条件。","source":"原创练习"},{"id":"fl-16","subject":"基本知识","chapter":"法律","stem":"按照民法典，不满八周岁的未成年人属于：","options":["视为完全民事行为能力人","完全民事行为能力人","无民事行为能力人","限制民事行为能力人"],"answer":2,"explanation":"不满八周岁的未成年人是无民事行为能力人，由法定代理人代理实施民事法律行为。八周岁以上的未成年人才是限制民事行为能力人，可以独立实施纯获利益的行为以及与其年龄、智力相适应的行为。最容易用旧标准把界限记成十周岁，从而把八九岁的孩子当成限制民事行为能力人。十六周岁以上、以自己的劳动收入为主要生活来源的未成年人，视为完全民事行为能力人，这和不满八周岁无关。","source":"原创练习"},{"id":"fl-17","subject":"基本知识","chapter":"法律","stem":"不能辨认自己行为的成年人，民事行为能力属于：","options":["完全民事行为能力","无民事行为能力","限制民事行为能力","与靠自己劳动生活的未成年人一样，视为完全民事行为能力"],"answer":1,"explanation":"不能辨认自己行为的成年人是无民事行为能力人，由法定代理人代理实施民事法律行为。不能完全辨认自己行为的成年人才是限制民事行为能力人。两句话只差“完全”二字，这是最容易看滑的地方：完全不能辨认，是无行为能力；还有部分辨认能力，才是限制行为能力。年龄已经成年，并不能单独推出完全行为能力。","source":"原创练习"},{"id":"fl-18","subject":"基本知识","chapter":"法律","stem":"基于重大误解实施的民事法律行为，效力状态是：","options":["可撤销；重大误解的撤销权，自知道或者应当知道撤销事由之日起九十日内不行使就消灭","有效，误解的一方只能自认吃亏","效力未定，必须等人民法院不告也主动宣告","自始无效，任何人都可以主张，而且不能再补救"],"answer":0,"explanation":"基于重大误解实施的民事法律行为，行为人有权请求人民法院或者仲裁机构予以撤销。欺诈、显失公平也走可撤销这条路，胁迫则从胁迫行为终止之日起计算一年。撤销前行为已经生效，不撤销就继续有效，这和自始无效不同。重大误解的撤销权期间是九十日，短于一般的一年，最容易把误解直接当成无效，或者把九十日没记成一年。法院也不会不经请求就主动撤销。","source":"原创练习"},{"id":"fl-19","subject":"基本知识","chapter":"法律","stem":"普通诉讼时效期间届满以后，权利本身发生什么变化？","options":["权利绝对消灭，义务人再履行也构成不当得利，可以要回","义务人取得可以不履行的抗辩；人民法院不得主动适用诉讼时效","届满后再过六个月，权利又自行恢复","债权自动变成刑事追诉"],"answer":1,"explanation":"普通诉讼时效期间为三年，自权利人知道或者应当知道权利受到损害以及义务人之日起计算。期间届满，义务人可以提出不履行的抗辩，权利本身并不消灭。义务人同意履行的，不得再拿时效当挡箭牌；已经自愿履行的，不得请求返还。人民法院不得主动适用诉讼时效。最容易理解错的是“权利绝对消灭”。另外，自权利受到损害之日起超过二十年的，人民法院不予保护，有特殊情况可以依申请延长，这和三年的普通时效不是同一个期间。","source":"原创练习"},{"id":"fl-20","subject":"基本知识","chapter":"法律","stem":"诉讼时效中止和中断的主要区别是：","options":["二者都使期间从零重新计算，没有差别","中止发生在最后六个月内，障碍消除之日起满六个月期间届满；中断则使时效期间重新计算","中止一经发生，权利就永久不再受时效限制","中断只适用于不可抗力，中止只适用于向法院起诉"],"answer":1,"explanation":"在诉讼时效期间的最后六个月内，因不可抗力、没有法定代理人等法定障碍不能行使请求权的，诉讼时效中止，自障碍消除之日起满六个月，期间届满。权利人请求履行、义务人同意履行、提起诉讼或者申请仲裁，引起中断，时效期间重新计算；起诉、仲裁的，从有关程序终结时起算。中止是最后阶段暂停后续上一段时间，中断是重算。把起诉说成中止的原因，就是把两种效果装反了。","source":"原创练习"},{"id":"fl-21","subject":"基本知识","chapter":"法律","stem":"成年子女请求父母支付拖欠的赡养费，是否适用普通诉讼时效？","options":["只在父母同意时才不适用","适用，超过三年法院就不再保护","不适用诉讼时效","适用二十年的最长时效，不适用三年，但满二十年绝对消灭"],"answer":2,"explanation":"请求支付抚养费、赡养费或者扶养费，不适用诉讼时效。请求停止侵害、排除妨碍、消除危险，以及不动产物权和登记的动产物权的权利人请求返还财产，同样不适用。不能把“请求权都适用三年”当成没有例外的公式。题目里最像正确答案的是“满二十年绝对消灭”：二十年是普通民事权利的最长保护期间，而且特殊情况还可以申请延长，并不能套到本来就不受诉讼时效限制的赡养费请求上。","source":"原创练习"},{"id":"fl-22","subject":"基本知识","chapter":"法律","stem":"公司长期让业务员持盖有公章的空白合同对外签约。公司后来开除了该业务员，却没有收回剩余空白合同，也没有通知老客户。业务员仍用这份空白合同与老客户签约。公司能否以业务员已被开除为由，主张该合同对自己不生效？","options":["不能；合同只约束业务员个人，与公司和客户都无关","能，因为空白合同一律没有法律效力","能，无权代理未经追认一律无效","不能；相对人有理由相信业务员有代理权，构成表见代理，代理行为有效"],"answer":3,"explanation":"狭义的无权代理，未经被代理人追认，对被代理人不发生效力。表见代理是例外：代理权已经终止，相对人仍有理由相信行为人有代理权的，代理行为有效，用来保护合理信赖。本题里，长期使用盖章空白合同、开除后不收回也不通知，给了老客户这种信赖。没有这层外表理由的普通无权代理，仍然要等追认。空白合同并不当然无效，关键看相对人的相信有没有根据。","source":"原创练习"},{"id":"fl-23","subject":"基本知识","chapter":"法律","stem":"王某捡到一只相机，以正常市价卖给不知情的赵某并已交付。失主一个月后找到赵某。赵某能否仅凭自己不知情且付了合理价格，就拒绝返还？","options":["不能；遗失物不适用“不知情就立刻取得所有权”，失主在知道受让人之日起二年内可以请求返还原物","能；凡是捡到的东西，拾得人都可以自由出卖","能；不知情、价格合理并且已经交付，所有权立刻确定归赵某","不能；相机属于不动产，必须登记才转移"],"answer":0,"explanation":"动产善意取得通常要同时具备：无权处分、受让时善意、合理价格、已经交付。遗失物是例外，不因这几项齐备就立刻切断失主的返还请求。失主自知道或者应当知道受让人之日起二年内，可以向受让人请求返还原物；如果受让人是通过拍卖或者向有经营资格的经营者购得的，请求返还时应当支付受让人所付的费用。最容易扩大的是把“不知情”一项当成全部条件。私人买卖也不等于拾得人有权处分。相机是动产，不是不动产。","source":"原创练习"},{"id":"fl-24","subject":"基本知识","chapter":"法律","stem":"船舶、航空器和机动车的所有权自何时变动，登记又起什么作用？","options":["合同一成立物权就转移，交付和登记都不影响归属","这三类财产只能质押，不能买卖","必须登记才在买卖双方之间发生物权变动，交付没有意义","交付时在当事人之间发生物权变动；未经登记，不得对抗善意第三人"],"answer":3,"explanation":"普通动产以交付为物权变动的标志。船舶、航空器、机动车仍是动产，交付就在当事人之间发生物权效力，但未经登记不得对抗善意第三人。不登记，并不表示买卖双方之间没有转移，只是不能用来排斥后来的善意第三人。把它说成不登记就完全不转移，是把不动产登记生效的规则套到了这些特殊动产上。","source":"原创练习"},{"id":"fl-25","subject":"基本知识","chapter":"法律","stem":"债务人以自己的房屋为债权人提供担保，办理了抵押登记，债务人继续住在这套房屋里。下列说法正确的是：","options":["不办登记、只凭口头约定，房屋抵押权也已经生效","这是质权，因为凡是担保都必须把财产交给债权人占有","这是抵押权；抵押权不转移占有，并以登记为设立条件。土地所有权不得抵押","城市房屋的土地所有权可以和房屋一起抵押给私人"],"answer":2,"explanation":"抵押不转移占有，债务人可以继续使用房屋；质押则要把动产交给债权人占有，或者完成权利质押的交付、登记。以建筑物抵押的，应当办理抵押登记，抵押权自登记时设立，口头约定不能让抵押权生效。土地所有权属于国家或者集体，不得抵押，这是最容易和房屋抵押权混在一起的一点：抵押的是房屋及其范围内的建设用地使用权等依法可以抵押的权利，不是土地所有权。","source":"原创练习"},{"id":"fl-26","subject":"基本知识","chapter":"法律","stem":"健身卡使用一份事先印好的条款。其中一句既可以理解成“发生任何伤残都由会员自负”，也可以理解成“只对场馆未尽安全提示的伤残负责”。应当怎样解释？","options":["格式条款一律无效，整份合同因此失效","一律采用场馆一方作出的解释","先按通常理解解释；仍有两种以上解释的，作出不利于提供格式条款一方的解释","争议发生后，由场馆单方选定一种解释"],"answer":2,"explanation":"格式条款先按通常理解解释。存在两种以上解释的，应当作出不利于提供格式条款一方的解释，因为条款是他预先单方拟定的，歧义不让相对人承担。这不等于格式条款全部无效，合同也不因此整份作废。无效的是那些不合理地免除或者减轻提供方责任、加重对方责任、限制或排除对方主要权利的条款。提供方对与对方有重大利害关系的条款还要尽到提示说明义务，没有做到的，对方可以主张该条款不成为合同内容。格式条款和非格式条款不一致的，采用非格式条款。","source":"原创练习"},{"id":"fl-27","subject":"基本知识","chapter":"法律","stem":"收受定金的一方不履行债务时，定金应当怎样处理？","options":["定金归收受方所有，同时必须再收一笔违约金","应当双倍返还定金；当事人不能既主张定金罚则又主张违约金","定金自动变成罚款，上缴国库","只把定金原数返还"],"answer":1,"explanation":"给付定金的一方不履行债务，无权请求返还定金；收受定金的一方不履行债务，应当双倍返还定金。定金数额不得超过主合同标的额的百分之二十，超过的部分不产生定金效力，定金合同自实际交付时成立。既约定定金又约定违约金的，对方只能选择适用其中之一，不能并行要两份。定金不够弥补损失的，仍可以就超出部分请求赔偿，这和“定金加违约金一起要”不是一回事。定金也不是上缴国库的罚款。","source":"原创练习"},{"id":"fl-28","subject":"基本知识","chapter":"法律","stem":"用人单位的工作人员因执行工作任务造成他人损害，对外由谁承担责任？","options":["由工作人员和受害人所在的社区平均分担","由用人单位承担侵权责任","只有工作人员出于故意时单位才负责，过失一概由个人承担","一律由工作人员个人承担，单位不负责"],"answer":1,"explanation":"工作人员因执行工作任务造成他人损害的，由用人单位承担侵权责任。单位承担责任后，可以向有故意或者重大过失的工作人员追偿。外部责任先落在单位，是为了让受害人找得到有清偿能力的主体，而不是先审查工作人员是故意还是过失。最容易选成一律由个人承担，那是把内部追偿和外部责任弄反了。劳务派遣中，由接受派遣的用工单位承担责任；派遣单位有过错的，承担相应的责任。纯粹的个人事务，不属于执行工作任务。","source":"原创练习"},{"id":"fl-29","subject":"基本知识","chapter":"法律","stem":"未到法定结婚年龄就办理了结婚登记。这一情形在效力上属于：","options":["效力待定，等待双方父母追认","无效事由；与因胁迫结婚那种可撤销事由不是同一类","可撤销，只能由婚姻登记机关在一年内撤销","有效，年龄可以在婚后自动补正"],"answer":1,"explanation":"法定结婚年龄是男不得早于二十二周岁，女不得早于二十周岁，并且必须双方完全自愿、亲自登记。重婚、有禁止结婚的亲属关系、未到法定婚龄，是婚姻无效的事由。因胁迫结婚，以及一方在登记前隐瞒重大疾病，才是可撤销。年龄问题不能靠父母追认变成有效。需要补上一笔：请求确认无效时，如果法定的无效情形已经消失，例如双方都已达到婚龄，法院不再确认无效。那是事由消失后的处理，并不把未达婚龄改成可撤销事由。","source":"原创练习"},{"id":"fl-30","subject":"基本知识","chapter":"法律","stem":"下列哪一项属于夫妻一方的个人财产？","options":["婚姻关系存续期间一方取得的工资和奖金","婚姻关系存续期间一方经营所得的收益","一方婚前全款购买并登记在自己名下的房屋","婚姻关系存续期间一方因知识产权取得的收益"],"answer":2,"explanation":"婚后取得的工资、奖金、经营收益、知识产权收益，一般是夫妻共同财产。一方的婚前财产，不因结婚自动变成共同财产。遗嘱或者赠与合同确定只归一方的财产，以及一方因人身损害获得的赔偿或者补偿，也是个人财产。最容易划进共同财产的是婚前房屋。本题限定全款并且登记在自己名下，没有婚后共同还贷的问题；没有特别约定时，它仍归婚前所有的一方。","source":"原创练习"},{"id":"fl-31","subject":"基本知识","chapter":"法律","stem":"老周没有留下遗嘱。他去世时，配偶、父母和一个子女都还在世，另外还有一个弟弟。法定继承中，第一顺序参加继承的是：","options":["配偶、父母和弟弟","子女、弟弟以及父母的兄弟姐妹","配偶、子女和父母","配偶、子女和弟弟"],"answer":2,"explanation":"第一顺序是配偶、子女、父母；第二顺序是兄弟姐妹、祖父母、外祖父母。有第一顺序继承人的，由第一顺序继承，第二顺序不继承。弟弟是兄弟姐妹，不能挤进第一顺序，这是本题最容易加进去的一个人。子女包括婚生子女、非婚生子女、养子女和有扶养关系的继子女。孙子女不是第二顺序继承人；子女先于被继承人死亡时，由子女的直系晚辈血亲代位继承。丧偶儿媳对公婆、丧偶女婿对岳父母尽了主要赡养义务的，可以作为第一顺序继承人。","source":"原创练习"},{"id":"fl-32","subject":"基本知识","chapter":"法律","stem":"遗嘱人先后立了几份内容互相抵触的遗嘱。应当以哪一份为准？","options":["以第一份遗嘱为准，后立的都只是补充","一律以公证遗嘱为准，后来的非公证遗嘱不能改变它","以最后一份本身有效的遗嘱为准","几份遗嘱全部无效，直接改为法定继承"],"answer":2,"explanation":"立有数份遗嘱、内容相抵触的，以最后的遗嘱为准。公证遗嘱不再当然优先于后来的其他合法遗嘱，沿用“公证遗嘱永远优先”是最常见的旧规则。最后一份必须本身有效：因无民事行为能力、伪造等原因无效的遗嘱，不能仅凭日期在后就推翻前面有效的遗嘱。全部无效也没有依据。另外，遗赠扶养协议优先于遗嘱，遗嘱又优先于法定继承，那是不同依据之间的顺序，和“数份遗嘱取最后一份”不是同一层问题。","source":"原创练习"},{"id":"fl-33","subject":"基本知识","chapter":"法律","stem":"因产品存在缺陷造成他人损害，生产者承担侵权责任的规则是：","options":["生产者不能以自己没有过失为由免责","只有生产者与受害人签订过合同才负责","公平责任，生产者和受害人一律各承担一半","过错责任，受害人必须证明生产者有过失"],"answer":0,"explanation":"一般侵权看过错。产品缺陷造成他人损害的，生产者应当承担侵权责任，不要求受害人证明生产者有过失。被侵权人可以向生产者请求赔偿，也可以向销售者请求赔偿；一边赔偿后，属于另一边责任的，有权追偿。法定的免责是未将产品投入流通、投入流通时引起损害的缺陷尚不存在等情形，而不是“我已经尽了注意”。没有合同，也不挡住这种侵权责任。各承担一半不是产品责任的规则。","source":"原创练习"},{"id":"fl-34","subject":"基本知识","chapter":"法律","stem":"甲在山坡上放倒一棵枯树，看见下方有人行走，仍继续放倒，心想砸到就砸到。行人被砸伤。甲的主观心态是：","options":["意外事件","过于自信的过失","疏忽大意的过失","间接故意"],"answer":3,"explanation":"故意和过失都可能预见到结果，分界在意志因素。希望结果发生是直接故意；明知可能发生而放任其发生，是间接故意。已经预见、却轻信能够避免，才是过于自信的过失。本题写明“砸到就砸到”，是放任，不是以为一定砸不中。疏忽大意的过失是应当预见而没有预见。意外事件是不能预见的原因引起的，行为人不构成犯罪。放任和轻信只差一个态度，这是最容易对调的两处。","source":"原创练习"},{"id":"fl-35","subject":"基本知识","chapter":"法律","stem":"已满十二周岁不满十四周岁的人，在什么条件下才可能负刑事责任？","options":["实施了刑法规定的任何犯罪都应当负刑事责任","犯抢劫、放火、贩卖毒品罪就应当负刑事责任","一律不负刑事责任，年龄线仍然固定在十四周岁","犯故意杀人、故意伤害罪，致人死亡或者以特别残忍手段致人重伤造成严重残疾，情节恶劣，并经最高人民检察院核准追诉"],"answer":3,"explanation":"已满十六周岁的人犯罪，应当负刑事责任。已满十四周岁不满十六周岁的人，只对故意杀人、故意伤害致人重伤或者死亡、强奸、抢劫、贩卖毒品、放火、爆炸、投放危险物质这几类行为负刑事责任。十二周岁到十四周岁更窄：仅限故意杀人、故意伤害，并且要致人死亡或者以特别残忍手段致人重伤造成严重残疾、情节恶劣，还须经最高人民检察院核准追诉。把抢劫、放火也放进这一档，是把十四至十六周岁的罪名表误用了。不满十二周岁的人，不负刑事责任。","source":"原创练习"},{"id":"fl-36","subject":"基本知识","chapter":"法律","stem":"醉酒的人实施了刑法禁止的行为，应当如何处理？","options":["一律不负刑事责任，因为当时控制不住自己","只有造成死亡结果才负刑事责任","应当负刑事责任","直接按不能辨认自己行为的精神病人处理，鉴定后免除责任"],"answer":2,"explanation":"醉酒的人犯罪，应当负刑事责任。法律不把自己喝醉当成免责事由。这和精神病人不同：经法定程序鉴定确认，在不能辨认或者不能控制自己行为的时候造成危害结果的，不负刑事责任。间歇性精神病人在精神正常的时候犯罪，应当负刑事责任。尚未完全丧失辨认或者控制能力的精神病人犯罪，应当负刑事责任，但是可以从轻或者减轻处罚。不能把醉酒类推成精神病免责，也不能只在死人时才追究。","source":"原创练习"},{"id":"fl-37","subject":"基本知识","chapter":"法律","stem":"乙用棍击打甲。甲夺下棍子后，乙扔掉棍子、举手求饶，侵害已经停止。甲又追上去击打，致乙轻伤。对甲后来这一部分追打，正确的评价是：","options":["对方先动手，所以后来的追打全部仍是正当防卫","只要没有造成死亡，事后的追打都不负刑事责任","不法侵害已经结束，后来的追打属于防卫不适时，不能再主张正当防卫","防卫可以针对对方以往任何一次违法，不限于这次"],"answer":2,"explanation":"正当防卫必须针对正在进行的不法侵害。侵害尚未开始就提前动手，或者侵害已经结束后再报复，都是防卫不适时，可能单独构成犯罪。本题里，对方已经弃棍求饶，侵害停止，后面的追打不再具备时间条件。最容易被当成正当的，就是“既然对方先动手，后面怎么打都还是防卫”。对正在进行的行凶、杀人、抢劫、强奸、绑架以及其他严重危及人身安全的暴力犯罪，造成不法侵害人伤亡可以不属于防卫过当，但这个规则同样要求暴力犯罪正在进行，不能扩展到事后追打。","source":"原创练习"},{"id":"fl-38","subject":"基本知识","chapter":"法律","stem":"防卫行为明显超过必要限度并造成重大损害的，刑事责任如何？","options":["不负刑事责任，因为出发点是防卫","按照对方原来准备实施的罪名从重处罚","只承担医药费，刑法不再评价","应当负刑事责任，但是应当减轻或者免除处罚"],"answer":3,"explanation":"没有明显超过必要限度造成重大损害的正当防卫，不负刑事责任。明显超过必要限度造成重大损害的，是防卫过当，应当负刑事责任，但是应当减轻或者免除处罚。出发点正当，影响的是从宽，不是把刑事责任整个拿掉。按对方本来想犯的罪去处罚防卫人，没有法律根据。民事上的赔偿也不能代替刑事上对防卫过当的评价。紧急避险超过必要限度造成不应有的损害的，同样应当负刑事责任，但是应当减轻或者免除处罚。","source":"原创练习"},{"id":"fl-39","subject":"基本知识","chapter":"法律","stem":"自动放弃犯罪、没有造成损害的中止犯，和由于意志以外的原因未得逞的未遂犯，处罚上的关键差别是：","options":["没有造成损害的中止犯应当免除处罚；未遂犯可以从轻或者减轻处罚，但不能免除","未遂犯应当免除处罚，中止犯只能从轻","二者都应当从重处罚","二者都应当免除处罚"],"answer":0,"explanation":"犯罪中止是在犯罪过程中自动放弃犯罪，或者自动有效地防止犯罪结果发生。没有造成损害的，应当免除处罚；造成损害的，应当减轻处罚。犯罪未遂是已经着手，由于意志以外的原因未得逞，可以比照既遂犯从轻或者减轻处罚，没有免除这一档。自动停止和被迫停下来，是中止和未遂的分界。最容易把未遂的“可以从轻或者减轻”套到没有造成损害的中止上，把“应当免除”降成了“可以减轻”。免除处罚不等于行为自始不是犯罪。犯罪预备是为了犯罪准备工具、制造条件，可以比照既遂犯从轻、减轻或者免除处罚，和已经着手的未遂也不同。","source":"原创练习"},{"id":"fl-40","subject":"基本知识","chapter":"法律","stem":"二人以上共同过失犯罪，应当如何论处？","options":["以共同犯罪论处，并区分主犯和从犯","只处罚其中职务较高的一人","过失不能构成任何犯罪，直接作无罪处理","不以共同犯罪论处；应当负刑事责任的，按照所犯的罪分别处罚"],"answer":3,"explanation":"共同犯罪是二人以上共同故意犯罪。共同过失犯罪，不以共同犯罪论处；应当负刑事责任的，按照他们所犯的罪分别处罚。共同犯罪要有共同的犯罪故意，过失缺少这个意思联络，所以不能用主犯、从犯那一套来分配。过失并非都不构成犯罪，交通肇事等过失犯罪仍然要个别地负刑事责任。只处罚其中一个人，没有这样的原则。","source":"原创练习"},{"id":"fl-41","subject":"基本知识","chapter":"法律","stem":"下列哪一项属于附加刑，而不是主刑？","options":["拘役","有期徒刑","罚金","管制"],"answer":2,"explanation":"主刑是管制、拘役、有期徒刑、无期徒刑和死刑，一种犯罪只能适用一个主刑。附加刑是罚金、剥夺政治权利、没收财产，以及对犯罪的外国人可以适用的驱逐出境，可以附加适用，也可以独立适用。罚金容易和罚款相混：罚金是刑罚，由法院判处；罚款是行政处罚，由行政机关决定。管制不去监狱关押，但它仍是主刑，不要因为它的执行方式就当成附加刑。死刑缓期二年执行不是独立刑种，而是死刑的执行制度。","source":"原创练习"},{"id":"fl-42","subject":"基本知识","chapter":"法律","stem":"下列哪一类人不适用死刑？","options":["审判的时候已满七十五周岁、并且以特别残忍手段致人死亡的人","醉酒后实施犯罪的人","犯罪的时候不满十八周岁的人","犯罪时已满十八周岁、审判时没有怀孕的人"],"answer":2,"explanation":"犯罪的时候不满十八周岁的人和审判的时候怀孕的妇女，不适用死刑。这里的不适用，包括不适用死刑缓期执行。审判的时候已满七十五周岁的人，一般也不适用死刑，但是以特别残忍手段致人死亡的除外。最容易记成“七十五周岁一律不能判死刑”，从而漏掉这个例外。醉酒和已经成年、审判时也没有怀孕，都不是排除死刑的事由。","source":"原创练习"},{"id":"fl-43","subject":"基本知识","chapter":"法律","stem":"关于一般累犯，正确的是：","options":["过失犯罪也可以构成累犯，并且应当从重处罚","不满十八周岁的人犯罪，同样构成累犯","构成累犯以后，仍可以宣告缓刑和假释","被判处有期徒刑以上刑罚，执行完毕或者赦免以后五年以内，再犯应当判处有期徒刑以上刑罚之罪的，是累犯；过失犯罪和不满十八周岁的人犯罪除外"],"answer":3,"explanation":"一般累犯要求前后罪都是故意犯罪、都应当判处有期徒刑以上刑罚，后罪发生在前罪刑罚执行完毕或者赦免以后五年以内。过失犯罪和不满十八周岁的人犯罪除外。累犯应当从重处罚，不得缓刑，不得假释。只看到“五年内再犯”就打成累犯，会把过失和未成年人这两类不该打进去的人打进去。危害国家安全犯罪、恐怖活动犯罪、黑社会性质的组织犯罪还有特别累犯，在刑罚执行完毕或者赦免以后，任何时候再犯这三类罪之一，都以累犯论处，不受五年间隔限制。","source":"原创练习"},{"id":"fl-44","subject":"基本知识","chapter":"法律","stem":"犯罪以后自动投案，并如实供述自己的罪行。这一情节属于：","options":["立功，必须揭发他人的犯罪才能成立","坦白，只能从轻，不能减轻，更不能免除","自首，应当一律免除处罚","自首；可以从轻或者减轻处罚，其中犯罪较轻的，可以免除处罚"],"answer":3,"explanation":"自动投案并如实供述自己的罪行，是自首。对于自首，可以从轻或者减轻处罚；犯罪较轻的，可以免除处罚。被采取强制措施的犯罪嫌疑人、被告人和正在服刑的罪犯，如实供述司法机关还未掌握的本人其他罪行的，以自首论。坦白是被动归案后如实供述，一般可以从轻；因其如实供述避免特别严重后果发生的，可以减轻。二者的关键差别是会不会自己把案件送到办案机关面前。立功是揭发他人或者提供线索、协助抓捕，对象是别人的犯罪。自首不是应当一律免除。","source":"原创练习"},{"id":"fl-45","subject":"基本知识","chapter":"法律","stem":"限制人身自由的行政处罚，只能由哪一类规范来设定？","options":["部门规章","县级政府的红头文件","行政法规","法律"],"answer":3,"explanation":"法律可以设定各种行政处罚。限制人身自由的行政处罚，只能由法律设定。行政法规可以设定除限制人身自由以外的行政处罚，地方性法规和规章的设定权更窄。人身自由是基本权利，设定权收到法律这一层。最容易放宽的就是行政法规：它的权限很大，唯独这一类不行。规章和县级文件不能创设限制人身自由的处罚。","source":"原创练习"},{"id":"fl-46","subject":"基本知识","chapter":"法律","stem":"行政处罚中“对当事人的同一个违法行为不得给予两次以上罚款”，确切含义是：","options":["不得对同一个违法行为给予两次以上罚款；法律另有规定时仍可并处其他种类的处罚","同一个违法行为无论违反几部法律，都只能处罚一次，而且只能用一种处罚","已经被口头劝告改正的，不得再作任何处罚","罚款之后就绝对不能再追究刑事责任"],"answer":0,"explanation":"限制的是两次以上罚款。同一个违法行为违反多个法律规范应当罚款的，按照罚款数额高的规定处罚。它不禁止在罚款之外，依法再并处吊销许可证、行政拘留等其他种类。构成犯罪的，还要依法追究刑事责任，行政罚款挡不住刑事追诉。把它理解成“只能处罚一次、只能一种手段”，范围就放得太大了。口头劝告也不是已经作过罚款。","source":"原创练习"},{"id":"fl-47","subject":"基本知识","chapter":"法律","stem":"违法行为在二年内未被发现的，不再给予行政处罚。这一期限的重要例外是：","options":["只要造成财产损失，时效就不受任何限制","涉及公民生命健康安全、金融安全且有危害后果的，期限为五年","期限从行政机关立案之日起计算，与行为何时发生无关","所有违法行为的期限都是六个月"],"answer":1,"explanation":"违法行为在二年内未被发现的，不再给予行政处罚；涉及公民生命健康安全、金融安全且有危害后果的，期限为五年。法律另有规定的除外。期限从违法行为发生之日起计算；有连续或者继续状态的，从行为终了之日起计算，不是从立案之日起算。这里的未被发现，指行政机关未发现。最要记住的例外是生命健康和金融安全这一类五年，而不是“有损失就没有期限”。","source":"原创练习"},{"id":"fl-48","subject":"基本知识","chapter":"法律","stem":"在行政诉讼中，证明被诉行政行为合法的举证责任主要由谁承担？","options":["人民法院调查之后自行承担，当事人都不必举证","人民检察院在每一件行政案件中承担","原告，因为是原告启动了诉讼","作出行政行为的被告行政机关"],"answer":3,"explanation":"行政诉讼中，被告应当对作出的行政行为提供证据和所依据的规范性文件，证明它合法。这和民事诉讼“谁主张、谁举证”的一般分配不同，因为证据和职权依据掌握在行政机关手里。原告并不是什么都不用证明，仍要证明起诉符合法定条件等事项。最容易用民事习惯选成原告举证。法院有权调取证据，但调取不是把举证责任转给法院；检察院也不是每案的举证主体。","source":"原创练习"},{"id":"fl-49","subject":"基本知识","chapter":"法律","stem":"复议机关决定维持原行政行为，当事人向法院起诉。被告应当如何列？","options":["作出原行政行为的行政机关和复议机关是共同被告","复议机关的上一级人民政府","只有复议机关","只有作出原行政行为的机关"],"answer":0,"explanation":"复议机关决定维持原行政行为的，作出原行政行为的行政机关和复议机关是共同被告。复议机关改变原行政行为的，复议机关是被告。这样规定，是为了让维持决定的复议机关也对合法性负责，而不是签一个维持就退出诉讼。只告原机关、漏掉复议机关，是维持案件里最常见的列被告错误。复议机关不作为时，要看起诉的是原来的行为还是不作为，被告相应不同。","source":"原创练习"},{"id":"fl-50","subject":"基本知识","chapter":"法律","stem":"监察机关调查严重职务违法、职务犯罪时采取的留置，性质是：","options":["行政机关作出的行政拘留","监察机关的调查措施，不是行政拘留，也不是刑事拘留","公安机关决定的刑事拘留","人民法院判处的拘役"],"answer":1,"explanation":"留置是监察机关在调查严重职务违法、职务犯罪时依法采取的调查措施，用来查明案情、防止干扰。它不是公安机关的刑事拘留，也不是作为行政处罚的行政拘留，更不是法院判处的拘役。监察委员会由人大产生，对本级人大及其常委会和上一级监察委员会负责。被调查人涉嫌犯罪移送司法机关后，留置一日可以折抵管制二日，折抵拘役、有期徒刑一日。折抵说明它会影响后来的刑期计算，但不改变留置本身的监察调查性质。看到限制人身自由就把四种措施当成一种，是这道题要避开的地方。","source":"原创练习"},{"id":"fl-51","subject":"基本知识","chapter":"法律","stem":"某单位与劳动者订立两年期劳动合同。依法可以约定的试用期上限是：","options":["一个月","一年","二个月","六个月"],"answer":2,"explanation":"试用期上限跟合同期限走：三个月以上不满一年的，不得超过一个月；一年以上不满三年的，不得超过二个月；三年以上固定期限和无固定期限的，不得超过六个月。两年期落在“一年以上不满三年”，上限是二个月。最容易记成六个月，六个月是三年以上或者无固定期限合同才允许的上限。正好三年，才进入六个月那一档。同一用人单位与同一劳动者只能约定一次试用期。期限不满三个月，或者以完成一定工作任务为期限的，不得约定试用期。只约定试用期的，试用期不成立，该期限就是劳动合同期限。","source":"原创练习"},{"id":"fl-52","subject":"基本知识","chapter":"法律","stem":"劳动者在试用期的工资，法定底线是：","options":["可以低于当地最低工资，只要单位内部同意","必须等于转正后的全部工资，法律不允许试用期有任何降低","不得低于约定工资的百分之五十即可","不得低于本单位相同岗位最低档工资或者劳动合同约定工资的百分之八十，并不得低于用人单位所在地的最低工资标准"],"answer":3,"explanation":"试用期工资不得低于本单位相同岗位最低档工资或者劳动合同约定工资的百分之八十，并不得低于用人单位所在地的最低工资标准。后面这句是独立的底线，不能因为还在试用，或者已经达到约定工资的八成，就跌破当地最低工资。法律允许在这个底线之内低于约定的转正工资，所以“必须一分不差等于正式工资”过了头；“百分之五十”和“可以低于最低工资”则把底线放低了。招聘广告也不能把这道法定底线约定掉。","source":"原创练习"},{"id":"fl-53","subject":"基本知识","chapter":"法律","stem":"用人单位在法定休假日安排劳动者工作，工资应当怎样支付？","options":["安排补休即可，不必再支付加班工资","只付本人当日的本薪，因为当天本来就放假","支付不低于工资百分之二百的报酬，也可以用补休代替","支付不低于工资百分之三百的工资报酬"],"answer":3,"explanation":"工作日延长劳动的，支付不低于工资百分之一百五十的报酬。休息日安排工作又不能安排补休的，支付不低于百分之二百。法定休假日安排工作的，支付不低于百分之三百。休息日和法定休假日的差别就在补休：休息日可以先安排补休，不能补休才按百分之二百支付；法定休假日的条文没有用补休来代替百分之三百。最容易把这两条合成一条，用休息日的补休规则去处理法定休假日。","source":"原创练习"},{"id":"fl-54","subject":"基本知识","chapter":"法律","stem":"用人单位违法解除劳动合同。劳动者不要求继续履行，或者合同已经不能继续履行。用人单位应当支付：","options":["任意一个月工资","按经济补偿标准的二倍支付赔偿金；支付赔偿金后，不再支付经济补偿","与经济补偿相同的一倍，付完就不再有别的计算","只赔偿医疗费，不按工资标准计算"],"answer":1,"explanation":"违法解除时，劳动者要求继续履行并且能够继续履行的，用人单位应当继续履行。不要求继续履行，或者合同不能继续履行的，应当依照经济补偿标准的二倍支付赔偿金。赔偿金已经按二倍计算，就不再同时支付经济补偿，不能两笔叠加。最容易错的是把赔偿金和经济补偿各付一遍，或者把违法解除记成只付一倍经济补偿。经济补偿本身按工作年限计算，每满一年支付一个月工资，六个月以上不满一年按一年，不满六个月支付半个月工资。二倍是在这个标准上乘。","source":"原创练习"},{"id":"fl-55","subject":"基本知识","chapter":"法律","stem":"女职工在孕期被证明严重违反用人单位依法制定的规章制度。用人单位能否解除劳动合同？","options":["不能；孕期、产期、哺乳期在任何情况下都不得解除","不能；必须等哺乳期结束，而且这期间可以停发全部工资","只能在职工本人书面同意后解除","能；孕期排除的是无过失解除和经济性裁员，严重违纪仍可按过错解除"],"answer":3,"explanation":"孕期、产期、哺乳期，以及医疗期内、在本单位连续工作满十五年且距法定退休年龄不足五年等情形，用人单位不得依照无过失解除和经济性裁员的规则解除合同。这个保护不挡住过错解除。劳动者严重违反规章制度、被依法追究刑事责任等，用人单位仍然可以解除。最容易记成“孕期一律不能解除”。保护的是不让单位用经营原因、不能胜任等理由把孕期职工辞退，不是免除职工遵守规章制度的义务。停发全部工资没有依据。","source":"原创练习"},{"id":"fl-56","subject":"基本知识","chapter":"法律","stem":"消防队员在灭火时，为避免自己被烧伤而擅自离开，导致火势扩大、他人重伤。他能否以紧急避险为由不负刑事责任？","options":["能；只要事后承认错误就可以免责","不能；关于避免本人危险的规定，不适用于职务上、业务上负有特定责任的人","能；避免自身危险本来就是紧急避险的正当目的","不能；紧急避险只保护国家财产，不保护人身"],"answer":1,"explanation":"紧急避险是为了使国家、公共利益、本人或者他人的人身、财产和其他权利免受正在发生的危险，不得已采取的损害另一较小合法权益的行为。关于避免本人危险的规定，不适用于职务上、业务上负有特定责任的人。消防队员的职责就是在危险中灭火，不能把保住自己写成避险来推掉责任。对一般人，避免本人危险可以成立避险，这是最容易直接套过来的一句，一碰到特定职责就不再适用。紧急避险既可以针对人身危险，也可以针对财产危险。避险超过必要限度造成不应有损害的，应当负刑事责任，但是应当减轻或者免除处罚。","source":"原创练习"},{"id":"fl-57","subject":"基本知识","chapter":"法律","stem":"公安机关对流窜作案、多次作案、结伙作案的重大嫌疑分子刑事拘留后，提请批准逮捕的时间可以延长至三十日，检察院应当在接到提请后的七日以内作出决定。这一类案件，从拘留到逮捕决定，最长是：","options":["两个月","三十日","三十七日","十四日"],"answer":2,"explanation":"认为需要逮捕的，公安机关一般应当在拘留后的三日以内提请检察院审查批准，特殊情况可以再延长一日至四日，检察院还有七日，所以常见的上限分别是十日和十四日。流窜作案、多次作案、结伙作案的重大嫌疑分子，提请批捕的时间可以延长至三十日，加上检察院的七日，最长三十七日。只记三十日，漏掉检察院审查的七日，是最常见的少算。两个月是把逮捕以后的侦查羁押期限混了进来。刑事拘留是强制措施。治安管理处罚中的行政拘留，合并执行最长不超过二十日，和这里的三十七日不是同一种措施。","source":"原创练习"},{"id":"pd-01","subject":"岗位能力","chapter":"判断推理","stem":"岗位轮换体验是指在不改变人员隶属关系的前提下，安排其到其他岗位短期跟班，目的是了解相关流程，而不是独立承担该岗位的考核任务。根据上述定义，下列属于岗位轮换体验的是：","options":["文书到车队跟班三天，只观察派车流程，考核仍由原部门负责","驾驶员被任命为车队调度，并按新岗位接受月度考核","两名保管员正式对调库房并更换岗位职责","新入职人员在本岗位完成为期一月的上岗考核"],"answer":0,"explanation":"定义要点有三个：隶属不变、短期跟班、只了解流程而不独立接受该岗位考核。文书跟班观察且考核仍在原部门，三点都符合。任命、对调和本岗位上岗考核都改变了责任归属或本来就是本岗位考核。","source":"原创练习"},{"id":"pd-02","subject":"岗位能力","chapter":"判断推理","stem":"回溯核查是指在结果已经出现之后，逆着流程查找导致该结果的关键环节，并记录可复核的证据。根据上述定义，下列属于回溯核查的是：","options":["开赛前检查所有器材是否齐全","成绩公布后，按评分表、监考记录和答题卡逐项查找某考场分数异常的原因","根据天气预报提前调整户外训练计划","为明年采购编制需求清单"],"answer":1,"explanation":"回溯核查要同时满足结果已经出现、从结果倒查环节、留下可复核证据。成绩公布后对照评分表、监考记录和答题卡，符合这三点。赛前检查、看天气预报和编制采购清单都发生在结果出现之前。","source":"原创练习"},{"id":"pd-03","subject":"岗位能力","chapter":"判断推理","stem":"并行会签是指同一事项需要多个部门分别出具意见，这些部门可以同时审阅，不必等前一个部门签完再开始，但事项办结必须集齐全部意见。根据上述定义，下列属于并行会签的是：","options":["采购申请同时发给财务、资产和纪检，三家可以同时填写意见，缺任何一家都不能办结","报告必须先由处长签，再由分管领导签，顺序不能颠倒","一个部门内部由经办人审核后直接归档","三个部门轮流值班，每天只由一家处理来文"],"answer":0,"explanation":"并行会签的方法是抓三个词：多个部门、可以同时审、办结时意见必须齐全。采购申请同时发给三家且缺一不可，符合定义。先处长后领导是按顺序签；一个人归档不是多部门；轮流值班意味着没有同时审阅。","source":"原创练习"},{"id":"pd-04","subject":"岗位能力","chapter":"判断推理","stem":"软约束是指某项要求写在文件里，但违反后只作提醒或记录，不直接取消资格，也不处罚。根据上述定义，下列属于软约束的是：","options":["未携带证件者不得进入考场","训练迟到将被取消当日成绩","参训须知写明尽量提前十分钟到场，迟到只在签到表备注，不影响参加训练","体检不合格者不能报名"],"answer":2,"explanation":"先看有没有明文要求，再看违反后的后果。提前到场写进了须知，迟到却只备注、资格保留，属于软约束。不得入场、取消成绩和不能报名都会直接限制资格。","source":"原创练习"},{"id":"pd-05","subject":"岗位能力","chapter":"判断推理","stem":"功能冗余是指为完成同一关键功能，同时保留一套以上能够独立工作的手段，以便其中一套失效时另一套仍能完成该功能。根据上述定义，下列属于功能冗余的是：","options":["会议室只安装一台投影仪，坏了就改用口头汇报","档案室同时配备电子目录和纸质登记簿，任何一种都能独立查出档案位置","三名库管编成一个班，共同使用同一本台账","为节省空间，只保留最新一年版本的手册"],"answer":1,"explanation":"判断时看两套手段能否各自独立完成同一功能。电子目录和纸质登记簿都能单独查出位置，一套失效另一套仍可用。一台投影仪没有备份；多人共用一本台账仍是单一手段；只留最新手册是在减少备份。","source":"原创练习"},{"id":"pd-06","subject":"岗位能力","chapter":"判断推理","stem":"触发式复盘是指只有当某项指标突破预先设定的界限时，才启动对近期工作的集中回顾；指标未越界则不启动。根据上述定义，下列属于触发式复盘的是：","options":["无论成绩如何，每周五固定开会总结","每完成一个项目都写一份总结","每天填写工作日志","规定投诉超过5件才召开专项回顾会。本月投诉达到6件，于是开会；上月只有3件，没有开会"],"answer":3,"explanation":"触发式复盘的界限是：越界才回顾，不越界就不回顾。6件超过5件所以开会，3件未超过所以不开，两边都按这个规则运行。固定周五开会、每个项目都总结、每天写日志，都不看指标是否越界。","source":"原创练习"},{"id":"pd-07","subject":"岗位能力","chapter":"判断推理","stem":"间接测量是指无法直接得到目标量时，先测量与目标量有稳定换算关系的其他量，再通过换算得到目标量。根据上述定义，下列属于间接测量的是：","options":["用尺子直接量出场边长度","用温度计读取室温","通过测量单圈用时和圈数，换算出长跑的平均速度","用点名册清点实到人数"],"answer":2,"explanation":"先分清目标量是直接读出的，还是换算出来的。平均速度没有被直接读出，而是由单圈用时和圈数换算，符合间接测量。边长、室温和实到人数都是直接得到的目标量。","source":"原创练习"},{"id":"pd-08","subject":"岗位能力","chapter":"判断推理","stem":"隔离存放是指把容易相互影响的物品分开放置，使一方的问题不会直接影响另一方。只贴不同标签、但仍放在同一空间，不算隔离存放。根据上述定义，下列属于隔离存放的是：","options":["消毒棉球和污敷料放进同一个带盖箱，箱外贴两张标签","干净被服和待洗被服分别放进两间不相通的房间","两种试剂倒进同一瓶子，瓶身写明成分","食品和清洁剂并排摆在同一块搁板上"],"answer":1,"explanation":"关键不在有没有标签，而在物品是否被物理分开。两间不相通的房间能使一方不影响另一方。同一个箱子、同一个瓶子和同一块搁板都没有隔开。","source":"原创练习"},{"id":"pd-09","subject":"岗位能力","chapter":"判断推理","stem":"口径还原是指不同部门对同一指标使用了不同统计范围，比较之前先把各方数字调整到同一个统计范围。根据上述定义，下列属于口径还原的是：","options":["甲部门人数含实习人员、乙部门不含，比较前双方都改成不含实习人员再算","直接把两个部门的原始人数相减并写入报告","只保留数字较大的那个部门的统计结果","把人数换成金额后再相加"],"answer":0,"explanation":"口径还原的步骤是先统一统计范围，再比较。双方都去掉实习人员后，人数才可比。直接相减没有统一范围；只留较大数字是取舍；把人数换成金额是更换了指标。","source":"原创练习"},{"id":"pd-10","subject":"岗位能力","chapter":"判断推理","stem":"可逆操作是指执行之后能够通过明确的反向步骤回到执行前的状态，而且反向步骤不会额外损失原有信息。根据上述定义，下列属于可逆操作的是：","options":["把纸质试卷粉碎","电子表格按部门排序后，又按唯一的原序号排回，每一行内容与排序前一致","用修正液覆盖原答案后写上新答案","把过期试剂直接倒掉"],"answer":1,"explanation":"可逆操作要同时有反向步骤和不损失原信息。按唯一原序号排回后，行内容恢复，符合定义。粉碎、覆盖和倒掉都会让原件或原信息无法完整回到执行前。","source":"原创练习"},{"id":"pd-11","subject":"岗位能力","chapter":"判断推理","stem":"临时授权是指在原本无权处理某事项的人，因紧急情况并经负责人当场同意，可以在限定时间和限定范围内处理该事项；紧急情况结束后授权即消失。根据上述定义，下列属于临时授权的是：","options":["保管员按岗位职责每天都可以独立开关库房","通信员平时不能调用备用车辆，演练中通信中断，负责人当场同意其调用一次，演练结束即收回","驾驶员持有长期驾驶证，全年都可以出车","档案员把本人权限永久转给同事"],"answer":1,"explanation":"临时授权要同时具备原本无权、紧急情况、负责人当场同意、时间和范围有限、结束后消失。通信中断时被当场同意调用一次，结束后收回，符合定义。日常职责、长期驾驶证和永久转交都不是临时授权。","source":"原创练习"},{"id":"pd-12","subject":"岗位能力","chapter":"判断推理","stem":"哨位：警戒。与这一组关系最相近的是：","options":["教材：印刷","键盘：屏幕","食堂：供餐","春季：秋季"],"answer":2,"explanation":"先定关系类型：哨位的核心功能是警戒，属于场所与其主要功能。食堂的主要功能是供餐。教材与印刷是制作关系，键盘与屏幕是并列部件，春季与秋季是并列季节。","source":"原创练习"},{"id":"pd-13","subject":"岗位能力","chapter":"判断推理","stem":"口令：识别。与这一组关系最相近的是：","options":["口罩：保暖","窗户：窗帘","铅笔：橡皮","印章：证明"],"answer":3,"explanation":"口令用来完成识别，是手段与其直接用途。印章用来完成证明。保暖不是口罩的主要用途；窗户与窗帘是遮挡搭配；铅笔与橡皮是功能相反的配合用品。","source":"原创练习"},{"id":"pd-14","subject":"岗位能力","chapter":"判断推理","stem":"听诊器：诊断。与这一组关系最相近的是：","options":["病历：病情","望远镜：观察","药房：药品","护士：病房"],"answer":1,"explanation":"听诊器是诊断所用的工具，对应工具与用途。望远镜是观察所用的工具。病历记录病情，是载体与内容；药房存放药品，是场所与物品；护士与病房是人员与场所。","source":"原创练习"},{"id":"pd-15","subject":"岗位能力","chapter":"判断推理","stem":"润滑：磨损。与这一组关系最相近的是：","options":["油漆：颜色","切割：片段","加密：泄露","目录：正文"],"answer":2,"explanation":"润滑是为了减轻或避免磨损，属于行为与其要防止的不利结果。加密是为了防止泄露。油漆赋予颜色，切割分出片段，目录是正文的检索部分。","source":"原创练习"},{"id":"pd-16","subject":"岗位能力","chapter":"判断推理","stem":"卷尺：长度。与这一组关系最相近的是：","options":["电池：电量","笔记本：笔记","眼镜：镜片","温度计：温度"],"answer":3,"explanation":"卷尺用来测量长度，是测量工具与所测的量。温度计用来测量温度。电池储存电量，不是测量工具；笔记本用来写下笔记；眼镜与镜片是整体与部件。","source":"原创练习"},{"id":"pd-17","subject":"岗位能力","chapter":"判断推理","stem":"连长：连队。与这一组关系最相近的是：","options":["队员：队伍","主编：刊物","学员：教材","乘客：车票"],"answer":1,"explanation":"连长是连队的负责人，对应负责人与所负责的组织。主编是刊物的负责人。队员是队伍中的成员，不是负责人；学员使用教材；乘客持有车票。","source":"原创练习"},{"id":"pd-18","subject":"岗位能力","chapter":"判断推理","stem":"树苗：树木。与这一组关系最相近的是：","options":["种子：果实","树叶：树根","幼虫：成虫","木材：桌椅"],"answer":2,"explanation":"树苗是树木生长的早期阶段，二者是同一生命体的前后阶段。幼虫和成虫也是同一生物的前后阶段。种子长成的是植株而不是果实；树叶和树根是并列器官；木材是制作桌椅的材料。","source":"原创练习"},{"id":"pd-19","subject":"岗位能力","chapter":"判断推理","stem":"规章：遵守。与这一组关系最相近的是：","options":["合同：履行","乐器：演奏","砖块：砌墙","地图：道路"],"answer":0,"explanation":"规章对应的行为是遵守，属于规范文本与依该规范作出的行为。合同对应的行为是履行。乐器与演奏是工具和操作，砖块是砌墙的材料，地图表示道路。","source":"原创练习"},{"id":"pd-20","subject":"岗位能力","chapter":"判断推理","stem":"刹车：减速。与这一组关系最相近的是：","options":["轮胎：橡胶","车灯：夜晚","座位：乘客","油门：加速"],"answer":3,"explanation":"刹车产生的直接效果是减速，对应装置与其运动效果。油门产生的直接效果是加速。轮胎的材料是橡胶，车灯并不产生夜晚，座位供乘客使用。","source":"原创练习"},{"id":"pd-21","subject":"岗位能力","chapter":"判断推理","stem":"过滤：杂质。与这一组关系最相近的是：","options":["搅拌：均匀","筛选：不合格品","加热：温度","包装：运输"],"answer":1,"explanation":"过滤是把杂质分离出去，对应动作与被去除的对象。筛选是把不合格品分离出去。搅拌追求均匀这一状态，加热改变温度，包装服务于运输。","source":"原创练习"},{"id":"pd-22","subject":"岗位能力","chapter":"判断推理","stem":"小时：分钟。与这一组关系最相近的是：","options":["公里：速度","月份：日历","千克：克","厘米：面积"],"answer":2,"explanation":"小时和分钟都是时间单位，而且小时是更大的单位。千克和克都是质量单位，千克更大。公里与速度、厘米与面积不是同一类量；月份是时间单位，日历是物品，不是单位与单位的关系。","source":"原创练习"},{"id":"pd-23","subject":"岗位能力","chapter":"判断推理","stem":"如果一份材料缺少签字，就不能归档。现在这份材料已经归档。由此必然推出：","options":["这份材料经过了复印","所有已归档材料都缺少签字","这份材料一定是今天提交的","这份材料不缺少签字"],"answer":3,"explanation":"原条件是缺少签字则不能归档。否定后件就要否定前件：已经归档，所以并非缺少签字。复印和提交日期没有出现在前提里；说已归档材料都缺少签字，是把条件方向说反了。","source":"原创练习"},{"id":"pd-24","subject":"岗位能力","chapter":"判断推理","stem":"所有参加夜训的人员都佩戴了识别牌。有的通信班人员参加了夜训。由此必然推出：","options":["有的通信班人员佩戴了识别牌","所有通信班人员都佩戴了识别牌","没有佩戴识别牌的人都在通信班","通信班人员都没有参加夜训"],"answer":0,"explanation":"参加夜训的人全部佩戴识别牌，通信班里至少有人参加了夜训，所以这些人也佩戴了识别牌。有的不能扩大成所有。没戴识别牌的人属于哪一班，前提没有说。","source":"原创练习"},{"id":"pd-25","subject":"岗位能力","chapter":"判断推理","stem":"某仓库规定：只有完成清点，才能出库。这批物资已经出库。由此必然推出：","options":["这批物资没有完成清点","这批物资已经完成清点","完成清点的物资都已经出库","没有出库的物资都没有完成清点"],"answer":1,"explanation":"只有清点才能出库，等于出库则已经清点。已经出库，所以已经清点。它不等于清点则出库，因此不能推出凡清点过的都已出库，也不能推出没出库就没清点。","source":"原创练习"},{"id":"pd-26","subject":"岗位能力","chapter":"判断推理","stem":"甲、乙、丙三人中只有一人值过夜班，三句话里也只有一句是真话。甲说：夜班是乙值的。乙说：夜班不是我值的。丙说：夜班不是甲值的。值夜班的是：","options":["乙","丙","甲","三人都没有值班"],"answer":2,"explanation":"假设甲值班：甲的话为假，乙的话为真，丙的话为假，恰好一句真话，成立。假设乙值班：甲和丙都为真。假设丙值班：乙和丙都为真。后两种都有两句真话，与题意矛盾。所以只能是甲。","source":"原创练习"},{"id":"pd-27","subject":"岗位能力","chapter":"判断推理","stem":"有人认为：某次理论测验平均分上升，说明全体参考人员的水平都提高了。下列哪一项最能削弱这一说法？","options":["低分组人数增加，而且复核发现其中一部分人的分数低于自己上次测验","试卷题型和去年相同","参考人数与去年相同","测验安排在同一周"],"answer":0,"explanation":"平均分上升只说明总分的平均数变了，推不出每一个人都提高。低分组扩大，且部分人低于自己上次成绩，直接否定全体都提高。题型、人数和考试周次都没有涉及个人成绩是否提高。","source":"原创练习"},{"id":"pd-28","subject":"岗位能力","chapter":"判断推理","stem":"研究者发现坚持写错题笔记的学员阶段测验成绩更好，于是认为写错题笔记能提高成绩。下列哪一项最能支持这一结论？","options":["写笔记的学员更喜欢早起","阶段测验只考一章内容","这些学员在开始写笔记之前，成绩与其他学员没有明显差别","有的学员用黑色笔写笔记"],"answer":2,"explanation":"支持因果关系时，要排除这些人本来就更强。开始写笔记前成绩相近，后来的差距就更可能与写笔记有关。早起、考试范围和笔的颜色都不能把笔记和成绩连成因果。","source":"原创练习"},{"id":"pd-29","subject":"岗位能力","chapter":"判断推理","stem":"如果通过技能考核，就能参加综合演练；如果参加综合演练，就能获得结业评语。小刘没有获得结业评语。由此必然推出：","options":["小刘通过了技能考核","小刘参加了综合演练","小刘放弃了评语","小刘没有通过技能考核"],"answer":3,"explanation":"两个条件可以传递：通过考核则参加演练，参加演练则获得评语，所以通过考核则获得评语。没有评语就否定了后件，必须否定前件，因此没有通过技能考核。放弃评语是前提里没有的新情况。","source":"原创练习"},{"id":"pd-30","subject":"岗位能力","chapter":"判断推理","stem":"周末值班由小赵或小钱担任，至少有一人值班，也可以两人都值班。已知小赵没有值班。由此必然推出：","options":["小钱值班了","小钱没有值班","两人都没有值班","小赵下周必须补班"],"answer":0,"explanation":"这里的或是至少一人。小赵不值班时，要满足至少一人，小钱必须值班。两人都不值班与前提冲突。下周补班没有出现在已知条件里。","source":"原创练习"},{"id":"pd-31","subject":"岗位能力","chapter":"判断推理","stem":"某队规定：所有外场人员都必须穿反光背心。小孙穿了反光背心。下列说法正确的是：","options":["小孙一定是外场人员","小孙一定不是外场人员","外场人员都不穿反光背心","不能确定小孙是不是外场人员"],"answer":3,"explanation":"外场人员则穿背心，不能反过来推出穿背心则是外场人员。小孙可能是外场人员，也可能因其他原因穿了背心，所以不能确定。说外场人员都不穿，与规定直接相反。","source":"原创练习"},{"id":"pd-32","subject":"岗位能力","chapter":"判断推理","stem":"甲、乙、丙三人排队。已知乙在甲前面，丙不在最后。下列哪一项一定为真？","options":["顺序一定是乙、甲、丙","甲在最后","丙在最前","顺序一定是乙、丙、甲"],"answer":1,"explanation":"乙在甲前，甲就不是第一。丙不能最后。若甲也不在最后，最后只能是乙，但乙必须在甲前面，不能排最后，矛盾。所以甲一定最后。可能的顺序有乙、丙、甲和丙、乙、甲，丙不一定在最前。","source":"原创练习"},{"id":"pd-33","subject":"岗位能力","chapter":"判断推理","stem":"有的观察记录没有写明时间。下列哪一项与这一断定相矛盾？","options":["有的观察记录写明了时间","所有观察记录都没有写明时间","所有观察记录都写明了时间","至少有一份观察记录没有写明地点"],"answer":2,"explanation":"有的S不是P与所有S都是P不能同真，也不能同假，二者矛盾。因此有的记录没写时间，矛盾于所有记录都写了时间。有的写了可以与有的没写同时成立；地点与时间无关。","source":"原创练习"},{"id":"pd-34","subject":"岗位能力","chapter":"判断推理","stem":"本次选拔要么笔试入围，要么技能入围，二者只取其一。已知小周笔试入围。由此必然推出：","options":["小周技能没有入围","小周技能也入围","小周两项都没有入围","小周放弃了技能考试"],"answer":0,"explanation":"要么要么表示只能成立一个。笔试已经入围，技能入围就不能同时成立。两项都没入围与笔试入围冲突。是否放弃考试，前提没有提供信息。","source":"原创练习"},{"id":"pd-35","subject":"岗位能力","chapter":"判断推理","stem":"图形依次是：开口向右的半圆，开口向上的半圆，开口向左的半圆。若每次按逆时针方向转动90度，下一幅应是：","options":["开口向右的半圆","开口向下的半圆","开口向左的半圆","一个整圆"],"answer":1,"explanation":"开口方向按逆时针每转90度，顺序是向右、向上、向左、向下。前三幅已经走到向左，下一幅开口向下。转动只改变方向，半圆不会变成整圆。","source":"原创练习"},{"id":"pd-36","subject":"岗位能力","chapter":"判断推理","stem":"每幅图都是一个正方形加内部直线。内部直线数依次是1、2、3，每次增加一条，且新增直线的方向与已有直线都不同。下一幅内部直线的条数是：","options":["2","3","4","6"],"answer":2,"explanation":"条数按1、2、3每次加1，下一幅是4。横、竖和两条不同斜线恰好是四个不同方向，第四条仍然加得上。6跳过了下一项。","source":"原创练习"},{"id":"pd-37","subject":"岗位能力","chapter":"判断推理","stem":"图形分成两半且一半涂黑：第一幅上黑下白，第二幅右黑左白，第三幅下黑上白。黑色区域每次沿顺时针方向移到下一条边。第四幅应是：","options":["上黑下白","右黑左白","左黑右白","上下都涂黑"],"answer":2,"explanation":"顺时针的位置顺序是上、右、下、左。前三幅对应上、右、下，下一位置是左，即左黑右白。上下都涂黑改变了涂黑数量，不符合只移动位置的规律。","source":"原创练习"},{"id":"pd-38","subject":"岗位能力","chapter":"判断推理","stem":"每幅图里的小黑点排成方阵，数量依次是1、4、9，分别对应边长1、2、3。按同一规律，下一幅小黑点的数量是：","options":["12","16","18","25"],"answer":1,"explanation":"方阵的点数等于边长的平方：1的平方、2的平方、3的平方。下一项边长为4，数量是16。25是5的平方，把4跳过了。","source":"原创练习"},{"id":"pd-39","subject":"岗位能力","chapter":"判断推理","stem":"图形都是闭合多边形：第一幅三角形，第二幅四边形，第三幅五边形，边数每次增加1。下一幅的内角个数是：","options":["3","5","6","8"],"answer":2,"explanation":"简单多边形的内角个数等于边数。边数按3、4、5递增，下一幅是六边形，内角有6个。","source":"原创练习"},{"id":"pd-40","subject":"岗位能力","chapter":"判断推理","stem":"对称轴数量依次为：等边三角形3条，正方形4条，正五边形5条。若下一项是边数再加1的正多边形，对称轴数量是：","options":["4","6","8","10"],"answer":1,"explanation":"正n边形有n条对称轴。已出现的边数是3、4、5，下一项是正六边形，对称轴为6条。","source":"原创练习"},{"id":"pd-41","subject":"岗位能力","chapter":"判断推理","stem":"每幅图都是外框套着内图。第一幅外框三角形、内图圆形；第二幅外框圆形、内图方形；第三幅外框方形、内图三角形。规律是上一幅的内图成为下一幅的外框。第四幅的外框是：","options":["三角形","圆形","方形","五边形"],"answer":0,"explanation":"用上一幅内图变成本幅外框去核对：圆形变成第二幅外框，方形变成第三幅外框。第三幅的内图是三角形，所以第四幅外框是三角形。","source":"原创练习"},{"id":"pd-42","subject":"岗位能力","chapter":"判断推理","stem":"黑白小球沿直线排列。第一幅为黑白，第二幅为白黑，第三幅为黑白。若两种颜色的位置每次整体对调，第四幅是：","options":["黑白","白黑","黑黑","白白"],"answer":1,"explanation":"整体对调一次，排列就变成相反的一种：黑白变成白黑，再变成黑白，再变成白黑。第四幅是白黑。对调不会把两球变成同色。","source":"原创练习"},{"id":"pd-43","subject":"岗位能力","chapter":"判断推理","stem":"用笔画封闭区域：口字有1个，日字有2个，目字有3个。按同样方式再加一条内部分隔横线，下一幅的封闭区域个数是：","options":["3","4","5","6"],"answer":1,"explanation":"在同一个外框里，每增加一条分隔横线，封闭区域就增加1个。口、日、目对应1、2、3，下一幅是4个。","source":"原创练习"},{"id":"pd-44","subject":"岗位能力","chapter":"判断推理","stem":"箭头方向依次指向东、南、西。若每次顺时针转动90度，下一幅箭头指向：","options":["东","北","南","西"],"answer":1,"explanation":"顺时针每转90度，方向顺序是东、南、西、北。前三幅符合这一顺序，下一幅指向北。","source":"原创练习"},{"id":"pd-45","subject":"岗位能力","chapter":"判断推理","stem":"外轮廓始终是圆，内部直线都经过圆心。直线条数为0、1、2时，圆被分成的块数是1、2、4。再加一条仍经过圆心、且不与已有直线重合的直线，下一块数是：","options":["3","5","6","8"],"answer":2,"explanation":"两条直径交于圆心时分成4块。第三条仍经过圆心，会同时切开对面的两块，块数增加2，4加2等于6。它不是在4上加1，也不是把4翻倍。","source":"原创练习"},{"id":"pd-46","subject":"岗位能力","chapter":"判断推理","stem":"每幅图都有圆、方、三角三类元素。第一幅数量为圆1、方0、三角2；第二幅为圆2、方1、三角0；第三幅为圆0、方2、三角1。数量沿圆到方、方到三角、三角到圆的方向整体传递。下一幅中方形的数量是：","options":["0","1","2","3"],"answer":0,"explanation":"每个数量都传给下一类。第三幅是圆0、方2、三角1，因此圆的0传给方，方的2传给三角，三角的1传给圆。下一幅方形数量是0。","source":"原创练习"},{"id":"zl-01","subject":"岗位能力","chapter":"资料分析","stem":"某训练基地报名人数：2023年800人，2024年1000人。2024年报名人数同比增长率是：","options":["20%","25%","30%","80%"],"answer":1,"explanation":"增长率等于（现期减基期）除以基期。（1000减800）除以800等于200除以800，即25%。20%是把增量200除以现期1000，基期用错了。","source":"原创练习"},{"id":"zl-02","subject":"岗位能力","chapter":"资料分析","stem":"某库房2024年纸张领用560包，比2023年增长12%。2024年比2023年多领用：","options":["50包","60包","67包","72包"],"answer":1,"explanation":"增长量等于现期乘增速再除以（1加增速）。560除以1.12等于500，500乘12%等于60包。直接用560乘12%约等于67包，那是把现期误当成基期。","source":"原创练习"},{"id":"zl-03","subject":"岗位能力","chapter":"资料分析","stem":"某月食堂采购：粮食4.5万元，蔬菜3.0万元，肉类2.5万元。肉类占采购总额的比重是：","options":["25%","30%","45%","50%"],"answer":0,"explanation":"比重等于部分除以整体。总额是4.5加3.0加2.5等于10万元，肉类2.5除以10等于25%。30%是蔬菜的比重，45%是粮食的比重。","source":"原创练习"},{"id":"zl-04","subject":"岗位能力","chapter":"资料分析","stem":"某队5天的训练里程分别是12、15、9、18、16公里。这5天的日均里程是：","options":["12公里","14公里","15公里","16公里"],"answer":1,"explanation":"平均数等于总和除以个数。12加15加9加18加16等于70，70除以5等于14公里。把这5个数从小到大排列后，正中间的15是中位数，不是平均数。","source":"原创练习"},{"id":"zl-05","subject":"岗位能力","chapter":"资料分析","stem":"甲教室藏书2400册，乙教室藏书800册。甲教室藏书是乙教室的：","options":["2倍","3倍","4倍","5倍"],"answer":1,"explanation":"是几倍用除法：2400除以800等于3，甲是乙的3倍。若问比乙多几倍，才是（2400减800）除以800等于2倍。题干问的是是几倍。","source":"原创练习"},{"id":"zl-06","subject":"岗位能力","chapter":"资料分析","stem":"某科室2024年办公费支出84万元，同比增长20%。2023年办公费支出是：","options":["64万元","67.2万元","70万元","100.8万元"],"answer":2,"explanation":"基期等于现期除以（1加增长率）。84除以1.2等于70万元。84乘（1减20%）等于67.2，是错误地用现期去减增长；84乘1.2是把基期当成了现期再增长一次。","source":"原创练习"},{"id":"zl-07","subject":"岗位能力","chapter":"资料分析","stem":"某指标3月为90，4月为108，上年4月为100。今年4月的环比增长率是：","options":["8%","10%","20%","18%"],"answer":2,"explanation":"环比以上一个月为基期。（108减90）除以90等于20%。8%是与上年4月相比的同比增速，比较对象不同，不能拿来回答环比。","source":"原创练习"},{"id":"zl-08","subject":"岗位能力","chapter":"资料分析","stem":"某单位用电量（单位：万度）如下。一季度：办公2.0、训练3.0、生活5.0。二季度：办公2.4、训练3.6、生活6.0。二季度用电总量比一季度增加：","options":["1.0万度","1.6万度","2.0万度","2.4万度"],"answer":2,"explanation":"先分别求总量。一季度是2.0加3.0加5.0等于10.0，二季度是2.4加3.6加6.0等于12.0，增加12.0减10.0等于2.0万度。1.0只是生活用电一项的增量。","source":"原创练习"},{"id":"zl-09","subject":"岗位能力","chapter":"资料分析","stem":"某馆藏中，纸质图书去年占全部藏书的60%，今年占55%。今年这一比重比去年下降了多少个百分点？","options":["5","8.3","12","15"],"answer":0,"explanation":"两个比重相减，差用百分点表示：60减55等于5，即下降5个百分点。（60减55）除以60约等于8.3%，那是比重本身的相对降幅，不是百分点差。","source":"原创练习"},{"id":"zl-10","subject":"岗位能力","chapter":"资料分析","stem":"某队总分去年为200分，今年为230分。其中射击项目今年比去年提高12分。射击对总分增长的贡献率是：","options":["6%","12%","40%","52%"],"answer":2,"explanation":"贡献率等于部分增长量除以总体增长量。总体增长量是230减200等于30，12除以30等于40%。6%是12除以去年总分200，分母用成了基期总量。","source":"原创练习"},{"id":"zl-11","subject":"岗位能力","chapter":"资料分析","stem":"一批物资共600箱，原由12辆车运送。若改由10辆车运送同样多的物资，平均每车比原来多运：","options":["10箱","14箱","50箱","60箱"],"answer":0,"explanation":"原平均是600除以12等于50箱，新平均是600除以10等于60箱，多运60减50等于10箱。60箱是新的每车运量，不是增加量。","source":"原创练习"},{"id":"zl-12","subject":"岗位能力","chapter":"资料分析","stem":"某指标2022年为100，2023年增长10%，2024年在2023年基础上又增长10%。2024年比2022年增长：","options":["20%","21%","22%","110%"],"answer":1,"explanation":"间隔增长率等于两个增速相加，再加上两者的乘积：10%加10%再加10%乘10%，等于21%。连续两年各增长10%，不能直接相加当成20%。","source":"原创练习"},{"id":"zl-13","subject":"岗位能力","chapter":"资料分析","stem":"某月油料消耗约198吨，上月约152吨。本月比上月的增长率最接近：","options":["不到20%","30%左右","50%左右","80%左右"],"answer":1,"explanation":"增量约198减152等于46。46除以152，先看成46除以150约等于0.31，即30%左右。不到20%要求增量小于约30，50%则增量要接近76。","source":"原创练习"},{"id":"zl-14","subject":"岗位能力","chapter":"资料分析","stem":"阅读区座位120个，自习区座位280个，讨论区座位100个。自习区座位约占三个区总座位的：","options":["28%","46%","56%","70%"],"answer":2,"explanation":"总座位是120加280加100等于500。自习区280除以500等于56%。28%是把280除以了1000，分母被放大了。","source":"原创练习"},{"id":"zl-15","subject":"岗位能力","chapter":"资料分析","stem":"四个科目的现期人数和同比增速为：甲200人、增速10%；乙300人、增速10%；丙400人、增速5%；丁150人、增速20%。增长量最大的是：","options":["甲","乙","丙","丁"],"answer":1,"explanation":"增长量等于现期乘增速再除以（1加增速）。甲约18.2，乙约27.3，丙约19.0，丁是150乘0.2再除以1.2等于25。乙最大。丁的增速最高，但基数小，增量不是最大。","source":"原创练习"},{"id":"zl-16","subject":"岗位能力","chapter":"资料分析","stem":"某周白天处理工单48件，夜间处理16件。白天、夜间都按4天、每天8小时计算。白天每小时处理的工单比夜间多：","options":["0.5件","1件","1.5件","2件"],"answer":1,"explanation":"两边都是4乘8等于32小时。白天效率是48除以32等于1.5件，夜间是16除以32等于0.5件，相差1.5减0.5等于1件。","source":"原创练习"},{"id":"zl-17","subject":"岗位能力","chapter":"资料分析","stem":"预算120万元按训练器材3份、教材2份、活动1份分配。教材分到：","options":["20万元","30万元","40万元","60万元"],"answer":2,"explanation":"总份数是3加2加1等于6，每份是120除以6等于20万元。教材占2份，为40万元。60万元是器材3份的金额。","source":"原创练习"},{"id":"zl-18","subject":"岗位能力","chapter":"资料分析","stem":"某浴池上月用水400吨，本月计划下降15%。本月计划用水是：","options":["60吨","320吨","340吨","385吨"],"answer":2,"explanation":"下降之后的量等于基期乘（1减下降率）。400乘（1减15%）等于400乘0.85等于340吨。60吨只是减少量，320吨相当于下降了20%。","source":"原创练习"},{"id":"zl-19","subject":"岗位能力","chapter":"资料分析","stem":"一队80人，平均成绩75分；二队20人，平均成绩90分。两队合并后的平均成绩是：","options":["78分","80分","82.5分","85分"],"answer":0,"explanation":"人数不同时，合并平均等于总分数除以总人数。（80乘75加20乘90）除以100，即（6000加1800）除以100等于78分。直接把75和90平均会得到82.5，忽略了人数权重。","source":"原创练习"},{"id":"zl-20","subject":"岗位能力","chapter":"资料分析","stem":"某线路去年客运量25万人次，今年30万人次。今年同比增长：","options":["5%","16.7%","20%","25%"],"answer":2,"explanation":"增量是30减25等于5，增长率是5除以25等于20%。16.7%是5除以30，错把现期当成了基期。5%是把增量5直接写成了百分数。","source":"原创练习"},{"id":"zl-21","subject":"岗位能力","chapter":"资料分析","stem":"某月装备维修次数：通信24次，车辆36次，器械18次，其他12次。车辆维修占全部维修次数的：","options":["30%","36%","40%","45%"],"answer":2,"explanation":"总次数是24加36加18加12等于90。车辆比重是36除以90等于40%。36%是把次数36直接写成了百分数。","source":"原创练习"},{"id":"zl-22","subject":"岗位能力","chapter":"资料分析","stem":"今年全部经费300万元，其中差旅费60万元。差旅费同比增长25%，全部经费同比增长20%。去年差旅费占全部经费的比重是：","options":["16%","19.2%","20%","25%"],"answer":1,"explanation":"先还原基期再求比重。去年差旅是60除以1.25等于48万元，去年总经费是300除以1.2等于250万元，48除以250等于19.2%。20%是今年的比重60除以300。","source":"原创练习"},{"id":"zl-23","subject":"岗位能力","chapter":"资料分析","stem":"某库存连续三个年末的数量为200、260、338。从第一年年末到第三年年末经过两年，年均增长率是：","options":["30%","34%","38%","69%"],"answer":0,"explanation":"338除以200等于1.69。1.3乘1.3等于1.69，所以年均增长率是30%。也可以核对中间年：200乘1.3等于260，260乘1.3等于338。69%是两年累计增长率，除以2约等于34%，那不是年均。","source":"原创练习"},{"id":"zl-24","subject":"岗位能力","chapter":"资料分析","stem":"某试验次数由15次增加到60次。试验次数增加到原来的：","options":["3倍","4倍","45倍","75倍"],"answer":1,"explanation":"增加到几倍，用后来的数除以原来的数：60除以15等于4倍。增加了3倍才对应增量45，题干用的是增加到。","source":"原创练习"},{"id":"zl-25","subject":"岗位能力","chapter":"资料分析","stem":"一段路程全长2.4公里，用时30分钟。平均速度是：","options":["4.8公里/小时","8公里/小时","12公里/小时","80公里/小时"],"answer":0,"explanation":"速度等于路程除以时间，时间要先换成小时。30分钟是0.5小时，2.4除以0.5等于4.8公里/小时。单位不统一时，不能直接用2.4除以30。","source":"原创练习"},{"id":"zl-26","subject":"岗位能力","chapter":"资料分析","stem":"甲组40人，合格率90%；乙组60人，合格率70%。两组合计合格率是：","options":["76%","78%","80%","82%"],"answer":1,"explanation":"先算合格人数再除以总人数。40乘90%加60乘70%等于36加42等于78，总人数100，合格率78%。两组人数不同，不能把90%和70%简单平均成80%。","source":"原创练习"},{"id":"zl-27","subject":"岗位能力","chapter":"资料分析","stem":"去年总支出500万元。今年人员支出增加30万元，其他项目支出合计没有变化。人员支出拉动总支出增长：","options":["3个百分点","6个百分点","15个百分点","30个百分点"],"answer":1,"explanation":"拉动增长等于部分增长量除以总体基期量。30除以500等于6%，即拉动6个百分点。30个百分点是把增量30直接当成了百分数。","source":"原创练习"},{"id":"zl-28","subject":"岗位能力","chapter":"资料分析","stem":"某周图书借出册次：周一30、周二45、周三25、周四40、周五60。周五借出册次比周三多多少倍？","options":["0.4倍","1.4倍","2.4倍","35倍"],"answer":1,"explanation":"多多少倍等于增量除以基期。（60减25）除以25等于1.4倍。2.4倍是60除以25，回答的是是周三的多少倍；35是增量本身。","source":"原创练习"},{"id":"zl-29","subject":"岗位能力","chapter":"资料分析","stem":"今年器材费48万元，同比增长20%；总经费240万元，同比增长25%。与去年相比，器材费占总经费的比重：","options":["上升了","下降了","没有变化","无法判断"],"answer":1,"explanation":"部分增速20%低于整体增速25%，比重下降。验算：今年48除以240等于20%；去年器材48除以1.2等于40，去年总经费240除以1.25等于192，40除以192约等于20.8%，确实下降。","source":"原创练习"},{"id":"zl-30","subject":"岗位能力","chapter":"资料分析","stem":"某项任务计划1000件，已完成250件。完成进度是：","options":["1/5","1/4","1/3","2/5"],"answer":1,"explanation":"进度等于已完成除以计划。250除以1000等于1/4。1/5对应200件，2/5对应400件。","source":"原创练习"},{"id":"zl-31","subject":"岗位能力","chapter":"资料分析","stem":"采购同一型号笔记本，第一次买8台共2.4万元，第二次买12台共3.0万元。第二次的单台价格比第一次：","options":["高500元","低500元","低1000元","高1000元"],"answer":1,"explanation":"先求单价。第一次2.4万元除以8等于3000元，第二次3.0万元除以12等于2500元，第二次低3000减2500等于500元。","source":"原创练习"},{"id":"zl-32","subject":"岗位能力","chapter":"资料分析","stem":"某指标现期值为306，同比增长2%。增长量是：","options":["6","12","15","30"],"answer":0,"explanation":"增长量等于现期除以（1加增速）再乘增速。306除以1.02等于300，300乘2%等于6。增速很小时，306乘2%约等于6.1，和精确值接近，但精确增长量是6。","source":"原创练习"},{"id":"zl-33","subject":"岗位能力","chapter":"资料分析","stem":"四条线路的准点情况：甲91/100，乙23/25，丙18/20，丁14/16。准点率最高的是：","options":["甲","乙","丙","丁"],"answer":1,"explanation":"先化成百分数再比。甲是91%，乙是23除以25等于92%，丙是18除以20等于90%，丁是14除以16等于87.5%。乙最高。不能只看分子大小。","source":"原创练习"},{"id":"zl-34","subject":"岗位能力","chapter":"资料分析","stem":"原计划每月耗材1500元，连续4个月。实际每月1200元。4个月实际比计划节约：","options":["300元","900元","1200元","4800元"],"answer":2,"explanation":"每月节约1500减1200等于300元，4个月节约300乘4等于1200元。300元只是单月节约额，4800元是4个月的实际支出总额。","source":"原创练习"},{"id":"zl-35","subject":"岗位能力","chapter":"资料分析","stem":"三段跑步距离之比为2:3:5，总距离4公里。最长的一段是：","options":["0.8公里","1.2公里","1.6公里","2.0公里"],"answer":3,"explanation":"总份数是2加3加5等于10，每份是4除以10等于0.4公里。最长一段占5份，为2.0公里。","source":"原创练习"},{"id":"zl-36","subject":"岗位能力","chapter":"资料分析","stem":"以2020年为100，2024年的指数为125。若2020年实际值为240，则2024年实际值是：","options":["192","265","300","325"],"answer":2,"explanation":"实际值等于基年实际值乘指数再除以100。240乘125除以100等于300。192是按下降25%计算的，方向反了。","source":"原创练习"},{"id":"zl-37","subject":"岗位能力","chapter":"资料分析","stem":"某服务窗口一周受理：咨询180件、办理150件、投诉20件。投诉占受理总量的比重约为：","options":["5.7%","11.1%","13.3%","20%"],"answer":0,"explanation":"总量是180加150加20等于350。比重是20除以350约等于0.057，即约5.7%。11.1%是20除以180，只拿咨询作分母；20%是把20件直接写成百分数。","source":"原创练习"},{"id":"zl-38","subject":"岗位能力","chapter":"资料分析","stem":"上半年完成额240万元，下半年完成额360万元。下半年比上半年增长：","options":["33%","50%","67%","150%"],"answer":1,"explanation":"增长率等于（360减240）除以240，即120除以240等于50%。33%是120除以360，错把下半年当基期。150%是360除以240，表示下半年相当于上半年的1.5倍，不是增长率。","source":"原创练习"},{"id":"zl-39","subject":"岗位能力","chapter":"资料分析","stem":"三个班领取笔记本数量分别是42、36、30，人数分别是21、18、15。人均领取最多的班是：","options":["第一班","第二班","第三班","三个班一样多"],"answer":3,"explanation":"人均等于数量除以人数。42除以21、36除以18、30除以15都等于2，三个班一样多。只比较总数量会误以为第一班最多。","source":"原创练习"},{"id":"zl-40","subject":"岗位能力","chapter":"资料分析","stem":"四项指标的变化是：甲从200增至250，乙从400增至460，丙从100增至140，丁从300增至345。增速最高的是：","options":["甲","乙","丙","丁"],"answer":2,"explanation":"增速等于增量除以基期。甲是50除以200等于25%，乙是60除以400等于15%，丙是40除以100等于40%，丁是45除以300等于15%。丙最高。","source":"原创练习"},{"id":"zl-41","subject":"岗位能力","chapter":"资料分析","stem":"某日上午到馆80人、下午到馆120人，其中上午会员20人、下午会员60人。全天会员占到馆人数的：","options":["25%","40%","50%","60%"],"answer":1,"explanation":"会员合计是20加60等于80，到馆合计是80加120等于200，比重是80除以200等于40%。50%只是下午会员占下午到馆人数，不是全天比重。","source":"原创练习"},{"id":"zl-42","subject":"岗位能力","chapter":"资料分析","stem":"某仓库入库约498箱，出库约249箱。出库约占入库的：","options":["三分之一","一半","三分之二","八成"],"answer":1,"explanation":"249除以498可以估算成250除以500，等于一半。实际分子、分母都略小，仍最接近一半。三分之一约是166箱，八成约是398箱，都离249较远。","source":"原创练习"},{"id":"zl-43","subject":"岗位能力","chapter":"资料分析","stem":"前2小时时速40公里，后3小时时速60公里。全程平均时速是：","options":["48公里/小时","50公里/小时","52公里/小时","54公里/小时"],"answer":2,"explanation":"平均速度等于总路程除以总时间，不能把两个速度直接平均。总路程是40乘2加60乘3等于260公里，总时间5小时，260除以5等于52公里/小时。","source":"原创练习"},{"id":"zl-44","subject":"岗位能力","chapter":"资料分析","stem":"合格率由80%提高到92%。合格率提高了多少个百分点？","options":["12","15","80","92"],"answer":0,"explanation":"百分数相减得到百分点：92减80等于12。15是相对增幅，算法是12除以80。题干问的是提高了多少个百分点。","source":"原创练习"},{"id":"zl-45","subject":"岗位能力","chapter":"资料分析","stem":"四个月支出分别为22万、35万、28万、15万元。支出最高的月份占四个月总支出的比重是：","options":["15%","28%","35%","40%"],"answer":2,"explanation":"总额是22加35加28加15等于100万元。最高的是35万，比重是35除以100等于35%。28%只是把第三个月的支出数字当成了比重。","source":"原创练习"},{"id":"zl-46","subject":"岗位能力","chapter":"资料分析","stem":"今年甲指标550，同比增长10%；乙指标360，同比下降10%。去年甲比乙多：","options":["90","100","190","290"],"answer":1,"explanation":"先分别还原去年的值。去年甲是550除以1.1等于500，去年乙是360除以0.9等于400，去年甲比乙多500减400等于100。190是今年的差550减360，不能代替去年。","source":"原创练习"},{"id":"kx-01","subject":"基本知识","chapter":"科学技术","stem":"冰块在光滑水平冰面上滑动，所受合外力可以忽略。按照牛顿第一定律，它将：","options":["立刻停止","保持匀速直线运动","速度一定越来越大","必须改做圆周运动"],"answer":1,"explanation":"牛顿第一定律：合外力为零时，物体保持静止或匀速直线运动，这就是惯性。冰块已经在滑动，又几乎不受合外力，所以继续匀速直线滑行。速度越来越大必须有合外力，那是牛顿第二定律描述的情形，本题正好把合外力排除了。","source":"原创练习"},{"id":"kx-02","subject":"基本知识","chapter":"科学技术","stem":"比较惯性大小时，应当主要依据：","options":["当时速度的快慢","物体体积的大小","质量的大小","表面温度的高低"],"answer":2,"explanation":"质量是惯性大小的量度，质量越大，运动状态越难改变。速度只表示这一刻运动得有多快，同一辆车速度变了，惯性并不跟着变。所以不能把跑得快当成惯性大。","source":"原创练习"},{"id":"kx-03","subject":"基本知识","chapter":"科学技术","stem":"人在船上用桨向后划水，船向前行。对桨向后推水和水向前推桨这两个力，判断正确的是：","options":["大小相等，都作用在船上，因而相互抵消","大小相等、方向相反，分别作用在水和桨上，不能抵消","只有桨推水，水不会反过来推桨","两力大小不等，所以才不算平衡力"],"answer":1,"explanation":"这是一对作用力与反作用力：同时产生，大小相等、方向相反，但分别作用在水和桨两个物体上，不能彼此抵消。船前进，是因为水对桨的力传到了船这一侧。把它们当成作用在同一物体上的平衡力，就会错以为船不该动。","source":"原创练习"},{"id":"kx-04","subject":"基本知识","chapter":"科学技术","stem":"同一种液体、同一深度，容器底部形状不同。这一深度的液体压强：","options":["只由液体密度和深度决定，与容器形状无关","底面积越大压强越大","容器越矮压强一定越大","因为不算大气压，所以液体压强为零"],"answer":0,"explanation":"液体压强由密度、重力加速度和深度决定，同种液体、同一深度，压强相同。容器胖瘦改变的是液重和底面积的搭配，不改变这个深度上的压强。底面积大压强大，是把压强和压力混成了一个量。","source":"原创练习"},{"id":"kx-05","subject":"基本知识","chapter":"科学技术","stem":"同一木块先后漂浮在水和酒精上。两次受到的浮力：","options":["在水中更大，因为水的密度大","在酒精中更大，因为木块会沉得更深","相等，都等于木块所受重力","都小于重力，否则木块不会浮起"],"answer":2,"explanation":"漂浮时浮力与重力平衡，木块重力不变，两次浮力就相等。水的密度更大，木块只需排开较小体积就能获得同样浮力，所以浸入更浅，而不是浮力更大。浮力小于重力时物体会下沉，不能用来描述稳定漂浮。","source":"原创练习"},{"id":"kx-06","subject":"基本知识","chapter":"科学技术","stem":"在高山营地用普通锅煮鸡蛋，水已经翻滚，鸡蛋却不容易熟。主要原因是：","options":["高山上没有重力，水不能沸腾","气压低，水的沸点降低，沸腾后水温仍偏低","高山氧气少，蛋清不能发生任何变化","水的比热容变为零"],"answer":1,"explanation":"气压下降，液体沸点下降。高山上水往往不到100摄氏度就沸腾，水温就停在这个较低的沸点，蛋白质不易凝固。氧气少会影响燃烧是否充分，不会单独决定已经沸腾的水温。看到翻滚只说明在沸腾，不能说明水温仍是100摄氏度。","source":"原创练习"},{"id":"kx-07","subject":"基本知识","chapter":"科学技术","stem":"太阳的能量能够穿过近乎真空的日地空间传到地球，主要传递方式是：","options":["热传导","热对流","热辐射","日地之间的空气流动"],"answer":2,"explanation":"传导靠物体各部分直接接触，对流靠液体或气体流动，两者都要介质。辐射通过电磁波传播，真空挡不住。日地之间没有可供对流的空气，把空气流动当成通道，和真空这个条件矛盾。","source":"原创练习"},{"id":"kx-08","subject":"基本知识","chapter":"科学技术","stem":"沿海城市昼夜温差往往比内陆小，与水的性质关系最直接的是：","options":["水的颜色","水的比热容较大，升降温都比较慢","水的沸点正好是100摄氏度","水不能流动"],"answer":1,"explanation":"比热容大，吸收或放出同样多的热量时温度变化小。海水升温慢、降温也慢，就缓和了沿岸气温。沸点只说明水在标准气压下何时沸腾，解释不了日常的气温变化幅度。","source":"原创练习"},{"id":"kx-09","subject":"基本知识","chapter":"科学技术","stem":"关于声音，正确的是：","options":["真空里爆炸声传得更快","音调由振幅决定，响度由频率决定","响度主要随振幅增大而增大，真空不能传声","音色只由声音传播的距离决定"],"answer":2,"explanation":"响度主要看振幅，音调看频率，音色看波形。声音靠介质中的振动传递，真空没有介质，所以不能传声。把音调和响度的决定因素对调，是这一题最常见的错法；真空里更不可能传得更快。","source":"原创练习"},{"id":"kx-10","subject":"基本知识","chapter":"科学技术","stem":"医院B超成像，利用的是：","options":["次声波被人耳直接听成图像","超声波在不同组织界面发生反射","X射线的电离作用","强磁场使骨骼发出可见光"],"answer":1,"explanation":"超声波频率高于2万赫兹，人耳听不见，遇到不同组织的界面会反射，仪器根据回波形成图像。X射线成像是CT和普通拍片的思路，电离作用并不是B超的原理。次声波频率太低，也不能被人耳听成图像。","source":"原创练习"},{"id":"kx-11","subject":"基本知识","chapter":"科学技术","stem":"一束光从空气斜着射入平静的池水。与入射角相比，折射角：","options":["更大，光线远离法线","更小，光线靠近法线","永远等于90度","无法比较，因为光在水中速度变大"],"answer":1,"explanation":"空气中的光速大于水中的光速。光从空气斜射入水，折射光线靠近法线，折射角小于入射角。从水斜射入空气时才会出现折射角更大的情况，方向不能记反。光进入水中速度变小，不是变大。","source":"原创练习"},{"id":"kx-12","subject":"基本知识","chapter":"科学技术","stem":"用放大镜看清报纸上被放大的字时，成像情况是：","options":["物体在焦点以内，成正立、放大的虚像","物体在二倍焦距以外，成倒立、放大的实像","成倒立、缩小的实像，再用眼睛把它正过来","只有凹透镜才能把字放得更大"],"answer":0,"explanation":"放大镜是凸透镜。物体放在焦点以内时，成正立、放大的虚像，这才是放大镜的用法。物体在二倍焦距以外时，凸透镜成的是倒立、缩小的实像，那是照相机一类的情形，而且不是放大。凹透镜对光起发散作用，不能当成放大镜。","source":"原创练习"},{"id":"kx-13","subject":"基本知识","chapter":"科学技术","stem":"嫦娥四号任务最突出的公开成果是：","options":["把航天员首次送上火星","实现探测器在月球背面软着陆，并借助中继卫星与地球通信","取代地球上所有光学望远镜","第一次把卫星送到地球同步轨道"],"answer":1,"explanation":"2019年嫦娥四号在月球背面软着陆。背面不能直接对地球传回信号，所以要靠中继卫星。它是无人探测，不是载人登火星；地球同步轨道早有通信卫星，也不能据此说它取代了望远镜。","source":"原创练习"},{"id":"kx-14","subject":"基本知识","chapter":"科学技术","stem":"下列电磁波按波长从长到短排列，正确的是：","options":["伽马射线、可见光、无线电波","紫外线、红外线、无线电波","可见光、无线电波、红外线","无线电波、可见光、伽马射线"],"answer":3,"explanation":"波长从长到短大致是无线电波、红外线、可见光、紫外线、X射线、伽马射线，频率和光子能量则越来越高。可见光只是中间很窄的一段。把伽马射线排在最前面，是把穿透力强、能量高误记成波长长。","source":"原创练习"},{"id":"kx-15","subject":"基本知识","chapter":"科学技术","stem":"家庭电路里电灯、冰箱等用电器通常并联。这样连接主要是为了：","options":["各用电器两端电压都等于电源电压，并且一条支路断开时其他支路仍能工作","让电流处处相等，总电阻变成各电阻之和","省去零线","使每个用电器的功率一定相同"],"answer":0,"explanation":"并联各支路电压相等，彼此独立，符合家用电器时开时关的需要。电流处处相等、总电阻相加，是串联的特点；串联时一个断开会全部熄灭。并联并不强迫各电器功率相同，功率还要看各自电阻。","source":"原创练习"},{"id":"kx-16","subject":"基本知识","chapter":"科学技术","stem":"远距离输送一定功率的电能时采用高压，主要目的是：","options":["增大导线电阻，让电表走得更慢","减小输电电流，从而减少线路上的热损失","把交流电全部变成直流电","让电阻从导线上消失"],"answer":1,"explanation":"输送功率近似等于电压乘以电流。功率一定时，提高电压就能减小电流。线路发热与电流的平方和电阻有关，电流小了，热损失才降下来。高压不会取消电阻，也不是为了把交流改成直流。","source":"原创练习"},{"id":"kx-17","subject":"基本知识","chapter":"科学技术","stem":"手摇发电机和小电动机的能量转化，对应正确的是：","options":["发电机把机械能转为电能，电动机把电能转为机械能","两者都只把化学能转为内能","发电机靠燃料燃烧，电动机靠光的折射","两者都必须先取消磁场才能工作"],"answer":0,"explanation":"发电机利用电磁感应，线圈在磁场中运动，把机械能变成电能。电动机利用通电导体在磁场中受力，把电能变成机械能。燃料燃烧是热机的思路，不是手摇发电机的原理；没有磁场，这两类电磁装置都无法按这个原理工作。","source":"原创练习"},{"id":"kx-18","subject":"基本知识","chapter":"科学技术","stem":"目前商业核电站堆芯释放能量，依靠的是：","options":["氢核的可控聚变","铀等重核的可控裂变","煤在反应堆里燃烧","原子核完全不变，只加热冷却水"],"answer":1,"explanation":"商业核电站利用重核裂变释放的能量加热工质、推动汽轮发电机。太阳内部和氢弹才是核聚变，可控聚变还没有成为现成的商业电站原理。煤的燃烧只是核外电子的化学变化，能量尺度和核反应不同。","source":"原创练习"},{"id":"kx-19","subject":"基本知识","chapter":"科学技术","stem":"制造大规模集成电路时，最典型的半导体材料是：","options":["纯铜","硅","普通玻璃","干燥木材"],"answer":1,"explanation":"半导体的导电能力介于导体和绝缘体之间，掺入微量杂质后可以制成二极管、三极管和芯片。硅是这方面最常用的材料。纯铜是良导体，玻璃和干燥木材更接近绝缘体，都没有半导体那种可用杂质精确调节的导电性。","source":"原创练习"},{"id":"kx-20","subject":"基本知识","chapter":"科学技术","stem":"贵州平塘的中国天眼FAST，所属类型是：","options":["用透镜会聚可见光的光学望远镜","接收天体无线电波的单口径球面射电望远镜","只负责预报降雨的气象站","载人深海潜水器"],"answer":1,"explanation":"FAST口径500米，是球面射电望远镜，收集的是天体发出的射电信号，不是可见光图像。它建在贵州的喀斯特洼地里，和气象雷达、深潜器没有同一类功能。看到天眼就当成光学望远镜，是把观测波段弄错了。","source":"原创练习"},{"id":"kx-21","subject":"基本知识","chapter":"科学技术","stem":"下列过程属于化学变化的是：","options":["酒精挥发","冰熔化成水","铁矿石炼成铁","玻璃杯摔碎"],"answer":2,"explanation":"判断化学变化，要看有没有新物质生成。炼铁时铁的化合物被还原成铁单质，物质种类变了。挥发、熔化和摔碎只改变状态或形状，物质种类没有变。酒精挥发最容易被误判，因为它好像消失了，其实只是扩散到空气中。","source":"原创练习"},{"id":"kx-22","subject":"基本知识","chapter":"科学技术","stem":"关于催化剂，正确的说法是：","options":["反应前后质量和化学性质都改变，所以才能加快反应","能改变化学反应速率，反应前后质量和化学性质不变","可以制造出新的原子，使生成物质量无中生有","能让任意两种原来不反应的物质都发生反应"],"answer":1,"explanation":"催化剂改变的是反应路径和速率，本身的质量和化学性质在反应前后不变，因此不能凭空增加原子。它也不是万能的，不能把本来不能发生的任意反应都变成可能。若反应前后催化剂本身变成了别的物质，它就不符合催化剂的定义。","source":"原创练习"},{"id":"kx-23","subject":"基本知识","chapter":"科学技术","stem":"酸雨和臭氧层破坏容易被混为一谈。对应正确的是：","options":["酸雨主要与二氧化硫、氮氧化物有关；平流层臭氧减少主要与消耗臭氧的物质有关","两者都是因为近地面氧气太多","酸雨是臭氧过多造成的","食盐是破坏臭氧层的典型物质"],"answer":0,"explanation":"二氧化硫和氮氧化物进入大气后会形成酸性物质，使降水明显变酸。平流层臭氧能吸收大量紫外线，它的减少主要与氟氯烃一类消耗臭氧的物质有关。两件事的污染物和发生高度都不同。用酸雨去解释臭氧，或者用食盐去解释臭氧减少，都把原因安错了对象。","source":"原创练习"},{"id":"kx-24","subject":"基本知识","chapter":"科学技术","stem":"某溶液的pH由3变为2。溶液中氢离子浓度大约变为原来的：","options":["十分之一","10倍","2倍","不变，因为只差1"],"answer":1,"explanation":"pH是氢离子浓度的负对数，不是普通的线性刻度。pH减小1，氢离子浓度大约变为原来的10倍，酸性更强。只按数值差1理解成2倍或几乎不变，就丢掉了对数这一步。pH变小是更酸，不是更稀。","source":"原创练习"},{"id":"kx-25","subject":"基本知识","chapter":"科学技术","stem":"植物叶肉细胞中，光合作用和有氧呼吸的主要场所分别是：","options":["都在线粒体","叶绿体；线粒体","核糖体；液泡","细胞核；细胞膜"],"answer":1,"explanation":"叶绿体利用光能，把二氧化碳和水合成有机物并释放氧气。线粒体是有氧呼吸的主要场所，分解有机物、释放能量。两者方向相反，不能都放到线粒体里。核糖体负责合成蛋白质，不是光合作用的场所。","source":"原创练习"},{"id":"kx-26","subject":"基本知识","chapter":"科学技术","stem":"普通流感一般不用抗生素治疗。最贴切的理由是：","options":["流感病毒没有细菌那种细胞结构，常用抗生素主要针对细菌","病毒比细菌大，药物分子进不去","抗生素只能杀死人体自身细胞","流感不会在人与人之间传播"],"answer":0,"explanation":"病毒没有细胞结构，必须进入活细胞才能繁殖。常用抗生素干扰的是细菌的细胞壁或蛋白质合成等环节，对病毒不起针对作用。病毒通常比细菌小，不是更大。流感本身是传染病，只是病原体类型决定了抗生素不对症。","source":"原创练习"},{"id":"kx-27","subject":"基本知识","chapter":"科学技术","stem":"红细胞中的血红蛋白，主要功能是：","options":["独立完成凝血的全部过程","吞噬入侵的细菌","与氧气结合，承担运氧任务","分泌消化酶"],"answer":2,"explanation":"血红蛋白能与氧气结合，所以红细胞负责运输氧气。止血凝血主要与血小板和凝血因子有关，吞噬病菌是一部分白细胞的功能，消化酶来自消化腺。血液是红色的，不能因此把血红蛋白说成凝血物质。","source":"原创练习"},{"id":"kx-28","subject":"基本知识","chapter":"科学技术","stem":"接种疫苗预防某种传染病，属于：","options":["人工主动免疫，促使机体自己产生抗体和记忆","人工被动免疫，直接输入大量现成抗体","不针对特定病原体的非特异性免疫","对遗传病的基因修复"],"answer":0,"explanation":"疫苗相当于抗原，进入人体后引起特异性免疫，留下记忆细胞，以后再遇到相同病原体反应更快。直接注射抗毒血清才是人工被动免疫，起效快、保持时间较短。皮肤屏障和吞噬作用才是非特异性的，而且疫苗预防的是传染病，不是遗传病。","source":"原创练习"},{"id":"kx-29","subject":"基本知识","chapter":"科学技术","stem":"唾液淀粉酶在沸水中几乎不再起作用。主要原因是：","options":["高温破坏了酶的空间结构，活性随之丧失","温度越高，酶的活性一定越强","酶变成了无机催化剂，只是反应变慢","淀粉在任何温度下都不能被分解"],"answer":0,"explanation":"酶主要是蛋白质，有适合自己的温度范围。过高温度会使蛋白质变性，催化部位被破坏，通常冷却后也不能恢复。酶不是越热越快。淀粉在强酸加热等条件下仍可水解，所以不能说淀粉本身永远不能分解。","source":"原创练习"},{"id":"kx-30","subject":"基本知识","chapter":"科学技术","stem":"生态系统中能量流动的特点是：","options":["沿食物链循环使用，总能量保持不变","从生产者开始单向传递，并且逐级递减","由消费者固定太阳能后再交给生产者","分解者使能量原路返回上一级"],"answer":1,"explanation":"生产者固定太阳能后，能量沿食物链向下传递。每一级都有呼吸消耗，还有热量散失，不能再流回给上一级，所以是单向的，而且越传越少。可以循环的是碳、氮等物质，不是能量。消费者不能代替生产者去固定太阳能。","source":"原创练习"},{"id":"kx-31","subject":"基本知识","chapter":"科学技术","stem":"一对相对性状由等位基因控制，显性完全。杂种子一代自交，子二代显性性状与隐性性状的比例约为：","options":["1比1","3比1","全部显性，不会分离","1比2比1，而且这是表现型之比"],"answer":1,"explanation":"杂合子自交，子代基因型大约是显性纯合1、杂合2、隐性纯合1。前两类都表现显性，所以表现型约为3比1。1比2比1是基因型之比，把它当成表现型就多算了一类。1比1更接近杂合子与隐性个体测交的结果。","source":"原创练习"},{"id":"kx-32","subject":"基本知识","chapter":"科学技术","stem":"用达尔文的自然选择解释长颈鹿脖子较长，应当强调：","options":["经常伸脖子会使脖子变长，而且这一变化直接遗传","种群里本来就有颈长差异，颈较长的个体更易生存并繁殖","环境只能改变外形，不会改变留下后代的机会","获得性遗传是自然选择的核心"],"answer":1,"explanation":"自然选择保留的是可遗传的有利变异：个体之间本来就有差异，生存和繁殖机会不同，有利变异才会在后代中增多。经常使用器官就变长、再直接传给后代，是拉马克的用进废退和获得性遗传，不是达尔文的机制。","source":"原创练习"},{"id":"kx-33","subject":"基本知识","chapter":"科学技术","stem":"北半球在一月前后离太阳较近，当地却是冬季。这说明：","options":["季节主要由日地距离决定","季节主要来自地轴倾斜引起的正午太阳高度和昼夜长短变化","冬季是因为月球挡住了阳光","地球自转一周约24小时，所以一年有四季"],"answer":1,"explanation":"地轴是倾斜的，地球公转时太阳直射点在南北回归线之间移动，同一地区得到的光热跟着变化，形成四季。一月地球位于近日点附近，北半球仍然因为阳光斜射、白昼较短而寒冷，可见距离远近不是主因。自转解释的是昼夜交替。","source":"原创练习"},{"id":"kx-34","subject":"基本知识","chapter":"科学技术","stem":"从地球上看不到月球背面。对此，正确的认识是：","options":["背面永远没有阳光","月球自转周期与绕地球公转的周期相同，几乎总以同一面朝向地球；背面同样有昼夜","月球不自转，所以背面是地球影子","背面长期被地球阴影完全罩住"],"answer":1,"explanation":"月球同步自转，绕地球一圈的同时也自转一圈，因此地球上的人几乎总看到同一面。背面只是对着地球的机会极少，太阳光仍会照到，那里一样有白昼和黑夜。地球阴影罩住月球是月食，而且只持续一段时间，不是背面的定义。","source":"原创练习"},{"id":"kx-35","subject":"基本知识","chapter":"科学技术","stem":"发生日食时，太阳、地球、月球的位置关系是：","options":["地球在太阳和月球之间","月球在太阳和地球之间，三者近于一条直线","太阳在地球和月球之间","月球移到地球黑夜的外侧，挡住地影"],"answer":1,"explanation":"日食是月球挡住了射向地球的太阳光，挡光的天体在中间，所以是月球位于太阳和地球之间。月食才是地球挡住太阳光，地球位于中间。把这两种食的位置对调，是这一类题最常见的错误。","source":"原创练习"},{"id":"kx-36","subject":"基本知识","chapter":"科学技术","stem":"同一次地震的震级和烈度，关系是：","options":["每个村一个震级，全国共用一个烈度","震级只有一个，不同地点的烈度可以不同","震级描述的是房屋裂缝的宽窄","烈度越大，就要把释放的能量按街道重新计算一遍"],"answer":1,"explanation":"震级表示震源释放了多少能量，一次地震只评定一个震级。烈度表示某个地点的震动和破坏程度，受距离、震源深度和场地条件影响，所以各地可以不一样。用房屋损坏去改写震级，就把能量和当地破坏换了位置。","source":"原创练习"},{"id":"kx-37","subject":"基本知识","chapter":"科学技术","stem":"云、雨、风等天气现象主要发生在大气的：","options":["对流层","平流层上部的臭氧集中区","热层","真空的行星际空间"],"answer":0,"explanation":"对流层集中了绝大部分水汽和杂质，空气上下对流明显，常见天气都发生在这里。平流层以水平运动为主，水汽很少，臭氧吸收紫外线，适合飞机巡航，但不是风雨的主要发生层。把天气放到平流层，多半是因为记得那里很重要，却记错了重要的原因。","source":"原创练习"},{"id":"kx-38","subject":"基本知识","chapter":"科学技术","stem":"光年表示的是：","options":["光传播所用的时间","光在真空中一年内所走的距离","光速的大小","望远镜的放大倍数"],"answer":1,"explanation":"光年带有年字，却是长度单位，等于真空中的光走一年的路程，用来衡量恒星之间的距离。它不是时间，也不是速度本身。看到年就选时间，是被单位的名称带偏了。","source":"原创练习"},{"id":"kx-39","subject":"基本知识","chapter":"科学技术","stem":"关于计算机中的存储，正确的是：","options":["正在运行的程序数据通常放在随机存取内存中，断电后这类内存里的数据会丢失","内存断电后内容一定还在，所以不必保存文件","硬盘是主存储器，内存属于外存","只有文字能变成二进制，图像不能"],"answer":0,"explanation":"随机存取内存速度快，供计算机当前工作使用，断电后数据消失；需要长期保存，就要写入硬盘等外存。因此编辑文件后要保存。硬盘容量大、掉电不丢数据，但它是外存，不是主存。图像同样用二进制表示，只是编码方式不同。","source":"原创练习"},{"id":"kx-40","subject":"基本知识","chapter":"科学技术","stem":"在浏览器中输入网站域名后能够打开网页，其中不可缺少的一步是：","options":["通过域名系统把域名解析成服务器的IP地址","把域名直接当成电压值发送","先关闭沿途所有路由器","用域名代替加密，因此不再需要地址"],"answer":0,"explanation":"域名方便人记忆，路由器转发数据包看的是IP地址。域名系统负责两者之间的翻译。域名不是电压，关掉路由器只会使访问失败。加密解决的是传输安全，不能代替地址问题。","source":"原创练习"},{"id":"kx-41","subject":"基本知识","chapter":"科学技术","stem":"由中国自主建设、可提供全球定位授时服务的卫星导航系统是：","options":["GPS","格洛纳斯","北斗","哈勃空间望远镜"],"answer":2,"explanation":"北斗是中国的卫星导航系统。GPS是美国的，格洛纳斯是俄罗斯的。哈勃是光学空间望远镜，不承担导航星座的功能。几种系统都能定位，不能按能定位就是GPS来判断国别。","source":"原创练习"},{"id":"kx-42","subject":"基本知识","chapter":"科学技术","stem":"载人飞船、货运飞船和运载火箭的公开名称，对应正确的是：","options":["神舟载人，天舟货运，长征负责发射","神舟货运，长征载人，天和是火箭","嫦娥货运，天问载人","天舟是空间站核心舱，神舟是运载火箭"],"answer":0,"explanation":"神舟系列运送航天员，天舟系列运送物资，两者都由长征系列火箭送入轨道。天和是中国空间站的核心舱，不是火箭。嫦娥承担探月，天问承担行星探测，不能按一个载人、一个送货去套。","source":"原创练习"},{"id":"kx-43","subject":"基本知识","chapter":"科学技术","stem":"我国宣布的碳达峰、碳中和时间顺序是：","options":["2030年前碳中和，2060年前碳达峰","2030年前碳达峰，2060年前碳中和","两个目标都要求在2020年前停止一切能源使用","先实现碳中和，排放量才会出现峰值"],"answer":1,"explanation":"碳达峰是二氧化碳排放由上升转为下降的峰值，碳中和是排放与吸收相互抵消。必须先经过峰值，再逐步走到净零，所以是2030年前达峰、2060年前中和。把两个年份对调，会让净零出现在峰值之前，顺序本身就矛盾。","source":"原创练习"},{"id":"kx-44","subject":"基本知识","chapter":"科学技术","stem":"青蒿素与杂交水稻这两项成果，代表性科学家对应正确的是：","options":["袁隆平发现青蒿素，屠呦呦培育杂交水稻","屠呦呦领导团队发现青蒿素，袁隆平培育杂交水稻","两人都主要贡献于运载火箭","弗莱明发现青蒿素，袁隆平发现青霉素"],"answer":1,"explanation":"屠呦呦团队从黄花蒿中发现青蒿素，用于治疗疟疾，屠呦呦获得诺贝尔生理学或医学奖。袁隆平长期研究杂交水稻，提高粮食产量。两人的领域一个是医药、一个是作物育种，对调后就和成果对不上。弗莱明发现的是青霉素，不是青蒿素。","source":"原创练习"},{"id":"kx-45","subject":"基本知识","chapter":"科学技术","stem":"要检验单摆周期是否随摆长改变，实验中应当：","options":["同时改变摆长、摆球质量和摆角","只改变摆长，尽量保持摆球质量和摆角不变","不做对照，一次测量就能得到规律","先写下想要的结论，再挑选相符的一次数据"],"answer":1,"explanation":"这是控制变量法：可能影响结果的因素里，一次只改变所研究的那个，其余保持相同，差异才能归因于摆长。所有条件一起变，就无法知道是哪一个因素在起作用。只挑一次符合预想的数据，也不是检验。","source":"原创练习"},{"id":"kx-46","subject":"基本知识","chapter":"科学技术","stem":"磁共振成像与CT在成像原理上的主要区别是：","options":["磁共振利用核磁共振信号，检查本身不依靠X射线；CT利用X射线","两者都只使用超声波","磁共振的电离辐射一定强于CT","CT不能成像，只能做血常规"],"answer":0,"explanation":"CT用X射线从不同角度扫描，再由计算机重建断层图像，存在电离辐射。磁共振利用人体内氢核在磁场中的共振信号成像，检查过程本身不使用X射线。把它说成辐射更强，是把机器更复杂当成了射线更强。超声波成像对应的是B超。","source":"原创练习"},{"id":"gf-01","subject":"基本知识","chapter":"国防与军队","stem":"坚持党对人民军队绝对领导，其根本制度和根本实现形式是：","options":["各省级政府分别指挥驻当地的部队","军委主席负责制","军队脱离政治领导","战区各自决定国家的战争与和平"],"answer":1,"explanation":"军委主席负责制把最高领导权和指挥权集中于中央军委主席，是党对军队绝对领导的根本实现形式。部队不能按行政区划交给地方政府分别指挥，战争与和平的决定权也不在某一个战区。","source":"原创练习"},{"id":"gf-02","subject":"基本知识","chapter":"国防与军队","stem":"陆军、海军、空军、火箭军在国家武装力量中的位置是：","options":["四者相加就是我国全部武装力量","它们是中国人民解放军的军种；武装力量还包括武警部队和民兵","它们都列入武警序列","它们是民兵的四种分类"],"answer":1,"explanation":"武装力量由中国人民解放军、中国人民武装警察部队和民兵组成。陆海空和火箭军是解放军内部的军种，范围比全部武装力量小。把军种当成武装力量的全部，就漏掉了武警和民兵。","source":"原创练习"},{"id":"gf-03","subject":"基本知识","chapter":"国防与军队","stem":"在军委管总、战区主战、军种主建中，战区的主要职责偏向：","options":["负责各军种的日常建设，不负责作战指挥","担负联合作战指挥","代替国务院管理退役安置","只领导民兵，不涉及现役部队"],"answer":1,"explanation":"这三句话要分开记：中央军委管总，战区主战，军种主建。战区是联合作战指挥机构。军种重点抓好本军种建设、训练和保障，不能把主建和主战对调。退役安置则是政府部门的职责。","source":"原创练习"},{"id":"gf-04","subject":"基本知识","chapter":"国防与军队","stem":"现行战区划分是：","options":["沈阳、北京、济南、南京、广州、兰州、成都七个军区","东部、南部、西部、北部、中部五个战区","北海、东海、南海三个舰队就是三个战区","每个省单独设一个战区"],"answer":1,"explanation":"2016年起，七大军区体制结束，设立东、南、西、北、中五个战区。北海、东海、南海是海军力量的传统方向，不是五个战区的名称。仍按七大军区作答，用的是已经调整掉的旧体制。","source":"原创练习"},{"id":"gf-05","subject":"基本知识","chapter":"国防与军队","stem":"在听党指挥、能打胜仗、作风优良中，能打胜仗的地位是：","options":["灵魂","核心","保证","只在阅兵时才需要"],"answer":1,"explanation":"听党指挥是灵魂，能打胜仗是核心，作风优良是保证。能打胜仗回答的是军队的根本职能。把它记成灵魂，就和听党指挥换了位。作风优良是保证，也不是可有可无的阅兵用语。","source":"原创练习"},{"id":"gf-06","subject":"基本知识","chapter":"国防与军队","stem":"国防和军队现代化进程的节点，对应正确的是：","options":["2027年全面建成世界一流军队","2027年实现建军一百年奋斗目标，2035年基本实现国防和军队现代化，本世纪中叶全面建成世界一流军队","2035年以后才开始提出建军目标","本世纪中叶改为只保留民兵"],"answer":1,"explanation":"2027年对应的是建军一百年奋斗目标，2035年是基本实现国防和军队现代化，本世纪中叶才是把人民军队全面建成世界一流军队。把2027年直接写成世界一流已经建成，是把最近的节点当成了最终目标。","source":"原创练习"},{"id":"gf-07","subject":"基本知识","chapter":"国防与军队","stem":"南昌起义与秋收起义的关系，表述正确的是：","options":["1927年8月1日的南昌起义打响了武装反抗国民党反动派的第一枪；秋收起义是同年9月的另一次起义","秋收起义打响第一枪，南昌起义发生在遵义会议之后","两次都是为了发动西安事变","南昌起义当天就建立了井冈山根据地"],"answer":0,"explanation":"南昌起义在1927年8月1日，后来这一天成为建军节。秋收起义在同年9月，之后队伍走向井冈山。第一枪属于南昌起义，不能安到秋收起义头上。井冈山根据地是秋收起义之后创建的，不是南昌起义当天的结果。","source":"原创练习"},{"id":"gf-08","subject":"基本知识","chapter":"国防与军队","stem":"支部建在连上作为一项制度确立于：","options":["三湾改编","古田会议才第一次涉及党的基层组织，三湾改编没有这一内容","遵义会议","1988年恢复军衔时"],"answer":0,"explanation":"1927年9月三湾改编明确支部建在连上，从组织上把党的领导扎到连队。1929年古田会议继续解决思想建党和政治建军，是发展而不是起点。把这项制度算到遵义会议或恢复军衔，时间就晚了。","source":"原创练习"},{"id":"gf-09","subject":"基本知识","chapter":"国防与军队","stem":"1929年古田会议主要解决的是：","options":["如何立即实施渡江战役","在农村游击战争环境中怎样思想建党、政治建军","如何裁减军队员额30万","如何组建国家综合性消防救援队伍"],"answer":1,"explanation":"古田会议指出红军是执行革命政治任务的武装集团，必须把思想建设放在首位，反对单纯军事观点。渡江战役是1949年的作战行动，裁军30万是2015年宣布的，消防改制在2018年，都不能用来说明1929年这次会议。","source":"原创练习"},{"id":"gf-10","subject":"基本知识","chapter":"国防与军队","stem":"遵义会议的历史作用是：","options":["开始确立以毛泽东为主要代表的正确领导，在危急关头挽救了党、红军和中国革命","宣布抗日战争胜利","决定发动南昌起义","通过现行兵役法"],"answer":0,"explanation":"1935年1月的遵义会议，是党的历史上一个生死攸关的转折点。南昌起义发生在1927年，不可能由后来的遵义会议决定。抗战胜利和现行兵役法更是之后的事情。最容易错的是把遵义会议和南昌起义的因果关系颠倒。","source":"原创练习"},{"id":"gf-11","subject":"基本知识","chapter":"国防与军队","stem":"三大纪律里，直接约束对群众财物行为的是：","options":["一切行动听指挥","不拿群众一针一线","一切缴获要归公","说话和气"],"answer":1,"explanation":"三大纪律是一切行动听指挥、不拿群众一针一线、一切缴获要归公。其中不拿群众一针一线针对的是人民群众的财物。一切缴获要归公规范的是战利品归属。说话和气属于八项注意，不在三大纪律里。","source":"原创练习"},{"id":"gf-12","subject":"基本知识","chapter":"国防与军队","stem":"人民军队政治工作的三大原则是：","options":["官兵一致、军民一致、瓦解敌军","政治民主、经济民主、军事民主","听党指挥、能打胜仗、作风优良","拥军优属、拥政爱民、军民融合"],"answer":0,"explanation":"政治工作三大原则是官兵一致、军民一致、瓦解敌军。政治、经济、军事三大民主是军队内部民主的另一组表述，强军目标的三句话又是新时代的建设要求。三组话都重要，但不能互相顶替。","source":"原创练习"},{"id":"gf-13","subject":"基本知识","chapter":"国防与军队","stem":"军队内部的三大民主是指：","options":["政治民主、经济民主、军事民主","官兵一致、军民一致、瓦解敌军","立法、行政、司法三权分立","陆战、海战、空战三种民主"],"answer":0,"explanation":"三大民主是政治民主、经济民主、军事民主，目的是调动官兵的积极性和创造性。官兵一致、军民一致、瓦解敌军是政治工作三大原则，词面相近，内容不是同一组。三权分立不是人民军队的组织原则。","source":"原创练习"},{"id":"gf-14","subject":"基本知识","chapter":"国防与军队","stem":"人民海军、人民空军的成立纪念日分别是：","options":["4月23日，11月11日","都是8月1日","11月11日，4月23日","都是1955年首次授衔的那一天"],"answer":0,"explanation":"1949年4月23日，华东军区海军组建，这一天定为海军成立日。1949年11月11日，空军领导机构成立，这一天定为空军成立日。8月1日是全军建军节，不能代替军种纪念日。把两个日期对调，是记混了军种。海军领导机关在北京成立是1950年4月，那是机关组建时间，不是4月23日这个纪念日的来历。","source":"原创练习"},{"id":"gf-15","subject":"基本知识","chapter":"国防与军队","stem":"火箭军与第二炮兵的关系是：","options":["火箭军于2015年底在第二炮兵基础上成立，第二炮兵番号不再使用","第二炮兵至今仍是火箭军之外的另一个军种","火箭军列入武警海警序列","火箭军是空军下属的一个运输团"],"answer":0,"explanation":"第二炮兵成立于1966年。2015年12月31日，火箭军在第二炮兵基础上正式亮相，成为解放军的一个军种，原番号不再保留。它不是武警的一部分，也不是空军的运输部队。认为两个番号今天同时存在，是没有把更名组建和另立一家区分开。","source":"原创练习"},{"id":"gf-16","subject":"基本知识","chapter":"国防与军队","stem":"2016年军委机关调整后，对原四总部体制的正确理解是：","options":["四总部体制结束，改行军委机关多部门制；战役作战指挥的重心在战区","四总部只换了牌子，指挥关系没有任何变化","四总部改成国务院的四个部","四总部直接改名为五个战区，军委不再设机关"],"answer":0,"explanation":"改革后不再保留总参谋部、总政治部、总后勤部、总装备部四个总部，而是设立联合参谋部、政治工作部、后勤保障部、装备发展部等军委机关部门。联合参谋部也不是把过去总部的战役指挥原样接过来，战区主战，战役指挥重心在战区。","source":"原创练习"},{"id":"gf-17","subject":"基本知识","chapter":"国防与军队","stem":"2018年领导指挥体制改革以后，武警部队：","options":["继续由国务院和中央军委双重领导","由党中央、中央军委集中统一领导","整建制改归应急管理部","交给各省政府分别指挥"],"answer":1,"explanation":"自2018年1月1日起，武警部队改由党中央、中央军委集中统一领导，实行中央军委、武警部队、部队的领导指挥体制，不再实行国务院和中央军委双重领导。应急管理部后来管理的是综合性消防救援等队伍，不是整个武警。最容易选错的是改革前的双重领导。","source":"原创练习"},{"id":"gf-18","subject":"基本知识","chapter":"国防与军队","stem":"对今天的国家综合性消防救援队伍，判断正确的是：","options":["仍是武警消防部队，属于现役军人","2018年由公安消防、武警森林等力量退出现役后组建，由应急管理部管理","属于民兵中的普通民兵","就是军队文职人员的一个岗位类别"],"answer":1,"explanation":"2018年机构改革后，公安消防部队、武警森林部队退出现役，组建国家综合性消防救援队伍，列入应急管理部管理。制服和纪律容易让人以为仍是现役，但身份已经不是现役军人，也不是文职人员或普通民兵。","source":"原创练习"},{"id":"gf-19","subject":"基本知识","chapter":"国防与军队","stem":"改革后，中国海警局与武警部队的关系是：","options":["海警队伍已经撤销","海警队伍由武警部队领导指挥，对外仍使用中国海警局名称","海警改属空军航空兵","海警是县级人武部的内设民政机构"],"answer":1,"explanation":"海警队伍转隶武警部队，履行海上维权执法等职责，中国海警局这个名称继续使用。不是撤销，也不是空军或地方民政机构。把转隶理解成解散，就漏掉了名称还在、领导关系变了这一层。","source":"原创练习"},{"id":"gf-20","subject":"基本知识","chapter":"国防与军队","stem":"2021年修订施行的兵役法规定，我国兵役制度是：","options":["只实行义务兵役，不再有志愿兵役","以志愿兵役为主体，志愿兵役与义务兵役相结合","平时不设兵役，只在战争爆发后临时雇兵","以外籍雇佣人员为主体"],"answer":1,"explanation":"修订后的兵役法把制度明确为以志愿兵役为主体、志愿兵役与义务兵役相结合。义务兵役仍然存在，但不再是唯一主体。理解成只剩义务兵或平时没有兵役，都和条文里为主体、相结合不符。","source":"原创练习"},{"id":"gf-21","subject":"基本知识","chapter":"国防与军队","stem":"现行义务兵服现役的期限是：","options":["六个月","二年","八年","没有法定期限，直到个人提出离职"],"answer":1,"explanation":"义务兵服现役的期限为二年。期满后如果军队需要、本人自愿，可以选改为军士，军士的服役管理另有规定，年限不能反写到义务兵身上。六个月常见于一些聘用岗位的试用期，不是义务兵役期限。","source":"原创练习"},{"id":"gf-22","subject":"基本知识","chapter":"国防与军队","stem":"依照宪法，有权决定战争与和平问题的是：","options":["全国人民代表大会","国家主席单独决定","某一个战区机关","县级人民武装部"],"answer":0,"explanation":"宪法规定，全国人民代表大会决定战争与和平的问题。全国人大闭会期间，常委会可以决定战争状态的宣布。国家主席根据全国人大及其常委会的决定，宣布战争状态、发布动员令。宣布权不等于独自的决定权，这是最容易混的一点。","source":"原创练习"},{"id":"gf-23","subject":"基本知识","chapter":"国防与军队","stem":"宪法对公民国防义务的表述是：","options":["保卫祖国、抵抗侵略是公民的神圣职责，依法服兵役和参加民兵组织是光荣义务","只有现役军人负有保卫祖国的职责","服兵役只是一项可以随意放弃的优惠","参加民兵组织与公民无关"],"answer":0,"explanation":"保卫祖国、抵抗侵略是每一个公民的神圣职责，依法服兵役和参加民兵组织是光荣义务。现役军人承担具体军事职务，并不能取消其他公民的宪法义务。把义务说成可有可无的优惠，就和光荣义务的性质相反。","source":"原创练习"},{"id":"gf-24","subject":"基本知识","chapter":"国防与军队","stem":"对我国积极防御国防政策，理解正确的是：","options":["战略上坚持自卫、后发制人，并不等于战役战斗中只能被动挨打","先取消战备，等打到城市再研究如何反应","可以主动对外争夺势力范围","只防御海岸，内陆不在国防范围内"],"answer":0,"explanation":"积极防御是战略上的自卫立场，不是消极等待。在战役战斗中，可以采取必要的攻势行动来达成防御目的。取消战备、挨打后再说，那是消极防御。对外争夺势力范围则离开了防御性国防政策。","source":"原创练习"},{"id":"gf-25","subject":"基本知识","chapter":"国防与军队","stem":"我国关于核武器使用的公开政策是：","options":["在任何时候、任何情况下都不首先使用核武器","可以优先对无核武器国家使用","核武器主要用于民用爆破开矿","承诺不保持任何国防力量"],"answer":0,"explanation":"我国承诺在任何时候、任何情况下都不首先使用核武器，并承诺无条件不对无核武器国家和无核武器区使用或威胁使用核武器。优先对无核国家使用恰好与后一项相反。不首先使用也不等于放弃必要的国防力量。","source":"原创练习"},{"id":"gf-26","subject":"基本知识","chapter":"国防与军队","stem":"全民国防教育日与全民国家安全教育日分别是：","options":["都是8月1日","每年9月的第三个星期六；4月15日","4月15日；每年9月的第三个星期六","都是10月1日"],"answer":1,"explanation":"国防教育法把每年9月第三个星期六定为全民国防教育日。国家安全法把4月15日定为全民国家安全教育日。两个日子分别对应国防教育和国家安全教育，对调后就张冠李戴。8月1日是建军节，10月1日是国庆节。","source":"原创练习"},{"id":"gf-27","subject":"基本知识","chapter":"国防与军队","stem":"中国人民解放军军旗的基本式样是：","options":["红地，缀有金黄色五角星和「八一」两字","与国旗完全相同，只是尺寸缩小","白地，中央为一枚橄榄枝","蓝地，不设五角星"],"answer":0,"explanation":"军旗以红色为底，上面有金黄色五角星和「八一」两字，标明南昌起义这一建军源头。它不是把国旗缩小，也不是以橄榄枝或纯蓝为基本样式。各军种军旗还会在这个基础上增加军种标志，但不能因此改掉解放军军旗本身的红地和八一。","source":"原创练习"},{"id":"gf-28","subject":"基本知识","chapter":"国防与军队","stem":"军队文职人员属于：","options":["现役军官的另一称谓","军队人员的组成部分，但不是现役军人","地方劳务派遣人员，不进入军队人员范围","普通民兵"],"answer":1,"explanation":"文职人员在军队编制岗位上工作，是军队人员的组成部分，同时不服现役，不能把他们简单叫成现役军官。他们也不是军队编制之外的劳务派遣人员，更不是不脱离生产的民兵。区分的关键是军队人员和非现役这两点要同时成立。","source":"原创练习"},{"id":"gf-29","subject":"基本知识","chapter":"国防与军队","stem":"设置文职人员岗位时，界限把握正确的是：","options":["直接作战指挥岗位应当优先配备文职人员","安排在军民通用、非直接参与作战，且不宜交给社会化保障的军队编制岗位","所有岗位都应交给市场，军队不再设编制","只用于生产经营"],"answer":1,"explanation":"文职岗位解决的是军队需要直接掌握、又不适合全部推给市场的军民通用工作，而且不是直接参与作战的岗位。把作战指挥岗位优先交给文职，把界限说反了。全部市场化会和不宜社会化保障这个条件冲突。","source":"原创练习"},{"id":"gf-30","subject":"基本知识","chapter":"国防与军队","stem":"文职人员岗位的两大类别是：","options":["管理类岗位和专业技术类岗位","现役类岗位和雇佣类岗位","元帅岗位和大将岗位","中央岗位和地方岗位"],"answer":0,"explanation":"文职人员按岗位分为管理类和专业技术类，分别从事管理工作和专业技术工作。现役身份不是文职岗位的分类标准。元帅、大将属于历史上的现役军衔，不能用来给文职岗位命名。","source":"原创练习"},{"id":"gf-31","subject":"基本知识","chapter":"国防与军队","stem":"关于我国已公开的三艘航空母舰，技术特征对应正确的是：","options":["辽宁舰和山东舰采用滑跃起飞，福建舰采用平直甲板和电磁弹射","三艘都是核动力，并且都用电磁弹射","福建舰滑跃起飞，辽宁舰电磁弹射","山东舰编入海警序列"],"answer":0,"explanation":"辽宁舰、山东舰使用滑跃甲板；福建舰采用平直甲板和电磁弹射，动力方式是常规动力。电磁弹射说的是飞机怎样起飞，不能据此推断舰艇一定使用核动力。把福建舰说成滑跃、辽宁舰说成电磁弹射，是把首舰和最新一艘的技术特征对调了。","source":"原创练习"},{"id":"gf-32","subject":"基本知识","chapter":"国防与军队","stem":"陆军航空兵与空降兵的隶属关系是：","options":["只要使用飞行器，就都归空军","陆军航空兵隶属陆军，空降兵隶属空军","两者都隶属火箭军","空降兵隶属海军潜艇部队"],"answer":1,"explanation":"陆军航空兵主要使用直升机，配合陆军地面作战，建制在陆军。空降兵从空中投入地面作战，建制在空军。不能只凭会飞都划进空军，也不能因为空降落到地面就把空降兵划给潜艇部队。","source":"原创练习"},{"id":"gf-33","subject":"基本知识","chapter":"国防与军队","stem":"解放战争中，三大战役和渡江战役的先后是：","options":["渡江战役发生在三大战役之前","辽沈、淮海、平津基本歼灭国民党军主力之后，发起渡江战役并解放南京","三大战役发生在长征途中","先解放南京，再进行辽沈战役"],"answer":1,"explanation":"三大战役从1948年秋打到1949年初，主力决战基本结束。1949年4月发起渡江战役，4月23日解放南京。渡江不是三大战役之一，更不是三大战役的前奏。长征则是土地革命战争时期的战略转移。","source":"原创练习"},{"id":"gf-34","subject":"基本知识","chapter":"国防与军队","stem":"中国人民志愿军抗美援朝出国作战纪念日，以及当时的司令员，对应正确的是：","options":["10月1日，朱德","10月25日，彭德怀任司令员兼政治委员","8月1日，贺龙","9月3日，刘伯承"],"answer":1,"explanation":"1950年10月，中国人民志愿军赴朝作战，10月25日后来被定为抗美援朝出国作战纪念日，彭德怀任司令员兼政治委员。10月1日是开国大典的日子，8月1日是建军节，9月3日是中国人民抗日战争胜利纪念日。把国庆当成出国作战纪念日，是日期上最接近的混淆。","source":"原创练习"},{"id":"gf-35","subject":"基本知识","chapter":"国防与军队","stem":"平型关大捷和百团大战的关系是：","options":["是同一次战役的两个名字","平型关大捷在1937年，是八路军出师后的第一个大胜仗；百团大战在1940年，是华北的大规模破袭战","两次都发生在解放战争时期","两次都由南昌起义前线指挥部直接指挥"],"answer":1,"explanation":"1937年9月，八路军第一一五师在平型关取得出师后的第一个大胜仗。1940年，八路军在华北发动百团大战，重点破袭交通线。两次都发生在全面抗战时期，但时间、规模和打法不同，不是一场战役的两个名字，更不属于解放战争或南昌起义。","source":"原创练习"},{"id":"gf-36","subject":"基本知识","chapter":"国防与军队","stem":"领空与防空识别区的差别在于：","options":["两者都是国家行使完整主权的领空","领空是领陆和领海上空的空气空间；防空识别区是为识别、监视设置的空域，进入其中不等于进入领空","防空识别区位于国土最内侧","领海宽200海里，所以领空也从200海里开始计算"],"answer":1,"explanation":"领空附属于领陆和领海，我国领海宽度是12海里。防空识别区是提前识别来向航空器的管理空域，可以划到领空之外，飞入识别区不等于侵犯领空。专属经济区可以延伸到200海里，但那不是领海，不能拿来推算领空起点。","source":"原创练习"},{"id":"gf-37","subject":"基本知识","chapter":"国防与军队","stem":"退役军人事务部是：","options":["中央军委联合参谋部的内设局","国务院组成部门，负责退役军人安置优抚等工作","某一战区的政治工作部","国家综合性消防救援队伍的原名"],"answer":1,"explanation":"退役军人事务部2018年组建，是国务院组成部门，面向退役军人提供安置、优抚等服务。军队内部的政治工作和战区机关不是这个部。消防救援队伍另有隶属。把政府的退役事务部门当成军委内设局，是把军队人员和管理退役事务的政府机构混在了一起。","source":"原创练习"},{"id":"gf-38","subject":"基本知识","chapter":"国防与军队","stem":"全军共同条令指的是：","options":["内务条令、纪律条令、队列条令","宪法、民法典、刑法","陆战条令、海战条令、空战条令","兵役法、教育法、道路交通安全法"],"answer":0,"explanation":"共同条令规范全军内务建设、纪律和维护队列生活，所以是内务条令、纪律条令、队列条令，对各类人员普遍适用。陆战、海战、空战条令针对作战行动，不是这三部共同条令。国家的民事、刑事法律重要，但不是军队所说的共同条令。","source":"原创练习"},{"id":"gf-39","subject":"基本知识","chapter":"国防与军队","stem":"1988年恢复军衔制度时，军官军衔中没有恢复的是：","options":["少将、上校、上尉","元帅、大将和大尉","中将、中校、中尉","少尉"],"answer":1,"explanation":"1955年授衔时设有元帅、大将，尉官中有大尉。1965年取消军衔。1988年恢复后，将官为上将、中将、少将，不设元帅、大将，也不设大尉。少将、上校、上尉都在恢复后的序列中，不能当作已经取消的等级。","source":"原创练习"},{"id":"gf-40","subject":"基本知识","chapter":"国防与军队","stem":"国家秘密的密级从高到低是：","options":["秘密、机密、绝密","绝密、机密、秘密","公开、内部、绝密","机密、绝密、秘密"],"answer":1,"explanation":"法定密级按泄露后可能造成的危害划分：绝密最高，机密次之，秘密再次。日常口语里的秘密听起来很重，却是三个法定等级里较低的一级。把机密排在绝密前面，是把前两级的次序记反了。","source":"原创练习"},{"id":"gf-41","subject":"基本知识","chapter":"国防与军队","stem":"双拥工作是指：","options":["拥军优属、拥政爱民","同时拥有核力量和航母","拥军优属、拥兵自重","军队经商、地方赞助"],"answer":0,"explanation":"双拥是拥军优属和拥政爱民，是密切军政军民关系的传统。它不是武器装备清单，更不是拥兵自重。军队也不再从事经营性活动，不能把双拥理解成军地一起经商。","source":"原创练习"},{"id":"gf-42","subject":"基本知识","chapter":"国防与军队","stem":"2024年军队相关力量调整中，符合公开事实的是：","options":["战略支援部队番号原样保留，只加挂一个办公室牌子","信息支援部队成立，战略支援部队番号不再保留","火箭军改称信息支援部队","退役军人事务部改称网络空间部队"],"answer":1,"explanation":"2024年，信息支援部队正式成立，军事航天部队、网络空间部队也按新的安排组建，战略支援部队的番号不再保留。火箭军仍然是火箭军，退役军人事务部仍然是国务院部门。认为战略支援部队只是加了一块牌子，就没有反映番号已经取消这一点。","source":"原创练习"},{"id":"gf-43","subject":"基本知识","chapter":"国防与军队","stem":"在现代条件下坚持人民战争，意思是：","options":["只需增加人数，不必发展装备和联合训练","把人民群众的支持与精锐力量、现代装备和信息系统结合起来","只适用于农村，城市和海上都不算","用民兵完全取代常备军"],"answer":1,"explanation":"人民战争的要义是战争的伟力存在于民众之中，现代条件下更强调人民支持、精锐部队和先进技术形成整体力量。把它简化成单纯堆人数，或者认为可以取消常备军，都离开了这个含义。","source":"原创练习"},{"id":"gf-44","subject":"基本知识","chapter":"国防与军队","stem":"衡量军队各项建设和工作的根本尺度是：","options":["营房是不是新建","战斗力这个唯一的根本的标准","编制人数是不是越多越好","是否承担经营性生产"],"answer":1,"explanation":"军队是要打仗的，战斗力是唯一的根本的标准。人数多、营房新，如果不能形成打赢能力，就不能代替这个标准。经营性生产也不是军队建设的尺度。","source":"原创练习"},{"id":"gf-45","subject":"基本知识","chapter":"国防与军队","stem":"军事禁区对普通公民的要求是：","options":["可以随时参观游览","采取严格保护措施，未经许可不得进入","只禁止外国人进入，本国公民不受限制","军事禁区就是城市中的开放公园"],"answer":1,"explanation":"军事禁区关系军事活动安全，管理严于军事管理区，无关人员不得擅自进入。保护措施不因访客是本国公民就取消。把它当成公园，就忽略了军事设施保护的特殊规定。","source":"原创练习"},{"id":"gf-46","subject":"基本知识","chapter":"国防与军队","stem":"兵役法对普通高等学校学生军事训练的态度是：","options":["在校期间必须接受基本军事训练","只有报考军校的学生才可以军训","学生可以自行决定永久取消","法律禁止高校组织军训"],"answer":0,"explanation":"兵役法要求普通高等学校学生在就学期间接受基本军事训练，这是国防教育的基础环节，不是军校独有，也不由个人宣布取消。法律是把军训作为应完成的安排，而不是加以禁止。","source":"原创练习"}]};
